INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('169239cc-46c5-4ed6-a8c2-26f270402f61', '上巳日貢院考雜文不遂赴九華觀祓禊之會以二絕句申贈 一', '上巳日貢院考杂文不遂赴九华观祓禊之會以二絕句申贈 一', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["三日韶光處處新，九華仙洞七香輪。","老夫留滯何由徃，珉玉相和正遶身。"]', '["三日韶光处处新，九华仙洞七香輪。","老夫留滯何由徃，珉玉相和正遶身。"]', '诗', 'shi', '', NULL, '上巳日貢院考雜文不遂赴九華觀祓禊之會以二絕句申贈 一 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf4ae95-1ee9-4dfb-932a-500501e17f6e', '上巳日貢院考雜文不遂赴九華觀祓禊之會以二絕句申贈 二', '上巳日貢院考杂文不遂赴九华观祓禊之會以二絕句申贈 二', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["禊飲尋春興有餘，深情婉婉見雙魚。","同心齊體如身到，臨水煩君便祓除。"]', '["禊饮尋春兴有餘，深情婉婉见雙鱼。","同心齊體如身到，臨水煩君便祓除。"]', '诗', 'shi', '', NULL, '上巳日貢院考雜文不遂赴九華觀祓禊之會以二絕句申贈 二 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aecdb8e-46cf-4941-a538-f5b3ed327989', '和九華觀見懷貢院八韻', '和九华观见懷貢院八韻', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["上巳好風景，仙家足芳菲。","地殊蘭亭會，人似山陰歸。","丹竈綴珠掩，白雲巖逕微。","真宮集女士，虛室涵春輝。","拘限心杳杳，歡言望依依。","滯茲文墨職，坐與琴觴違。","麗曲滌煩虛，幽緘發清機。","支頤一吟想，恨不雙翻飛。"]', '["上巳好风景，仙家足芳菲。","地殊蘭亭會，人似山陰归。","丹竈綴珠掩，白云巖逕微。","真宮集女士，虛室涵春輝。","拘限心杳杳，歡言望依依。","滯茲文墨職，坐與琴觴違。","丽曲滌煩虛，幽緘發清機。","支頤一吟想，恨不雙翻飞。"]', '诗', 'shi', '', NULL, '和九華觀見懷貢院八韻 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f19c7864-67cf-4485-9b9d-a02c505ec4c7', '桃源篇', '桃源篇', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["小年嘗讀桃源記，忽覩良工施繪事。","巖逕初欣繚繞通，溪風轉覺芬芳異。","一路鮮雲雜彩霞，漁舟遠遠逐桃花。","漸入空濛迷島道，寧知掩映有人家。","龐眉秀骨爭迎客，鑿井耕田人世隔。","不知漢代有衣冠，猶說秦家變阡陌。","石髓雲英甘且香，仙翁留飯出青囊。","相逢自是松喬侶，良會應殊劉阮郎。","內子閑吟倚瑤瑟，翫此沈沈銷永日。","忽聞麗曲金玉聲，便使老夫思閣筆。"]', '["小年嘗读桃源記，忽覩良工施繪事。","巖逕初欣繚繞通，溪风轉覺芬芳異。","一路鲜云杂彩霞，漁舟远远逐桃花。","漸入空濛迷島道，寧知掩映有人家。","龐眉秀骨爭迎客，鑿井耕田人世隔。","不知漢代有衣冠，猶说秦家变阡陌。","石髓云英甘且香，仙翁留飯出青囊。","相逢自是松喬侶，良會應殊劉阮郎。","內子闲吟倚瑤瑟，翫此沈沈銷永日。","忽闻丽曲金玉声，便使老夫思閣笔。"]', '诗', 'shi', '', NULL, '桃源篇 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81f582d-b7b9-4812-817a-515e5a7cdedb', '新月與兒女夜坐聽琴舉酒', '新月與兒女夜坐听琴舉酒', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["泥泥露凝葉，騷騷風入林。","以茲皓月圓，不厭良夜深。","列坐屏輕箑，放懷弦素琴。","兒女各冠笄，孫孩遶衣襟。","乃知大隱趣，宛若滄洲心。","方結偕老期，豈憚華髮侵。","笑語向蘭室，風流傳玉音。","愧君袖中字，價重雙南金。"]', '["泥泥露凝葉，騷騷风入林。","以茲皓月圓，不厭良夜深。","列坐屏轻箑，放懷弦素琴。","兒女各冠笄，孫孩遶衣襟。","乃知大隐趣，宛若滄洲心。","方結偕老期，豈憚华髮侵。","笑語向蘭室，风流傳玉音。","愧君袖中字，價重雙南金。"]', '诗', 'shi', '', NULL, '新月與兒女夜坐聽琴舉酒 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32f69392-6fb2-499a-9e8b-55081b5d48e3', '七夕', '七夕', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["今日雲軿渡鵲橋，應非脈脈與迢迢。","家人競喜開妝鏡，月下穿針拜九霄。"]', '["今日云軿渡鵲橋，應非脈脈與迢迢。","家人競喜开妝镜，月下穿針拜九霄。"]', '诗', 'shi', '', NULL, '七夕 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c180065-37ac-4063-8945-1672263179d5', '縣君赴興慶宮朝賀載之奉行冊禮因書即事', '縣君赴兴慶宮朝賀載之奉行冊禮因书即事', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["合巹交歡二十年，今朝比翼共朝天。","風傳漏刻香車度，日照旌旗綵仗鮮。","顧我華簪鳴玉珮，看君盛服耀金鈿。","相期偕老宜家處，鶴髮魚軒更可憐。"]', '["合巹交歡二十年，今朝比翼共朝天。","风傳漏刻香车度，日照旌旗綵仗鲜。","顧我华簪鳴玉珮，看君盛服耀金鈿。","相期偕老宜家处，鹤髮鱼軒更可怜。"]', '诗', 'shi', '', NULL, '縣君赴興慶宮朝賀載之奉行冊禮因書即事 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('557bcd4c-243a-44dd-adf1-cba7aa89a122', '元和元年蒙恩封成紀縣伯時室中封安喜縣君感慶兼懷聊申賀贈', '元和元年蒙恩封成紀縣伯时室中封安喜縣君感慶兼懷聊申賀贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["啓土封成紀，宜家縣安喜。","同欣井賦開，共受閨門祉。","珩璜聯采組，琴瑟諧宮徴。","更待懸車時，與君歡暮齒。"]', '["啓土封成紀，宜家縣安喜。","同欣井賦开，共受閨门祉。","珩璜聯采組，琴瑟諧宮徴。","更待懸车时，與君歡暮齒。"]', '诗', 'shi', '', NULL, '元和元年蒙恩封成紀縣伯時室中封安喜縣君感慶兼懷聊申賀贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d599371d-553d-409b-a105-4295f7726408', '河南崔尹即安喜從兄宜于室家四十餘歲一昨寓書病傳永寫告身既枉善祝因成絕句', '河南崔尹即安喜從兄宜于室家四十餘歲一昨寓书病傳永寫告身既枉善祝因成絕句', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["五色金光鸞鳳飛，三川墨妙巧相輝。","尊崇善祝今如此，共待曾玄捧翟衣。"]', '["五色金光鸾鳳飞，三川墨妙巧相輝。","尊崇善祝今如此，共待曾玄捧翟衣。"]', '诗', 'shi', '', NULL, '河南崔尹即安喜從兄宜于室家四十餘歲一昨寓書病傳永寫告身既枉善祝因成絕句 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b78941df-0bf5-4961-b770-ed0dbf6466ca', '奉使豐陵職司鹵簿通宵涉路因寄內', '奉使豐陵職司鹵簿通宵涉路因寄內', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["綵仗列森森，行宮夜漏深。","殳鋋方啓路，鉦鼓正交音。","曙月思蘭室，前山辨穀林。","家人念行役，應見此時心。"]', '["綵仗列森森，行宮夜漏深。","殳鋋方啓路，鉦鼓正交音。","曙月思蘭室，前山辨穀林。","家人念行役，應见此时心。"]', '诗', 'shi', '', NULL, '奉使豐陵職司鹵簿通宵涉路因寄內 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a5f6ded-1405-4526-8854-ad5a293b49b8', '酬南園新亭宴會璩新第慰慶之作時任賓客', '酬南园新亭宴會璩新第慰慶之作时任賓客', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["南宮煙景濃，平視中南峯。","官閑似休沐，盡室來相從。","日抱漢陰甕，或成蝴蝶夢。","樹老欲連雲，竹深疑入洞。","歡言交羽觴，列坐儼成行。","歌吟不能去，待此明月光。","好逑蘊明識，內顧多慙色。","不厭梁鴻貧，常譏伯宗直。","予壻信時英，諫垣金玉聲。","男兒纔弱冠，射策幸成名。","偃放斯自足，翛然去營欲。","散木固無堪，虛舟常任觸。","大隱本吾心，喜君流好音。","相期懸車歲，此地即中林。"]', '["南宮煙景濃，平視中南峯。","官闲似休沐，尽室来相從。","日抱漢陰甕，或成蝴蝶梦。","樹老欲連云，竹深疑入洞。","歡言交羽觴，列坐儼成行。","歌吟不能去，待此明月光。","好逑蘊明識，內顧多慙色。","不厭梁鴻貧，常譏伯宗直。","予壻信时英，諫垣金玉声。","男兒纔弱冠，射策幸成名。","偃放斯自足，翛然去營欲。","散木固無堪，虛舟常任觸。","大隐本吾心，喜君流好音。","相期懸车歲，此地即中林。"]', '诗', 'shi', '', NULL, '酬南園新亭宴會璩新第慰慶之作時任賓客 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('939d5ee1-0a6a-4a4d-abc8-1566418ae232', '七夕見與諸孫題乞巧文', '七夕见與諸孫題乞巧文', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["外孫爭乞巧，內子共題文。","隱暎花匳對，參差綺席分。","鵲橋臨片月，河鼓掩輕雲。","羨此嬰兒輩，歡呼徹曙聞。"]', '["外孫爭乞巧，內子共題文。","隐暎花匳对，參差綺席分。","鵲橋臨片月，河鼓掩轻云。","羨此嬰兒輩，歡呼徹曙闻。"]', '诗', 'shi', '', NULL, '七夕見與諸孫題乞巧文 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b996fb6a-c0b5-445f-8657-3599a929ab56', '太常寺宿齋有寄', '太常寺宿斋有寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["轉枕挑燈候曉雞，相君應歎太常妻。","長年多病偏相憶，不遣歸時醉似泥。"]', '["轉枕挑灯候晓雞，相君應歎太常妻。","长年多病偏相憶，不遣归时醉似泥。"]', '诗', 'shi', '', NULL, '太常寺宿齋有寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98b9892-c6ab-46af-91f2-340e5659034e', '朝迴閱樂寄絕句', '朝迴閱乐寄絕句', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["子城風煖百花初，樓上龜茲引導車。","曲罷卿卿理騶馭，細君相望意何如。"]', '["子城风煖百花初，楼上龟茲引導车。","曲罷卿卿理騶馭，細君相望意何如。"]', '诗', 'shi', '', NULL, '朝迴閱樂寄絕句 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c6ee1a3-3f3a-4d2f-801c-af195d259c38', '中書宿齋有寄', '中书宿斋有寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["銅壺漏滴斗闌干，泛灩金波照露盤。","遙想洞房眠正熟，不堪深夜鳳池寒。"]', '["銅壺漏滴斗闌干，泛灩金波照露盤。","遙想洞房眠正熟，不堪深夜鳳池寒。"]', '诗', 'shi', '', NULL, '中書宿齋有寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1b28069-1f1e-44f6-b655-8c6d19edc5b1', '中書送勅賜齋饌戲酬', '中书送勅賜斋饌戲酬', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["常日每齊眉，今朝共解頤。","遙知大官膳，應與衆雛嬉。"]', '["常日每齊眉，今朝共解頤。","遙知大官膳，應與衆雛嬉。"]', '诗', 'shi', '', NULL, '中書送勅賜齋饌戲酬 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97215c41-72ff-4c04-b690-f6586c324f3d', '勅賜長壽酒因口號以贈', '勅賜长壽酒因口號以贈', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["恩霑長壽酒，歸遺同心人。","滿酌共君醉，一杯千萬春。"]', '["恩霑长壽酒，归遺同心人。","满酌共君醉，一杯千万春。"]', '诗', 'shi', '', NULL, '勅賜長壽酒因口號以贈 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52fe3ab8-8248-46d2-99c7-102d601c4b12', '湖南觀察使故相國袁公挽歌二首 一', '湖南观察使故相国袁公挽歌二首 一', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["五驅龍虎節，一入鳳皇池。","令尹自無喜，羊公人不疑。","天歸京兆日，葉下洞庭時。","湘水秋風至，淒涼吹素旗。"]', '["五驱龙虎節，一入鳳皇池。","令尹自無喜，羊公人不疑。","天归京兆日，葉下洞庭时。","湘水秋风至，淒涼吹素旗。"]', '诗', 'shi', '', NULL, '湖南觀察使故相國袁公挽歌二首 一 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b4a1b7f-9c59-43ef-abe2-93047d6b6a0f', '湖南觀察使故相國袁公挽歌二首 二', '湖南观察使故相国袁公挽歌二首 二', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["丹旐發江臯，人悲鴈亦號。","湘南罷亥市，漢上改詞曹。","表墓雙碑立，尊名一字襃。","常聞平楚獄，爲報里門高。"]', '["丹旐發江臯，人悲鴈亦號。","湘南罷亥市，漢上改词曹。","表墓雙碑立，尊名一字襃。","常闻平楚獄，爲報里门高。"]', '诗', 'shi', '', NULL, '湖南觀察使故相國袁公挽歌二首 二 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d8508dc-2a87-446b-8b86-610535a406a6', '玉山嶺上作', '玉山嶺上作', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["悠悠驅匹馬，征路上連岡。","晚翠深雲竇，寒苔淨石梁。","荻花偏似雪，楓葉不禁霜。","愁見前程遠，空郊下夕陽。"]', '["悠悠驱匹马，征路上連岡。","晚翠深云竇，寒苔淨石梁。","荻花偏似雪，楓葉不禁霜。","愁见前程远，空郊下夕陽。"]', '诗', 'shi', '', NULL, '玉山嶺上作 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06682a26-33db-4a60-877d-53f68f6de57f', '題邵端公林亭', '題邵端公林亭', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["春光何處好，柱史有林塘。","鶯囀風初暖，花開日欲長。","鑿池通野水，掃徑閱新芳。","更置盈尊酒，時時醉楚狂。"]', '["春光何处好，柱史有林塘。","鶯囀风初暖，花开日欲长。","鑿池通野水，掃徑閱新芳。","更置盈尊酒，时时醉楚狂。"]', '诗', 'shi', '', NULL, '題邵端公林亭 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c5a05e-436c-4fd9-b093-3886e90cd529', '酬裴傑秀才新櫻桃', '酬裴傑秀才新櫻桃', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["新果真瓊液，來應宴紫蘭。","圓疑竊龍頷，色已奪雞冠。","遠火微微辨，殘星隱隱看。","茂先知味易，曼倩恨偷難。","忍用烹騂駱，從將翫玉盤。","流年如可駐，何必九華丹。"]', '["新果真瓊液，来應宴紫蘭。","圓疑竊龙頷，色已奪雞冠。","远火微微辨，殘星隐隐看。","茂先知味易，曼倩恨偷难。","忍用烹騂駱，從將翫玉盤。","流年如可駐，何必九华丹。"]', '诗', 'shi', '', NULL, '酬裴傑秀才新櫻桃 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f01c56b-709e-4bfb-b1ff-1d4b9c366802', '次滕老莊', '次滕老莊', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["征途無旅館，當晝喜逢君。","羸病仍留客，朝朝掃白雲。"]', '["征途無旅館，當晝喜逢君。","羸病仍留客，朝朝掃白云。"]', '诗', 'shi', '', NULL, '次滕老莊 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17c8d328-f828-4069-b3a0-6ac70497f3b6', '宿嚴陵', '宿嚴陵', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["身羈從事驅征傳，江入新安泛暮濤。","今夜子陵灘下泊，自慙相去九牛毛。"]', '["身羈從事驱征傳，江入新安泛暮濤。","今夜子陵灘下泊，自慙相去九牛毛。"]', '诗', 'shi', '', NULL, '宿嚴陵 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24699abe-2779-4f87-ac05-50f72f052c77', '題雲師山房', '題云師山房', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["雲公蘭若深山裏，月明松殿微風起。","試問空門清淨心，蓮花不著秋潭水。"]', '["云公蘭若深山裏，月明松殿微风起。","試问空门清淨心，蓮花不著秋潭水。"]', '诗', 'shi', '', NULL, '題雲師山房 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50adab66-404f-48e4-bcab-f6c11d56846d', '棲霞寺雲居室', '棲霞寺云居室', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["一徑縈紆至此窮，山僧盥漱白雲中。","閑吟定後更何事，石上松枝常有風。"]', '["一徑縈紆至此窮，山僧盥漱白云中。","闲吟定後更何事，石上松枝常有风。"]', '诗', 'shi', '', NULL, '棲霞寺雲居室 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9388acc-9645-4056-9950-00d258ebcda6', '舟行夜泊', '舟行夜泊', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["蕭蕭落葉送殘秋，寂寞寒波急暝流。","今夜不知何處泊，斷猨晴月引孤舟。"]', '["蕭蕭落葉送殘秋，寂寞寒波急暝流。","今夜不知何处泊，斷猨晴月引孤舟。"]', '诗', 'shi', '', NULL, '舟行夜泊 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43f374a9-522c-4e88-92ce-426d01946d7c', '發硤石路上却寄內', '發硤石路上却寄內', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["莎柵東行五谷深，千峯萬壑雨沈沈。","細君幾日路經此，應見悲翁相望心。"]', '["莎柵东行五谷深，千峯万壑雨沈沈。","細君幾日路經此，應见悲翁相望心。"]', '诗', 'shi', '', NULL, '發硤石路上却寄內 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b984031-a4e2-4e84-a151-d88548c46042', '冬至宿齋時郡君南內朝謁因寄', '冬至宿斋时郡君南內朝謁因寄', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["清齋獨向丘園拜，盛服想君興慶朝。","明日一陽生百福，不辭相望阻寒宵。"]', '["清斋独向丘园拜，盛服想君兴慶朝。","明日一陽生百福，不辞相望阻寒宵。"]', '诗', 'shi', '', NULL, '冬至宿齋時郡君南內朝謁因寄 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b340d8-51b9-4204-9299-435c52052a79', '和河南羅主簿送校書兄歸江南', '和河南羅主簿送校书兄归江南', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["兄弟泣殊方，天涯指故鄉。","斷雲無定處，歸鴈不成行。","草莽人煙少，風波水驛長。","上虞親渤澥，東楚隔瀟湘。","古戍陰傳火，寒蕪曉帶霜。","海門潮灩灩，沙岸荻蒼蒼。","京輦辭芸閣，衡方憶草堂。","知君始寧隱，還緝舊荷裳。"]', '["兄弟泣殊方，天涯指故乡。","斷云無定处，归鴈不成行。","草莽人煙少，风波水驛长。","上虞親渤澥，东楚隔瀟湘。","古戍陰傳火，寒蕪晓带霜。","海门潮灩灩，沙岸荻蒼蒼。","京輦辞芸閣，衡方憶草堂。","知君始寧隐，還緝旧荷裳。"]', '诗', 'shi', '', NULL, '和河南羅主簿送校書兄歸江南 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc8f6efd-2404-4797-a014-894d28b8ac4b', '與故人夜坐道舊', '與故人夜坐道旧', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["笑語歡今夕，煙霞愴昔遊。","清羸還對月，遲暮更逢秋。","勝理方自得，浮名不在求。","終當製初服，相與臥林丘。"]', '["笑語歡今夕，煙霞愴昔游。","清羸還对月，遲暮更逢秋。","勝理方自得，浮名不在求。","終當製初服，相與臥林丘。"]', '诗', 'shi', '', NULL, '與故人夜坐道舊 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e6d9628-9907-4001-986c-5ffd78b68d05', '句', '句', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["耒水波紋細，湘江竹葉輕。","古時樓上清明夜，月照樓前撩亂花。","今日成陰復成子，可憐春盡未歸家。","新婦磯頭雲半歛，女兒灘畔月初明。","迴合千峰裏，晴光似畫圖。","征車隨反照，候吏暎白雲。"]', '["耒水波紋細，湘江竹葉轻。","古时楼上清明夜，月照楼前撩亂花。","今日成陰复成子，可怜春尽未归家。","新婦磯头云半歛，女兒灘畔月初明。","迴合千峰裏，晴光似畫圖。","征车隨反照，候吏暎白云。"]', '诗', 'shi', '', NULL, '句 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35bc218a-0814-4ae9-bb01-1c33852426d2', '奉酬禮部閣老轉韻離合見贈', '奉酬禮部閣老轉韻離合见贈', 'a937f111-941d-44f9-8b58-128e97c2017e', '唐', '["移居既同里，多幸陪君子。","弘雅重當朝，弓旌早見招。","植根瓊林圃，直夜金閨步。","勸深子玉銘，力競相如賦。","間闊向春闈，日復想光儀。","格言信難繼，木石強爲詞。"]', '["移居既同里，多幸陪君子。","弘雅重當朝，弓旌早见招。","植根瓊林圃，直夜金閨步。","勸深子玉銘，力競相如賦。","间闊向春闈，日复想光儀。","格言信难繼，木石強爲词。"]', '诗', 'shi', '', NULL, '奉酬禮部閣老轉韻離合見贈 張薦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ffca718-321a-48fe-9c7a-d46d59d32934', '和潘孟陽春日雪迴文絕句', '和潘孟陽春日雪迴文絕句', 'a937f111-941d-44f9-8b58-128e97c2017e', '唐', '["遲遲日氣暖，漫漫雪天春。","知君欲醉飲，思見此交親。"]', '["遲遲日氣暖，漫漫雪天春。","知君欲醉饮，思见此交親。"]', '诗', 'shi', '', NULL, '和潘孟陽春日雪迴文絕句 張薦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('829fdca5-f440-4cb0-9f7c-edea5d7b6739', '享文恭太子廟樂章', '享文恭太子廟乐章', 'a937f111-941d-44f9-8b58-128e97c2017e', '唐', '["三獻具舉，九旗將旋。","追勞表德，罷享賓天。","風引仙管，堂虛畫筵。","芳馨常在，瞻望悠然。"]', '["三獻具舉，九旗將旋。","追勞表德，罷享賓天。","风引仙管，堂虛畫筵。","芳馨常在，瞻望悠然。"]', '诗', 'shi', '', NULL, '享文恭太子廟樂章 張薦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('959bb5a4-0311-4226-a86f-d057032e62d7', '禮部權侍郎閣老史館張秘監閣老有離合酬贈之什宿直吟翫聊繼此章', '禮部權侍郎閣老史館張秘監閣老有離合酬贈之什宿直吟翫聊繼此章', '9070f068-dd7f-4d84-bee3-e8d673819cd3', '唐', '["脉脉羨佳期，月夜吟麗詞。","諫垣則隨步，東觀方承顧。","林雪消豔陽，簡冊漏華光。","坐更芝蘭室，千載各芬芳。","節苦文俱盛，即時人竝命。","翩翻紫霄中，羽翮相輝映。"]', '["脉脉羨佳期，月夜吟丽词。","諫垣則隨步，东观方承顧。","林雪消豔陽，簡冊漏华光。","坐更芝蘭室，千載各芬芳。","節苦文俱盛，即时人竝命。","翩翻紫霄中，羽翮相輝映。"]', '诗', 'shi', '', NULL, '禮部權侍郎閣老史館張秘監閣老有離合酬贈之什宿直吟翫聊繼此章 崔邠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69c51939-a750-47b5-950e-b70fdb31472f', '享文恭太子廟樂章', '享文恭太子廟乐章', '9070f068-dd7f-4d84-bee3-e8d673819cd3', '唐', '["醴齊泛罇彝，軒縣動干戚。","入室僾如在，升階虔所歷。","舊疾合威容，定利舒皦澤。","方崇廟貌禮，永被君恩錫。"]', '["醴齊泛罇彝，軒縣动干戚。","入室僾如在，升階虔所歷。","旧疾合威容，定利舒皦澤。","方崇廟貌禮，永被君恩錫。"]', '诗', 'shi', '', NULL, '享文恭太子廟樂章 崔邠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13219d7a-60e9-4869-9de5-aca4d970f369', '和權載之離合詩', '和權載之離合诗', '68dcad37-4ab6-4d78-ae3a-6697b54b4641', '唐', '["校德盡珪璋，才臣時所揚。","放情寄文律，方茂經邦術。","王猷符發揮，十載契心期。","晝遊有嘉話，書法無隱辭。","信茲酧和美，言與芝蘭比。","昨來恣吟繹，日覺祛蒙鄙。"]', '["校德尽珪璋，才臣时所揚。","放情寄文律，方茂經邦術。","王猷符發揮，十載契心期。","晝游有嘉話，书法無隐辞。","信茲酧和美，言與芝蘭比。","昨来恣吟繹，日覺祛蒙鄙。"]', '诗', 'shi', '', NULL, '和權載之離合詩 楊於陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b706f51-babf-4b3b-bab4-371f66ad586b', '郡齋有紫薇雙本自朱明接于徂暑其花芳馥數旬猶茂庭宇之內逈無其倫予嘉其美而能久因詩紀述', '郡斋有紫薇雙本自朱明接于徂暑其花芳馥數旬猶茂庭宇之內逈無其倫予嘉其美而能久因诗紀述', '68dcad37-4ab6-4d78-ae3a-6697b54b4641', '唐', '["晏朝受明命，繼夏走天衢。","逮茲三伏候，息駕萬里途。","省躬既跼蹐，結思多煩紆。","簿領幸無事，宴休誰與娛。","內齋有嘉樹，雙植分庭隅。","綠葉下成幄，紫花紛若鋪。","摛霞晚舒豔，凝露朝垂珠。","炎沴晝方鑠，幽姿閑且都。","夭桃固難匹，芍藥寧爲徒。","懿此時節久，詎同光景驅。","陶甄試一致，品彙乃散殊。","濯質非受彩，無心那奪朱。","粤予負羈縶，留賞益踟躕。","通夕靡云倦，西南山月孤。"]', '["晏朝受明命，繼夏走天衢。","逮茲三伏候，息駕万里途。","省躬既跼蹐，結思多煩紆。","簿領幸無事，宴休誰與娛。","內斋有嘉樹，雙植分庭隅。","綠葉下成幄，紫花紛若鋪。","摛霞晚舒豔，凝露朝垂珠。","炎沴晝方鑠，幽姿闲且都。","夭桃固难匹，芍藥寧爲徒。","懿此时節久，詎同光景驱。","陶甄試一致，品彙乃散殊。","濯質非受彩，無心那奪朱。","粤予負羈縶，留賞益踟躕。","通夕靡云倦，西南山月孤。"]', '诗', 'shi', '', NULL, '郡齋有紫薇雙本自朱明接于徂暑其花芳馥數旬猶茂庭宇之內逈無其倫予嘉其美而能久因詩紀述 楊於陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bcb1efa-2174-4d1d-9549-4112d208b8fd', '贈毛仙翁', '贈毛仙翁', '68dcad37-4ab6-4d78-ae3a-6697b54b4641', '唐', '["先生赤松侶，混俗遊人間。","崑閬無窮路，何時下故山。","千年猶孺質，秘術救塵寰。","莫便沖天去，雲雷不可攀。"]', '["先生赤松侶，混俗游人间。","崑閬無窮路，何时下故山。","千年猶孺質，秘術救塵寰。","莫便沖天去，云雷不可攀。"]', '诗', 'shi', '', NULL, '贈毛仙翁 楊於陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6445e06e-5ec4-4a46-8b1d-83b492a0fec5', '荅權載之離合詩', '荅權載之離合诗', '3cc8d08d-8bdd-4dc9-aad3-531cf95b6532', '唐', '["史才司秘府，文哲今超古。","亦有擅風騷，六聯文墨曹。","聖賢三代意，工藝千金字。","化識從臣謠，人推仙閣吏。","如登崑閬時，口誦靈真詞。","孫簡下威鳳，系霜瓊玉枝。"]', '["史才司秘府，文哲今超古。","亦有擅风騷，六聯文墨曹。","聖賢三代意，工藝千金字。","化識從臣謠，人推仙閣吏。","如登崑閬时，口誦靈真词。","孫簡下威鳳，系霜瓊玉枝。"]', '诗', 'shi', '', NULL, '荅權載之離合詩 許孟容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54f7ec2d-da01-4743-86fa-c6c7a5fb3925', '奉和武相公春曉聞鶯', '奉和武相公春晓闻鶯', '3cc8d08d-8bdd-4dc9-aad3-531cf95b6532', '唐', '["碧樹當窗啼曉鶯，間關入夢聽難成。","千回萬囀盡愁思，疑是血魂哀困聲。"]', '["碧樹當窗啼晓鶯，间关入梦听难成。","千回万囀尽愁思，疑是血魂哀困声。"]', '诗', 'shi', '', NULL, '奉和武相公春曉聞鶯 許孟容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9a529af-e423-4fa0-958e-71b6758e84fe', '享文恭太子廟樂章', '享文恭太子廟乐章', '3cc8d08d-8bdd-4dc9-aad3-531cf95b6532', '唐', '["觴牢具品，管弦有節。","祝道寅恭，神儀昭晰。","桐珪早貴，象輅追設。","罄達樂成，降歆豐潔。"]', '["觴牢具品，管弦有節。","祝道寅恭，神儀昭晰。","桐珪早貴，象輅追設。","罄達乐成，降歆豐潔。"]', '诗', 'shi', '', NULL, '享文恭太子廟樂章 許孟容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('954c6e24-7265-46f5-8331-dfe1d59af786', '和權載之離合詩', '和權載之離合诗', 'a88379cd-5098-40bc-bcbc-869e7ffe66f4', '唐', '["車馬退朝後，聿懷在文友。","動詞宗伯雄，重美良史功。","亦曾吟鮑謝，二妙尤增價。","雨霜鴻唳天，匝樹鳥鳴夜。","覃思各縱橫，早擅希代名。","息心欲焚硯，自靦陪羣英。"]', '["车马退朝後，聿懷在文友。","动词宗伯雄，重美良史功。","亦曾吟鲍謝，二妙尤增價。","雨霜鴻唳天，匝樹鸟鳴夜。","覃思各縱橫，早擅希代名。","息心欲焚硯，自靦陪羣英。"]', '诗', 'shi', '', NULL, '和權載之離合詩 馮伉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37800dd9-895c-4fcc-8bb6-3ce8f3437c21', '享文恭太子廟樂章二首 一', '享文恭太子廟乐章二首 一', 'a88379cd-5098-40bc-bcbc-869e7ffe66f4', '唐', '["撰日瞻景，誠陳樂張。","禮容秩秩，羽舞煌煌。","肅將滌濯，祗薦芬芳。","永錫繁祉，思深享嘗。"]', '["撰日瞻景，誠陳乐張。","禮容秩秩，羽舞煌煌。","肅將滌濯，祗薦芬芳。","永錫繁祉，思深享嘗。"]', '诗', 'shi', '', NULL, '享文恭太子廟樂章二首 一 馮伉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f50a741-7508-4119-b111-861b797c94c6', '享文恭太子廟樂章二首 二', '享文恭太子廟乐章二首 二', 'a88379cd-5098-40bc-bcbc-869e7ffe66f4', '唐', '["干旄羽籥相虧蔽，一進一退殊行綴。","昔獻三雍盛禮容，今陳六佾崇儀制。"]', '["干旄羽籥相虧蔽，一進一退殊行綴。","昔獻三雍盛禮容，今陳六佾崇儀制。"]', '诗', 'shi', '', NULL, '享文恭太子廟樂章二首 二 馮伉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b81a6d29-b9c1-43e4-905f-fe719bfb1d5b', '和權載之離合詩', '和權載之離合诗', 'cca8bd49-6138-4dab-bc07-0f62e6e251cc', '唐', '["詠歌有離合，永夜觀酬荅。","笥中操綵牋，竹簡何足編。","意深俱妙絕，心契交情結。","計彼官接聯，言初竝清切。","翔集本相隨，羽儀良在斯。","煙雲競文藻，因喜翫新詩。"]', '["詠歌有離合，永夜观酬荅。","笥中操綵牋，竹簡何足編。","意深俱妙絕，心契交情結。","計彼官接聯，言初竝清切。","翔集本相隨，羽儀良在斯。","煙云競文藻，因喜翫新诗。"]', '诗', 'shi', '', NULL, '和權載之離合詩 潘孟陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2db887c-ebca-4b41-b9d4-d1d47dc960c7', '春日雪以迴文絕句呈張薦權德輿', '春日雪以迴文絕句呈張薦權德輿', 'cca8bd49-6138-4dab-bc07-0f62e6e251cc', '唐', '["春梅雜落雪，發樹幾花開。","真須盡興飲，仁里願同來。"]', '["春梅杂落雪，發樹幾花开。","真須尽兴饮，仁里願同来。"]', '诗', 'shi', '', NULL, '春日雪以迴文絕句呈張薦權德輿 潘孟陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab695a2b-71a4-4c5c-b68e-64a063896add', '元日和布澤', '元日和布澤', 'cca8bd49-6138-4dab-bc07-0f62e6e251cc', '唐', '["至德生成泰，咸歡照育恩。","流輝霑萬物，布澤在三元。","北闋祥雲逈，東方嘉氣繁。","青陽初應律，蒼玉正臨軒。","恩洽因時令，風和比化原。","自慙同草木，無以荅乾坤。"]', '["至德生成泰，咸歡照育恩。","流輝霑万物，布澤在三元。","北闋祥云逈，东方嘉氣繁。","青陽初應律，蒼玉正臨軒。","恩洽因时令，风和比化原。","自慙同草木，無以荅乾坤。"]', '诗', 'shi', '', NULL, '元日和布澤 潘孟陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca50e3f2-e8eb-470f-8acc-5cf5ff6237ae', '和權載之離合詩', '和權載之離合诗', '0fdc119f-b210-49cb-a2ac-dd2a97c316c6', '唐', '["少年慕時彥，小悟文多變。","木鐸比羣英，八方流德聲。","雷陳美交契，雨雪音塵繼。","恩顧各飛翔，因詩覩瑰麗。","傅野絕遺賢，人希有盛遷。","早欽風與雅，日詠贈酬篇。"]', '["少年慕时彥，小悟文多变。","木鐸比羣英，八方流德声。","雷陳美交契，雨雪音塵繼。","恩顧各飞翔，因诗覩瑰丽。","傅野絕遺賢，人希有盛遷。","早欽风與雅，日詠贈酬篇。"]', '诗', 'shi', '', NULL, '和權載之離合詩 武少儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3941670d-5a40-4a09-86a1-d920dafae88a', '諸葛丞相廟', '諸葛丞相廟', '0fdc119f-b210-49cb-a2ac-dd2a97c316c6', '唐', '["執簡焚香入廟門，武侯神象儼如存。","因機定蜀延衰漢，以計連吳振弱孫。","欲盡智能傾僭盜，善持忠節轉庸昏。","宣王請戰貽巾幗，始見才吞亦氣吞。"]', '["執簡焚香入廟门，武侯神象儼如存。","因機定蜀延衰漢，以計連吳振弱孫。","欲尽智能傾僭盜，善持忠節轉庸昏。","宣王請戰貽巾幗，始见才吞亦氣吞。"]', '诗', 'shi', '', NULL, '諸葛丞相廟 武少儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95a3b804-29fb-4f39-a970-ae9a24812c90', '享太廟樂章', '享太廟乐章', 'e2aa1c92-a236-489d-8caa-edad96e1c05d', '唐', '["肅肅清廟，登顯至德。","澤周八荒，兵定四極。","生物咸遂，羣盜滅息。","明聖欽承，子孫千億。"]', '["肅肅清廟，登显至德。","澤周八荒，兵定四極。","生物咸遂，羣盜滅息。","明聖欽承，子孫千億。"]', '诗', 'shi', '', NULL, '享太廟樂章 段文昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53e8b730-e2b2-4d93-8d7b-0db81dd467b4', '題武擔寺西臺', '題武擔寺西台', 'e2aa1c92-a236-489d-8caa-edad96e1c05d', '唐', '["秋天如鏡空，樓閣盡玲瓏。","水暗餘霞外，山明落照中。","鳥行看漸遠，松韻聽難窮。","今日登臨意，多歡語笑同。"]', '["秋天如镜空，楼閣尽玲瓏。","水暗餘霞外，山明落照中。","鸟行看漸远，松韻听难窮。","今日登臨意，多歡語笑同。"]', '诗', 'shi', '', NULL, '題武擔寺西臺 段文昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b016a84-fa7c-4d53-a3bd-766c3818c790', '晚夏登張儀樓呈院中諸公', '晚夏登張儀楼呈院中諸公', 'e2aa1c92-a236-489d-8caa-edad96e1c05d', '唐', '["重樓窗戶開，四望斂煙埃。","遠岫林端出，清波城下迴。","乍疑蟬韻促，稍覺雪風來。","併起鄉關思，銷憂在酒杯。"]', '["重楼窗戶开，四望斂煙埃。","远岫林端出，清波城下迴。","乍疑蟬韻促，稍覺雪风来。","併起乡关思，銷憂在酒杯。"]', '诗', 'shi', '', NULL, '晚夏登張儀樓呈院中諸公 段文昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1d387c0-d2e3-4dd2-8f57-2c787fad16d4', '還別業尋龍華山寺廣宣上人', '還別業尋龙华山寺廣宣上人', 'e2aa1c92-a236-489d-8caa-edad96e1c05d', '唐', '["十里惟聞松桂風，江山忽轉見龍宮。","正與休師方話舊，風煙幾度入樓中。"]', '["十里惟闻松桂风，江山忽轉见龙宮。","正與休師方話旧，风煙幾度入楼中。"]', '诗', 'shi', '', NULL, '還別業尋龍華山寺廣宣上人 段文昌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed70612b-03db-4550-a59b-75224f262aa9', '奉陪段相公晚夏登張儀樓', '奉陪段相公晚夏登張儀楼', '4f8d2762-3771-44a8-9188-3eac24711d67', '唐', '["秦相架羣材，登臨契上台。","查從銀漢落，江自雪山來。","儷曲親流火，凌風洽小杯。","帝鄉如在目，欲下盡裴回。"]', '["秦相架羣材，登臨契上台。","查從銀漢落，江自雪山来。","儷曲親流火，凌风洽小杯。","帝乡如在目，欲下尽裴回。"]', '诗', 'shi', '', NULL, '奉陪段相公晚夏登張儀樓 姚向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd81aad1-7619-4289-af5c-7202b3f1be67', '和段相公登武擔寺西臺', '和段相公登武擔寺西台', '4f8d2762-3771-44a8-9188-3eac24711d67', '唐', '["開閣錦城中，餘閑訪梵宮。","九層連晝景，萬象寫秋空。","天半將身到，江長與海通。","提攜出塵土，曾是穆清風。"]', '["开閣錦城中，餘闲訪梵宮。","九層連晝景，万象寫秋空。","天半將身到，江长與海通。","提携出塵土，曾是穆清风。"]', '诗', 'shi', '', NULL, '和段相公登武擔寺西臺 姚向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2455734f-c366-49ee-825e-dc73809af5db', '和段相公登武擔寺西臺', '和段相公登武擔寺西台', '838a3df1-4bae-4c26-97fb-e82ba8fa0253', '唐', '["桑臺煙樹中，臺榭造雲空。","眺聽逢秋興，篇辭變國風。","坐愁高鳥起，笑指遠人同。","始愧才情薄，躋攀繼韻窮。"]', '["桑台煙樹中，台榭造云空。","眺听逢秋兴，篇辞变国风。","坐愁高鸟起，笑指远人同。","始愧才情薄，躋攀繼韻窮。"]', '诗', 'shi', '', NULL, '和段相公登武擔寺西臺 溫會 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00b52b15-a2a8-4020-bd5f-660331c44495', '奉陪段相公晚夏登張儀樓', '奉陪段相公晚夏登張儀楼', '838a3df1-4bae-4c26-97fb-e82ba8fa0253', '唐', '["危軒重疊開，訪古上裴回。","有舌嗟秦策，飛樑駕楚材。","雲霄隨鳳到，物象爲詩來。","欲和關山意，巴歌調更哀。"]', '["危軒重叠开，訪古上裴回。","有舌嗟秦策，飞樑駕楚材。","云霄隨鳳到，物象爲诗来。","欲和关山意，巴歌調更哀。"]', '诗', 'shi', '', NULL, '奉陪段相公晚夏登張儀樓 溫會 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71074f7d-5edb-497c-aaaf-5aa46085beb9', '和段相公登武擔寺西臺', '和段相公登武擔寺西台', 'dffc16fd-d188-493b-9b9d-6f7f1ee95dee', '唐', '["臺上起涼風，乘閑覽歲功。","自隨台席貴，盡許羽觴同。","樓殿斜暉照，江山極望通。","賦詩思共樂，俱得詠時豐。"]', '["台上起涼风，乘闲覽歲功。","自隨台席貴，尽許羽觴同。","楼殿斜暉照，江山極望通。","賦诗思共乐，俱得詠时豐。"]', '诗', 'shi', '', NULL, '和段相公登武擔寺西臺 李敬伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5b561ac-2084-4f6a-a2f3-0d9d62f69868', '奉陪段相公晚夏登張儀樓', '奉陪段相公晚夏登張儀楼', 'dffc16fd-d188-493b-9b9d-6f7f1ee95dee', '唐', '["層屋架城隈，賓筵此日開。","文鋒摧八陣，星分應三台。","望雪煩襟釋，當歡遠思來。","披雲霄漢近，蹔覺出塵埃。"]', '["層屋架城隈，賓筵此日开。","文鋒摧八陣，星分應三台。","望雪煩襟釋，當歡远思来。","披云霄漢近，蹔覺出塵埃。"]', '诗', 'shi', '', NULL, '奉陪段相公晚夏登張儀樓 李敬伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc513435-4f3b-49ab-9bb4-f0c1caf09d1e', '奉陪段相公晚夏登張儀樓', '奉陪段相公晚夏登張儀楼', '7f62485f-e7d0-4980-9a95-c9c1d345dd70', '唐', '["登覽值晴開，詩從野思來。","蜀川新草木，秦日舊樓臺。","池景搖中座，山光接上台。","近秋宜晚景，極目斷浮埃。"]', '["登覽值晴开，诗從野思来。","蜀川新草木，秦日旧楼台。","池景搖中座，山光接上台。","近秋宜晚景，極目斷浮埃。"]', '诗', 'shi', '', NULL, '奉陪段相公晚夏登張儀樓 姚康 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eefcdb6-3fcc-436c-bbd4-3193129e2cb0', '和段相公登武擔寺西臺', '和段相公登武擔寺西台', '7f62485f-e7d0-4980-9a95-c9c1d345dd70', '唐', '["松逕引清風，登臺古寺中。","江平沙岸白，日下錦川紅。","疎樹山根淨，深雲鳥跡窮。","自慚陪末席，便與九霄通。"]', '["松逕引清风，登台古寺中。","江平沙岸白，日下錦川紅。","疎樹山根淨，深云鸟跡窮。","自慚陪末席，便與九霄通。"]', '诗', 'shi', '', NULL, '和段相公登武擔寺西臺 姚康 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c0b0847-6a32-4c71-a548-5bd2dcba6fe8', '禮部試早春殘雪', '禮部試早春殘雪', '7f62485f-e7d0-4980-9a95-c9c1d345dd70', '唐', '["微暖春潛至，輕明雪尚殘。","銀鋪光漸濕，珪破色仍寒。","無柳花常在，非秋露正團。","素光浮轉薄，皓質駐應難。","幸得依陰處，偏宜帶月看。","玉塵銷欲盡，窮巷起袁安。"]', '["微暖春潛至，轻明雪尚殘。","銀鋪光漸濕，珪破色仍寒。","無柳花常在，非秋露正團。","素光浮轉薄，皓質駐應难。","幸得依陰处，偏宜带月看。","玉塵銷欲尽，窮巷起袁安。"]', '诗', 'shi', '', NULL, '禮部試早春殘雪 姚康 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a85c6fc-d870-494d-83c1-51ac3bd8878a', '賦得巨魚縱大壑', '賦得巨鱼縱大壑', '7f62485f-e7d0-4980-9a95-c9c1d345dd70', '唐', '["水府乘閑望，圓波息躍魚。","從來暴泥久，今日脫泉初。","得志寧相忌，無心任宛如。","龍門應可度，鮫室豈常居。","掉尾方窮樂，遊鱗每自舒。","乘流千里去，風力藉吹噓。"]', '["水府乘闲望，圓波息躍鱼。","從来暴泥久，今日脫泉初。","得志寧相忌，無心任宛如。","龙门應可度，鮫室豈常居。","掉尾方窮乐，游鱗每自舒。","乘流千里去，风力藉吹噓。"]', '诗', 'shi', '', NULL, '賦得巨魚縱大壑 姚康 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40d58e5f-5373-4b3a-8cb2-28904853fd1d', '早春對雨', '早春对雨', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["南館垂楊早，東風細雨頻。","輕寒消玉斝，幽賞滯朱輪。","千里巴江守，三年故國春。","含情非遲客，懸榻但生塵。"]', '["南館垂楊早，东风細雨頻。","轻寒消玉斝，幽賞滯朱輪。","千里巴江守，三年故国春。","含情非遲客，懸榻但生塵。"]', '诗', 'shi', '', NULL, '早春對雨 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b4a301e-b540-4d63-867a-31a144117f98', '永寧小園即事', '永寧小园即事', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["蕭條梧竹下，秋物映園廬。","宿雨方然桂，朝飢更摘蔬。","陰苔生白石，時菊覆清渠。","陳力當何事，忘言媿道書。"]', '["蕭條梧竹下，秋物映园廬。","宿雨方然桂，朝飢更摘蔬。","陰苔生白石，时菊覆清渠。","陳力當何事，忘言媿道书。"]', '诗', 'shi', '', NULL, '永寧小園即事 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07181959-ec40-4958-83d2-57f2c55d6233', '臺中遇直晨覽蕭侍御壁畫山水', '台中遇直晨覽蕭侍御壁畫山水', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["蟲思庭莎白露天，微風吹竹曉淒然。","今來始悟朝迴客，暗寫歸心向石泉。"]', '["蟲思庭莎白露天，微风吹竹晓淒然。","今来始悟朝迴客，暗寫归心向石泉。"]', '诗', 'shi', '', NULL, '臺中遇直晨覽蕭侍御壁畫山水 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36c25663-9c88-4f7b-9411-1453dad7065c', '過三鄉望女几山早歲有卜築之志', '過三乡望女几山早歲有卜築之志', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["女几山頭春雪消，路傍仙杏發柔條。","心期欲去知何日，惆悵回車上野橋。"]', '["女几山头春雪消，路傍仙杏發柔條。","心期欲去知何日，惆悵回车上野橋。"]', '诗', 'shi', '', NULL, '過三鄉望女几山早歲有卜築之志 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5624eaa5-331a-418c-a0e1-5cf616e01e43', '和李都官郎中經宮人斜', '和李都官郎中經宮人斜', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["翡翠無窮掩夜泉，猶疑一半作神仙。","秋來還照長門月，珠露寒花是野田。"]', '["翡翠無窮掩夜泉，猶疑一半作神仙。","秋来還照长门月，珠露寒花是野田。"]', '诗', 'shi', '', NULL, '和李都官郎中經宮人斜 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43e725a9-1f56-446c-af8e-61702ec6f27f', '山閣聞笛', '山閣闻笛', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["臨風玉管吹參差，山塢春深日又遲。","李白桃紅滿城郭，馬融閑臥望京師。"]', '["臨风玉管吹參差，山塢春深日又遲。","李白桃紅满城郭，马融闲臥望京師。"]', '诗', 'shi', '', NULL, '山閣聞笛 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8fd1a28-064e-44d5-837b-c22087500732', '登樓', '登楼', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["槐柳蕭疎遶郡城，夜添山雨作江聲。","秋風南陌無車馬，獨上高樓故國情。"]', '["槐柳蕭疎遶郡城，夜添山雨作江声。","秋风南陌無车马，独上高楼故国情。"]', '诗', 'shi', '', NULL, '登樓 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c026b4e0-d430-46a2-a03c-b0cd56ead963', '憶江南舊遊二首 一', '憶江南旧游二首 一', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["山陰道上桂花初，王謝風流滿晉書。","曾作江南步從事，秋來還復憶鱸魚。"]', '["山陰道上桂花初，王謝风流满晉书。","曾作江南步從事，秋来還复憶鱸鱼。"]', '诗', 'shi', '', NULL, '憶江南舊遊二首 一 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6f1a92e-34ce-4410-885f-8eb349ef9149', '憶江南舊遊二首 二', '憶江南旧游二首 二', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["曲水三春弄綵毫，樟亭八月又觀濤。","金罍幾醉烏程酒，鶴舫閑吟把蟹螯。"]', '["曲水三春弄綵毫，樟亭八月又观濤。","金罍幾醉烏程酒，鹤舫闲吟把蟹螯。"]', '诗', 'shi', '', NULL, '憶江南舊遊二首 二 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbf9ab89-3ae8-4dd5-83a5-49ffca306ed0', '郡中即事三首 一', '郡中即事三首 一', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["曉風山郭雁飛初，霜拂回塘水榭虛。","鼓角清明如戰壘，梧桐搖落似貧居。","青門遠憶中人產，白首閑看太史書。","城下秋江寒見底，賓筵莫訝食無魚。"]', '["晓风山郭雁飞初，霜拂回塘水榭虛。","鼓角清明如戰壘，梧桐搖落似貧居。","青门远憶中人產，白首闲看太史书。","城下秋江寒见底，賓筵莫訝食無鱼。"]', '诗', 'shi', '', NULL, '郡中即事三首 一 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('051fd41c-24cf-4995-b76b-4055580aeff6', '郡中即事三首 二', '郡中即事三首 二', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["紅衣落盡暗香殘，葉上秋光白露寒。","越女含情已無限，莫敎長袖倚闌干。"]', '["紅衣落尽暗香殘，葉上秋光白露寒。","越女含情已無限，莫敎长袖倚闌干。"]', '诗', 'shi', '', NULL, '郡中即事三首 二 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af8e1d25-fcfb-4d07-8536-ee00052216c1', '郡中即事三首 三', '郡中即事三首 三', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["登臨何事見瓊枝，白露黃花自繞籬。","惟有樓中好山色，稻畦殘水入秋池。"]', '["登臨何事见瓊枝，白露黄花自繞籬。","惟有楼中好山色，稻畦殘水入秋池。"]', '诗', 'shi', '', NULL, '郡中即事三首 三 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d23990e-9d41-4356-9c86-92307223979d', '野望二首 一', '野望二首 一', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["萋萋麥隴杏花風，好是行春野望中。","日暮不辭停五馬，鴛鴦飛去綠江空。"]', '["萋萋麦隴杏花风，好是行春野望中。","日暮不辞停五马，鴛鴦飞去綠江空。"]', '诗', 'shi', '', NULL, '野望二首 一 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d342c44-d5a6-4c0e-ae05-80d8776a7ecb', '野望二首 二', '野望二首 二', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["忘懷不使海鷗疑，水映桃花酒滿巵。","亭上一聲歌白苧，野人歸棹亦行遲。"]', '["忘懷不使海鷗疑，水映桃花酒满巵。","亭上一声歌白苧，野人归棹亦行遲。"]', '诗', 'shi', '', NULL, '野望二首 二 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13ed7a6a-9980-450f-9140-97720a386182', '遊西山蘭若', '游西山蘭若', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["路傍垂柳古今情，春草春泉咽又生。","借問山僧好風景，看花攜酒幾人行。"]', '["路傍垂柳古今情，春草春泉咽又生。","借问山僧好风景，看花携酒幾人行。"]', '诗', 'shi', '', NULL, '遊西山蘭若 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baf40934-ac92-4c41-8c0c-8628442881fd', '泛舟入後溪 一', '泛舟入後溪 一', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["東風朝日破輕嵐，仙棹初移酒未酣。","玉笛閑吹折楊柳，春風無事傍魚潭。"]', '["东风朝日破轻嵐，仙棹初移酒未酣。","玉笛闲吹折楊柳，春风無事傍鱼潭。"]', '诗', 'shi', '', NULL, '泛舟入後溪 一 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b6f27f0-86ee-49a8-86a6-8bd66a887c7b', '泛舟入後溪 二', '泛舟入後溪 二', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["雨餘芳草淨沙塵，水綠灘平一帶春。","唯有啼鵑似留客，桃花深處更無人。"]', '["雨餘芳草淨沙塵，水綠灘平一带春。","唯有啼鵑似留客，桃花深处更無人。"]', '诗', 'shi', '', NULL, '泛舟入後溪 二 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('295ad12e-47aa-4d56-979e-0f68b80b730b', '看花', '看花', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["一到花間一忘歸，玉桮瑤瑟減光輝。","歌筵更覆青油幕，忽似朝雲瑞雪飛。"]', '["一到花间一忘归，玉桮瑤瑟減光輝。","歌筵更覆青油幕，忽似朝云瑞雪飞。"]', '诗', 'shi', '', NULL, '看花 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab17fc2-5d2c-4cd6-b8a0-67d5885531d3', '春望', '春望', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["莫問華簪髮已斑，歸心滿目是青山。","獨上層城倚危檻，柳營春盡馬嘶閑。"]', '["莫问华簪髮已斑，归心满目是青山。","独上層城倚危檻，柳營春尽马嘶闲。"]', '诗', 'shi', '', NULL, '春望 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84a76cfe-3f1d-4736-83fc-82f00b9ea903', '寄江陵韓少尹', '寄江陵韓少尹', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["別來玄鬢共成霜，雲起無心出帝鄉。","蜀國魚箋數行字，憶君秋夢過南塘。"]', '["別来玄鬢共成霜，云起無心出帝乡。","蜀国鱼箋數行字，憶君秋梦過南塘。"]', '诗', 'shi', '', NULL, '寄江陵韓少尹 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72efa79b-8bc6-4695-8e15-e8935e3a7433', '賀州宴行營回將', '賀州宴行營回將', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["九劒盈庭酒滿巵，戍人歸日及瓜時。","元戎靜鎮無邊事，遣向營中偃畫旗。"]', '["九劒盈庭酒满巵，戍人归日及瓜时。","元戎静鎮無邊事，遣向營中偃畫旗。"]', '诗', 'shi', '', NULL, '賀州宴行營回將 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81976ec6-c164-4b0d-adfa-6e218f0a0e0c', '遊郭駙馬大安山池', '游郭駙马大安山池', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["馬嘶芳草自淹留，別館何人屬細侯。","仙杏破顏逢醉客，綵鴛飛去避行舟。","洞簫日暖移賓榻，垂柳風多掩妓樓。","坐閱清暉不知暮，煙橫北渚水悠悠。"]', '["马嘶芳草自淹留，別館何人屬細侯。","仙杏破顏逢醉客，綵鴛飞去避行舟。","洞簫日暖移賓榻，垂柳风多掩妓楼。","坐閱清暉不知暮，煙橫北渚水悠悠。"]', '诗', 'shi', '', NULL, '遊郭駙馬大安山池 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a83ef032-ad73-46e3-b3ae-64862963c810', '故蕭尚書癭柏齋前玉蘂樹與王起居吏部孟員外同賞', '故蕭尚书癭柏斋前玉蘂樹與王起居吏部孟員外同賞', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["柏寢閉何時，瑤華自滿枝。","天清凝積素，風暖動芬絲。","留步蒼苔暗，停觴白日遲。","因吟茂陵草，幽賞待妍詞。"]', '["柏寢閉何时，瑤华自满枝。","天清凝積素，风暖动芬絲。","留步蒼苔暗，停觴白日遲。","因吟茂陵草，幽賞待妍词。"]', '诗', 'shi', '', NULL, '故蕭尚書癭柏齋前玉蘂樹與王起居吏部孟員外同賞 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb571e62-a750-422c-a2e1-8dfa86c8d262', '和武相早朝中書候傳點書懷奉呈', '和武相早朝中书候傳点书懷奉呈', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["殿省祕清曉，夔龍升紫微。","星辰拱帝座，劒履翊天機。","耿耿金波缺，沉沉玉漏稀。","綵箋蹲鷙獸，畫扇列名翬。","志業丹青重，恩華雨露霏。","三台昭建極，一德慶垂衣。","昌運瞻文敎，雄圖本武威。","殊勳如帶遠，佳氣似煙非。","抗節衷無隱，同心尚弼違。","良哉致君日，維嶽有光輝。"]', '["殿省祕清晓，夔龙升紫微。","星辰拱帝座，劒履翊天機。","耿耿金波缺，沉沉玉漏稀。","綵箋蹲鷙獸，畫扇列名翬。","志業丹青重，恩华雨露霏。","三台昭建極，一德慶垂衣。","昌運瞻文敎，雄圖本武威。","殊勳如带远，佳氣似煙非。","抗節衷無隐，同心尚弼違。","良哉致君日，維嶽有光輝。"]', '诗', 'shi', '', NULL, '和武相早朝中書候傳點書懷奉呈 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c11807f-5410-4d90-868e-89702e1a7bec', '和蕭侍御監祭白帝城西村寺齋沐覽鏡有懷吏部孟員外幷見贈', '和蕭侍御監祭白帝城西村寺斋沐覽镜有懷吏部孟員外幷见贈', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["晚沐金仙宇，迎秋白帝祠。","軒裳煩吏職，風物動心期。","清鏡開塵匣，華簪指髮絲。","南宮有高步，歲晏豈磷緇。"]', '["晚沐金仙宇，迎秋白帝祠。","軒裳煩吏職，风物动心期。","清镜开塵匣，华簪指髮絲。","南宮有高步，歲晏豈磷緇。"]', '诗', 'shi', '', NULL, '和蕭侍御監祭白帝城西村寺齋沐覽鏡有懷吏部孟員外幷見贈 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('425e3fdc-9226-47ec-984f-ac82b8997a71', '送張郎中副使自南省赴鳳翔府幕', '送張郎中副使自南省赴鳳翔府幕', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["仙郎佐氏謀，廷議寵元侯。","城郭須來貢，河隍亦順流。","亞夫高壘靜，充國大田秋。","當奮燕然筆，銘功向隴頭。"]', '["仙郎佐氏謀，廷議寵元侯。","城郭須来貢，河隍亦順流。","亞夫高壘静，充国大田秋。","當奮燕然笔，銘功向隴头。"]', '诗', 'shi', '', NULL, '送張郎中副使自南省赴鳳翔府幕 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a3b75a9-ca36-4ebc-bc01-9e7c953216b4', '和竇吏部雪中寓直', '和竇吏部雪中寓直', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["瑞花飄朔雪，灝氣滿南宮。","迢遰層城掩，徘徊午夜中。","金閨通籍恨，銀燭直廬空。","誰問烏臺客，家山憶桂叢。"]', '["瑞花飄朔雪，灝氣满南宮。","迢遰層城掩，徘徊午夜中。","金閨通籍恨，銀燭直廬空。","誰问烏台客，家山憶桂叢。"]', '诗', 'shi', '', NULL, '和竇吏部雪中寓直 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8d230ba-fe7e-4d4c-9718-12488ff27195', '小園春至偶呈吏部竇郎中', '小园春至偶呈吏部竇郎中', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["松篠雖苦節，冰霜慘其間。","欣然發佳色，如喜東風還。","幽抱想前躅，冥鴻度南山。","春臺一以眺，達士亦解顏。","偃息非老圃，沉吟閟玄關。","馳暉忽復失，壯氣不得閑。","君子當濟物，丹梯誰共攀。","心期自有約，去掃蒼苔斑。"]', '["松篠雖苦節，冰霜慘其间。","欣然發佳色，如喜东风還。","幽抱想前躅，冥鴻度南山。","春台一以眺，達士亦解顏。","偃息非老圃，沉吟閟玄关。","驰暉忽复失，壯氣不得闲。","君子當濟物，丹梯誰共攀。","心期自有約，去掃蒼苔斑。"]', '诗', 'shi', '', NULL, '小園春至偶呈吏部竇郎中 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff8cb3dc-dcc5-4be8-8e15-1ee6d54de22d', '酬吏部竇郎中直夜見寄', '酬吏部竇郎中直夜见寄', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["解巾侍雲陛，三命早爲郎。","復以雕龍彩，旋歸振鷺行。","玉書期養素，金印已懷黃。","茲夕南宮詠，遐情媿不忘。"]', '["解巾侍云陛，三命早爲郎。","复以雕龙彩，旋归振鷺行。","玉书期養素，金印已懷黄。","茲夕南宮詠，遐情媿不忘。"]', '诗', 'shi', '', NULL, '酬吏部竇郎中直夜見寄 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('371ebf75-34dc-4c08-a2c4-27670c6cf19a', '永寧里園亭休沐悵然成詠', '永寧里园亭休沐悵然成詠', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["雲景含初夏，休歸曲陌深。","幽簾宜永日，珍樹始清陰。","遲客唯長簟，忘言有匣琴。","畫披靈物態，書見古人心。","芳草多留步，鮮飆自滿襟。","勞形非立事，瀟灑媿頭簪。"]', '["云景含初夏，休归曲陌深。","幽簾宜永日，珍樹始清陰。","遲客唯长簟，忘言有匣琴。","畫披靈物態，书见古人心。","芳草多留步，鲜飆自满襟。","勞形非立事，瀟灑媿头簪。"]', '诗', 'shi', '', NULL, '永寧里園亭休沐悵然成詠 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d20fa6c-fa53-4f69-abe6-b3201bf0361b', '登樂遊原寄司封孟郎中盧補闕', '登乐游原寄司封孟郎中盧補闕', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["爽節時清眺，秋懷悵獨過。","神臯值宿雨，曲水已增波。","白鳥凌風迥，紅蕖濯露多。","伊川有歸思，君子復如何。"]', '["爽節时清眺，秋懷悵独過。","神臯值宿雨，曲水已增波。","白鸟凌风迥，紅蕖濯露多。","伊川有归思，君子复如何。"]', '诗', 'shi', '', NULL, '登樂遊原寄司封孟郎中盧補闕 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bec6b9f-91c5-4883-ae6f-88d4389841b3', '乾元初嚴黃門自京兆少尹貶牧巴郡以長才英氣固多暇日每遊郡之東山山側精舍有盤石細泉䟽爲浮桮之勝苔深樹老蒼然遺躅士諤謬因出守得繼茲賞乃賦詩十四韻刻於石壁', '乾元初嚴黄门自京兆少尹貶牧巴郡以长才英氣固多暇日每游郡之东山山側精舍有盤石細泉䟽爲浮桮之勝苔深樹老蒼然遺躅士諤謬因出守得繼茲賞乃賦诗十四韻刻於石壁', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["石座雙峰古，雲泉九曲深。","寂寥疏鑿意，蕪沒歲時侵。","繞席流還壅，浮杯咽復沉。","追懷王謝侶，更似會稽岑誰謂天池翼，相期宅畔吟。","光輝輕尺璧，然諾重黃金。","幾醉東山妓，長懸北闕心。","蕙蘭留雜佩，桃李想華簪。","閉閣余何事，鳴騶亦屢尋。","軒裳遵往轍，風景憩中林。","橫吹多淒調，安歌送好音。","初筵方側弁，故老忽沾襟。","盛世當弘濟，平生諒所欽。","無能愧陳力，惆悵拂瑤琴。"]', '["石座雙峰古，云泉九曲深。","寂寥疏鑿意，蕪沒歲时侵。","繞席流還壅，浮杯咽复沉。","追懷王謝侶，更似會稽岑誰謂天池翼，相期宅畔吟。","光輝轻尺璧，然諾重黄金。","幾醉东山妓，长懸北闕心。","蕙蘭留杂佩，桃李想华簪。","閉閣余何事，鳴騶亦屢尋。","軒裳遵往轍，风景憩中林。","橫吹多淒調，安歌送好音。","初筵方側弁，故老忽沾襟。","盛世當弘濟，平生諒所欽。","無能愧陳力，惆悵拂瑤琴。"]', '诗', 'shi', '', NULL, '乾元初嚴黃門自京兆少尹貶牧巴郡以長才英氣固多暇日每遊郡之東山山側精舍有盤石細泉䟽爲浮桮之勝苔深樹老蒼然遺躅士諤謬因出守得繼茲賞乃賦詩十四韻刻於石壁 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('672526d7-45d8-4e03-bcdf-6f0df7c9c3bf', '閑齋示一二道者', '闲斋示一二道者', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["幽蘭誰復奏，閑匣以端憂。","知止慙先覺，歸歟想故侯。","山蟬鈴閣晚，江雨麥田秋。","唯有空門學，相期老一丘。"]', '["幽蘭誰复奏，闲匣以端憂。","知止慙先覺，归歟想故侯。","山蟬鈴閣晚，江雨麦田秋。","唯有空门学，相期老一丘。"]', '诗', 'shi', '', NULL, '閑齋示一二道者 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b320cb73-b204-4653-b12a-5480f3e0436d', '南池荷花', '南池荷花', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["蟬噪城溝水，芙蓉忽已繁。","紅花迷越豔，芳意過湘沅。","湛露宜清暑，披香正滿軒。","朝朝秖自賞，穠李亦何言。"]', '["蟬噪城溝水，芙蓉忽已繁。","紅花迷越豔，芳意過湘沅。","湛露宜清暑，披香正满軒。","朝朝秖自賞，穠李亦何言。"]', '诗', 'shi', '', NULL, '南池荷花 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4db6efc-10b5-47cb-8081-e602281a1313', '郡中翫月寄江南李少尹虞部孟員外三首 一', '郡中翫月寄江南李少尹虞部孟員外三首 一', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["月滿自高丘，江通無狹流。","軒窗開到曉，風物坐含秋。","鵲警銀河斷，蛩悲翠幕幽。","清光望不極，耿耿下西樓。"]', '["月满自高丘，江通無狹流。","軒窗开到晓，风物坐含秋。","鵲警銀河斷，蛩悲翠幕幽。","清光望不極，耿耿下西楼。"]', '诗', 'shi', '', NULL, '郡中翫月寄江南李少尹虞部孟員外三首 一 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd11e20-5547-48ef-91fc-24bd8bf46140', '郡中翫月寄江南李少尹虞部孟員外三首 二', '郡中翫月寄江南李少尹虞部孟員外三首 二', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["桂華臨洛浦，如挹李膺仙。","茲夕披雲望，還吟擲地篇。","鳳池分直夜，牛渚泛舟年。","會是風流賞，惟君內史賢。"]', '["桂华臨洛浦，如挹李膺仙。","茲夕披云望，還吟擲地篇。","鳳池分直夜，牛渚泛舟年。","會是风流賞，惟君內史賢。"]', '诗', 'shi', '', NULL, '郡中翫月寄江南李少尹虞部孟員外三首 二 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba1b9b01-80cd-47be-be65-f70fe8e3b35a', '郡中翫月寄江南李少尹虞部孟員外三首 三', '郡中翫月寄江南李少尹虞部孟員外三首 三', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["圓景曠佳賓，徘徊夜漏頻。","金波徒汎酒，瑤瑟已生塵。","露白移長簟，風清挂幅巾。","西園舊才子，想見洛陽人。"]', '["圓景曠佳賓，徘徊夜漏頻。","金波徒汎酒，瑤瑟已生塵。","露白移长簟，风清挂幅巾。","西园旧才子，想见洛陽人。"]', '诗', 'shi', '', NULL, '郡中翫月寄江南李少尹虞部孟員外三首 三 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b028e741-70ba-43a1-851c-6361e47fb09e', '城隍廟賽雨二首 一', '城隍廟賽雨二首 一', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["零雨慰斯人，齋心薦綠蘋。","山風簫鼓響，如祭敬亭神。"]', '["零雨慰斯人，斋心薦綠蘋。","山风簫鼓响，如祭敬亭神。"]', '诗', 'shi', '', NULL, '城隍廟賽雨二首 一 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4de94729-879c-4e15-a1b6-004d27c013a2', '城隍廟賽雨二首 二', '城隍廟賽雨二首 二', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["積潤通千里，推誠奠一巵。","回飆經畫壁，忽似偃雲旗。"]', '["積潤通千里，推誠奠一巵。","回飆經畫壁，忽似偃云旗。"]', '诗', 'shi', '', NULL, '城隍廟賽雨二首 二 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bb1e503-05e8-4cb7-a331-d0e16fe7ee11', '郡樓晴望二首 一', '郡楼晴望二首 一', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["霽色朝雲盡，亭臯露亦晞。","褰開臨曲檻，蕭瑟換輕衣。","地遠秦人望，天晴社燕飛。","無功慙歲晚，唯念故山歸。"]', '["霽色朝云尽，亭臯露亦晞。","褰开臨曲檻，蕭瑟換轻衣。","地远秦人望，天晴社燕飞。","無功慙歲晚，唯念故山归。"]', '诗', 'shi', '', NULL, '郡樓晴望二首 一 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0226faf-8724-49ba-abe6-6c2096447765', '郡樓晴望二首 二', '郡楼晴望二首 二', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["一雨晴山郭，驚秋碧樹風。","蘭巵誰與薦，玉斾自無悰。","雲景嘶賓雁，嵐陰露彩虹。","閑吟嬾閉閣，旦夕郡樓中。"]', '["一雨晴山郭，驚秋碧樹风。","蘭巵誰與薦，玉斾自無悰。","云景嘶賓雁，嵐陰露彩虹。","闲吟嬾閉閣，旦夕郡楼中。"]', '诗', 'shi', '', NULL, '郡樓晴望二首 二 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54178e7b-e921-4450-9716-825647f123ef', '初移琪樹', '初移琪樹', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["愛此丘中物，煙霜盡日看。","無窮碧雲意，更助綠窗寒。"]', '["愛此丘中物，煙霜尽日看。","無窮碧云意，更助綠窗寒。"]', '诗', 'shi', '', NULL, '初移琪樹 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('884a25ac-d492-45dc-aeb8-d1e7c987ff0a', '燕居', '燕居', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["秋齋膏沐暇，旭日照軒墀。","露重芭蕉葉，香凝橘柚枝。","簡書隨吏散，寶騎與僧期。","報國得何力，流年已覺衰。"]', '["秋斋膏沐暇，旭日照軒墀。","露重芭蕉葉，香凝橘柚枝。","簡书隨吏散，寶騎與僧期。","報国得何力，流年已覺衰。"]', '诗', 'shi', '', NULL, '燕居 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93a445d5-7630-4bcf-91ab-bb2b43d8ef20', '寄黔府竇中丞', '寄黔府竇中丞', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["漢臣旌節貴，萬里護牂牁。","夏月天無暑，秋風水不波。","朝衣蟠艾綬，戎幕偃雕戈。","滿歲歸龍闕，良哉佇作歌。"]', '["漢臣旌節貴，万里護牂牁。","夏月天無暑，秋风水不波。","朝衣蟠艾綬，戎幕偃雕戈。","满歲归龙闕，良哉佇作歌。"]', '诗', 'shi', '', NULL, '寄黔府竇中丞 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daf422be-010a-4bb0-b4f7-65582d7f949e', '書樓懷古', '书楼懷古', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["何獨文翁化，風流與代深。","泉雲無舊轍，騷雅有遺音。","遠目窮巴漢，閑情閱古今。","忘言意不極，日暮但橫琴。"]', '["何独文翁化，风流與代深。","泉云無旧轍，騷雅有遺音。","远目窮巴漢，闲情閱古今。","忘言意不極，日暮但橫琴。"]', '诗', 'shi', '', NULL, '書樓懷古 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9997cdc-ee59-4d48-899c-20ace66b7d9b', '九月十日郡樓獨酌', '九月十日郡楼独酌', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["掾史當授衣，郡中稀物役。","嘉辰悵已失，殘菊誰爲惜。","櫺軒一尊泛，天景洞虛碧。","暮節獨賞心，寒江鳴湍石。","歸期北州里，舊友東山客。","飄蕩雲海深，相思桂花白。"]', '["掾史當授衣，郡中稀物役。","嘉辰悵已失，殘菊誰爲惜。","櫺軒一尊泛，天景洞虛碧。","暮節独賞心，寒江鳴湍石。","归期北州里，旧友东山客。","飄蕩云海深，相思桂花白。"]', '诗', 'shi', '', NULL, '九月十日郡樓獨酌 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87abd287-ffb5-4f95-bc4b-8cf3df3fa96f', '暮秋言懷', '暮秋言懷', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["城隅凝綵畫，紅樹帶青山。","遲客金尊晚，談空玉柄閑。","馳暉三峽水，旅夢百勞關。","非是淮陽薄，丘中只望還。"]', '["城隅凝綵畫，紅樹带青山。","遲客金尊晚，談空玉柄闲。","驰暉三峽水，旅梦百勞关。","非是淮陽薄，丘中只望還。"]', '诗', 'shi', '', NULL, '暮秋言懷 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af11fe29-0546-40fb-be10-2ef8bb92c3fe', '題枇杷樹', '題枇杷樹', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["珍樹寒始花，氛氳九秋月。","佳期若有待，芳意常無絕。","嫋嫋碧海風，濛濛綠枝雪。","急景自餘妍，春禽幸流悅。"]', '["珍樹寒始花，氛氳九秋月。","佳期若有待，芳意常無絕。","嫋嫋碧海风，濛濛綠枝雪。","急景自餘妍，春禽幸流悅。"]', '诗', 'shi', '', NULL, '題枇杷樹 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4ff4cbf-b005-4524-b64e-2fb81538e07b', '上元日紫極宮門觀州民然燈張樂', '上元日紫極宮门观州民然灯張乐', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["山郭通衢隘，瑤壇紫府深。","燈花助春意，舞綬織歡心。","閑似淮陽臥，恭聞樂職吟。","唯將聖明化，聊以達飛沈。"]', '["山郭通衢隘，瑤壇紫府深。","灯花助春意，舞綬织歡心。","闲似淮陽臥，恭闻乐職吟。","唯將聖明化，聊以達飞沈。"]', '诗', 'shi', '', NULL, '上元日紫極宮門觀州民然燈張樂 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57d0ccf1-c4d7-4dca-a1a3-adea540990ca', '西郊蘭若', '西郊蘭若', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["雲天宜北戶，塔廟似西方。","林下僧無事，江清日復長。","石泉盈掬冷，山實滿枝香。","寂寞傳心印，玄言亦已忘。"]', '["云天宜北戶，塔廟似西方。","林下僧無事，江清日复长。","石泉盈掬冷，山實满枝香。","寂寞傳心印，玄言亦已忘。"]', '诗', 'shi', '', NULL, '西郊蘭若 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94778466-139c-45bb-8d06-f9c341062163', '在郡三年今秋見白髮聊以書事', '在郡三年今秋见白髮聊以书事', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["二毛非騎省，朝鏡忽秋風。","絲縷寒衣上，霜華舊簡中。","承明那足厭，車服媿無功。","日日山城守，淹留巖桂叢。"]', '["二毛非騎省，朝镜忽秋风。","絲縷寒衣上，霜华旧簡中。","承明那足厭，车服媿無功。","日日山城守，淹留巖桂叢。"]', '诗', 'shi', '', NULL, '在郡三年今秋見白髮聊以書事 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b85824f-cde8-4fdb-887b-f10b1d263675', '郡中端居有懷袁州王員外使君', '郡中端居有懷袁州王員外使君', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["憶作同門友，承明奉直廬。","禁闈人自異，休澣跡非疎。","珥筆金華殿，三朝玉璽書。","恩光榮侍從，文彩應符徐。","青眼真知我，玄談愧起予。","蘭巵招促膝，松砌引長裾。","麗日流鶯早，涼天墜露初。","前山臨紫閣，曲水眺紅蕖。","誰爲音塵曠，俄驚歲月除。","風波移故轍，符守忽離居。","濟物陰功在，分憂盛業餘。","弱翁方大用，延首遲雙魚。"]', '["憶作同门友，承明奉直廬。","禁闈人自異，休澣跡非疎。","珥笔金华殿，三朝玉璽书。","恩光榮侍從，文彩應符徐。","青眼真知我，玄談愧起予。","蘭巵招促膝，松砌引长裾。","丽日流鶯早，涼天墜露初。","前山臨紫閣，曲水眺紅蕖。","誰爲音塵曠，俄驚歲月除。","风波移故轍，符守忽離居。","濟物陰功在，分憂盛業餘。","弱翁方大用，延首遲雙鱼。"]', '诗', 'shi', '', NULL, '郡中端居有懷袁州王員外使君 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8abbe576-b214-4c1d-8a04-d47900743de5', '山寺題壁', '山寺題壁', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["物外真何事，幽廊步不窮。","一燈心法在，三世影堂空。","山果青苔上，寒蟬落葉中。","歸來還閉閣，棠樹幾秋風。"]', '["物外真何事，幽廊步不窮。","一灯心法在，三世影堂空。","山果青苔上，寒蟬落葉中。","归来還閉閣，棠樹幾秋风。"]', '诗', 'shi', '', NULL, '山寺題壁 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('316b7da2-d0f1-471b-959e-ad7b18a8403d', '暇日適值澄霽江亭遊宴', '暇日適值澄霽江亭游宴', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["碧落風如洗，清光鏡不分。","弦歌方對酒，山谷盡無雲。","振臥淮陽病，悲秋宋玉文。","今來強攜妓，醉舞石榴裙。"]', '["碧落风如洗，清光镜不分。","弦歌方对酒，山谷尽無云。","振臥淮陽病，悲秋宋玉文。","今来強携妓，醉舞石榴裙。"]', '诗', 'shi', '', NULL, '暇日適值澄霽江亭遊宴 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62100c8e-32f1-4d7c-be75-bfdf446e6add', '玩槿花', '玩槿花', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["何乃詩人興，妍詞屬舜華。","風流感異代，窈窕比同車。","凝豔垂清露，驚秋隔絳紗。","蟬鳴復蟲思，惆悵竹陰斜。"]', '["何乃诗人兴，妍词屬舜华。","风流感異代，窈窕比同车。","凝豔垂清露，驚秋隔絳紗。","蟬鳴复蟲思，惆悵竹陰斜。"]', '诗', 'shi', '', NULL, '玩槿花 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab3d7fd-5db8-48d7-a40d-21bcf3c85c61', '郡齋讀經', '郡斋读經', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["壯齡非濟物，柔翰誤爲儒。","及此齋心暇，翛然與道俱。","散材誠獨善，正覺豈無徒。","半偈蓮生水，幽香桂滿爐。","息陰慙蔽芾，講義得醍醐。","跡似桃源客，身攖竹使符。","華夷參吏事，巴漢混州圖。","偃草懷君子，移風念嗇夫。","翳桑俄有績，宿麥復盈租。","圓寂期超詣，凋殘幸已蘇。","解空囊不智，滅景谷何愚。","幾日遵歸轍，東菑殆欲蕪。"]', '["壯齡非濟物，柔翰誤爲儒。","及此斋心暇，翛然與道俱。","散材誠独善，正覺豈無徒。","半偈蓮生水，幽香桂满爐。","息陰慙蔽芾，講義得醍醐。","跡似桃源客，身攖竹使符。","华夷參吏事，巴漢混州圖。","偃草懷君子，移风念嗇夫。","翳桑俄有績，宿麦复盈租。","圓寂期超詣，凋殘幸已蘇。","解空囊不智，滅景谷何愚。","幾日遵归轍，东菑殆欲蕪。"]', '诗', 'shi', '', NULL, '郡齋讀經 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c60f223-6df4-496d-97b9-60446bcaf422', '州民自言巴土冬濕且多陰晦今茲晴朗苦寒霜頗甚故老或異之因示寮吏', '州民自言巴土冬濕且多陰晦今茲晴朗苦寒霜頗甚故老或異之因示寮吏', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["雨霜以成歲，看舊感前聞。","愛景隨朝日，凝陰積暮雲。","囗囗囗囗囗，忘言酒暫醺。","囗囗囗囗囗，囗囗囗囗囗。"]', '["雨霜以成歲，看旧感前闻。","愛景隨朝日，凝陰積暮云。","囗囗囗囗囗，忘言酒暫醺。","囗囗囗囗囗，囗囗囗囗囗。"]', '诗', 'shi', '', NULL, '州民自言巴土冬濕且多陰晦今茲晴朗苦寒霜頗甚故老或異之因示寮吏 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a2497cd-1f17-4ed7-9ba8-6a51e436a4ea', '齋中有獸皮茵偶成詠', '斋中有獸皮茵偶成詠', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["逸才豈凡獸，服猛愚人得。","山澤生異姿，蒙戎蔚佳色。","青氈持與藉，重錦裁爲飾。","臥閣幸相宜，溫然承宴息。"]', '["逸才豈凡獸，服猛愚人得。","山澤生異姿，蒙戎蔚佳色。","青氈持與藉，重錦裁爲飾。","臥閣幸相宜，溫然承宴息。"]', '诗', 'shi', '', NULL, '齋中有獸皮茵偶成詠 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92388528-e94c-4eb4-acab-f105f4423e9b', '野夫採鞭於東山偶得元者', '野夫採鞭於东山偶得元者', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["追風豈無策，持斧有遐想。","鳳去留孤根，嵓懸非朽壤。","苔斑自天生，玉節垂雲長。","勿謂山之幽，丹梯亦可上。"]', '["追风豈無策，持斧有遐想。","鳳去留孤根，嵓懸非朽壤。","苔斑自天生，玉節垂云长。","勿謂山之幽，丹梯亦可上。"]', '诗', 'shi', '', NULL, '野夫採鞭於東山偶得元者 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b59f9bb3-8f6b-4b3f-bcfb-8a36dd1df2f7', '守郡累年俄及知命聊以言志', '守郡累年俄及知命聊以言志', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["南國疑逋客，東山作老夫。","登朝非大隱，出谷是真愚。","氣直慙龍劒，心清愛玉壺。","聊持循吏傳，早晚囗爲徒。"]', '["南国疑逋客，东山作老夫。","登朝非大隐，出谷是真愚。","氣直慙龙劒，心清愛玉壺。","聊持循吏傳，早晚囗爲徒。"]', '诗', 'shi', '', NULL, '守郡累年俄及知命聊以言志 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25b83882-d6df-4662-9463-fdde2af46b26', '東渡早梅一樹歲華如雪酣賞成詠', '东渡早梅一樹歲华如雪酣賞成詠', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["暇日留囗事，期雲亦囗開。","鄉心持歲酒，津下賞山梅。","晚實和商鼎，濃香拂壽杯。","唯應招北客，日日踏青來。"]', '["暇日留囗事，期云亦囗开。","乡心持歲酒，津下賞山梅。","晚實和商鼎，濃香拂壽杯。","唯應招北客，日日踏青来。"]', '诗', 'shi', '', NULL, '東渡早梅一樹歲華如雪酣賞成詠 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10ec309b-8ab4-47c7-b67c-d39a70bf91c1', '題郡南山光福寺寺即嚴黃門所置時自給事中京兆少尹出守年三十性樂山水故老云每旬數至後分閫川州門有去思碑即郄拾遺之詞也', '題郡南山光福寺寺即嚴黄门所置时自給事中京兆少尹出守年三十性乐山水故老云每旬數至後分閫川州门有去思碑即郄拾遺之词也', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["傳聞黃閣守，茲地賦長沙。","少壯稱時傑，功名惜歲華。","巖廊初建剎，賓從亟鳴笳。","玉帳空嚴道，甘棠見野花。","碑殘猶墮淚，城古自歸鴉。","籍籍清風在，懷人諒不遐。"]', '["傳闻黄閣守，茲地賦长沙。","少壯稱时傑，功名惜歲华。","巖廊初建剎，賓從亟鳴笳。","玉帳空嚴道，甘棠见野花。","碑殘猶墮泪，城古自归鴉。","籍籍清风在，懷人諒不遐。"]', '诗', 'shi', '', NULL, '題郡南山光福寺寺即嚴黃門所置時自給事中京兆少尹出守年三十性樂山水故老云每旬數至後分閫川州門有去思碑即郄拾遺之詞也 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d7c2618-c8d8-4ff5-a7b6-88ffb05263fe', '雨中寒食', '雨中寒食', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["令節逢煙雨，園亭但掩關。","佳人宿妝薄，芳樹綵繩閑。","歸思偏消酒，春寒爲近山。","花枝不可見，別恨灞陵間。"]', '["令節逢煙雨，园亭但掩关。","佳人宿妝薄，芳樹綵繩闲。","归思偏消酒，春寒爲近山。","花枝不可见，別恨灞陵间。"]', '诗', 'shi', '', NULL, '雨中寒食 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89786f64-930e-45ab-81a2-3d07dd6b050d', '晚夏郡中臥疾', '晚夏郡中臥疾', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["事外心如寄，虛齋臥更幽。","微風生白羽，畏日隔青油。","用拙懷歸去，沉痾畏借留。","東山自有計，蓬鬢莫先秋。"]', '["事外心如寄，虛斋臥更幽。","微风生白羽，畏日隔青油。","用拙懷归去，沉痾畏借留。","东山自有計，蓬鬢莫先秋。"]', '诗', 'shi', '', NULL, '晚夏郡中臥疾 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8557007-0d0a-48b2-913b-679da7a3e6ab', '酬盧司門晚夏過永寧里弊居林亭見寄', '酬盧司门晚夏過永寧里弊居林亭见寄', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["自嘆淮陽臥，誰知去國心。","幽亭來北戶，高韻得南金。","苔甃窺泉少，籃輿愛竹深。","風蟬一清暑，應喜脫朝簪。"]', '["自嘆淮陽臥，誰知去国心。","幽亭来北戶，高韻得南金。","苔甃窺泉少，籃輿愛竹深。","风蟬一清暑，應喜脫朝簪。"]', '诗', 'shi', '', NULL, '酬盧司門晚夏過永寧里弊居林亭見寄 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a588e1ad-df02-4431-af6f-55091191d890', '山郭風雨朝齋悵然秋思', '山郭风雨朝斋悵然秋思', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["桐竹離披曉，涼風似故園。","驚秋對旭日，感物坐前軒。","江燕飛還盡，山榴落尚繁。","平生信有意，衰久已忘言。"]', '["桐竹離披晓，涼风似故园。","驚秋对旭日，感物坐前軒。","江燕飞還尽，山榴落尚繁。","平生信有意，衰久已忘言。"]', '诗', 'shi', '', NULL, '山郭風雨朝齋悵然秋思 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d1a0edc-1423-4056-939a-01c32cc2de7d', '南館林塘', '南館林塘', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["郡閣山斜對，風煙隔短牆。","清池如寫月，珍樹盡凌霜。","行樂知無悶，加餐頗自強。","心期空歲晚，魚意久相忘。"]', '["郡閣山斜对，风煙隔短牆。","清池如寫月，珍樹尽凌霜。","行乐知無悶，加餐頗自強。","心期空歲晚，鱼意久相忘。"]', '诗', 'shi', '', NULL, '南館林塘 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44e2a297-1c3c-4756-9c82-5096aa853854', '臘夜對酒', '臘夜对酒', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["琥珀盃中物，瓊枝席上人。","樂聲方助醉，燭影已含春。","自顧行將老，何辭坐達晨。","傳觴稱厚德，不問吐車茵。"]', '["琥珀盃中物，瓊枝席上人。","乐声方助醉，燭影已含春。","自顧行將老，何辞坐達晨。","傳觴稱厚德，不问吐车茵。"]', '诗', 'shi', '', NULL, '臘夜對酒 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('694da900-155b-4c6c-844a-c0b806318797', '池上搆小山詠懷', '池上搆小山詠懷', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["玉立出巖石，風清曲囗囗。","偶成聊近意，靜對想凝神。","牛渚中流月，蘭亭上道春。","古來心可見，寂寞爲斯人。"]', '["玉立出巖石，风清曲囗囗。","偶成聊近意，静对想凝神。","牛渚中流月，蘭亭上道春。","古来心可见，寂寞爲斯人。"]', '诗', 'shi', '', NULL, '池上搆小山詠懷 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30fc43da-e775-4d1f-a40e-a3fb15cd9fc3', '林塘臘候', '林塘臘候', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["南國冰霜晚，年華已暗歸。","閑招別館客，遠念故山薇。","野艇虛還觸，籠禽倦更飛。","忘言亦何事，酣賞步清輝。"]', '["南国冰霜晚，年华已暗归。","闲招別館客，远念故山薇。","野艇虛還觸，籠禽倦更飞。","忘言亦何事，酣賞步清輝。"]', '诗', 'shi', '', NULL, '林塘臘候 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49b8585e-7aec-4518-ad10-190fc67fe9ab', '酬禮部崔員外備獨永寧里弊居見寄來詩云圖書鎖塵閣符節守山城', '酬禮部崔員外備独永寧里弊居见寄来诗云圖书鎖塵閣符節守山城', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["守土親巴俗，腰章囗漢儀。","春行樂職詠，秋感伴牢詞。","舊里藏書閣，閑門閉槿籬。","遙慙退朝客，下馬獨相思。"]', '["守土親巴俗，腰章囗漢儀。","春行乐職詠，秋感伴牢词。","旧里藏书閣，闲门閉槿籬。","遙慙退朝客，下马独相思。"]', '诗', 'shi', '', NULL, '酬禮部崔員外備獨永寧里弊居見寄來詩云圖書鎖塵閣符節守山城 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f454b1c8-d40f-4655-968b-da935b14c351', '梁國惠康公主挽歌詞二首 一', '梁国惠康公主挽歌词二首 一', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["湯沐成陳跡，山林遂寂寥。","鵲飛應織素，鳳起獨吹簫。","玉殿中參罷，雲軿上漢遙。","皇情非不極，空輟未央朝。"]', '["湯沐成陳跡，山林遂寂寥。","鵲飞應织素，鳳起独吹簫。","玉殿中參罷，云軿上漢遙。","皇情非不極，空輟未央朝。"]', '诗', 'shi', '', NULL, '梁國惠康公主挽歌詞二首 一 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5d8ff7f-0f16-4883-a63e-37c5080d3efb', '梁國惠康公主挽歌詞二首 二', '梁国惠康公主挽歌词二首 二', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["授冊榮天使，陳詩感聖恩。","山河啓梁國，縞素及于門。","泉向金巵咽，霜來玉樹繁。","都人聽哀挽，淚盡望寒原。"]', '["授冊榮天使，陳诗感聖恩。","山河啓梁国，縞素及于门。","泉向金巵咽，霜来玉樹繁。","都人听哀挽，泪尽望寒原。"]', '诗', 'shi', '', NULL, '梁國惠康公主挽歌詞二首 二 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7cad7a5-e28e-4248-b122-4467ec9a7bbd', '南池晨望', '南池晨望', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["起來林上月，瀟灑故人情。","鈴閣人何事，蓮塘曉獨行。","衣沾竹露爽，茶對石泉清。","鼓吹前賢薄，羣蛙試一鳴。"]', '["起来林上月，瀟灑故人情。","鈴閣人何事，蓮塘晓独行。","衣沾竹露爽，茶对石泉清。","鼓吹前賢薄，羣蛙試一鳴。"]', '诗', 'shi', '', NULL, '南池晨望 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06df9495-9c5a-4893-8ac8-a520c5cd8ea8', '林館避暑', '林館避暑', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["池島清陰裏，無人泛酒船。","山蜩金奏響，荷露水精圓。","靜勝朝還暮，幽觀白已玄。","家林正如此，何事賦歸田。"]', '["池島清陰裏，無人泛酒船。","山蜩金奏响，荷露水精圓。","静勝朝還暮，幽观白已玄。","家林正如此，何事賦归田。"]', '诗', 'shi', '', NULL, '林館避暑 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c51254d8-3d87-4ee3-94e0-eb31365bbd05', '巴南郡齋雨中偶看長曆是日小雪有懷昔年朝謁因成八韻', '巴南郡斋雨中偶看长曆是日小雪有懷昔年朝謁因成八韻', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["夷落朝雲候，王正小雪辰。","緬懷朝紫陌，曾是灑朱輪。","氣耿簪裾肅，風嚴刻漏頻。","暗飛金馬仗，寒舞玉京塵。","豸角隨中憲，龍池列近臣。","蘂珠凝瑞彩，懸圃淨華茵。","帝澤千箱慶，天顏萬物春。","明廷猶咫尺，高詠愧巴人。"]', '["夷落朝云候，王正小雪辰。","緬懷朝紫陌，曾是灑朱輪。","氣耿簪裾肅，风嚴刻漏頻。","暗飞金马仗，寒舞玉京塵。","豸角隨中憲，龙池列近臣。","蘂珠凝瑞彩，懸圃淨华茵。","帝澤千箱慶，天顏万物春。","明廷猶咫尺，高詠愧巴人。"]', '诗', 'shi', '', NULL, '巴南郡齋雨中偶看長曆是日小雪有懷昔年朝謁因成八韻 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('047a85c3-cc56-463d-9ed2-c43cd0c3b542', '褒城驛池塘翫月', '褒城驛池塘翫月', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["夜長秋始半，圓景麗銀河。","北渚清光溢，西山爽氣多。","鶴飛聞墜露，魚戲見增波。","千里家林望，涼飆換綠蘿。"]', '["夜长秋始半，圓景丽銀河。","北渚清光溢，西山爽氣多。","鹤飞闻墜露，鱼戲见增波。","千里家林望，涼飆換綠蘿。"]', '诗', 'shi', '', NULL, '褒城驛池塘翫月 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e5cb175-a788-4583-95ba-711b8a12ba63', '資陽郡中詠懷', '資陽郡中詠懷', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["腰章非達士，閉閣是潛夫。","匣劒寧求試，籠禽但自拘。","江清牛渚鎮，酒熟步兵廚。","唯此前賢意，風流似不孤。"]', '["腰章非達士，閉閣是潛夫。","匣劒寧求試，籠禽但自拘。","江清牛渚鎮，酒熟步兵廚。","唯此前賢意，风流似不孤。"]', '诗', 'shi', '', NULL, '資陽郡中詠懷 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e6f466c-3fc6-4930-a25b-3c14172c1b41', '寒食宴城北山池即故郡守榮陽鄭鋼目爲折柳亭', '寒食宴城北山池即故郡守榮陽鄭鋼目爲折柳亭', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["別館青山郭，遊人折柳行。","落花經上巳，細雨帶清明。","鶗鴂流芳暗，鴛鴦曲水平。","歸心何處醉，寶瑟有餘聲。"]', '["別館青山郭，游人折柳行。","落花經上巳，細雨带清明。","鶗鴂流芳暗，鴛鴦曲水平。","归心何处醉，寶瑟有餘声。"]', '诗', 'shi', '', NULL, '寒食宴城北山池即故郡守榮陽鄭鋼目爲折柳亭 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('067c9fbc-344f-4505-82f4-9a06fd042851', '酬彭州蕭使君秋中言懷', '酬彭州蕭使君秋中言懷', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["右職移青綬，雄藩拜紫泥。","江回玉壘下，氣爽錦城西。","臯鶴驚秋律，琴烏怨夜啼。","離居同舍念，宿昔奉金閨。"]', '["右職移青綬，雄藩拜紫泥。","江回玉壘下，氣爽錦城西。","臯鹤驚秋律，琴烏怨夜啼。","離居同舍念，宿昔奉金閨。"]', '诗', 'shi', '', NULL, '酬彭州蕭使君秋中言懷 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07665546-70cf-4577-a765-e5adaea4a6d4', '資中早春', '資中早春', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["一雨東風晚，山鶯獨報春。","淹留巫峽夢，惆悵洛陽人。","柳意籠丹檻，梅香覆錦茵。","年華行可惜，瑤瑟莫生塵。"]', '["一雨东风晚，山鶯独報春。","淹留巫峽梦，惆悵洛陽人。","柳意籠丹檻，梅香覆錦茵。","年华行可惜，瑤瑟莫生塵。"]', '诗', 'shi', '', NULL, '資中早春 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fed29882-43d1-43b7-86ca-1fa4c1999975', '郡樓懷長安親友', '郡楼懷长安親友', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["殘暑三巴地，沈陰八月天。","氣昏高閣雨，夢倦下簾眠。","愁鬢華簪小，歸心社燕前。","相思杜陵野，溝水獨潺湲。"]', '["殘暑三巴地，沈陰八月天。","氣昏高閣雨，梦倦下簾眠。","愁鬢华簪小，归心社燕前。","相思杜陵野，溝水独潺湲。"]', '诗', 'shi', '', NULL, '郡樓懷長安親友 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f515aba3-5d02-403d-b829-c550e84156db', '王起居獨遊青龍寺翫紅葉因寄', '王起居独游青龙寺翫紅葉因寄', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["十畝蒼苔遶畫廊，幾株紅樹過清霜。","高情還似看花去，閑對南山步夕陽。"]', '["十畝蒼苔遶畫廊，幾株紅樹過清霜。","高情還似看花去，闲对南山步夕陽。"]', '诗', 'shi', '', NULL, '王起居獨遊青龍寺翫紅葉因寄 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc2d507b-d3f7-46da-9b54-2e8a5b9e8d67', '夜聽琵琶三首 一', '夜听琵琶三首 一', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["掩抑危絃咽又通，朔雲邊月想朦朧。","當時誰佩將軍印，長使蛾眉怨不窮。"]', '["掩抑危絃咽又通，朔云邊月想朦朧。","當时誰佩將軍印，长使蛾眉怨不窮。"]', '诗', 'shi', '', NULL, '夜聽琵琶三首 一 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42c97f41-c035-4417-93e4-68430beb37a7', '夜聽琵琶三首 二', '夜听琵琶三首 二', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["一曲徘徊星漢稀，夜闌幽怨重依依。","忽似摐金來上馬，南枝棲鳥盡驚飛。"]', '["一曲徘徊星漢稀，夜闌幽怨重依依。","忽似摐金来上马，南枝棲鸟尽驚飞。"]', '诗', 'shi', '', NULL, '夜聽琵琶三首 二 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79d1b5e4-7deb-41df-9758-3cfb9c5007d4', '夜聽琵琶三首 三', '夜听琵琶三首 三', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["破撥聲繁恨已長，低鬟斂黛更摧藏。","潺湲隴水聽難盡，併覺風沙繞杏梁。"]', '["破撥声繁恨已长，低鬟斂黛更摧藏。","潺湲隴水听难尽，併覺风沙繞杏梁。"]', '诗', 'shi', '', NULL, '夜聽琵琶三首 三 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d7be9fe-531f-466b-85b8-5f35da37240d', '彭州蕭使君出妓夜宴見送', '彭州蕭使君出妓夜宴见送', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["玉顏紅燭忽驚春，微步凌波暗拂塵。","自是當歌歛眉黛，不因惆悵爲行人。"]', '["玉顏紅燭忽驚春，微步凌波暗拂塵。","自是當歌歛眉黛，不因惆悵爲行人。"]', '诗', 'shi', '', NULL, '彭州蕭使君出妓夜宴見送 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e49b0fa-c528-427e-a47b-2f22ce3b2c26', '題松江館', '題松江館', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["津柳江風白浪平，棹移高館古今情。","扁舟一去鴟夷子，應笑分符計日程。"]', '["津柳江风白浪平，棹移高館古今情。","扁舟一去鴟夷子，應笑分符計日程。"]', '诗', 'shi', '', NULL, '題松江館 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48bb2e9d-c59b-4718-9292-caad75646bef', '偶題寄獨孤使君', '偶題寄独孤使君', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["病起淮陽自有時，秋來未覺長年悲。","坐逢在日唯相望，嫋嫋涼風滿桂枝。"]', '["病起淮陽自有时，秋来未覺长年悲。","坐逢在日唯相望，嫋嫋涼风满桂枝。"]', '诗', 'shi', '', NULL, '偶題寄獨孤使君 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a6b59be-f9f2-47cf-b9e3-3dcf04d7e651', '永寧里小園與沈校書接近悵然題寄', '永寧里小园與沈校书接近悵然題寄', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["故里心期奈別何，手移芳樹憶庭柯。","東臯黍熟君應醉，梨葉初紅白露多。"]', '["故里心期奈別何，手移芳樹憶庭柯。","东臯黍熟君應醉，梨葉初紅白露多。"]', '诗', 'shi', '', NULL, '永寧里小園與沈校書接近悵然題寄 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41dd5fd7-8183-45f5-9f0e-ba43d4d39065', '齋中詠懷', '斋中詠懷', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["無心唯有白雲知，閑臥高齋夢蝶時。","不覺東風過寒食，雨來萱草出巴籬。"]', '["無心唯有白云知，闲臥高斋梦蝶时。","不覺东风過寒食，雨来萱草出巴籬。"]', '诗', 'shi', '', NULL, '齋中詠懷 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('690a3750-d7d5-40e0-9826-e4dcf7f02db6', '登郡前山', '登郡前山', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["洛陽歸客滯巴東，處處山櫻雪滿叢。","峴首當時爲風景，豈將官舍作池籠。"]', '["洛陽归客滯巴东，处处山櫻雪满叢。","峴首當时爲风景，豈將官舍作池籠。"]', '诗', 'shi', '', NULL, '登郡前山 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f9e50f5-c661-4ffd-92e2-b39c8f06c032', '客有自渠州來說常諫議使君故事悵然成詠', '客有自渠州来说常諫議使君故事悵然成詠', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["才子長沙暫左遷，能將意氣慰當年。","至今猶有東山妓，長使歌詩被管弦。"]', '["才子长沙暫左遷，能將意氣慰當年。","至今猶有东山妓，长使歌诗被管弦。"]', '诗', 'shi', '', NULL, '客有自渠州來說常諫議使君故事悵然成詠 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9353a746-6d8e-4308-8338-f8ed2f384420', '春日朝罷呈臺中寮友', '春日朝罷呈台中寮友', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["退食鵷行振羽儀，九霄雙闕迥參差。","雲披綵仗春風度，日暖香堦晝刻移。","玉樹籠煙鳷鵲觀，石渠流水鳳凰池。","時清執法慚無事，未有長楊漢主知。"]', '["退食鵷行振羽儀，九霄雙闕迥參差。","云披綵仗春风度，日暖香堦晝刻移。","玉樹籠煙鳷鵲观，石渠流水鳳凰池。","时清執法慚無事，未有长楊漢主知。"]', '诗', 'shi', '', NULL, '春日朝罷呈臺中寮友 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a1b0474-eac3-402f-9199-b3de34900240', '州民有獻杏者瑰麗溢目因感花未幾聊以成詠', '州民有獻杏者瑰丽溢目因感花未幾聊以成詠', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["南郭東風賞杏壇，幾株芳樹昨留歡。","却憶落花飄綺席，忽驚如實滿雕盤。","蛾眉半歛千金薄，鷤鴂初鳴百草闌。","志士古來悲節換，美人啼鳥亦長嘆。"]', '["南郭东风賞杏壇，幾株芳樹昨留歡。","却憶落花飄綺席，忽驚如實满雕盤。","蛾眉半歛千金薄，鷤鴂初鳴百草闌。","志士古来悲節換，美人啼鸟亦长嘆。"]', '诗', 'shi', '', NULL, '州民有獻杏者瑰麗溢目因感花未幾聊以成詠 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('121c87f7-c989-49a3-b25c-fd198002a0e2', '西川獨孤侍御見寄七言四韻一首爲郡翰墨都捐逮此詶答誠乖拙速', '西川独孤侍御见寄七言四韻一首爲郡翰墨都捐逮此詶答誠乖拙速', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["百雉層城上將壇，列營西照雪峰寒。","文章立事須銘鼎，談笑論功恥據鞍。","草檄清油推健筆，曳裾黃閣聳危冠。","雙金未比三千字，負弩空慙知者難。"]', '["百雉層城上將壇，列營西照雪峰寒。","文章立事須銘鼎，談笑論功恥據鞍。","草檄清油推健笔，曳裾黄閣聳危冠。","雙金未比三千字，負弩空慙知者难。"]', '诗', 'shi', '', NULL, '西川獨孤侍御見寄七言四韻一首爲郡翰墨都捐逮此詶答誠乖拙速 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a7842f2-0253-4acd-9995-f328fd55c532', '都城從事蕭員外寄海梨花詩盡綺麗至惠然遠及', '都城從事蕭員外寄海梨花诗尽綺丽至惠然远及', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["珠履行臺擁附蟬，外郎高步似神仙。","陳詞今見唐風盛，從事遙瞻衛國賢。","擲地好詞凌綵筆，浣花春水膩魚箋。","東山芳意須同賞，子看囊盛幾日傳。"]', '["珠履行台擁附蟬，外郎高步似神仙。","陳词今见唐风盛，從事遙瞻衛国賢。","擲地好词凌綵笔，浣花春水膩鱼箋。","东山芳意須同賞，子看囊盛幾日傳。"]', '诗', 'shi', '', NULL, '都城從事蕭員外寄海梨花詩盡綺麗至惠然遠及 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2f39e83-ead0-49e3-8a3b-17b30991be14', '赴資陽經嶓冢山', '赴資陽經嶓冢山', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["寧辭舊路駕朱轓，重使疲人感漢恩。","今日鳴騶到嶓峽，還勝博望至河源。"]', '["寧辞旧路駕朱轓，重使疲人感漢恩。","今日鳴騶到嶓峽，還勝博望至河源。"]', '诗', 'shi', '', NULL, '赴資陽經嶓冢山 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f8541ff-dbdd-42db-b0e5-3c53567b6c5d', '郡中言懷寄西川蕭員外', '郡中言懷寄西川蕭員外', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["功名無力愧勤王，已近終南得草堂。","身外盡歸天竺偈，腰間唯有會稽章。","何時臘酒逢山客，可惜梅枝亞石牀。","歲晚我知仙客意，懸心應在白雲鄉。"]', '["功名無力愧勤王，已近終南得草堂。","身外尽归天竺偈，腰间唯有會稽章。","何时臘酒逢山客，可惜梅枝亞石牀。","歲晚我知仙客意，懸心應在白云乡。"]', '诗', 'shi', '', NULL, '郡中言懷寄西川蕭員外 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef33157-b307-4b67-afea-bfa3ca1f9ae0', '郡齋感物寄長安親友', '郡斋感物寄长安親友', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["晴天春意併無窮，過臘江樓日日風。","瓊樹花香故人別，蘭巵酒色去年同。","閑吟鈴閣巴歌裏，回首神臯瑞氣中。","自愧朝衣猶在篋，歸來應是白頭翁。"]', '["晴天春意併無窮，過臘江楼日日风。","瓊樹花香故人別，蘭巵酒色去年同。","闲吟鈴閣巴歌裏，回首神臯瑞氣中。","自愧朝衣猶在篋，归来應是白头翁。"]', '诗', 'shi', '', NULL, '郡齋感物寄長安親友 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89055736-d733-4953-896e-d9fbd99221ae', '息舟荆溪入陽羨南山遊善權寺呈李功曹巨', '息舟荆溪入陽羨南山游善權寺呈李功曹巨', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["結纜蘭香渚，柴車上連岡。","晏溫值初霽，去遶山河長。","獻歲冰雪盡，細泉生路傍。","行披煙杉入，激澗橫石梁。","層閣表精廬，飛甍切雲翔。","沖襟得高步，清眺極遠方。","潭嶂積佳氣，荑英多早芳。","具觀澤國秀，重使春心傷。","念遵煩促途，榮利騖隟光。","勉君脫冠意，共匿無何鄉。"]', '["結纜蘭香渚，柴车上連岡。","晏溫值初霽，去遶山河长。","獻歲冰雪尽，細泉生路傍。","行披煙杉入，激澗橫石梁。","層閣表精廬，飞甍切云翔。","沖襟得高步，清眺極远方。","潭嶂積佳氣，荑英多早芳。","具观澤国秀，重使春心傷。","念遵煩促途，榮利騖隟光。","勉君脫冠意，共匿無何乡。"]', '诗', 'shi', '', NULL, '息舟荆溪入陽羨南山遊善權寺呈李功曹巨 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc069bee-3dc3-4408-9f7d-aedf5490a89b', '亂後曲江', '亂後曲江', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["憶昔曾遊曲水濱，春來長有探春人。","遊春人靜空地在，直至春深不似春。"]', '["憶昔曾游曲水濱，春来长有探春人。","游春人静空地在，直至春深不似春。"]', '诗', 'shi', '', NULL, '亂後曲江 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b41ba79-5526-43ea-8fe6-ed1f2c451370', '尋山家', '尋山家', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["獨訪山家歇還涉，茅屋斜連隔松葉。","主人聞語未開門，繞籬野菜飛黃蝶。"]', '["独訪山家歇還涉，茅屋斜連隔松葉。","主人闻語未开门，繞籬野菜飞黄蝶。"]', '诗', 'shi', '', NULL, '尋山家 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6682f8fc-ac0a-4ac0-89b9-09efe55db3c1', '寄裴校書', '寄裴校书', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["登高何處見瓊枝，白露黃花自繞籬。","惟有樓中好山色，稻畦殘水入秋池。"]', '["登高何处见瓊枝，白露黄花自繞籬。","惟有楼中好山色，稻畦殘水入秋池。"]', '诗', 'shi', '', NULL, '寄裴校書 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f76ee2e-ef33-42e9-baa1-03cdcd51c9e6', '句', '句', '8fc3a3a6-2c31-4242-a37a-077dba11d194', '唐', '["風泉留古韻，笙磬想遺音。","桂朽有遺馥，鸞飛安可待。","塵沙藹如霧，長波驚飆度。","雁起汀洲寒，馬嘶高城暮。","銀釭倦秋館，綺瑟瞻永路。","重有攜手期，清光倚玉樹。"]', '["风泉留古韻，笙磬想遺音。","桂朽有遺馥，鸾飞安可待。","塵沙藹如霧，长波驚飆度。","雁起汀洲寒，马嘶高城暮。","銀釭倦秋館，綺瑟瞻永路。","重有携手期，清光倚玉樹。"]', '诗', 'shi', '', NULL, '句 羊士諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6d4ba9-75d7-4ba7-8301-774273cde941', '秋夜閑居即事寄廬山鄭員外蜀郡符處士', '秋夜闲居即事寄廬山鄭員外蜀郡符处士', '08b14256-c564-4489-be33-927205119c81', '唐', '["憂思繁未整，良辰會無由。","引領遲佳音，星紀屢以周。","蓬閬絕華耀，況乃處窮愁。","墜葉寒擁砌，燈火夜悠悠。","開琴弄清弦，窺月俯澄流。","冉冉鴻鴈度，蕭蕭帷箔秋。","悵懷石門詠，緬慕碧雞遊。","髣髴蒙顏色，崇蘭隱芳洲。"]', '["憂思繁未整，良辰會無由。","引領遲佳音，星紀屢以周。","蓬閬絕华耀，況乃处窮愁。","墜葉寒擁砌，灯火夜悠悠。","开琴弄清弦，窺月俯澄流。","冉冉鴻鴈度，蕭蕭帷箔秋。","悵懷石门詠，緬慕碧雞游。","髣髴蒙顏色，崇蘭隐芳洲。"]', '诗', 'shi', '', NULL, '秋夜閑居即事寄廬山鄭員外蜀郡符處士 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aebc840d-b60a-43ad-8a42-40e37645435b', '獨不見', '独不见', '08b14256-c564-4489-be33-927205119c81', '唐', '["東風豔陽色，柳綠花如霰。","競理同心鬟，爭持合歡扇。","香傳賈娘手，粉離何郎面。","最恨卷簾時，含情獨不見。"]', '["东风豔陽色，柳綠花如霰。","競理同心鬟，爭持合歡扇。","香傳賈娘手，粉離何郎面。","最恨卷簾时，含情独不见。"]', '诗', 'shi', '', NULL, '獨不見 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1179db7f-af39-42de-a692-14574c10df9f', '題趙孟莊', '題趙孟莊', '08b14256-c564-4489-be33-927205119c81', '唐', '["管鮑化爲塵，交友存如線。","升堂俱自媚，得路難相見。","懿君敦三益，頹俗期一變。","心同襲芝蘭，氣合回霜霰。","石門雲臥久，玉洞花尋遍。","王濬愛旌旗，梁竦勞州縣。","煙鴻秋更遠，天馬寒愈健。","願事郭先生，青囊書幾卷。"]', '["管鲍化爲塵，交友存如線。","升堂俱自媚，得路难相见。","懿君敦三益，頹俗期一变。","心同襲芝蘭，氣合回霜霰。","石门云臥久，玉洞花尋遍。","王濬愛旌旗，梁竦勞州縣。","煙鴻秋更远，天马寒愈健。","願事郭先生，青囊书幾卷。"]', '诗', 'shi', '', NULL, '題趙孟莊 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74f4363c-5782-47ec-9dc6-38dd37fc1bd7', '辭魏博田尚書出境後感恩戀德因登藂臺', '辞魏博田尚书出境後感恩戀德因登藂台', '08b14256-c564-4489-be33-927205119c81', '唐', '["薦書及龍鍾，此事鏤心骨。","親知殊悢悢，徒御方咄咄。","藂臺邯鄲郭，臺上見新月。","離恨始分明，[歸思]□□更超忽。","懷仁淚空盡，感事情又發。","他時躧履聲，曉日照丹闕。"]', '["薦书及龙鍾，此事鏤心骨。","親知殊悢悢，徒御方咄咄。","藂台邯鄲郭，台上见新月。","離恨始分明，[归思]□□更超忽。","懷仁泪空尽，感事情又發。","他时躧履声，晓日照丹闕。"]', '诗', 'shi', '', NULL, '辭魏博田尚書出境後感恩戀德因登藂臺 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('595e0520-f7da-4db7-958c-c175cecba4ec', '夏日苦熱同長孫主簿過仁壽寺納涼', '夏日苦熱同长孫主簿過仁壽寺納涼', '08b14256-c564-4489-be33-927205119c81', '唐', '["火入天地罏，南方正何劇。","四郊長雲紅，六合太陽赤。","爀爀沸泉壑，燄燄燋砂石。","思減祝融權，期匡諸子宅。","因投竹林寺，一問青蓮客。","心空得清涼，理證等喧寂。","開襟天籟回，步履雨花積。","微風動珠簾，惠氣入瑤席。","境閑性方謐，塵遠趣皆適。","淹駕殊未還，朱欄敞虛碧。"]', '["火入天地罏，南方正何劇。","四郊长云紅，六合太陽赤。","爀爀沸泉壑，燄燄燋砂石。","思減祝融權，期匡諸子宅。","因投竹林寺，一问青蓮客。","心空得清涼，理證等喧寂。","开襟天籟回，步履雨花積。","微风动珠簾，惠氣入瑤席。","境闲性方謐，塵远趣皆適。","淹駕殊未還，朱欄敞虛碧。"]', '诗', 'shi', '', NULL, '夏日苦熱同長孫主簿過仁壽寺納涼 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eef8f8d0-8f59-456b-9c07-088bcefcd367', '送李虞仲秀才歸東都因寄元李二友', '送李虞仲秀才归东都因寄元李二友', '08b14256-c564-4489-be33-927205119c81', '唐', '["高翼閑未倦，孤雲曠無期。","晴霞海西畔，秋草燕南時。","鄴中多上才，耿耿丹霄姿。","顧我於逆旅，與君發光儀。","同將儒者方，獲忝攜人知。","幽蘭與芳佩，寒玉鏘美詞。","舊友在伊洛，鳴蟬思山陂。","到來再春風，夢盡雙瓊枝。","素業且無負，青冥殊未遲。","南橋天氣好，脈脈一相思。"]', '["高翼闲未倦，孤云曠無期。","晴霞海西畔，秋草燕南时。","鄴中多上才，耿耿丹霄姿。","顧我於逆旅，與君發光儀。","同將儒者方，獲忝携人知。","幽蘭與芳佩，寒玉鏘美词。","旧友在伊洛，鳴蟬思山陂。","到来再春风，梦尽雙瓊枝。","素業且無負，青冥殊未遲。","南橋天氣好，脈脈一相思。"]', '诗', 'shi', '', NULL, '送李虞仲秀才歸東都因寄元李二友 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('498f3303-9455-45fb-a789-a4af2f1ae201', '和盧諫議朝回書情即事寄兩省閣老兼呈二起居諫院諸院長', '和盧諫議朝回书情即事寄兩省閣老兼呈二起居諫院諸院长', '08b14256-c564-4489-be33-927205119c81', '唐', '["寵位資寂用，回頭憐二疎。","超遙比鶴性，皎潔同僧居。","華組澹無累，單牀歡有餘。","題詩天風灑，屬思紅霞舒。","藹藹延閤東，晨光映林初。","爐香深內殿，山色明前除。","對客默焚稾，何人知諫書。","全仁氣逾勁，大辨言甚徐。","逸步寄青璅，閑吟親綺疏。","清輝被鸞渚，瑞藹含龍渠。","謝監營野墅，陶公愛吾廬。","悠然遠者懷，聖代飄長裾。","端弼緝元化，至音生太虛。","一戎殄欃槍，重譯充儲胥。","借地種寒竹，看雲憶春蔬。","靈機棲杳冥，談笑登軒車。","晚迹識麒麟，秋英見芙蕖。","危言直且莊，曠抱鬱以攄。","志業耿冰雪，光容粲璠璵。","時賢儼仙掖，氣謝心何如。"]', '["寵位資寂用，回头怜二疎。","超遙比鹤性，皎潔同僧居。","华組澹無累，單牀歡有餘。","題诗天风灑，屬思紅霞舒。","藹藹延閤东，晨光映林初。","爐香深內殿，山色明前除。","对客默焚稾，何人知諫书。","全仁氣逾勁，大辨言甚徐。","逸步寄青璅，闲吟親綺疏。","清輝被鸾渚，瑞藹含龙渠。","謝監營野墅，陶公愛吾廬。","悠然远者懷，聖代飄长裾。","端弼緝元化，至音生太虛。","一戎殄欃槍，重譯充儲胥。","借地種寒竹，看云憶春蔬。","靈機棲杳冥，談笑登軒车。","晚迹識麒麟，秋英见芙蕖。","危言直且莊，曠抱鬱以攄。","志業耿冰雪，光容粲璠璵。","时賢儼仙掖，氣謝心何如。"]', '诗', 'shi', '', NULL, '和盧諫議朝回書情即事寄兩省閣老兼呈二起居諫院諸院長 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d38a3179-65f5-4314-a9dd-5b99454d713b', '奉酬竇郎中早入省苦寒見寄', '奉酬竇郎中早入省苦寒见寄', '08b14256-c564-4489-be33-927205119c81', '唐', '["玄冥怒含風，羣物戒嚴節。","空山頑石破，幽澗層冰裂。","題詩金華彥，接武丹霄烈。","曠懷玉京雲，孤唱粉垣雪。","窮陰總凝沍，正氣直肅殺。","天狼看墜地，霜兔敢拒穴。","悠然蓬蒿士，亦得奉朝謁。","羸驂苦遲遲，單僕怨切切。","端闈仙階邃，廣陌凍橋滑。","旭日鴛鴦行，瑞煙芙蓉闕。","司寒申鄭重，成歲在凜冽。","謝監逢酒時，袁生閉門月。","漸思霜霰減，欲報陽和發。","誰家挾纊心，何地當罏熱。","慘舒能一改，恭聽遠者說。"]', '["玄冥怒含风，羣物戒嚴節。","空山頑石破，幽澗層冰裂。","題诗金华彥，接武丹霄烈。","曠懷玉京云，孤唱粉垣雪。","窮陰總凝沍，正氣直肅殺。","天狼看墜地，霜兔敢拒穴。","悠然蓬蒿士，亦得奉朝謁。","羸驂苦遲遲，單僕怨切切。","端闈仙階邃，廣陌凍橋滑。","旭日鴛鴦行，瑞煙芙蓉闕。","司寒申鄭重，成歲在凜冽。","謝監逢酒时，袁生閉门月。","漸思霜霰減，欲報陽和發。","誰家挾纊心，何地當罏熱。","慘舒能一改，恭听远者说。"]', '诗', 'shi', '', NULL, '奉酬竇郎中早入省苦寒見寄 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db0b70c0-b894-426a-b7a1-e5136dedd031', '野園獻果呈員外', '野园獻果呈員外', '08b14256-c564-4489-be33-927205119c81', '唐', '["西園果初熟，上客心逾愜。","凝粉乍辭枝，飄紅仍帶葉。","幽姿寫瓊實，殷彩呈妝頰。","持此贈佳期，清芬羅袖裛。"]', '["西园果初熟，上客心逾愜。","凝粉乍辞枝，飄紅仍带葉。","幽姿寫瓊實，殷彩呈妝頰。","持此贈佳期，清芬羅袖裛。"]', '诗', 'shi', '', NULL, '野園獻果呈員外 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bddf2874-e96b-43b9-85d9-e4d7d89d25b9', '大堤曲', '大堤曲', '08b14256-c564-4489-be33-927205119c81', '唐', '["二八嬋娟大堤女，開壚相對依江渚。","待客登樓向水看，邀郎捲幔臨花語。","細雨濛濛濕芰荷，巴東商侶挂帆多。","自傳芳酒涴紅袖，誰調妍妝回翠娥。","珍簟華燈夕陽後，當壚理瑟矜纖手。","月落星微五鼓聲，春風搖蕩牕前柳。","歲歲逢迎沙岸間，北人多識綠雲鬟。","無端嫁與五陵少，離別煙波傷玉顏。"]', '["二八嬋娟大堤女，开壚相对依江渚。","待客登楼向水看，邀郎捲幔臨花語。","細雨濛濛濕芰荷，巴东商侶挂帆多。","自傳芳酒涴紅袖，誰調妍妝回翠娥。","珍簟华灯夕陽後，當壚理瑟矜纖手。","月落星微五鼓声，春风搖蕩牕前柳。","歲歲逢迎沙岸间，北人多識綠云鬟。","無端嫁與五陵少，離別煙波傷玉顏。"]', '诗', 'shi', '', NULL, '大堤曲 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('328b8671-623b-4496-9d14-8db6fe0e79ee', '楊花落', '楊花落', '08b14256-c564-4489-be33-927205119c81', '唐', '["北斗南回春物老，紅英落盡綠尚早。","韶風澹蕩無所依，偏惜垂楊作春好。","此時可憐楊柳花，滎盈豔曳滿人家。","人家女兒出羅幕，靜掃玉庭待花落。","寶環纖手捧更飛，翠羽輕裾承不著。","歷歷瑤琴舞金陳，菲紅拂黛憐玉人。","東園桃李芳已歇，獨有楊花嬌暮春。"]', '["北斗南回春物老，紅英落尽綠尚早。","韶风澹蕩無所依，偏惜垂楊作春好。","此时可怜楊柳花，滎盈豔曳满人家。","人家女兒出羅幕，静掃玉庭待花落。","寶环纖手捧更飞，翠羽轻裾承不著。","歷歷瑤琴舞金陳，菲紅拂黛怜玉人。","东园桃李芳已歇，独有楊花嬌暮春。"]', '诗', 'shi', '', NULL, '楊花落 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0be6b0d-6be7-4235-9db2-55ab10e437fd', '月宮詞', '月宮词', '08b14256-c564-4489-be33-927205119c81', '唐', '["宮中月明何所似，如積如流滿田地。","逈過前殿曾學眉，回照長門慣催淚。","昭陽昨夜秋風來，綺閣金鋪情影開。","藻井浮花共陵亂，玉階零露相裴回。","稍映明河泛仙馭，滿牕猶在更衣處。","管弦回燭無限情，環珮憑欄不能去。","皎皎蒼蒼千里同，穿煙飄葉九門通。","珠簾欲卷畏成水，瑤席初陳驚似空。","復值君王事歡宴，宮女三千一時見。","飛蓋愁看素暈低，稱觴願踏清輝遍。","江上無雲夜可憐，冒沙披浪自嬋娟。","若共心賞風流夜，那比高高太液前。"]', '["宮中月明何所似，如積如流满田地。","逈過前殿曾学眉，回照长门慣催泪。","昭陽昨夜秋风来，綺閣金鋪情影开。","藻井浮花共陵亂，玉階零露相裴回。","稍映明河泛仙馭，满牕猶在更衣处。","管弦回燭無限情，环珮憑欄不能去。","皎皎蒼蒼千里同，穿煙飄葉九门通。","珠簾欲卷畏成水，瑤席初陳驚似空。","复值君王事歡宴，宮女三千一时见。","飞蓋愁看素暈低，稱觴願踏清輝遍。","江上無云夜可怜，冒沙披浪自嬋娟。","若共心賞风流夜，那比高高太液前。"]', '诗', 'shi', '', NULL, '月宮詞 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d2f261c-4519-45c6-b0a4-202baf147773', '贈從弟茂卿', '贈從弟茂卿', '08b14256-c564-4489-be33-927205119c81', '唐', '["吾從驥足楊茂卿，性靈且奇才甚清。","海內方微風雅道，鄴中更有文章盟。","扣寂由來在淵思，搜奇本自通禪智。","王維證時符水月，杜甫狂處遺天地。","流水東西岐路分，幽州迢遰舊來聞。","若爲向北驅疲馬，山似寒空塞似雲。"]', '["吾從驥足楊茂卿，性靈且奇才甚清。","海內方微风雅道，鄴中更有文章盟。","扣寂由来在淵思，搜奇本自通禪智。","王維證时符水月，杜甫狂处遺天地。","流水东西岐路分，幽州迢遰旧来闻。","若爲向北驱疲马，山似寒空塞似云。"]', '诗', 'shi', '', NULL, '贈從弟茂卿 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cefcd9d-136e-441e-ad94-113b8c15181b', '烏啼曲贈張評事', '烏啼曲贈張評事', '08b14256-c564-4489-be33-927205119c81', '唐', '["可憐楊葉復楊花，雪淨煙深碧玉家。","烏棲不定枝條弱，城頭夜半聲啞啞。","浮萍流蕩門前水，任罥芙蓉莫墮沙。"]', '["可怜楊葉复楊花，雪淨煙深碧玉家。","烏棲不定枝條弱，城头夜半声啞啞。","浮萍流蕩门前水，任罥芙蓉莫墮沙。"]', '诗', 'shi', '', NULL, '烏啼曲贈張評事 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93dc913e-1b3a-4406-90a7-d9f4149bc1ef', '端午日伏蒙內侍賜晨服', '端午日伏蒙內侍賜晨服', '08b14256-c564-4489-be33-927205119c81', '唐', '["綵縷纖仍麗，凌風卷復開。","方應五日至，應自九天來。","在笥清光發，當軒暑氣回。","遙知及時節，刀尺火雲催。"]', '["綵縷纖仍丽，凌风卷复开。","方應五日至，應自九天来。","在笥清光發，當軒暑氣回。","遙知及时節，刀尺火云催。"]', '诗', 'shi', '', NULL, '端午日伏蒙內侍賜晨服 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3078c95-ad0b-4381-9d0f-767484fac386', '胡姬詞', '胡姬词', '08b14256-c564-4489-be33-927205119c81', '唐', '["妍豔照江頭，春風好客留。","當壚知妾慣，送酒爲郎羞。","香渡傳蕉扇，妝成上竹樓。","數錢憐皓腕，非是不能留。"]', '["妍豔照江头，春风好客留。","當壚知妾慣，送酒爲郎羞。","香渡傳蕉扇，妝成上竹楼。","數錢怜皓腕，非是不能留。"]', '诗', 'shi', '', NULL, '胡姬詞 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a67ba24d-99e2-43d0-8366-a60811bfa7ae', '春日有贈', '春日有贈', '08b14256-c564-4489-be33-927205119c81', '唐', '["堤暖柳絲斜，風光屬謝家。","晚心應戀水，春恨定因花。","步遠憐芳草，歸遲見綺霞。","由來感情思，獨自惜年華。"]', '["堤暖柳絲斜，风光屬謝家。","晚心應戀水，春恨定因花。","步远怜芳草，归遲见綺霞。","由来感情思，独自惜年华。"]', '诗', 'shi', '', NULL, '春日有贈 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9245cc97-4e85-4619-9437-afc450f43f1e', '襄陽樂', '襄陽乐', '08b14256-c564-4489-be33-927205119c81', '唐', '["閑隨少年去，試上大堤遊。","畫角棲烏起，清弦過客愁。","碑沈楚山石，珠徹漢江秋。","處處風情好，盧家更上樓。"]', '["闲隨少年去，試上大堤游。","畫角棲烏起，清弦過客愁。","碑沈楚山石，珠徹漢江秋。","处处风情好，盧家更上楼。"]', '诗', 'shi', '', NULL, '襄陽樂 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02bd5366-b3b8-4d23-92f9-5857e9256ce2', '關山月', '关山月', '08b14256-c564-4489-be33-927205119c81', '唐', '["蒼茫臨故關，迢遰照秋山。","萬里平蕪靜，孤城落葉閑。","露濃棲鴈起，天遠戍兵還。","復映征西府，光深組練間。"]', '["蒼茫臨故关，迢遰照秋山。","万里平蕪静，孤城落葉闲。","露濃棲鴈起，天远戍兵還。","复映征西府，光深組練间。"]', '诗', 'shi', '', NULL, '關山月 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1853d1e9-e305-49d9-894f-5ff235b537c1', '長城聞笛', '长城闻笛', '08b14256-c564-4489-be33-927205119c81', '唐', '["孤城笛滿林，斷續共霜砧。","夜月降羌淚，秋風老將心。","靜過寒壘遍，暗入故關深。","惆悵梅花落，山川不可尋。"]', '["孤城笛满林，斷續共霜砧。","夜月降羌泪，秋风老將心。","静過寒壘遍，暗入故关深。","惆悵梅花落，山川不可尋。"]', '诗', 'shi', '', NULL, '長城聞笛 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('089973d6-706d-44a0-8a2f-31924e6045fb', '春晚東歸留贈李功曹', '春晚东归留贈李功曹', '08b14256-c564-4489-be33-927205119c81', '唐', '["芳田岐路斜，脈脈惜年華。","雲路青絲騎，香含翠幰車。","歌聲仍隔水，醉色未侵花。","唯有懷鄉客，東飛羨曙鵶。"]', '["芳田岐路斜，脈脈惜年华。","云路青絲騎，香含翠幰车。","歌声仍隔水，醉色未侵花。","唯有懷乡客，东飞羨曙鵶。"]', '诗', 'shi', '', NULL, '春晚東歸留贈李功曹 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('364a33f8-53ef-46c3-92df-7ae656cca792', '送殷員外使北蕃', '送殷員外使北蕃', '08b14256-c564-4489-be33-927205119c81', '唐', '["二軒將雨露，萬里入煙沙。","和氣生中國，薰風屬外家。","塞蘆隨鴈影，關柳拂駝花。","努力黃雲北，僊曹有雉車。"]', '["二軒將雨露，万里入煙沙。","和氣生中国，薰风屬外家。","塞蘆隨鴈影，关柳拂駝花。","努力黄云北，僊曹有雉车。"]', '诗', 'shi', '', NULL, '送殷員外使北蕃 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28d3990e-8a80-4c9f-b24e-b72f01eb2cd0', '送許侍御充雲南哀冊使判官', '送許侍御充云南哀冊使判官', '08b14256-c564-4489-be33-927205119c81', '唐', '["萬里永昌城，威儀奉聖明。","冰心瘴江冷，霜憲漏天晴。","荒外開亭候，雲南降斾旌。","他時功自許，絕域轉哀榮。"]', '["万里永昌城，威儀奉聖明。","冰心瘴江冷，霜憲漏天晴。","荒外开亭候，云南降斾旌。","他时功自許，絕域轉哀榮。"]', '诗', 'shi', '', NULL, '送許侍御充雲南哀冊使判官 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd03ef17-b6d9-42de-afd8-89faa7d76e27', '秋日題陳宗儒圃亭悽然感舊', '秋日題陳宗儒圃亭悽然感旧', '08b14256-c564-4489-be33-927205119c81', '唐', '["曾隨何水部，待月東亭宿。","今日重凭欄，清風空在竹。","前山依舊碧，閑草經秋綠。","時物方宛然，蛛絲一何速。"]', '["曾隨何水部，待月东亭宿。","今日重凭欄，清风空在竹。","前山依旧碧，闲草經秋綠。","时物方宛然，蛛絲一何速。"]', '诗', 'shi', '', NULL, '秋日題陳宗儒圃亭悽然感舊 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2fd13a1-7e42-4a9c-a4f8-ffdeb9d40f17', '和鄭少師相公題慈恩寺禪院', '和鄭少師相公題慈恩寺禪院', '08b14256-c564-4489-be33-927205119c81', '唐', '["舊寺長桐孫，朝天是聖恩。","謝公詩更老，蕭傅道方尊。","白法知深得，蒼生要重論。","若爲將此望，心地向空門。"]', '["旧寺长桐孫，朝天是聖恩。","謝公诗更老，蕭傅道方尊。","白法知深得，蒼生要重論。","若爲將此望，心地向空门。"]', '诗', 'shi', '', NULL, '和鄭少師相公題慈恩寺禪院 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b2dd6c-6fed-4b8b-b847-be25c04b059a', '同趙校書題普救寺', '同趙校书題普救寺', '08b14256-c564-4489-be33-927205119c81', '唐', '["東門高處天，一望幾悠然。","白浪過城下，青山滿寺前。","塵光分驛道，嵐色到人煙。","氣象須文字，逢君大雅篇。"]', '["东门高处天，一望幾悠然。","白浪過城下，青山满寺前。","塵光分驛道，嵐色到人煙。","氣象須文字，逢君大雅篇。"]', '诗', 'shi', '', NULL, '同趙校書題普救寺 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11ba6660-7fdc-431c-9c8d-8c95b37bb50c', '春日與劉評事過故證上人院', '春日與劉評事過故證上人院', '08b14256-c564-4489-be33-927205119c81', '唐', '["曾共劉諮議，同時事道林。","與君方掩淚，來客是知心。","堦雪凌春積，鐘煙向夕深。","依然舊童子，相送出花陰。"]', '["曾共劉諮議，同时事道林。","與君方掩泪，来客是知心。","堦雪凌春積，鐘煙向夕深。","依然旧童子，相送出花陰。"]', '诗', 'shi', '', NULL, '春日與劉評事過故證上人院 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c18667b-708f-4a2a-9c20-d4a104e36904', '春雪題興善寺廣宣上人竹院', '春雪題兴善寺廣宣上人竹院', '08b14256-c564-4489-be33-927205119c81', '唐', '["皎潔青蓮客，焚香對雪朝。","竹風催淅瀝，花雨讓飄颻。","觸石和雲積，縈池拂水消。","只應將日月，顏色不相饒。"]', '["皎潔青蓮客，焚香对雪朝。","竹风催淅瀝，花雨讓飄颻。","觸石和云積，縈池拂水消。","只應將日月，顏色不相饒。"]', '诗', 'shi', '', NULL, '春雪題興善寺廣宣上人竹院 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a96f1b0d-7c85-4f6a-98f9-b26e3ca2dfd2', '清明日后土祠送田徹', '清明日后土祠送田徹', '08b14256-c564-4489-be33-927205119c81', '唐', '["清明千萬家，處處是年華。","榆柳芳辰火，梧桐今日花。","祭祠結雲綺，遊陌擁香車。","惆悵田郎去，原回煙樹斜。"]', '["清明千万家，处处是年华。","榆柳芳辰火，梧桐今日花。","祭祠結云綺，游陌擁香车。","惆悵田郎去，原回煙樹斜。"]', '诗', 'shi', '', NULL, '清明日后土祠送田徹 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c4f87ef-3508-44ca-9d12-a6bf110a81e8', '酬令狐員外直夜書懷見寄', '酬令狐員外直夜书懷见寄', '08b14256-c564-4489-be33-927205119c81', '唐', '["花枝暖欲舒，粉署夜方初。","世職推傳盛，春刑是減餘。","芸香能護字，鉛槧善呈書。","此地從頭白，經年望雉車。"]', '["花枝暖欲舒，粉署夜方初。","世職推傳盛，春刑是減餘。","芸香能護字，鉛槧善呈书。","此地從头白，經年望雉车。"]', '诗', 'shi', '', NULL, '酬令狐員外直夜書懷見寄 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c31fbe9c-bc54-455e-9c18-bf7c065eee35', '題表丈三大夫書齋', '題表丈三大夫书斋', '08b14256-c564-4489-be33-927205119c81', '唐', '["盛府自蓮花，羣公是歲華。","蘭姿丈人圃，松色大夫家。","素卷堆瑤席，朱弦映絳紗。","詩題三百首，高韻照春霞。"]', '["盛府自蓮花，羣公是歲华。","蘭姿丈人圃，松色大夫家。","素卷堆瑤席，朱弦映絳紗。","诗題三百首，高韻照春霞。"]', '诗', 'shi', '', NULL, '題表丈三大夫書齋 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d719fd0e-bbf4-49b5-83f7-e04ad1d1b9d3', '春日送沈贊府歸潯陽覲叔父', '春日送沈贊府归潯陽覲叔父', '08b14256-c564-4489-be33-927205119c81', '唐', '["潯陽阮咸宅，九派竹林前。","花嶼高如浪，雲峰遠似天。","江聲在南巷，海氣入東田。","才子今朝去，風濤思渺然。"]', '["潯陽阮咸宅，九派竹林前。","花嶼高如浪，云峰远似天。","江声在南巷，海氣入东田。","才子今朝去，风濤思渺然。"]', '诗', 'shi', '', NULL, '春日送沈贊府歸潯陽覲叔父 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27d08ec0-f76c-4855-9671-c2b4a4559795', '與李文仲秀才同賦泛酒花詩', '與李文仲秀才同賦泛酒花诗', '08b14256-c564-4489-be33-927205119c81', '唐', '["若道春無賴，飛花合逐風。","巧知人意裏，解入酒杯中。","香濕勝含露，光搖似泛空。","請君回首看，幾片舞芳叢。"]', '["若道春無賴，飞花合逐风。","巧知人意裏，解入酒杯中。","香濕勝含露，光搖似泛空。","請君回首看，幾片舞芳叢。"]', '诗', 'shi', '', NULL, '與李文仲秀才同賦泛酒花詩 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c67b0e78-53ba-4ed1-96d4-da38c7e0809f', '登寧州城樓', '登寧州城楼', '08b14256-c564-4489-be33-927205119c81', '唐', '["宋玉本悲秋，今朝更上樓。","清波城下去，此意重悠悠。","晚菊臨杯思，寒山滿郡愁。","故關非內地，一爲漢家羞。"]', '["宋玉本悲秋，今朝更上楼。","清波城下去，此意重悠悠。","晚菊臨杯思，寒山满郡愁。","故关非內地，一爲漢家羞。"]', '诗', 'shi', '', NULL, '登寧州城樓 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cf67235-a1bb-402f-bd49-4b6c03d83a0c', '同薛侍御登黎陽縣樓眺黃河', '同薛侍御登黎陽縣楼眺黄河', '08b14256-c564-4489-be33-927205119c81', '唐', '["倚檻恣流目，高城臨大川。","九回紆白浪，一半在青天。","氣肅晴空外，光翻曉日邊。","開襟值佳景，懷抱更悠然。"]', '["倚檻恣流目，高城臨大川。","九回紆白浪，一半在青天。","氣肅晴空外，光翻晓日邊。","开襟值佳景，懷抱更悠然。"]', '诗', 'shi', '', NULL, '同薛侍御登黎陽縣樓眺黃河 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03832c09-0b93-4df0-b4b5-39b6f8208d46', '和權相公南園閑涉寄廣宣上人', '和權相公南园闲涉寄廣宣上人', '08b14256-c564-4489-be33-927205119c81', '唐', '["浩氣抱天和，閑園載酒過。","步因秋景曠，心向晚雲多。","翠玉思回鳳，玄珠肯在鵝。","問師登幾地，空性奈詩何。"]', '["浩氣抱天和，闲园載酒過。","步因秋景曠，心向晚云多。","翠玉思回鳳，玄珠肯在鵝。","问師登幾地，空性奈诗何。"]', '诗', 'shi', '', NULL, '和權相公南園閑涉寄廣宣上人 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ab2e477-66f2-4f1d-a642-ff3f157b1cde', '供奉定法師歸安南', '供奉定法師归安南', '08b14256-c564-4489-be33-927205119c81', '唐', '["故鄉南越外，萬里白雲峰。","經論辭天去，香花入海逢。","鷺濤清梵徹，蜃閣化城重。","心到長安陌，交州後夜鐘。"]', '["故乡南越外，万里白云峰。","經論辞天去，香花入海逢。","鷺濤清梵徹，蜃閣化城重。","心到长安陌，交州後夜鐘。"]', '诗', 'shi', '', NULL, '供奉定法師歸安南 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2833e0a-d45e-4103-9604-e22a620a016b', '池上竹', '池上竹', '08b14256-c564-4489-be33-927205119c81', '唐', '["一叢嬋娟色，四面清冷波。","氣潤晚煙重，光閑秋露多。","翠筠入疎柳，清影拂圓荷。","歲晏琅玕實，心期有鳳過。"]', '["一叢嬋娟色，四面清冷波。","氣潤晚煙重，光闲秋露多。","翠筠入疎柳，清影拂圓荷。","歲晏琅玕實，心期有鳳過。"]', '诗', 'shi', '', NULL, '池上竹 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21bdc7ed-bb33-4021-a078-7e5aab4c44d1', '長安春遊', '长安春游', '08b14256-c564-4489-be33-927205119c81', '唐', '["鳳城春報曲江頭，上客年年是勝遊。","日暖雲山當廣陌，天清絲管在高樓。","蘢蔥樹色分僊閣，縹緲花香汎御溝。","桂壁朱門新邸第，漢家恩澤問酇侯。"]', '["鳳城春報曲江头，上客年年是勝游。","日暖云山當廣陌，天清絲管在高楼。","蘢蔥樹色分僊閣，縹緲花香汎御溝。","桂壁朱门新邸第，漢家恩澤问酇侯。"]', '诗', 'shi', '', NULL, '長安春遊 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ca57010-dc25-47bf-8811-a84c71023ddb', '送定法師歸蜀法師即紅樓院供奉廣宣上人兄弟', '送定法師归蜀法師即紅楼院供奉廣宣上人兄弟', '08b14256-c564-4489-be33-927205119c81', '唐', '["鳳城初日照紅樓，禁寺公卿識惠休。","詩引棣華沾一雨，經分貝葉向雙流。","孤猿學定前山夕，遠鴈傷離幾地秋。","空性碧雲無處所，約公曾許剡溪遊。"]', '["鳳城初日照紅楼，禁寺公卿識惠休。","诗引棣华沾一雨，經分貝葉向雙流。","孤猿学定前山夕，远鴈傷離幾地秋。","空性碧云無处所，約公曾許剡溪游。"]', '诗', 'shi', '', NULL, '送定法師歸蜀法師即紅樓院供奉廣宣上人兄弟 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c08602c-77e8-4f62-b04c-8312f8783443', '早朝', '早朝', '08b14256-c564-4489-be33-927205119c81', '唐', '["鐘聲清禁纔應徹，漏報仙闈儼已開。","雙闕薄煙籠菡萏，九成初日照蓬萊。","朝時但向丹墀拜，仗下方從碧殿回。","聖道逍遙更何事，願將巴曲贊康哉。"]', '["鐘声清禁纔應徹，漏報仙闈儼已开。","雙闕薄煙籠菡萏，九成初日照蓬萊。","朝时但向丹墀拜，仗下方從碧殿回。","聖道逍遙更何事，願將巴曲贊康哉。"]', '诗', 'shi', '', NULL, '早朝 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7637c62-e5ce-45cb-a092-a9b31da8fc3b', '贈張將軍', '贈張將軍', '08b14256-c564-4489-be33-927205119c81', '唐', '["關西諸將揖容光，獨立營門劒有霜。","知愛魯連歸海上，肯令王翦在頻陽。","天晴紅幟當山滿，日暮清笳入塞長。","年少功高人最羨，漢家壇樹月蒼蒼。"]', '["关西諸將揖容光，独立營门劒有霜。","知愛魯連归海上，肯令王翦在頻陽。","天晴紅幟當山满，日暮清笳入塞长。","年少功高人最羨，漢家壇樹月蒼蒼。"]', '诗', 'shi', '', NULL, '贈張將軍 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fea12b95-a957-43ee-9e8e-d5949c20b205', '和侯大夫秋原山觀征人回', '和侯大夫秋原山观征人回', '08b14256-c564-4489-be33-927205119c81', '唐', '["兩河戰罷萬方清，原上軍回識舊營。","立馬望雲秋塞靜，射鵰臨水晚天晴。","戍閑部伍分岐路，地遠家鄉寄斾旌。","聖代止戈資廟略，諸侯不復更長征。"]', '["兩河戰罷万方清，原上軍回識旧營。","立马望云秋塞静，射鵰臨水晚天晴。","戍闲部伍分岐路，地远家乡寄斾旌。","聖代止戈資廟略，諸侯不复更长征。"]', '诗', 'shi', '', NULL, '和侯大夫秋原山觀征人回 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8131ca14-2dba-4241-8bd1-89a1c91911e1', '送人過衛州', '送人過衛州', '08b14256-c564-4489-be33-927205119c81', '唐', '["憶昔征南府內遊，君家東閤最淹留。","縱橫聯句長侵曉，次第看花直到秋。","論舊舉杯先下淚，傷離臨水更登樓。","相思前路幾回首，滿眼青山過衛州。"]', '["憶昔征南府內游，君家东閤最淹留。","縱橫聯句长侵晓，次第看花直到秋。","論旧舉杯先下泪，傷離臨水更登楼。","相思前路幾回首，满眼青山過衛州。"]', '诗', 'shi', '', NULL, '送人過衛州 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f13eab4c-c322-4d11-9c66-5054847c1301', '寄中書同年舍人', '寄中书同年舍人', '08b14256-c564-4489-be33-927205119c81', '唐', '["晴明紫閣最高峰，仙掖開簾范彥龍。","五色天書詞煥爛，九華春殿語從客。","綵毫應染爐煙細，清珮仍含玉漏重。","二十年前同日喜，碧霄何路得相逢。"]', '["晴明紫閣最高峰，仙掖开簾范彥龙。","五色天书词煥爛，九华春殿語從客。","綵毫應染爐煙細，清珮仍含玉漏重。","二十年前同日喜，碧霄何路得相逢。"]', '诗', 'shi', '', NULL, '寄中書同年舍人 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('025d356a-a58e-4b6b-a8b0-85d8e541c99b', '酬于駙馬二首 一', '酬于駙马二首 一', '08b14256-c564-4489-be33-927205119c81', '唐', '["綺陌塵香曙色分，碧山如畫又逢君。","蛟藏秋月一片水，驥鎖晴空千尺雲。","戚里舊知何駙馬，詩家今得鮑參軍。","陽和本是煙霄曲，須向花間次第聞。"]', '["綺陌塵香曙色分，碧山如畫又逢君。","蛟藏秋月一片水，驥鎖晴空千尺云。","戚里旧知何駙马，诗家今得鲍參軍。","陽和本是煙霄曲，須向花间次第闻。"]', '诗', 'shi', '', NULL, '酬于駙馬二首 一 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e97554f5-b802-487a-97bd-22d16887ceb2', '酬于駙馬二首 二', '酬于駙马二首 二', '08b14256-c564-4489-be33-927205119c81', '唐', '["芳時碧落心應斷，今日清詞事不同。","瑤草秋殘仙圃在，綵雲天遠鳳樓空。","晴花煖送金羈影，涼葉寒生玉簟風。","長得聞詩歡自足，會看春露濕蘭叢。"]', '["芳时碧落心應斷，今日清词事不同。","瑤草秋殘仙圃在，綵云天远鳳楼空。","晴花煖送金羈影，涼葉寒生玉簟风。","长得闻诗歡自足，會看春露濕蘭叢。"]', '诗', 'shi', '', NULL, '酬于駙馬二首 二 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5b26daa-bc57-4760-9966-a50d6f5a7175', '將歸東都寄令狐舍人', '將归东都寄令狐舍人', '08b14256-c564-4489-be33-927205119c81', '唐', '["綠楊紅杏滿城春，一騎悠悠萬井塵。","岐路未關今日事，風光欲醉長年人。","閑過綺陌尋高寺，強對朱門謁近臣。","多病晚來還有策，雒陽山色舊相親。"]', '["綠楊紅杏满城春，一騎悠悠万井塵。","岐路未关今日事，风光欲醉长年人。","闲過綺陌尋高寺，強对朱门謁近臣。","多病晚来還有策，雒陽山色旧相親。"]', '诗', 'shi', '', NULL, '將歸東都寄令狐舍人 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0ee48d6-4af5-4bc8-87c0-cfec42caacc2', '寄江州白司馬', '寄江州白司马', '08b14256-c564-4489-be33-927205119c81', '唐', '["江州司馬平安否，惠遠東林住得無。","湓浦曾聞似衣帶，廬峰見說勝香爐。","題詩歲晏離鴻斷，望闕天遙病鶴孤。","莫謾拘牽雨花社，青雲依舊是前途。"]', '["江州司马平安否，惠远东林住得無。","湓浦曾闻似衣带，廬峰见说勝香爐。","題诗歲晏離鴻斷，望闕天遙病鹤孤。","莫謾拘牽雨花社，青云依旧是前途。"]', '诗', 'shi', '', NULL, '寄江州白司馬 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49af4682-5a7e-4f86-8035-471cc839d8f9', '薛司空自青州歸朝', '薛司空自青州归朝', '08b14256-c564-4489-be33-927205119c81', '唐', '["天眷君陳久（一作「舊」）在東，歸朝人看大司空。","黃河岸畔長無事，滄海東邊獨有功。","已變畏途成雅俗，仍過舊里揖秋風。","一門累葉凌煙閣，次第儀形漢上公。"]', '["天眷君陳久（一作「旧」）在东，归朝人看大司空。","黄河岸畔长無事，滄海东邊独有功。","已变畏途成雅俗，仍過旧里揖秋风。","一门累葉凌煙閣，次第儀形漢上公。"]', '诗', 'shi', '', NULL, '薛司空自青州歸朝 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8ed792c-b061-4e84-8d14-c3f3164128f3', '送章孝標校書歸杭州因寄白舍人', '送章孝標校书归杭州因寄白舍人', '08b14256-c564-4489-be33-927205119c81', '唐', '["曾過靈隱江邊寺，獨宿東樓看海門。","潮色銀河鋪碧落，日光金柱出紅盆。","不妨公事資高臥，無限詩情要細論。","若訪郡人徐孺子，應須騎馬到沙村。"]', '["曾過靈隐江邊寺，独宿东楼看海门。","潮色銀河鋪碧落，日光金柱出紅盆。","不妨公事資高臥，無限诗情要細論。","若訪郡人徐孺子，應須騎马到沙村。"]', '诗', 'shi', '', NULL, '送章孝標校書歸杭州因寄白舍人 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e85e47b-336d-4c32-a797-ddbff22177a2', '述舊紀勳太原寄李光顏侍中二首 一', '述旧紀勳太原寄李光顏侍中二首 一', '08b14256-c564-4489-be33-927205119c81', '唐', '["玉塞含悽見鴈行，北垣新詔拜龍驤。","弟兄間世真飛將，貔虎歸時似故鄉。","鼓角因風飄朔氣，旌旗映水發秋光。","河源收地心猶壯，笑向天西萬里霜。"]', '["玉塞含悽见鴈行，北垣新詔拜龙驤。","弟兄间世真飞將，貔虎归时似故乡。","鼓角因风飄朔氣，旌旗映水發秋光。","河源收地心猶壯，笑向天西万里霜。"]', '诗', 'shi', '', NULL, '述舊紀勳太原寄李光顏侍中二首 一 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c9acc43-e0e0-4509-94b9-2f877ea705e1', '述舊紀勳太原寄李光顏侍中二首 二', '述旧紀勳太原寄李光顏侍中二首 二', '08b14256-c564-4489-be33-927205119c81', '唐', '["倚天長劒截雲孤，報國縱橫見丈夫。","五載登壇真宰相，六重分閫正司徒。","曾聞轉戰平堅寇，共說題詩壓腐儒。","料敵知機在方寸，不勞心力講陰符。"]', '["倚天长劒截云孤，報国縱橫见丈夫。","五載登壇真宰相，六重分閫正司徒。","曾闻轉戰平堅寇，共说題诗壓腐儒。","料敵知機在方寸，不勞心力講陰符。"]', '诗', 'shi', '', NULL, '述舊紀勳太原寄李光顏侍中二首 二 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('473000b9-20f8-4dd5-a7c6-8943aa51e756', '酬盧員外', '酬盧員外', '08b14256-c564-4489-be33-927205119c81', '唐', '["謝傅旌旗控上游，盧郎罇俎借前籌。","舜城風土臨清廟，魏國山川在白樓。","雲寺當時接高步，水亭今日又同遊。","滿筵舊府笙歌在，獨有羊曇最淚流。"]', '["謝傅旌旗控上游，盧郎罇俎借前籌。","舜城风土臨清廟，魏国山川在白楼。","云寺當时接高步，水亭今日又同游。","满筵旧府笙歌在，独有羊曇最泪流。"]', '诗', 'shi', '', NULL, '酬盧員外 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e70f0a58-0ea9-4fba-ade5-57a4657f44e4', '古意贈王常侍', '古意贈王常侍', '08b14256-c564-4489-be33-927205119c81', '唐', '["繡戶紗窗北里深，香風暗動鳳凰簪。","組紃常在佳人手，刀尺空搖寒女心。","欲學齊謳逐雲管，還思楚練拂霜砧。","東家少婦當機織，應念無衣雪滿林。"]', '["繡戶紗窗北里深，香风暗动鳳凰簪。","組紃常在佳人手，刀尺空搖寒女心。","欲学齊謳逐云管，還思楚練拂霜砧。","东家少婦當機织，應念無衣雪满林。"]', '诗', 'shi', '', NULL, '古意贈王常侍 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e67dde25-ec74-4d61-91c9-451a7fbef56b', '送裴中丞出使', '送裴中丞出使', '08b14256-c564-4489-be33-927205119c81', '唐', '["一清淮甸假朝綱，金印初迎細柳黃。","辭闕天威和雨露，出關春色避風霜。","龍韜何必陳三略，虎旅由來肅萬方。","宣諭生靈真重任，回軒應問石渠郎。"]', '["一清淮甸假朝綱，金印初迎細柳黄。","辞闕天威和雨露，出关春色避风霜。","龙韜何必陳三略，虎旅由来肅万方。","宣諭生靈真重任，回軒應问石渠郎。"]', '诗', 'shi', '', NULL, '送裴中丞出使 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f273bbf4-e006-4910-96e3-9a4a039110ed', '送絳州盧使君', '送絳州盧使君', '08b14256-c564-4489-be33-927205119c81', '唐', '["應將清淨結心期，又共陽和到郡時。","絳老問年須算字，庾公逢月要題詩。","朱欄迢遰因高勝，粉堞清明欲下遲。","他日徴還作霖雨，不須求賽敬亭祠。"]', '["應將清淨結心期，又共陽和到郡时。","絳老问年須算字，庾公逢月要題诗。","朱欄迢遰因高勝，粉堞清明欲下遲。","他日徴還作霖雨，不須求賽敬亭祠。"]', '诗', 'shi', '', NULL, '送絳州盧使君 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('198fe56d-802d-4f47-ae39-6e99956200ea', '贈李傅', '贈李傅', '08b14256-c564-4489-be33-927205119c81', '唐', '["知因公望掩能文，誓激明誠在致君。","曾罷雙旌瞻白日，猶將一劒許黃雲。","搖牕竹色留僧語，入院松聲共鶴聞。","莫被此心生晚計，鎮南人憶杜將軍。"]', '["知因公望掩能文，誓激明誠在致君。","曾罷雙旌瞻白日，猶將一劒許黄云。","搖牕竹色留僧語，入院松声共鹤闻。","莫被此心生晚計，鎮南人憶杜將軍。"]', '诗', 'shi', '', NULL, '贈李傅 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('684f5ff0-0ef2-4639-ad16-ec08ca6e6209', '上裴中丞', '上裴中丞', '08b14256-c564-4489-be33-927205119c81', '唐', '["六年西掖弘湯誥，三捷東堂總漢科。","政引風霜成物色，語回天地到陽和。","清威更助朝端重，聖澤曾隨筆下多。","應笑白鬚揚執戟，可憐春日老如何。"]', '["六年西掖弘湯誥，三捷东堂總漢科。","政引风霜成物色，語回天地到陽和。","清威更助朝端重，聖澤曾隨笔下多。","應笑白鬚揚執戟，可怜春日老如何。"]', '诗', 'shi', '', NULL, '上裴中丞 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a1a7f0-df25-4c99-aa6e-9040cbb67964', '和人與人分惠賜冰', '和人與人分惠賜冰', '08b14256-c564-4489-be33-927205119c81', '唐', '["天水藏來玉墮空，先頒密署幾人同。","映盤皎潔非資月，披扇清涼不在風。","瑩質方從綸閣內，凝輝更向畫堂中。","麗詞珍貺難雙有，迢遰金輿殿角東。"]', '["天水藏来玉墮空，先頒密署幾人同。","映盤皎潔非資月，披扇清涼不在风。","瑩質方從綸閣內，凝輝更向畫堂中。","丽词珍貺难雙有，迢遰金輿殿角东。"]', '诗', 'shi', '', NULL, '和人與人分惠賜冰 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b6a59fe-a78a-4fd7-bbf3-d3c208deb63d', '觀打毬有作', '观打毬有作', '08b14256-c564-4489-be33-927205119c81', '唐', '["親掃毬場如砥平，龍驤驟馬曉光晴。","入門百拜瞻雄勢，動地三軍唱好聲。","玉勒回時霑赤汗，花鬉分處拂紅纓。","欲令四海氛煙靜，杖底纖塵不敢生。"]', '["親掃毬場如砥平，龙驤驟马晓光晴。","入门百拜瞻雄勢，动地三軍唱好声。","玉勒回时霑赤汗，花鬉分处拂紅纓。","欲令四海氛煙静，杖底纖塵不敢生。"]', '诗', 'shi', '', NULL, '觀打毬有作 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd926ae-08d4-436e-af8c-dbd3af3dba93', '早春即事呈劉員外', '早春即事呈劉員外', '08b14256-c564-4489-be33-927205119c81', '唐', '["明朝晴暖即相隨，肯信春光被雨欺。","且任文書堆案上，免令杯酒負花時。","馬蹄經歷須應徧，鶯語叮嚀已怪遲。","更待雜芳成豔錦，鄴中爭唱仲宣詩。"]', '["明朝晴暖即相隨，肯信春光被雨欺。","且任文书堆案上，免令杯酒負花时。","马蹄經歷須應徧，鶯語叮嚀已怪遲。","更待杂芳成豔錦，鄴中爭唱仲宣诗。"]', '诗', 'shi', '', NULL, '早春即事呈劉員外 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62105508-0128-49a3-b02d-8e0a68c7149b', '送司徒童子', '送司徒童子', '08b14256-c564-4489-be33-927205119c81', '唐', '["衛多君子魯多儒，七歲聞天笑舞雩。","光彩春風初轉蕙，性靈秋水不藏珠。","兩經在口知名小，百拜垂髫稟氣殊。","況復元侯旌爾善，桂林枝上得鵷雛。"]', '["衛多君子魯多儒，七歲闻天笑舞雩。","光彩春风初轉蕙，性靈秋水不藏珠。","兩經在口知名小，百拜垂髫稟氣殊。","況复元侯旌爾善，桂林枝上得鵷雛。"]', '诗', 'shi', '', NULL, '送司徒童子 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8293f49-0cba-47a8-9f1f-6e08a83ee973', '寄昭應王丞', '寄昭應王丞', '08b14256-c564-4489-be33-927205119c81', '唐', '["武皇金輅輾香塵，每歲朝元及此辰。","光動泉心初浴日，氣蒸山腹總成春。","謳歌已入雲韶曲，詞賦方歸侍從臣。","瑞靄朝朝猶望幸，天敎赤縣有詩人。"]', '["武皇金輅輾香塵，每歲朝元及此辰。","光动泉心初浴日，氣蒸山腹總成春。","謳歌已入云韶曲，词賦方归侍從臣。","瑞靄朝朝猶望幸，天敎赤縣有诗人。"]', '诗', 'shi', '', NULL, '寄昭應王丞 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffd9a717-6d20-447f-b45c-509bef3291e2', '酬崔博士', '酬崔博士', '08b14256-c564-4489-be33-927205119c81', '唐', '["自知頑叟更何能，唯學雕蟲謬見稱。","長被有情邀唱和，近來無力更祗承。","青松樹杪三千鶴，白玉壺中一片冰。","今日爲君書壁右，孤城莫怕世人憎。"]', '["自知頑叟更何能，唯学雕蟲謬见稱。","长被有情邀唱和，近来無力更祗承。","青松樹杪三千鹤，白玉壺中一片冰。","今日爲君书壁右，孤城莫怕世人憎。"]', '诗', 'shi', '', NULL, '酬崔博士 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('961c2d6b-321d-4dd6-9abb-ad9c507f6945', '酬裴舍人見寄', '酬裴舍人见寄', '08b14256-c564-4489-be33-927205119c81', '唐', '["誰道重遷是舊班，自將霄漢比鄉關。","二妃樓下宜臨水，五老祠西好看山。","再葺吾廬心已足，每來公府路常閑。","詩陪亞相逾三紀，石笥煙霞不共攀。"]', '["誰道重遷是旧班，自將霄漢比乡关。","二妃楼下宜臨水，五老祠西好看山。","再葺吾廬心已足，每来公府路常闲。","诗陪亞相逾三紀，石笥煙霞不共攀。"]', '诗', 'shi', '', NULL, '酬裴舍人見寄 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2e8b3a-7eda-4add-bb4a-c13a05e3035a', '和劉員外陪韓僕射野亭公宴', '和劉員外陪韓僕射野亭公宴', '08b14256-c564-4489-be33-927205119c81', '唐', '["好客風流玳瑁簪，重簷高幕曉沈沈。","綺筵霜重旌旗滿，玉帳天清絲管聲。","繁戲徒過魯儒目，衆歡方集漢郎心。","寒笳一曲嚴城暮，雲騎連嘶香外林。"]', '["好客风流玳瑁簪，重簷高幕晓沈沈。","綺筵霜重旌旗满，玉帳天清絲管声。","繁戲徒過魯儒目，衆歡方集漢郎心。","寒笳一曲嚴城暮，云騎連嘶香外林。"]', '诗', 'shi', '', NULL, '和劉員外陪韓僕射野亭公宴 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8ddc5ef-63e7-4857-b165-6372ec3f2852', '酬崔駙馬惠箋百張兼貽四韻', '酬崔駙马惠箋百張兼貽四韻', '08b14256-c564-4489-be33-927205119c81', '唐', '["百張雲樣亂花開，七字文頭豔錦回。","浮碧空從天上得，殷紅應自日邊來。","捧持價重凌雲葉，封裹香深笑海苔。","滿篋清光應照眼，欲題凡韻輒裴回。"]', '["百張云樣亂花开，七字文头豔錦回。","浮碧空從天上得，殷紅應自日邊来。","捧持價重凌云葉，封裹香深笑海苔。","满篋清光應照眼，欲題凡韻輒裴回。"]', '诗', 'shi', '', NULL, '酬崔駙馬惠箋百張兼貽四韻 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d41f5f-d0fa-43d3-8a90-0b254d1f9e99', '贈史開封', '贈史开封', '08b14256-c564-4489-be33-927205119c81', '唐', '["天低荒草誓師壇，鄧艾心知戰地寬。","鼓角逈臨霜野曙，旌旗高對雪峰寒。","五營向水紅塵起，一劒當風白日看。","曾從伏波征絕域，磧西蕃部怯金鞍。"]', '["天低荒草誓師壇，鄧艾心知戰地寬。","鼓角逈臨霜野曙，旌旗高对雪峰寒。","五營向水紅塵起，一劒當风白日看。","曾從伏波征絕域，磧西蕃部怯金鞍。"]', '诗', 'shi', '', NULL, '贈史開封 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8f41582-077a-4ded-892e-cacb96194359', '奉寄通州元九侍御', '奉寄通州元九侍御', '08b14256-c564-4489-be33-927205119c81', '唐', '["大明宮殿鬱蒼蒼，紫禁龍樓直署香。","九陌華軒爭道路，一枝寒玉任煙霜。","須聽瑞雪傳心語，莫被啼猨續淚行。","共說聖朝容直氣，期君新歲奉恩光。"]', '["大明宮殿鬱蒼蒼，紫禁龙楼直署香。","九陌华軒爭道路，一枝寒玉任煙霜。","須听瑞雪傳心語，莫被啼猨續泪行。","共说聖朝容直氣，期君新歲奉恩光。"]', '诗', 'shi', '', NULL, '奉寄通州元九侍御 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7843577-ded5-4519-a7b7-fd384d98ece4', '贈渾鉅中允', '贈渾鉅中允', '08b14256-c564-4489-be33-927205119c81', '唐', '["公子髫年四海聞，城南侍獵雪雰雰。","馬盤曠野弦開月，鴈落寒原箭在雲。","曾向天西穿虜陣，慣遊花下領儒羣。","一枝瓊萼朝光好，綵服飄飄從冠軍。"]', '["公子髫年四海闻，城南侍獵雪雰雰。","马盤曠野弦开月，鴈落寒原箭在云。","曾向天西穿虜陣，慣游花下領儒羣。","一枝瓊萼朝光好，綵服飄飄從冠軍。"]', '诗', 'shi', '', NULL, '贈渾鉅中允 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd2bb04-2396-431d-9eeb-84ed85ee615d', '重送胡大夫赴振武', '重送胡大夫赴振武', '08b14256-c564-4489-be33-927205119c81', '唐', '["向年擢桂儒生業，今日分茅聖主恩。","旌斾仍將過鄉路，軒車爭看出都門。","人間文武能雙捷，天下安危待一論。","布惠宣威大夫事，不妨詩思許琴尊。"]', '["向年擢桂儒生業，今日分茅聖主恩。","旌斾仍將過乡路，軒车爭看出都门。","人间文武能雙捷，天下安危待一論。","布惠宣威大夫事，不妨诗思許琴尊。"]', '诗', 'shi', '', NULL, '重送胡大夫赴振武 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efab7c09-c36f-4cbc-b10c-0ab2fd32dd22', '送陳判官罷舉赴江外', '送陳判官罷舉赴江外', '08b14256-c564-4489-be33-927205119c81', '唐', '["練思多時冰雪清，拂衣無語別書生。","莫將甲乙爲前累，不廢煙霄是此行。","定愛紅雲燃楚色，應看白雨打江聲。","心期玉帳親台位，魏勃因君說姓名。"]', '["練思多时冰雪清，拂衣無語別书生。","莫將甲乙爲前累，不廢煙霄是此行。","定愛紅云燃楚色，應看白雨打江声。","心期玉帳親台位，魏勃因君说姓名。"]', '诗', 'shi', '', NULL, '送陳判官罷舉赴江外 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8d11ac8-d2bc-40db-b959-fec9911df427', '奉和裴相公', '奉和裴相公', '08b14256-c564-4489-be33-927205119c81', '唐', '["竹寺題名一半空，衰榮三十六人中。","在生本要求知己，垂老應憐值相公。","敢望燮和回舊律，任應時節到春風。","若爲問得蒼蒼意，造化無言自是功。"]', '["竹寺題名一半空，衰榮三十六人中。","在生本要求知己，垂老應怜值相公。","敢望燮和回旧律，任應时節到春风。","若爲问得蒼蒼意，造化無言自是功。"]', '诗', 'shi', '', NULL, '奉和裴相公 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b548cc1-f164-4eee-a85e-e639d17a5333', '和大夫邊春呈長安親故', '和大夫邊春呈长安親故', '08b14256-c564-4489-be33-927205119c81', '唐', '["嚴城吹笛思寒梅，二月冰河一半開。","紫陌詩情依舊在，黑山弓力畏春來。","遊人曲岸看花發，走馬平沙獵雪回。","旌斾朝天不知晚，將星高處近三台。"]', '["嚴城吹笛思寒梅，二月冰河一半开。","紫陌诗情依旧在，黑山弓力畏春来。","游人曲岸看花發，走马平沙獵雪回。","旌斾朝天不知晚，將星高处近三台。"]', '诗', 'shi', '', NULL, '和大夫邊春呈長安親故 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3faddf1-cd7b-460f-87d3-e17fc2cc92d5', '張郎中段員外初直翰林報寄長句', '張郎中段員外初直翰林報寄长句', '08b14256-c564-4489-be33-927205119c81', '唐', '["秋空如練瑞雲明，天上人間莫問程。","丹鳳詞頭供二妙，金鑾殿角直三清。","方瞻北極臨星月，猶向南班滯姓名。","啓沃朝朝深禁裏，香爐煙外是公卿。"]', '["秋空如練瑞云明，天上人间莫问程。","丹鳳词头供二妙，金鑾殿角直三清。","方瞻北極臨星月，猶向南班滯姓名。","啓沃朝朝深禁裏，香爐煙外是公卿。"]', '诗', 'shi', '', NULL, '張郎中段員外初直翰林報寄長句 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1143a4c3-a712-42e6-a5b0-07d4d664809d', '奉酬端公春雪見寄', '奉酬端公春雪见寄', '08b14256-c564-4489-be33-927205119c81', '唐', '["造化多情狀物親，剪花鋪玉萬重新。","閑飄上路呈豐歲，狂舞中庭學醉春。","興逸何妨尋剡客，唱高還肯寄巴人。","遙知獨立芝蘭閣，滿眼清光壓俗塵。"]', '["造化多情狀物親，剪花鋪玉万重新。","闲飄上路呈豐歲，狂舞中庭学醉春。","兴逸何妨尋剡客，唱高還肯寄巴人。","遙知独立芝蘭閣，满眼清光壓俗塵。"]', '诗', 'shi', '', NULL, '奉酬端公春雪見寄 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dbcc618-65cb-4f0c-9325-590bcb99f022', '盧郎中拜陵遇雪蒙見召因寄', '盧郎中拜陵遇雪蒙见召因寄', '08b14256-c564-4489-be33-927205119c81', '唐', '["南宮使者有光輝，欲拜諸陵瑞雪飛。","蘋葉已修青玉薦，柳花仍拂赤車衣。","應同谷口尋春去，定似山陰帶月歸。","寒冷出郊猶未得，羨公將事看芳菲。"]', '["南宮使者有光輝，欲拜諸陵瑞雪飞。","蘋葉已修青玉薦，柳花仍拂赤车衣。","應同谷口尋春去，定似山陰带月归。","寒冷出郊猶未得，羨公將事看芳菲。"]', '诗', 'shi', '', NULL, '盧郎中拜陵遇雪蒙見召因寄 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62aa9125-a433-4f39-9c5a-85aee1be1b03', '冬夜陪丘侍御先輩聽崔校書彈琴', '冬夜陪丘侍御先輩听崔校书彈琴', '08b14256-c564-4489-be33-927205119c81', '唐', '["雪滿中庭月映林，謝家幽賞在瑤琴。","楚妃波浪天南遠，蔡女煙沙漠北深。","顧盼何曾因誤曲，殷勤終是感知音。","若將雅調開詩興，未抵丘遲一片心。"]', '["雪满中庭月映林，謝家幽賞在瑤琴。","楚妃波浪天南远，蔡女煙沙漠北深。","顧盼何曾因誤曲，殷勤終是感知音。","若將雅調开诗兴，未抵丘遲一片心。"]', '诗', 'shi', '', NULL, '冬夜陪丘侍御先輩聽崔校書彈琴 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cced284-9452-486d-9721-9bde4caa33c8', '元日含元殿下立仗丹鳳樓門下宣赦相公稱賀二首 一', '元日含元殿下立仗丹鳳楼门下宣赦相公稱賀二首 一', '08b14256-c564-4489-be33-927205119c81', '唐', '["天垂台耀掃欃槍，壽獻香山祝聖明。","丹鳳樓前歌九奏，金雞竿下鼓千聲。","衣冠南面薰風動，文字東方喜氣生。","從此登封資廟略，兩河連海一時清。"]', '["天垂台耀掃欃槍，壽獻香山祝聖明。","丹鳳楼前歌九奏，金雞竿下鼓千声。","衣冠南面薰风动，文字东方喜氣生。","從此登封資廟略，兩河連海一时清。"]', '诗', 'shi', '', NULL, '元日含元殿下立仗丹鳳樓門下宣赦相公稱賀二首 一 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fc66539-b184-47ee-8a8f-cc8beae12002', '元日含元殿下立仗丹鳳樓門下宣赦相公稱賀二首 二', '元日含元殿下立仗丹鳳楼门下宣赦相公稱賀二首 二', '08b14256-c564-4489-be33-927205119c81', '唐', '["臨軒啓扇似雲收，率土朝天劇水流。","瑞色含春當正殿，香煙捧日在高樓。","三朝氣蚤迎恩澤，萬歲聲長繞冕旒。","請問漢家功第一，麒麟閣上識酇侯。"]', '["臨軒啓扇似云收，率土朝天劇水流。","瑞色含春當正殿，香煙捧日在高楼。","三朝氣蚤迎恩澤，万歲声长繞冕旒。","請问漢家功第一，麒麟閣上識酇侯。"]', '诗', 'shi', '', NULL, '元日含元殿下立仗丹鳳樓門下宣赦相公稱賀二首 二 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7c59319-bb0e-4250-8a6d-4ce2dfb836cf', '元日觀朝', '元日观朝', '08b14256-c564-4489-be33-927205119c81', '唐', '["北極長尊報聖期，周家何用問元龜。","天顏入曙千官拜，元日迎春萬物知。","閶闔迴臨黃道正，衣裳高對碧山垂。","微臣願獻堯人祝，壽酒年年太液池。"]', '["北極长尊報聖期，周家何用问元龟。","天顏入曙千官拜，元日迎春万物知。","閶闔迴臨黄道正，衣裳高对碧山垂。","微臣願獻堯人祝，壽酒年年太液池。"]', '诗', 'shi', '', NULL, '元日觀朝 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c2fd9c3-7847-463c-902c-7a71028930aa', '題賈巡官林亭', '題賈巡官林亭', '08b14256-c564-4489-be33-927205119c81', '唐', '["白鳥閑棲亭樹枝，綠罇仍對菊花籬。","許詢本愛交禪侶，陳寔由來是好兒。","明月出雲秋館思，遠泉經雨夜牕知。","門前長者無虛轍，一片寒光動水池。"]', '["白鸟闲棲亭樹枝，綠罇仍对菊花籬。","許詢本愛交禪侶，陳寔由来是好兒。","明月出云秋館思，远泉經雨夜牕知。","门前长者無虛轍，一片寒光动水池。"]', '诗', 'shi', '', NULL, '題賈巡官林亭 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59f461d6-4cec-496f-8a52-22c12169b7b6', '和元員外題昇平里新齋', '和元員外題昇平里新斋', '08b14256-c564-4489-be33-927205119c81', '唐', '["自知休沐諸幽勝，遂肯高齋枕廣衢。","舊地已開新玉圃，春山仍展綠雲圖。","心源邀得閑詩證，肺氣宜將慢酒扶。","此外唯應任真宰，同塵敢是道門樞。"]', '["自知休沐諸幽勝，遂肯高斋枕廣衢。","旧地已开新玉圃，春山仍展綠云圖。","心源邀得闲诗證，肺氣宜將慢酒扶。","此外唯應任真宰，同塵敢是道门樞。"]', '诗', 'shi', '', NULL, '和元員外題昇平里新齋 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a831a090-6fc7-4424-b36e-8eaa1270bfde', '送澹公歸嵩山龍潭寺葬本師', '送澹公归嵩山龙潭寺葬本師', '08b14256-c564-4489-be33-927205119c81', '唐', '["野煙秋水蒼茫遠，禪境真機去住閑。","雙樹爲家思舊壑，千花成塔禮寒山。","洞宮曾向龍邊宿，雲徑應從鳥外還。","莫戀本師金骨地，空門無處復無關。"]', '["野煙秋水蒼茫远，禪境真機去住闲。","雙樹爲家思旧壑，千花成塔禮寒山。","洞宮曾向龙邊宿，云徑應從鸟外還。","莫戀本師金骨地，空门無处复無关。"]', '诗', 'shi', '', NULL, '送澹公歸嵩山龍潭寺葬本師 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d66952-9960-4122-afa2-67caf07c3494', '邵州陪王郎中宴', '邵州陪王郎中宴', '08b14256-c564-4489-be33-927205119c81', '唐', '["西塞無塵多玉筵，貔貅鴛鷺儼相連。","紅茵照水開罇俎，翠幕當雲發管弦。","歌態曉臨團扇靜，舞容春映薄衫妍。","魯儒縱使他時有，不似歡娛及少年。"]', '["西塞無塵多玉筵，貔貅鴛鷺儼相連。","紅茵照水开罇俎，翠幕當云發管弦。","歌態晓臨團扇静，舞容春映薄衫妍。","魯儒縱使他时有，不似歡娛及少年。"]', '诗', 'shi', '', NULL, '邵州陪王郎中宴 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e2f586b-9ef4-4672-af24-723a5ec87773', '和令狐舍人酬峰上人題山欄孤竹', '和令狐舍人酬峰上人題山欄孤竹', '08b14256-c564-4489-be33-927205119c81', '唐', '["滿院冰姿粉籜殘，一莖青翠近簾端。","離叢自欲親香火，抱節何妨共歲寒。","能讓繁聲任真籟，解將孤影對芳蘭。","范雲許訪西林寺，枝葉須和彩鳳看。"]', '["满院冰姿粉籜殘，一莖青翠近簾端。","離叢自欲親香火，抱節何妨共歲寒。","能讓繁声任真籟，解將孤影对芳蘭。","范云許訪西林寺，枝葉須和彩鳳看。"]', '诗', 'shi', '', NULL, '和令狐舍人酬峰上人題山欄孤竹 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('884c530d-c487-4626-81e2-514c065aff9a', '寄贈田倉曹灣', '寄贈田倉曹灣', '08b14256-c564-4489-be33-927205119c81', '唐', '["芳蘭媚庭除，灼灼紅英舒。","身爲陋巷客，門有絳轅車。","朝覽夷吾傳，暮習潁陽書。","眄雲高羽翼，待賈蘊璠璵。","纓弁雖云阻，音塵豈復疎。","若因風雨晦，應念寂寥居。"]', '["芳蘭媚庭除，灼灼紅英舒。","身爲陋巷客，门有絳轅车。","朝覽夷吾傳，暮習潁陽书。","眄云高羽翼，待賈蘊璠璵。","纓弁雖云阻，音塵豈复疎。","若因风雨晦，應念寂寥居。"]', '诗', 'shi', '', NULL, '寄贈田倉曹灣 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfef684c-5c4c-41ce-9d13-d87a676190ee', '上劉侍中', '上劉侍中', '08b14256-c564-4489-be33-927205119c81', '唐', '["命代生申甫，承家翊禹湯。","廟謨膺間氣，師律動清霜。","鐘鼎勳庸大，山河誡誓長。","英姿凌虎視，逸步壓龍驤。","道協陶鈞力，恩回日月光。","一言弘社稷，九命備珪璋。","政洽軍逾肅，仁敷物已康。","朱門重棨戟，丹詔半縑緗。","位總雲龍野，師臨涿鹿鄉。","射雕天更碧，吹角塞仍黃。","深入平夷路，橫行闢漢疆。","功垂貞石遠，名映色絲香。","斷磧瞻貔武，臨池識鳳凰。","舞腰凝綺榭，歌響拂彫梁。","杯淨傳鸚鵡，裘鮮照鷫鸘。","吟詩白羽扇，校獵綠沈槍。","風景佳人地，煙沙壯士場。","幕中邀謝鑒，麾下得周郎。","珠影含空徹，瓊枝映座芳。","王渾知武子，陳寔獎元方。","富貴春無限，歡娛夜未央。","管弦隨玉帳，尊俎奉金章。","俗理寧因勸，邊城詎假防。","軍容雄朔漠，公望冠巖廊。","分野鄰孤島，京坻溢萬廂。","曙華分碣石，秋色入衡陽。","城遠迷玄兔，川明辯白狼。","忠賢多感激，今古共蒼茫。","堤擁紅蕖豔，橋分翠柳行。","軒車紛自至，亭館鬱相當。","珍簟回煩暑，層軒引早涼。","聽琴知思靜，說劒覺神揚。","佳景燕臺上，清輝鄭驛傍。","鼓鼙喧北里，珪玉映東牀。","敢衒由之瑟，甘循賜也牆。","官微思假路，戰勝忝升堂。","欲奮三年翼，頻迴一夕腸。","消憂期酒聖，乘興任詩狂。","海內栽桃李，天涯荷稻粱。","昇沈門下意，誰道在蒼蒼。"]', '["命代生申甫，承家翊禹湯。","廟謨膺间氣，師律动清霜。","鐘鼎勳庸大，山河誡誓长。","英姿凌虎視，逸步壓龙驤。","道協陶鈞力，恩回日月光。","一言弘社稷，九命備珪璋。","政洽軍逾肅，仁敷物已康。","朱门重棨戟，丹詔半縑緗。","位總云龙野，師臨涿鹿乡。","射雕天更碧，吹角塞仍黄。","深入平夷路，橫行闢漢疆。","功垂貞石远，名映色絲香。","斷磧瞻貔武，臨池識鳳凰。","舞腰凝綺榭，歌响拂彫梁。","杯淨傳鸚鵡，裘鲜照鷫鸘。","吟诗白羽扇，校獵綠沈槍。","风景佳人地，煙沙壯士場。","幕中邀謝鑒，麾下得周郎。","珠影含空徹，瓊枝映座芳。","王渾知武子，陳寔獎元方。","富貴春無限，歡娛夜未央。","管弦隨玉帳，尊俎奉金章。","俗理寧因勸，邊城詎假防。","軍容雄朔漠，公望冠巖廊。","分野鄰孤島，京坻溢万廂。","曙华分碣石，秋色入衡陽。","城远迷玄兔，川明辯白狼。","忠賢多感激，今古共蒼茫。","堤擁紅蕖豔，橋分翠柳行。","軒车紛自至，亭館鬱相當。","珍簟回煩暑，層軒引早涼。","听琴知思静，说劒覺神揚。","佳景燕台上，清輝鄭驛傍。","鼓鼙喧北里，珪玉映东牀。","敢衒由之瑟，甘循賜也牆。","官微思假路，戰勝忝升堂。","欲奮三年翼，頻迴一夕腸。","消憂期酒聖，乘兴任诗狂。","海內栽桃李，天涯荷稻粱。","昇沈门下意，誰道在蒼蒼。"]', '诗', 'shi', '', NULL, '上劉侍中 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89086a0f-8cb5-4f91-91cb-de3b532e0439', '贈侯侍御', '贈侯侍御', '08b14256-c564-4489-be33-927205119c81', '唐', '["步逸辭羣迹，機真結遠心。","敦詩揚大雅，映古酌高音。","逃禍棲蝸舍，因醒解豸簪。","紫蘭秋露濕，黃鶴晚天陰。","舊業餘荒草，寒山出遠林。","月明多宿寺，世亂重悲琴。","霄漢時應在，詩書道未沈。","坐期閶闔霽，雲暖一開襟。"]', '["步逸辞羣迹，機真結远心。","敦诗揚大雅，映古酌高音。","逃禍棲蝸舍，因醒解豸簪。","紫蘭秋露濕，黄鹤晚天陰。","旧業餘荒草，寒山出远林。","月明多宿寺，世亂重悲琴。","霄漢时應在，诗书道未沈。","坐期閶闔霽，云暖一开襟。"]', '诗', 'shi', '', NULL, '贈侯侍御 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb063de-38ae-4189-b4e9-1d8ed3e7d75d', '懷德抒情寄上信州座主', '懷德抒情寄上信州座主', '08b14256-c564-4489-be33-927205119c81', '唐', '["五馬江天郡，諸生淚共垂。","讌餘明主德，恩在侍臣知。","悵望緘雙鯉，龍鍾假一枝。","玉峰遙寄夢，雲海暗傷離。","幢蓋全家去，琴書首路隨。","滄州值康樂，明月向元規。","鵷鳳終凌漢，蛟龍會出池。","蕙香因曙發，松色肯寒移。","舉世瞻風藻，當朝揖羽儀。","加餐門下意，溪水綠逶迤。"]', '["五马江天郡，諸生泪共垂。","讌餘明主德，恩在侍臣知。","悵望緘雙鯉，龙鍾假一枝。","玉峰遙寄梦，云海暗傷離。","幢蓋全家去，琴书首路隨。","滄州值康乐，明月向元規。","鵷鳳終凌漢，蛟龙會出池。","蕙香因曙發，松色肯寒移。","舉世瞻风藻，當朝揖羽儀。","加餐门下意，溪水綠逶迤。"]', '诗', 'shi', '', NULL, '懷德抒情寄上信州座主 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7075f90a-bd11-4c1a-b346-8b65e2b8bc20', '送杜郎中使君赴虔州', '送杜郎中使君赴虔州', '08b14256-c564-4489-be33-927205119c81', '唐', '["迢遰南康路，清輝得使君。","虎符秋領俗，鵷署早辭羣。","地遠仍連戍，城嚴本帶軍。","傍江低檻月，當嶺滿牕雲。","境勝閭閻間，天清水陸分。","和詩將惠政，頌述九衢聞。"]', '["迢遰南康路，清輝得使君。","虎符秋領俗，鵷署早辞羣。","地远仍連戍，城嚴本带軍。","傍江低檻月，當嶺满牕云。","境勝閭閻间，天清水陸分。","和诗將惠政，頌述九衢闻。"]', '诗', 'shi', '', NULL, '送杜郎中使君赴虔州 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dd4cb50-450f-4d79-a73f-2fb80f98e1c5', '別鶴詞送令狐校書之桂府', '別鹤词送令狐校书之桂府', '08b14256-c564-4489-be33-927205119c81', '唐', '["海鶴一爲別，高程方窅然。","影搖江漢路，思結瀟湘天。","皎然仰白日，真姿棲紫煙。","含情九霄際，顧侶五雲前。","遐心屬清都，淒響激朱弦。","超遙聞風雨，迢遰各山川。","東南信多水，會合當有年。","雌飛唳冥冥，此意何由傳。"]', '["海鹤一爲別，高程方窅然。","影搖江漢路，思結瀟湘天。","皎然仰白日，真姿棲紫煙。","含情九霄際，顧侶五云前。","遐心屬清都，淒响激朱弦。","超遙闻风雨，迢遰各山川。","东南信多水，會合當有年。","雌飞唳冥冥，此意何由傳。"]', '诗', 'shi', '', NULL, '別鶴詞送令狐校書之桂府 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde9c6ba-5144-40b7-a5c8-284a4ac67b80', '夏日裴尹員外西齋看花', '夏日裴尹員外西斋看花', '08b14256-c564-4489-be33-927205119c81', '唐', '["笑向東來客，看花枉在前。","始知清夏月，更勝豔陽天。","露濕呈妝汙，風吹畏火燃。","蔥蘢和葉盛，爛熳壓枝鮮。","紅彩當[鈴]閣，清香到玉筵。","蝶棲驚曙色，鶯語滯晴煙。","得地殊堪賞，過時倍覺妍。","芳菲遲最好，唯是謝家憐。"]', '["笑向东来客，看花枉在前。","始知清夏月，更勝豔陽天。","露濕呈妝汙，风吹畏火燃。","蔥蘢和葉盛，爛熳壓枝鲜。","紅彩當[鈴]閣，清香到玉筵。","蝶棲驚曙色，鶯語滯晴煙。","得地殊堪賞，過时倍覺妍。","芳菲遲最好，唯是謝家怜。"]', '诗', 'shi', '', NULL, '夏日裴尹員外西齋看花 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eba7eb3-5f7b-4790-9d19-7092da5806a4', '贈鄰家老將', '贈鄰家老將', '08b14256-c564-4489-be33-927205119c81', '唐', '["白首羽林郎，丁年戍朔方。","陰天瞻磧落，秋日渡遼陽。","大漠寒山黑，孤城夜月黃。","十年依蓐食，萬里帶金瘡。","拂雪陳師祭，衝風立敎場。","箭飛瓊羽合，旗動火雲張。","虎翼分營勢，魚鱗擁陣行。","誓心清塞色，鬬血雜沙光。","戰地晴輝薄，軍門曉氣長。","寇深爭暗襲，關逈勒春防。","身賤竟何訴，天高徒自傷。","功成封寵將，力盡到貧鄉。","雀老方悲海，鷹衰却念霜。","空餘孤劒在，開匣一霑裳。"]', '["白首羽林郎，丁年戍朔方。","陰天瞻磧落，秋日渡遼陽。","大漠寒山黑，孤城夜月黄。","十年依蓐食，万里带金瘡。","拂雪陳師祭，衝风立敎場。","箭飞瓊羽合，旗动火云張。","虎翼分營勢，鱼鱗擁陣行。","誓心清塞色，鬬血杂沙光。","戰地晴輝薄，軍门晓氣长。","寇深爭暗襲，关逈勒春防。","身賤竟何訴，天高徒自傷。","功成封寵將，力尽到貧乡。","雀老方悲海，鷹衰却念霜。","空餘孤劒在，开匣一霑裳。"]', '诗', 'shi', '', NULL, '贈鄰家老將 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('656213da-6880-4334-8d4f-889a846a229b', '和呂舍人喜張員外自北番回至境上先寄二十韻', '和呂舍人喜張員外自北番回至境上先寄二十韻', '08b14256-c564-4489-be33-927205119c81', '唐', '["割愛天文動，敦和國步安。","仙姿歸舊好，戎意結新歡。","並命瞻鵷鷺，同心揖蕙蘭。","玉簫臨祖帳，金牓引征鞍。","廣陌雙旌去，平沙萬里看。","海雲侵鬢起，邊月向眉殘。","突兀陰山迥，蒼茫朔野寬。","毳廬同甲帳，韋橐比琱盤。","義著親胡俗，儀全識漢官。","地鄰冰鼠淨，天映燭龍寒。","節異蘇卿執，弦殊蔡女彈。","磧分黃渺渺，塞極黑漫漫。","歡味羶腥列，徴聲佅僸攢。","歸期先鴈候，登路劇鵬搏。","上客離心遠，西宮草詔殫。","麗詞傳錦綺，珍價掩琅玕。","百兩開戎壘，千蹄入御欄。","瑞光麟閣上，喜氣鳳城端。","尚德曾辭劒，柔凶本舞干。","茫茫斗星北，威服古來難。"]', '["割愛天文动，敦和国步安。","仙姿归旧好，戎意結新歡。","並命瞻鵷鷺，同心揖蕙蘭。","玉簫臨祖帳，金牓引征鞍。","廣陌雙旌去，平沙万里看。","海云侵鬢起，邊月向眉殘。","突兀陰山迥，蒼茫朔野寬。","毳廬同甲帳，韋橐比琱盤。","義著親胡俗，儀全識漢官。","地鄰冰鼠淨，天映燭龙寒。","節異蘇卿執，弦殊蔡女彈。","磧分黄渺渺，塞極黑漫漫。","歡味羶腥列，徴声佅僸攢。","归期先鴈候，登路劇鵬搏。","上客離心远，西宮草詔殫。","丽词傳錦綺，珍價掩琅玕。","百兩开戎壘，千蹄入御欄。","瑞光麟閣上，喜氣鳳城端。","尚德曾辞劒，柔凶本舞干。","茫茫斗星北，威服古来难。"]', '诗', 'shi', '', NULL, '和呂舍人喜張員外自北番回至境上先寄二十韻 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5bc9791-07cd-4386-8028-4101ad7412dd', '春日奉獻聖壽無疆詞十首 一', '春日奉獻聖壽無疆词十首 一', '08b14256-c564-4489-be33-927205119c81', '唐', '["文物京華盛，謳歌國步康。","瑤池供壽酒，銀漢麗宸章。","靈雨含雙闕，雷霆肅萬方。","代推仙祚遠，春共聖恩長。","鳳扆臨花暖，龍罏旁日香。","遙知千萬歲，天意奉君王。"]', '["文物京华盛，謳歌国步康。","瑤池供壽酒，銀漢丽宸章。","靈雨含雙闕，雷霆肅万方。","代推仙祚远，春共聖恩长。","鳳扆臨花暖，龙罏旁日香。","遙知千万歲，天意奉君王。"]', '诗', 'shi', '', NULL, '春日奉獻聖壽無疆詞十首 一 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e27f9d-3fb9-4963-b2ec-53f33c617bee', '春日奉獻聖壽無疆詞十首 二', '春日奉獻聖壽無疆词十首 二', '08b14256-c564-4489-be33-927205119c81', '唐', '["鴛鷺彤庭際，軒車綺陌前。","九城多好色，萬井半祥煙。","人醉逢堯酒，鶯歌荅舜弦。","花明御溝水，香暖禁城天。","賜宴文逾盛，徴歌物更妍。","無窮豔陽月，長照太平年。"]', '["鴛鷺彤庭際，軒车綺陌前。","九城多好色，万井半祥煙。","人醉逢堯酒，鶯歌荅舜弦。","花明御溝水，香暖禁城天。","賜宴文逾盛，徴歌物更妍。","無窮豔陽月，长照太平年。"]', '诗', 'shi', '', NULL, '春日奉獻聖壽無疆詞十首 二 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('938159b0-ec3c-45ca-97f4-1d2868ec9b52', '春日奉獻聖壽無疆詞十首 三', '春日奉獻聖壽無疆词十首 三', '08b14256-c564-4489-be33-927205119c81', '唐', '["雲陛臨黃道，天門在碧虛。","大明含睿藻，元氣抱宸居。","戈偃征苗後，詩傳宴鎬初。","年華富仙苑，時哲滿公車。","化入絪緼大，恩垂渙汗餘。","悠然萬方靜，風俗揖華胥。"]', '["云陛臨黄道，天门在碧虛。","大明含睿藻，元氣抱宸居。","戈偃征苗後，诗傳宴鎬初。","年华富仙苑，时哲满公车。","化入絪緼大，恩垂渙汗餘。","悠然万方静，风俗揖华胥。"]', '诗', 'shi', '', NULL, '春日奉獻聖壽無疆詞十首 三 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2de91cae-cb48-44e4-9f7f-7559c2a47419', '春日奉獻聖壽無疆詞十首 四', '春日奉獻聖壽無疆词十首 四', '08b14256-c564-4489-be33-927205119c81', '唐', '["玉漏飄青璅，金鋪麗紫宸。","雲山九門曙，天地一家春。","瑞靄方呈賞，暄風本配仁。","巖廊開鳳翼，水殿壓鼇身。","文雅逢明代，歡娛及賤臣。","年年未央闕，恩共物華新。"]', '["玉漏飄青璅，金鋪丽紫宸。","云山九门曙，天地一家春。","瑞靄方呈賞，暄风本配仁。","巖廊开鳳翼，水殿壓鼇身。","文雅逢明代，歡娛及賤臣。","年年未央闕，恩共物华新。"]', '诗', 'shi', '', NULL, '春日奉獻聖壽無疆詞十首 四 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d22a64c-c978-4d39-b00b-f9998d2bdc37', '春日奉獻聖壽無疆詞十首 五', '春日奉獻聖壽無疆词十首 五', '08b14256-c564-4489-be33-927205119c81', '唐', '["垂拱乾坤正，歡心品類同。","紫煙含北極，玄澤付東風。","珠綴留晴景，金莖直曉空。","發生資盛德，交泰讓全功。","間氣登三事，祥光啓四聰。","遐荒似川水，天外亦朝宗。"]', '["垂拱乾坤正，歡心品類同。","紫煙含北極，玄澤付东风。","珠綴留晴景，金莖直晓空。","發生資盛德，交泰讓全功。","间氣登三事，祥光啓四聰。","遐荒似川水，天外亦朝宗。"]', '诗', 'shi', '', NULL, '春日奉獻聖壽無疆詞十首 五 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36356bd0-5a81-457f-ba21-89aaabe9190a', '春日奉獻聖壽無疆詞十首 六', '春日奉獻聖壽無疆词十首 六', '08b14256-c564-4489-be33-927205119c81', '唐', '["代是文明晝，春當宴喜時。","罏煙添柳重，宮漏出花遲。","漢典方寬律，周官正採詩。","碧宵傳鳳吹，紅旭在龍旗。","造化膺神契，陽和沃聖思。","無因隨百獸，率舞奉丹墀。"]', '["代是文明晝，春當宴喜时。","罏煙添柳重，宮漏出花遲。","漢典方寬律，周官正採诗。","碧宵傳鳳吹，紅旭在龙旗。","造化膺神契，陽和沃聖思。","無因隨百獸，率舞奉丹墀。"]', '诗', 'shi', '', NULL, '春日奉獻聖壽無疆詞十首 六 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee05d7f0-55b0-446d-8624-13ac06f5e860', '春日奉獻聖壽無疆詞十首 七', '春日奉獻聖壽無疆词十首 七', '08b14256-c564-4489-be33-927205119c81', '唐', '["睿德符玄化，芳情翊太和。","日輪皇鑒遠，天仗聖朝多。","曙色含金牓，晴光轉玉珂。","中宮陳廣樂，元老進賡歌。","蓮葉看龜上，桐花識鳳過。","小臣空擊壤，滄海是恩波。"]', '["睿德符玄化，芳情翊太和。","日輪皇鑒远，天仗聖朝多。","曙色含金牓，晴光轉玉珂。","中宮陳廣乐，元老進賡歌。","蓮葉看龟上，桐花識鳳過。","小臣空擊壤，滄海是恩波。"]', '诗', 'shi', '', NULL, '春日奉獻聖壽無疆詞十首 七 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02148c8b-5445-4c35-bf56-7787ccec972c', '春日奉獻聖壽無疆詞十首 八', '春日奉獻聖壽無疆词十首 八', '08b14256-c564-4489-be33-927205119c81', '唐', '["物象朝高殿，簪裾溢上京。","春當九衢好，天向萬方明。","樂報簫韶發，杯看沆瀣生。","芙蓉丹闕暖，楊柳玉樓晴。","閶闔開中禁，衣裳儼太清。","南山同聖壽，長對鳳皇城。"]', '["物象朝高殿，簪裾溢上京。","春當九衢好，天向万方明。","乐報簫韶發，杯看沆瀣生。","芙蓉丹闕暖，楊柳玉楼晴。","閶闔开中禁，衣裳儼太清。","南山同聖壽，长对鳳皇城。"]', '诗', 'shi', '', NULL, '春日奉獻聖壽無疆詞十首 八 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('668e1376-fc01-490e-ab20-09b81e663792', '春日奉獻聖壽無疆詞十首 九', '春日奉獻聖壽無疆词十首 九', '08b14256-c564-4489-be33-927205119c81', '唐', '["日上蒼龍闕，香含紫禁林。","晴光五雲疊，春色九重深。","賞叶元和德，文垂雅頌音。","景雲隨御輦，顥氣在宸襟。","永保無疆壽，長懷不戰心。","聖朝多慶賜，瓊樹粉牆陰。"]', '["日上蒼龙闕，香含紫禁林。","晴光五云叠，春色九重深。","賞叶元和德，文垂雅頌音。","景云隨御輦，顥氣在宸襟。","永保無疆壽，长懷不戰心。","聖朝多慶賜，瓊樹粉牆陰。"]', '诗', 'shi', '', NULL, '春日奉獻聖壽無疆詞十首 九 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeeeeb98-2769-44bd-82b7-0efe63346c5c', '春日奉獻聖壽無疆詞十首 十', '春日奉獻聖壽無疆词十首 十', '08b14256-c564-4489-be33-927205119c81', '唐', '["化洽生成遂，功宣動植知。","瑞凝三秀草，春入萬年枝。","鳳掖嘉言進，鴛行喜氣隨。","仗臨丹地近，衣對碧山垂。","渥澤方柔遠，聰明本聽卑。","願同東觀士，長對漢威儀。"]', '["化洽生成遂，功宣动植知。","瑞凝三秀草，春入万年枝。","鳳掖嘉言進，鴛行喜氣隨。","仗臨丹地近，衣对碧山垂。","渥澤方柔远，聰明本听卑。","願同东观士，长对漢威儀。"]', '诗', 'shi', '', NULL, '春日奉獻聖壽無疆詞十首 十 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa239c0f-618e-4907-bb00-c1bae5253bc5', '銜魚翠鳥', '銜鱼翠鸟', '08b14256-c564-4489-be33-927205119c81', '唐', '["有意蓮葉間，瞥然下高樹。","擘破得全魚，一點翠光去。"]', '["有意蓮葉间，瞥然下高樹。","擘破得全鱼，一点翠光去。"]', '诗', 'shi', '', NULL, '銜魚翠鳥 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a5a1280-f6fe-4ef2-ab16-477a76e79235', '和鄭相公尋宣上人不遇', '和鄭相公尋宣上人不遇', '08b14256-c564-4489-be33-927205119c81', '唐', '["方尋蓮境去，又值竹房空。","幾韻飄寒玉，餘清不在風。"]', '["方尋蓮境去，又值竹房空。","幾韻飄寒玉，餘清不在风。"]', '诗', 'shi', '', NULL, '和鄭相公尋宣上人不遇 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2acc5a00-860e-4556-b57c-c1067baaf226', '題范陽金臺驛', '題范陽金台驛', '08b14256-c564-4489-be33-927205119c81', '唐', '["六國唯求客，千金遂築臺。","若令逢聖代，憔悴郭生回。"]', '["六国唯求客，千金遂築台。","若令逢聖代，憔悴郭生回。"]', '诗', 'shi', '', NULL, '題范陽金臺驛 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6661c096-e1ec-4f32-837f-1083ff079269', '寄薛侍御', '寄薛侍御', '08b14256-c564-4489-be33-927205119c81', '唐', '["世上無窮事，生涯莫廢詩。","何曾好風月，不是憶君時。"]', '["世上無窮事，生涯莫廢诗。","何曾好风月，不是憶君时。"]', '诗', 'shi', '', NULL, '寄薛侍御 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf1004cf-3917-4820-9997-4a561ca0231f', '賦得灞岸柳留辭鄭員外', '賦得灞岸柳留辞鄭員外', '08b14256-c564-4489-be33-927205119c81', '唐', '["楊柳含煙灞岸春，年年攀折爲行人。","好風儻借低枝便，莫遣青絲掃路塵。"]', '["楊柳含煙灞岸春，年年攀折爲行人。","好风儻借低枝便，莫遣青絲掃路塵。"]', '诗', 'shi', '', NULL, '賦得灞岸柳留辭鄭員外 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e304a48f-1dae-47df-835b-ca5067182979', '折楊柳', '折楊柳', '08b14256-c564-4489-be33-927205119c81', '唐', '["水邊楊柳麴塵絲，立馬煩君折一枝。","惟有春風最相惜，殷勤更向手中吹。"]', '["水邊楊柳麴塵絲，立马煩君折一枝。","惟有春风最相惜，殷勤更向手中吹。"]', '诗', 'shi', '', NULL, '折楊柳 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('274b344d-ab48-4980-bd2a-525fe00dda88', '雪中聽箏', '雪中听箏', '08b14256-c564-4489-be33-927205119c81', '唐', '["玉柱泠泠對寒雪，清商怨徴聲何切。","誰憐楚客向隅時，一片愁心與弦絕。"]', '["玉柱泠泠对寒雪，清商怨徴声何切。","誰怜楚客向隅时，一片愁心與弦絕。"]', '诗', 'shi', '', NULL, '雪中聽箏 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2835b1b4-eb6e-4f3e-863e-53eec479943a', '盧龍塞行送韋掌記二首 一', '盧龙塞行送韋掌記二首 一', '08b14256-c564-4489-be33-927205119c81', '唐', '["雨雪粉粉黑水外。","行人共指盧龍塞，萬里飛沙壓鼓鼙。","三軍殺氣凝旌斾。"]', '["雨雪粉粉黑水外。","行人共指盧龙塞，万里飞沙壓鼓鼙。","三軍殺氣凝旌斾。"]', '诗', 'shi', '', NULL, '盧龍塞行送韋掌記二首 一 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7a7d5b1-5027-499d-9dd2-324fbd10a08a', '盧龍塞行送韋掌記二首 二', '盧龙塞行送韋掌記二首 二', '08b14256-c564-4489-be33-927205119c81', '唐', '["陳琳書記本翩翩，料敵能兵奪酒泉。","聖主好文兼好武，封侯莫比漢皇年。"]', '["陳琳书記本翩翩，料敵能兵奪酒泉。","聖主好文兼好武，封侯莫比漢皇年。"]', '诗', 'shi', '', NULL, '盧龍塞行送韋掌記二首 二 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ab2021b-5249-46d6-9bc9-1b1d65ed1283', '題五老峰下費君書院', '題五老峰下費君书院', '08b14256-c564-4489-be33-927205119c81', '唐', '["解向花間栽碧松，門前不負老人峰。","已將心事隨身隱，認得溪雲第幾重。"]', '["解向花间栽碧松，门前不負老人峰。","已將心事隨身隐，認得溪云第幾重。"]', '诗', 'shi', '', NULL, '題五老峰下費君書院 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e37713ed-c386-4d3e-80c0-b64cc30fc014', '僧院聽琴', '僧院听琴', '08b14256-c564-4489-be33-927205119c81', '唐', '["禪思何妨在玉琴，真僧不見聽時心。","離聲怨調秋堂夕，雲向蒼梧湘水深。"]', '["禪思何妨在玉琴，真僧不见听时心。","離声怨調秋堂夕，云向蒼梧湘水深。"]', '诗', 'shi', '', NULL, '僧院聽琴 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f07c371-ee22-44c7-9c3a-9afa1bb028bf', '和武相公春曉聞鶯', '和武相公春晓闻鶯', '08b14256-c564-4489-be33-927205119c81', '唐', '["語恨飛遲天欲明，殷勤似訴有餘情。","仁風已及芳菲節，猶向花溪鳴幾聲。"]', '["語恨飞遲天欲明，殷勤似訴有餘情。","仁风已及芳菲節，猶向花溪鳴幾声。"]', '诗', 'shi', '', NULL, '和武相公春曉聞鶯 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('579c6c7f-d7c9-4926-9fa1-bec76cbd30d8', '唐昌觀玉蘂花', '唐昌观玉蘂花', '08b14256-c564-4489-be33-927205119c81', '唐', '["晴空素豔照霞新，香灑天風不到塵。","持贈昔聞將白雪，蘂珠宮上玉花春。"]', '["晴空素豔照霞新，香灑天风不到塵。","持贈昔闻將白雪，蘂珠宮上玉花春。"]', '诗', 'shi', '', NULL, '唐昌觀玉蘂花 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e132d470-4f32-4fcb-b4d8-2cd75f95ae17', '山中主人', '山中主人', '08b14256-c564-4489-be33-927205119c81', '唐', '["十里青山有一家，翠屏深處更添霞。","若爲說得溪中事，錦石和煙四面花。"]', '["十里青山有一家，翠屏深处更添霞。","若爲说得溪中事，錦石和煙四面花。"]', '诗', 'shi', '', NULL, '山中主人 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec62cc0-90c2-4aa3-9f82-391697829fd6', '太原贈李屬侍御', '太原贈李屬侍御', '08b14256-c564-4489-be33-927205119c81', '唐', '["路入桑乾塞鴈飛，棗郎年少有光輝。","春風走馬三千里，不廢看花君繡衣。"]', '["路入桑乾塞鴈飞，棗郎年少有光輝。","春风走马三千里，不廢看花君繡衣。"]', '诗', 'shi', '', NULL, '太原贈李屬侍御 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3247080d-bd0e-4e72-8419-1b94416972cc', '崔娘詩', '崔娘诗', '08b14256-c564-4489-be33-927205119c81', '唐', '["清潤潘郎玉不如，中庭蕙草雪消初。","風流才子多春思，腸斷蕭娘一紙書。"]', '["清潤潘郎玉不如，中庭蕙草雪消初。","风流才子多春思，腸斷蕭娘一紙书。"]', '诗', 'shi', '', NULL, '崔娘詩 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8803af85-ca60-49fd-a3d6-2e9154ff885c', '題雲師山房', '題云師山房', '08b14256-c564-4489-be33-927205119c81', '唐', '["雲公蘭若深山裏，月明松殿微風起。","試問空門清淨心，蓮花不著秋潭水。"]', '["云公蘭若深山裏，月明松殿微风起。","試问空门清淨心，蓮花不著秋潭水。"]', '诗', 'shi', '', NULL, '題雲師山房 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15cb1b7c-d295-49e3-a1a8-e596d5add553', '城東早春', '城东早春', '08b14256-c564-4489-be33-927205119c81', '唐', '["詩家清景在新春，綠柳纔黃半未勻。","若待上林花似錦，出門俱是看花人。"]', '["诗家清景在新春，綠柳纔黄半未勻。","若待上林花似錦，出门俱是看花人。"]', '诗', 'shi', '', NULL, '城東早春 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('704bd164-4532-4515-8864-ec2233553d87', '秋日登亭贈薛侍御', '秋日登亭贈薛侍御', '08b14256-c564-4489-be33-927205119c81', '唐', '["潦倒從軍何取益，東西走馬暫同遊。","梁王舊客皆能賦，今日因何獨怨秋。"]', '["潦倒從軍何取益，东西走马暫同游。","梁王旧客皆能賦，今日因何独怨秋。"]', '诗', 'shi', '', NULL, '秋日登亭贈薛侍御 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d01527bb-853e-44cc-9676-62b63e635774', '石水詞二首 一', '石水词二首 一', '08b14256-c564-4489-be33-927205119c81', '唐', '["銀罌深鏁貯清光，無限來人不得嘗。","知共金丹爭氣力，一杯全勝五雲漿。"]', '["銀罌深鏁貯清光，無限来人不得嘗。","知共金丹爭氣力，一杯全勝五云漿。"]', '诗', 'shi', '', NULL, '石水詞二首 一 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb271943-c601-4207-8b5a-c3ac170c1569', '石水詞二首 二', '石水词二首 二', '08b14256-c564-4489-be33-927205119c81', '唐', '["山叟和雲斸翠屏，煎時分日檢仙經。","天人持此扶衰病，勝得瑤池水一瓶。"]', '["山叟和云斸翠屏，煎时分日檢仙經。","天人持此扶衰病，勝得瑤池水一瓶。"]', '诗', 'shi', '', NULL, '石水詞二首 二 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8db7a58-9ef1-40fa-ac91-fea395888ba1', '荅振武李逢吉判官', '荅振武李逢吉判官', '08b14256-c564-4489-be33-927205119c81', '唐', '["近來時輩都無興，把酒皆言肺病同。","唯有單于李評事，不將華髮負春風。"]', '["近来时輩都無兴，把酒皆言肺病同。","唯有單于李評事，不將华髮負春风。"]', '诗', 'shi', '', NULL, '荅振武李逢吉判官 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a640ca36-8003-477d-baf9-1e306c257a20', '宮燕詞', '宮燕词', '08b14256-c564-4489-be33-927205119c81', '唐', '["毛衣似錦語如弦，日煖爭高綺陌天。","幾處野花留不得，雙雙飛向御爐前。"]', '["毛衣似錦語如弦，日煖爭高綺陌天。","幾处野花留不得，雙雙飞向御爐前。"]', '诗', 'shi', '', NULL, '宮燕詞 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('172c8af8-df46-4fe3-93fa-f6aacfc8a355', '贈崔駙馬', '贈崔駙马', '08b14256-c564-4489-be33-927205119c81', '唐', '["百尺梧桐畫閣齊，簫聲落處翠雲低。","平陽不惜黃金埒，細雨花驄踏作泥。"]', '["百尺梧桐畫閣齊，簫声落处翠云低。","平陽不惜黄金埒，細雨花驄踏作泥。"]', '诗', 'shi', '', NULL, '贈崔駙馬 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c50fb26-2ba6-46ba-9cef-a5248f262832', '聽李憑彈箜篌二首 一', '听李憑彈箜篌二首 一', '08b14256-c564-4489-be33-927205119c81', '唐', '["聽奏繁弦玉殿清，風傳曲度禁林明。","君王聽樂棃園煖，翻到雲門第幾聲。"]', '["听奏繁弦玉殿清，风傳曲度禁林明。","君王听乐棃园煖，翻到云门第幾声。"]', '诗', 'shi', '', NULL, '聽李憑彈箜篌二首 一 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e2b526-43e6-4cf6-8f4d-2124b5583bac', '聽李憑彈箜篌二首 二', '听李憑彈箜篌二首 二', '08b14256-c564-4489-be33-927205119c81', '唐', '["花咽嬌鶯玉漱泉，名高半在御筵前。","漢王欲助人間樂，從遣新聲墜九天。"]', '["花咽嬌鶯玉漱泉，名高半在御筵前。","漢王欲助人间乐，從遣新声墜九天。"]', '诗', 'shi', '', NULL, '聽李憑彈箜篌二首 二 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a76e6729-3841-4964-a0c5-dfe57469922e', '臨水看花', '臨水看花', '08b14256-c564-4489-be33-927205119c81', '唐', '["一樹紅花暎綠波，晴明騎馬好經過。","今朝幾許風吹落，聞道蕭郎最惜多。"]', '["一樹紅花暎綠波，晴明騎马好經過。","今朝幾許风吹落，闻道蕭郎最惜多。"]', '诗', 'shi', '', NULL, '臨水看花 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc77b7b9-f1ae-4a47-9a43-1d72471a1c10', '觀妓人入道二首 一', '观妓人入道二首 一', '08b14256-c564-4489-be33-927205119c81', '唐', '["荀令歌鐘北里亭，翠娥紅粉敞雲屏。","舞衣施盡餘香在，今日花前學誦經。"]', '["荀令歌鐘北里亭，翠娥紅粉敞云屏。","舞衣施尽餘香在，今日花前学誦經。"]', '诗', 'shi', '', NULL, '觀妓人入道二首 一 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('794028d7-8844-447d-9d0d-f5d14ccf06a4', '觀妓人入道二首 二', '观妓人入道二首 二', '08b14256-c564-4489-be33-927205119c81', '唐', '["碧玉芳年事冠軍，清歌空得隔花聞。","春來削髮芙蓉寺，蟬鬢臨風墮綠雲。"]', '["碧玉芳年事冠軍，清歌空得隔花闻。","春来削髮芙蓉寺，蟬鬢臨风墮綠云。"]', '诗', 'shi', '', NULL, '觀妓人入道二首 二 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac2180be-799b-4116-b6f8-6d0501572a38', '方城驛逢孟侍御', '方城驛逢孟侍御', '08b14256-c564-4489-be33-927205119c81', '唐', '["走馬溫湯直隼飛，相逢矍鑠理征衣。","軍中得力兒男事，入驛從容見落暉。"]', '["走马溫湯直隼飞，相逢矍鑠理征衣。","軍中得力兒男事，入驛從容见落暉。"]', '诗', 'shi', '', NULL, '方城驛逢孟侍御 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d55ccd0b-3c31-4426-a9e4-d1af082bd642', '題清涼寺', '題清涼寺', '08b14256-c564-4489-be33-927205119c81', '唐', '["憑檻霏微松樹煙，陶潛曾用道林錢。","一聲寒磬空心曉，花雨知從第幾天。"]', '["憑檻霏微松樹煙，陶潛曾用道林錢。","一声寒磬空心晓，花雨知從第幾天。"]', '诗', 'shi', '', NULL, '題清涼寺 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa9bde41-de31-4a73-8589-c923ae74ed10', '酬令狐舍人', '酬令狐舍人', '08b14256-c564-4489-be33-927205119c81', '唐', '["曉禁蒼蒼換直還，暫低鸞翼向人間。","亦知受業公門事，數仞丘牆不見山。"]', '["晓禁蒼蒼換直還，暫低鸾翼向人间。","亦知受業公门事，數仞丘牆不见山。"]', '诗', 'shi', '', NULL, '酬令狐舍人 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36c04e97-8fb5-42bc-b123-fd4aa108f884', '和令狐郎中', '和令狐郎中', '08b14256-c564-4489-be33-927205119c81', '唐', '["題詩一代占清機，秉筆三年直紫微。","自稟道情齠齓異，不同蘧玉學知非。"]', '["題诗一代占清機，秉笔三年直紫微。","自稟道情齠齓異，不同蘧玉学知非。"]', '诗', 'shi', '', NULL, '和令狐郎中 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bd3f70d-8d74-4f43-b562-60e42970e500', '美人春怨', '美人春怨', '08b14256-c564-4489-be33-927205119c81', '唐', '["妾家巫峽陽，羅幌寢蘭堂。","曉日臨窗久，春風引夢長。","落釵仍挂鬢，微汗欲銷黃。","縱便朦朧覺，魂猶逐楚王。"]', '["妾家巫峽陽，羅幌寢蘭堂。","晓日臨窗久，春风引梦长。","落釵仍挂鬢，微汗欲銷黄。","縱便朦朧覺，魂猶逐楚王。"]', '诗', 'shi', '', NULL, '美人春怨 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b2ae326-c8b4-4224-8cc2-11beebbd941b', '豔女詞', '豔女词', '08b14256-c564-4489-be33-927205119c81', '唐', '["露井桃花發，雙雙燕並飛。","美人姿態裏，春色上羅衣。","自愛頻開鏡，時羞欲掩扉。","心知行路客，遙惹五香歸。"]', '["露井桃花發，雙雙燕並飞。","美人姿態裏，春色上羅衣。","自愛頻开镜，时羞欲掩扉。","心知行路客，遙惹五香归。"]', '诗', 'shi', '', NULL, '豔女詞 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5e0c4a8-2946-45c7-96ac-3a99370a9b55', '名姝詠', '名姝詠', '08b14256-c564-4489-be33-927205119c81', '唐', '["阿嬌年未多，體弱性能和。","怕重愁拈鏡，憐輕喜曳羅。","臨津雙洛浦，對月兩嫦娥。","獨有荆王殿，時時暮雨過。"]', '["阿嬌年未多，體弱性能和。","怕重愁拈镜，怜轻喜曳羅。","臨津雙洛浦，对月兩嫦娥。","独有荆王殿，时时暮雨過。"]', '诗', 'shi', '', NULL, '名姝詠 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afdbc718-fc07-45f8-8d16-c292396e6b7d', '送太和公主和蕃', '送太和公主和蕃', '08b14256-c564-4489-be33-927205119c81', '唐', '["北路古來難，年光獨認寒。","朔雲侵鬢起，邊月向眉殘。","蘆井尋沙到，花門度磧看。","薰風一萬里，來處是長安。"]', '["北路古来难，年光独認寒。","朔云侵鬢起，邊月向眉殘。","蘆井尋沙到，花门度磧看。","薰风一万里，来处是长安。"]', '诗', 'shi', '', NULL, '送太和公主和蕃 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd37eb1-7e6a-40c7-87d4-339753904fbe', '秋日韋少府廳池上詠石', '秋日韋少府廳池上詠石', '08b14256-c564-4489-be33-927205119c81', '唐', '["主人得幽石，日覺公堂清。","一片池上色，孤峰雲外情。","舊溪紅蘚在，秋水綠痕生。","何必澄湖徹，移來有令名。"]', '["主人得幽石，日覺公堂清。","一片池上色，孤峰云外情。","旧溪紅蘚在，秋水綠痕生。","何必澄湖徹，移来有令名。"]', '诗', 'shi', '', NULL, '秋日韋少府廳池上詠石 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0d4bf68-5b1c-4645-a7db-1054b921c7dd', '失題', '失題', '08b14256-c564-4489-be33-927205119c81', '唐', '["何事慰朝夕，不踰詩酒情。","山河空道路，蕃漢共刀兵。","禮樂新朝市，園林舊弟兄。","向風一點淚，塞晚暮江平。"]', '["何事慰朝夕，不踰诗酒情。","山河空道路，蕃漢共刀兵。","禮乐新朝市，园林旧弟兄。","向风一点泪，塞晚暮江平。"]', '诗', 'shi', '', NULL, '失題 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f076e777-de3d-4c3f-bd69-5aac890e9ab8', '春日題龍門香山寺', '春日題龙门香山寺', '08b14256-c564-4489-be33-927205119c81', '唐', '["衆香天上梵王宮，鐘磬寥寥半碧空。","清景乍開松嶺月，亂流長響石樓風。","山河杳映春雲外，城闕參差曉樹中。","欲盡出尋那可得，三千世界本無窮。"]', '["衆香天上梵王宮，鐘磬寥寥半碧空。","清景乍开松嶺月，亂流长响石楼风。","山河杳映春云外，城闕參差晓樹中。","欲尽出尋那可得，三千世界本無窮。"]', '诗', 'shi', '', NULL, '春日題龍門香山寺 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8add04a-83cc-4e89-a9b8-85a61071cf7b', '寄申州盧拱使君', '寄申州盧拱使君', '08b14256-c564-4489-be33-927205119c81', '唐', '["領郡仍聞總虎貔，致身還是見男兒。","小船隔水催桃葉，大鼓當風舞柘枝。","酒坐微酣諸客倒，毬場慢撥幾人隨。","從來樂事憎詩苦，莫放窗中遠岫知。"]', '["領郡仍闻總虎貔，致身還是见男兒。","小船隔水催桃葉，大鼓當风舞柘枝。","酒坐微酣諸客倒，毬場慢撥幾人隨。","從来乐事憎诗苦，莫放窗中远岫知。"]', '诗', 'shi', '', NULL, '寄申州盧拱使君 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c9bb358-89d9-4880-92db-57b0b9da5084', '郊居秋日酬奚贊府見寄', '郊居秋日酬奚贊府见寄', '08b14256-c564-4489-be33-927205119c81', '唐', '["繁菊照深居，芳香春不如。","聞尋周觸士，知伴庾尚書。","日晚汀洲曠，天晴草木疎。","閑言揮麈柄，清步掩蝸廬。","野老能親牧，高人念遠漁。","幽叢臨古岸，輕葉度寒渠。","暮色無狂蝶，秋華有嫩蔬。","若爲酬郢曲，從此愧璠璵。"]', '["繁菊照深居，芳香春不如。","闻尋周觸士，知伴庾尚书。","日晚汀洲曠，天晴草木疎。","闲言揮麈柄，清步掩蝸廬。","野老能親牧，高人念远漁。","幽叢臨古岸，轻葉度寒渠。","暮色無狂蝶，秋华有嫩蔬。","若爲酬郢曲，從此愧璠璵。"]', '诗', 'shi', '', NULL, '郊居秋日酬奚贊府見寄 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ba7943e-8d62-4fe0-97c1-546431f6a3c5', '聖恩洗雪鎮州寄獻裴相公', '聖恩洗雪鎮州寄獻裴相公', '08b14256-c564-4489-be33-927205119c81', '唐', '["天借春光洗綠林，戰塵收盡見花陰。","好生本是君王德，忍死何妨壯士心。","曾賀截雲翻柵遠，仍聞劚凍下營深。","井陘昨日雙旗入，蕭相無言淚濕襟。"]', '["天借春光洗綠林，戰塵收尽见花陰。","好生本是君王德，忍死何妨壯士心。","曾賀截云翻柵远，仍闻劚凍下營深。","井陘昨日雙旗入，蕭相無言泪濕襟。"]', '诗', 'shi', '', NULL, '聖恩洗雪鎮州寄獻裴相公 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b9d7ccd-0943-4e41-9146-6df9d2e7870e', '賀田僕射子弟榮拜金吾', '賀田僕射子弟榮拜金吾', '08b14256-c564-4489-be33-927205119c81', '唐', '["五侯恩澤不同年，叔姪朱門䂍矟連。","鳳沼九重相喜氣，鴈行一半入祥煙。","街衢燭影侵寒月，文武珂聲疊曉天。","爲數麒麟高閣上，誰家父子勒燕然。"]', '["五侯恩澤不同年，叔姪朱门䂍矟連。","鳳沼九重相喜氣，鴈行一半入祥煙。","街衢燭影侵寒月，文武珂声叠晓天。","爲數麒麟高閣上，誰家父子勒燕然。"]', '诗', 'shi', '', NULL, '賀田僕射子弟榮拜金吾 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb2710f0-6afb-4c19-a1f4-634e6378d655', '和裴舍人觀田尚書出獵', '和裴舍人观田尚书出獵', '08b14256-c564-4489-be33-927205119c81', '唐', '["聖代司空比玉清，雄藩觀獵見皇情。","雲禽已覺高無益，霜兔應知狡不成。","飛鞚擁塵寒草盡，彎弓開月朔風生。","今朝始賀將軍貴，紫禁詩人看斾旌。"]', '["聖代司空比玉清，雄藩观獵见皇情。","云禽已覺高無益，霜兔應知狡不成。","飞鞚擁塵寒草尽，彎弓开月朔风生。","今朝始賀將軍貴，紫禁诗人看斾旌。"]', '诗', 'shi', '', NULL, '和裴舍人觀田尚書出獵 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11dc4672-dfe8-40b0-97e2-419133063297', '送李舍人歸蘭陵里', '送李舍人归蘭陵里', '08b14256-c564-4489-be33-927205119c81', '唐', '["清詞舉世皆藏篋，美酒當山爲滿罇。","三畝嫩蔬臨綺陌，四行高樹擁朱門。","家貧境勝心無累，名重官閑口不論。","惟有道情常自足，啓期天地易知恩。"]', '["清词舉世皆藏篋，美酒當山爲满罇。","三畝嫩蔬臨綺陌，四行高樹擁朱门。","家貧境勝心無累，名重官闲口不論。","惟有道情常自足，啓期天地易知恩。"]', '诗', 'shi', '', NULL, '送李舍人歸蘭陵里 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40155463-e840-4235-a854-1150a58cd190', '同太常尉遲博士闕下待漏', '同太常尉遲博士闕下待漏', '08b14256-c564-4489-be33-927205119c81', '唐', '["沈沈延閣抱丹墀，松色苔花顥露滋。","爽氣曉來青玉甃，薰風宿在翠花旗。","方瞻御陌三條廣，猶覺仙門一刻遲。","此地含香從白首，馮唐何事怨明時。"]', '["沈沈延閣抱丹墀，松色苔花顥露滋。","爽氣晓来青玉甃，薰风宿在翠花旗。","方瞻御陌三條廣，猶覺仙门一刻遲。","此地含香從白首，馮唐何事怨明时。"]', '诗', 'shi', '', NULL, '同太常尉遲博士闕下待漏 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f0715e-52e0-460b-958f-2349f14154c7', '見薛侍御戴不損裹帽子因贈', '见薛侍御戴不損裹帽子因贈', '08b14256-c564-4489-be33-927205119c81', '唐', '["潘郎對青鏡，烏帽似新裁。","曉露鴉初洗，春荷葉半開。","堪將護巾櫛，不獨隔塵埃。","已見籠蟬翼，無因映鹿胎。","何人呈巧思，好手自西來。","有意憐衰醜，煩君致一枚。"]', '["潘郎对青镜，烏帽似新裁。","晓露鴉初洗，春荷葉半开。","堪將護巾櫛，不独隔塵埃。","已见籠蟬翼，無因映鹿胎。","何人呈巧思，好手自西来。","有意怜衰醜，煩君致一枚。"]', '诗', 'shi', '', NULL, '見薛侍御戴不損裹帽子因贈 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04fc2f75-917c-414d-af2f-e3dfe04fdaae', '胡二十拜戶部兼判度支', '胡二十拜戶部兼判度支', '08b14256-c564-4489-be33-927205119c81', '唐', '["清機果被公材撓，雄拜知承聖主恩。","廟略已調天府實，國征方覺地官尊。","徒言玉節將分閫，定是沙隄欲到門。","爲愛山前新卜第，不妨風月事琴罇。"]', '["清機果被公材撓，雄拜知承聖主恩。","廟略已調天府實，国征方覺地官尊。","徒言玉節將分閫，定是沙隄欲到门。","爲愛山前新卜第，不妨风月事琴罇。"]', '诗', 'shi', '', NULL, '胡二十拜戶部兼判度支 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32e7e766-c424-4232-8188-8f65fdceead0', '元日呈李逢吉舍人', '元日呈李逢吉舍人', '08b14256-c564-4489-be33-927205119c81', '唐', '["華夷文物賀新年，霜仗遙排鳳闕前。","一片彩霞迎曙日，萬條紅燭動春天。","稱觴山色和元氣，端冕爐香疊瑞煙。","共說正初當聖澤，試過西掖問羣賢。"]', '["华夷文物賀新年，霜仗遙排鳳闕前。","一片彩霞迎曙日，万條紅燭动春天。","稱觴山色和元氣，端冕爐香叠瑞煙。","共说正初當聖澤，試過西掖问羣賢。"]', '诗', 'shi', '', NULL, '元日呈李逢吉舍人 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb4fd2ed-c987-4317-af07-59ba076ea2a1', '和杜中丞西禪院看花', '和杜中丞西禪院看花', '08b14256-c564-4489-be33-927205119c81', '唐', '["一林堆錦映千燈，照眼牽情欲不勝。","知倚晴明嬌自足，解將顏色醉相仍。","好風輕引香煙入，甘露纔和粉豔凝。","深處最憐鶯蹂踐，嬾時先被蝶侵凌。","對持真境應無取，分付空門又未能。","迎日似翻紅燒斷，臨流疑映綺霞層。","幽含晚態憐丹桂，盛績春光識紫藤。","每到花枝獨惆悵，山東惟有杜中丞。"]', '["一林堆錦映千灯，照眼牽情欲不勝。","知倚晴明嬌自足，解將顏色醉相仍。","好风轻引香煙入，甘露纔和粉豔凝。","深处最怜鶯蹂踐，嬾时先被蝶侵凌。","对持真境應無取，分付空门又未能。","迎日似翻紅燒斷，臨流疑映綺霞層。","幽含晚態怜丹桂，盛績春光識紫藤。","每到花枝独惆悵，山东惟有杜中丞。"]', '诗', 'shi', '', NULL, '和杜中丞西禪院看花 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39698dc7-0888-4fa9-9972-56430754c3f5', '句', '句', '08b14256-c564-4489-be33-927205119c81', '唐', '["三刀夢益州，一箭取遼城。","伊陟無聞祖，韋賢不到孫。"]', '["三刀梦益州，一箭取遼城。","伊陟無闻祖，韋賢不到孫。"]', '诗', 'shi', '', NULL, '句 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('470907da-027c-466a-bf33-15db8d8377a1', '夏至日衡陽郡齋書懷', '夏至日衡陽郡斋书懷', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["一來江城守，七見江月圓。","齒髮將六十，鄉關越三千。","褰帷罕遊觀，閉閤多沉眠。","新節還復至，故交盡相捐。","何時羾閶闔，上訴高高天。"]', '["一来江城守，七见江月圓。","齒髮將六十，乡关越三千。","褰帷罕游观，閉閤多沉眠。","新節還复至，故交尽相捐。","何时羾閶闔，上訴高高天。"]', '诗', 'shi', '', NULL, '夏至日衡陽郡齋書懷 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73f537b4-febf-4032-8737-e1be2e1f681f', '八月十七日夜書懷', '八月十七日夜书懷', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["三五既不留，二八又還過。","金蟾著未出，玉樹悲稍破。","誰向西園遊，空歸北堂臥。","佳期信難得，永夕無可奈。","撫枕獨高歌，煩君爲予和。"]', '["三五既不留，二八又還過。","金蟾著未出，玉樹悲稍破。","誰向西园游，空归北堂臥。","佳期信难得，永夕無可奈。","撫枕独高歌，煩君爲予和。"]', '诗', 'shi', '', NULL, '八月十七日夜書懷 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67f144e3-8928-46c7-b95f-168c6a2657c7', '九日言懷', '九日言懷', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["二九即重陽，天清野菊黃。","近來逢此日，多是在他鄉。","晚色霞千片，秋聲鴈一行。","不能高處望，恐斷老人腸。"]', '["二九即重陽，天清野菊黄。","近来逢此日，多是在他乡。","晚色霞千片，秋声鴈一行。","不能高处望，恐斷老人腸。"]', '诗', 'shi', '', NULL, '九日言懷 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c33f395-b5aa-47d5-aff5-6480bce2df80', '和寄竇七中丞', '和寄竇七中丞', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["仙吏秦峨別，新詩鄂渚來。","才推今北斗，職賦舊三台。","雕鏤心偏許，緘封手自開。","何年相贈荅，却得到中臺。"]', '["仙吏秦峨別，新诗鄂渚来。","才推今北斗，職賦旧三台。","雕鏤心偏許，緘封手自开。","何年相贈荅，却得到中台。"]', '诗', 'shi', '', NULL, '和寄竇七中丞 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('826794a6-84fd-43a1-af20-4375d0839e35', '立秋日悲懷', '立秋日悲懷', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["清曉上高臺，秋風今日來。","又添新節恨，猶抱故年哀。","淚豈揮能盡，泉終閉不開。","更傷春月過，私服示無縗。"]', '["清晓上高台，秋风今日来。","又添新節恨，猶抱故年哀。","泪豈揮能尽，泉終閉不开。","更傷春月過，私服示無縗。"]', '诗', 'shi', '', NULL, '立秋日悲懷 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0a6f0fe-e5dd-43f8-85ea-36d6f915f584', '秋懷寄錢侍郎', '秋懷寄錢侍郎', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["晚歲俱爲郡，新秋各異鄉。","燕鴻一聲呌，郢樹盡青蒼。","山霞侵衣潤，江風捲簟涼。","相思如漢水，日夜向潯陽。"]', '["晚歲俱爲郡，新秋各異乡。","燕鴻一声呌，郢樹尽青蒼。","山霞侵衣潤，江风捲簟涼。","相思如漢水，日夜向潯陽。"]', '诗', 'shi', '', NULL, '秋懷寄錢侍郎 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42ee9d0e-3e52-42f6-9776-4bafea4d2bf6', '立秋日', '立秋日', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["平日本多恨，新秋偏易悲。","燕詞如惜別，柳意已呈衰。","事國終無補，還家未有期。","心中舊氣味，苦校去年時。"]', '["平日本多恨，新秋偏易悲。","燕词如惜別，柳意已呈衰。","事国終無補，還家未有期。","心中旧氣味，苦校去年时。"]', '诗', 'shi', '', NULL, '立秋日 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1124628e-1cfc-4f5a-86d7-be07cb307e73', '贈毛仙翁', '贈毛仙翁', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["宣州渾是上清宮，客有真人貌似童。","紺髮垂纓光髧髧，細髯緣頷綠茸茸。","壺中藥物梯霞訣，肘後方書縮地功。","既許焚香爲弟子，願敎年紀共椿同。"]', '["宣州渾是上清宮，客有真人貌似童。","紺髮垂纓光髧髧，細髯緣頷綠茸茸。","壺中藥物梯霞訣，肘後方书縮地功。","既許焚香爲弟子，願敎年紀共椿同。"]', '诗', 'shi', '', NULL, '贈毛仙翁 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('791da1d7-ca84-47fa-aa2a-fda1635a2f79', '遊義興寺寄上李逢吉相公', '游義兴寺寄上李逢吉相公', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["柳營無事詣蓮宮，步步猶疑是夢中。","勞役徒爲萬夫長，閑遊曾與二人同。","鳳鸞飛去仙巢在，龍象潛來講席空。","松下花飛頻佇立，一心千里憶梁公。"]', '["柳營無事詣蓮宮，步步猶疑是梦中。","勞役徒爲万夫长，闲游曾與二人同。","鳳鸾飞去仙巢在，龙象潛来講席空。","松下花飞頻佇立，一心千里憶梁公。"]', '诗', 'shi', '', NULL, '遊義興寺寄上李逢吉相公 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bca74224-6f2d-4d98-8513-f79c95596188', '遊晉祠上李逢吉相公', '游晉祠上李逢吉相公', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["不立晉祠三十年，白頭重到一淒然。","泉聲自昔鏘寒玉，草色雖秋耀翠鈿。","少壯同遊寧有數，尊榮再會便無緣。","相思臨水下雙淚，寄入幷汾向洛川。"]', '["不立晉祠三十年，白头重到一淒然。","泉声自昔鏘寒玉，草色雖秋耀翠鈿。","少壯同游寧有數，尊榮再會便無緣。","相思臨水下雙泪，寄入幷汾向洛川。"]', '诗', 'shi', '', NULL, '遊晉祠上李逢吉相公 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('435ff308-9160-4964-96ad-0eaa26fa8258', '節度宣武酬樂天夢得', '節度宣武酬乐天梦得', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["蓬萊仙監客曹郎，曾枉高車客大梁。","見擁旌旄治軍旅，知親筆硯事文章。","愁看柳色懸離恨，憶遞花枝助酒狂。","洛下相逢肯相寄，南金璀錯玉淒涼。"]', '["蓬萊仙監客曹郎，曾枉高车客大梁。","见擁旌旄治軍旅，知親笔硯事文章。","愁看柳色懸離恨，憶遞花枝助酒狂。","洛下相逢肯相寄，南金璀錯玉淒涼。"]', '诗', 'shi', '', NULL, '節度宣武酬樂天夢得 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c38714c1-2218-4035-8026-d433f8b9d34f', '奉和嚴司空重陽日同崔常侍崔郎及諸公登龍山落帽臺佳宴', '奉和嚴司空重陽日同崔常侍崔郎及諸公登龙山落帽台佳宴', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["謝公秋思渺天涯，蠟屐登高爲菊花。","貴重近臣光綺席，笑憐從事落烏紗。","萸房暗綻紅珠朵，茗碗寒供白露芽。","詠碎龍山歸出號，馬奔流電妓奔車。"]', '["謝公秋思渺天涯，蠟屐登高爲菊花。","貴重近臣光綺席，笑怜從事落烏紗。","萸房暗綻紅珠朵，茗碗寒供白露芽。","詠碎龙山归出號，马奔流電妓奔车。"]', '诗', 'shi', '', NULL, '奉和嚴司空重陽日同崔常侍崔郎及諸公登龍山落帽臺佳宴 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd43eca-d6ea-45f6-9cda-7baa44bbe426', '立春後言懷招汴州李匡衙推', '立春後言懷招汴州李匡衙推', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["閑齋夜擊唾壺歌，試望夷門奈遠何。","每聽塞笳離夢斷，時窺清鑑旅愁多。","初驚宵漏丁丁促，已覺春風習習和。","海內故人君最老，花開鞭馬更相過。"]', '["闲斋夜擊唾壺歌，試望夷门奈远何。","每听塞笳離梦斷，时窺清鑑旅愁多。","初驚宵漏丁丁促，已覺春风習習和。","海內故人君最老，花开鞭马更相過。"]', '诗', 'shi', '', NULL, '立春後言懷招汴州李匡衙推 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5092435e-edbc-4702-8493-d938128db1ee', '奉和僕射相公酬忠武李相公見寄之作', '奉和僕射相公酬忠武李相公见寄之作', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["麗藻飛來自相庭，五文相錯八音清。","初瞻綺色連霞色，又聽金聲繼玉聲。","才出山西文與武，歡從塞北弟兼兄。","白頭老尹三川上，雙和陽春喜復驚。"]', '["丽藻飞来自相庭，五文相錯八音清。","初瞻綺色連霞色，又听金声繼玉声。","才出山西文與武，歡從塞北弟兼兄。","白头老尹三川上，雙和陽春喜复驚。"]', '诗', 'shi', '', NULL, '奉和僕射相公酬忠武李相公見寄之作 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf912dac-30ed-4f16-a951-ddecd90387ed', '郡齋左偏栽竹百餘竿炎涼已周青翠不改而爲墻垣所蔽有乖愛賞假日命去齋居之東墻由是俯臨軒階低映帷戶日夕相對頗有翛然之趣', '郡斋左偏栽竹百餘竿炎涼已周青翠不改而爲墻垣所蔽有乖愛賞假日命去斋居之东墻由是俯臨軒階低映帷戶日夕相对頗有翛然之趣', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["齋居栽竹北窗邊，素壁新開映碧鮮。","青藹近當行藥處，綠陰深到臥帷前。","風驚曉葉如聞雨，月過春枝似帶煙。","老子憶山心暫緩，退公閑坐對嬋娟。"]', '["斋居栽竹北窗邊，素壁新开映碧鲜。","青藹近當行藥处，綠陰深到臥帷前。","风驚晓葉如闻雨，月過春枝似带煙。","老子憶山心暫緩，退公闲坐对嬋娟。"]', '诗', 'shi', '', NULL, '郡齋左偏栽竹百餘竿炎涼已周青翠不改而爲墻垣所蔽有乖愛賞假日命去齋居之東墻由是俯臨軒階低映帷戶日夕相對頗有翛然之趣 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4919ada6-5b90-4a82-9cec-81b67f64c524', '省中直夜對雪寄李師素侍郎', '省中直夜对雪寄李師素侍郎', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["密雪紛初降，重城杳未開。","雜花飛爛熳，連蝶舞徘徊。","灑散千株葉，銷凝九陌埃。","素華凝粉署，清氣繞霜臺。","明覺侵窗積，寒知度塞來。","謝家爭擬絮，越嶺悞驚梅。","暗魄微茫照，嚴飆次第催。","稍封黃竹亞，先集紫蘭摧。","孫室臨書幌，梁園泛酒杯。","靜懷瓊樹倚，醉憶玉山頹。","翠陌飢烏噪，蒼雲遠鴈哀。","此時方夜直，想望意悠哉。"]', '["密雪紛初降，重城杳未开。","杂花飞爛熳，連蝶舞徘徊。","灑散千株葉，銷凝九陌埃。","素华凝粉署，清氣繞霜台。","明覺侵窗積，寒知度塞来。","謝家爭擬絮，越嶺悞驚梅。","暗魄微茫照，嚴飆次第催。","稍封黄竹亞，先集紫蘭摧。","孫室臨书幌，梁园泛酒杯。","静懷瓊樹倚，醉憶玉山頹。","翠陌飢烏噪，蒼云远鴈哀。","此时方夜直，想望意悠哉。"]', '诗', 'shi', '', NULL, '省中直夜對雪寄李師素侍郎 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5232b91-25fb-4ebf-ab67-e96902f4376a', '南宮夜直宿見李給事封題其所下制敕知奏直在東省因以詩寄', '南宮夜直宿见李給事封題其所下制敕知奏直在东省因以诗寄', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["番直同遙夜，嚴扃限幾重。","青編書白雀，黃紙降蒼龍。","北極絲綸句，東垣翰墨蹤。","尚垂玄露點，猶濕紫泥封。","炫眼凝仙燭，馳心裊禁鍾。","定應形夢寐，暫似接音容。","玉樹春枝動，金樽臘釀醲。","在朝君最舊，休澣許過從。"]', '["番直同遙夜，嚴扃限幾重。","青編书白雀，黄紙降蒼龙。","北極絲綸句，东垣翰墨蹤。","尚垂玄露点，猶濕紫泥封。","炫眼凝仙燭，驰心裊禁鍾。","定應形梦寐，暫似接音容。","玉樹春枝动，金樽臘釀醲。","在朝君最旧，休澣許過從。"]', '诗', 'shi', '', NULL, '南宮夜直宿見李給事封題其所下制敕知奏直在東省因以詩寄 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e5a9fc9-3055-486a-8eb4-4c641670a93b', '將赴洛下旅次漢南獻上相公二十兄言懷八韻', '將赴洛下旅次漢南獻上相公二十兄言懷八韻', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["台室名曾繼，旌門節暫過。","歡情老去少，苦事別離多。","便爲開樽俎，應憐出網羅。","百憂今已失，一醉孰知他。","帝德千年日，君恩萬里波。","許隨黃綺輩，閑唱紫芝歌。","龍衮期重補，梅羹佇再和。","嵩丘來攜手，君子意如何。"]', '["台室名曾繼，旌门節暫過。","歡情老去少，苦事別離多。","便爲开樽俎，應怜出網羅。","百憂今已失，一醉孰知他。","帝德千年日，君恩万里波。","許隨黄綺輩，闲唱紫芝歌。","龙衮期重補，梅羹佇再和。","嵩丘来携手，君子意如何。"]', '诗', 'shi', '', NULL, '將赴洛下旅次漢南獻上相公二十兄言懷八韻 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f03a6855-e60d-4b75-8881-e59ea03599a7', '青雲干呂', '青云干呂', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["郁郁復紛紛，青霄干呂雲。","色令天下見，候向管中分。","遠覆無人境，遙彰有德君。","瑞容驚不散，冥感信稀聞。","湛露羞依草，南風耻帶薰。","恭惟漢武帝，餘烈尚氛氳。"]', '["郁郁复紛紛，青霄干呂云。","色令天下见，候向管中分。","远覆無人境，遙彰有德君。","瑞容驚不散，冥感信稀闻。","湛露羞依草，南风耻带薰。","恭惟漢武帝，餘烈尚氛氳。"]', '诗', 'shi', '', NULL, '青雲干呂 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9656e10f-301d-40c1-86a9-54ce992f86cb', '聖明樂', '聖明乐', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["海浪恬丹徼，邊塵靜異山。","從今萬里外，不復鎖蕭關。"]', '["海浪恬丹徼，邊塵静異山。","從今万里外，不复鎖蕭关。"]', '诗', 'shi', '', NULL, '聖明樂 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e320cbef-225b-4d78-a2e9-ac02e9a092aa', '春閨思', '春閨思', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["戴勝飛晴野，凌澌下濁河。","春風樓上望，誰見淚痕多。"]', '["戴勝飞晴野，凌澌下濁河。","春风楼上望，誰见泪痕多。"]', '诗', 'shi', '', NULL, '春閨思 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f0ad38-9713-4ae2-8697-c04a1429bbef', '宮中樂五首 一', '宮中乐五首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["楚塞金陵靖，巴山玉壘空。","萬方無一事，端拱大明宮。"]', '["楚塞金陵靖，巴山玉壘空。","万方無一事，端拱大明宮。"]', '诗', 'shi', '', NULL, '宮中樂五首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b8245c6-adaa-49cf-a1ce-9037c01a4311', '宮中樂五首 二', '宮中乐五首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["雪霽長楊苑，冰開太液池。","宮中行樂日，天下盛明時。"]', '["雪霽长楊苑，冰开太液池。","宮中行乐日，天下盛明时。"]', '诗', 'shi', '', NULL, '宮中樂五首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86676d89-8a49-49c5-a5e4-a72a260eb0be', '宮中樂五首 三', '宮中乐五首 三', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["柳色煙相似，梨花雪不如。","春風真有意，一一麗皇居。"]', '["柳色煙相似，梨花雪不如。","春风真有意，一一丽皇居。"]', '诗', 'shi', '', NULL, '宮中樂五首 三 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83e4c143-6765-4a3b-941a-20af4e623317', '宮中樂五首 四', '宮中乐五首 四', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["月上宮花靜，煙含苑樹深。","銀臺門已閉，仙漏夜沉沉。"]', '["月上宮花静，煙含苑樹深。","銀台门已閉，仙漏夜沉沉。"]', '诗', 'shi', '', NULL, '宮中樂五首 四 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d78410c-e75c-4af5-8729-4a8ebe0891a7', '宮中樂五首 五', '宮中乐五首 五', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["九重青瑣闥，百尺碧雲樓。","明月秋風起，珠簾上玉鉤。"]', '["九重青瑣闥，百尺碧云楼。","明月秋风起，珠簾上玉鉤。"]', '诗', 'shi', '', NULL, '宮中樂五首 五 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d221d17-e090-435c-9745-7299f5c27efa', '春遊曲三首 一', '春游曲三首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["曉遊臨碧殿，日上望春亭。","芳樹羅仙仗，晴山展翠屏。"]', '["晓游臨碧殿，日上望春亭。","芳樹羅仙仗，晴山展翠屏。"]', '诗', 'shi', '', NULL, '春遊曲三首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ed4fe8-65f1-4c6c-b812-749768b549af', '春遊曲三首 二', '春游曲三首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["一夜好風吹，新花一萬枝。","風前調玉管，花下簇金羈。"]', '["一夜好风吹，新花一万枝。","风前調玉管，花下簇金羈。"]', '诗', 'shi', '', NULL, '春遊曲三首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdd140eb-32ee-4ae9-b073-5ee77ef21123', '春遊曲三首 三', '春游曲三首 三', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["閶闔春風起，蓬萊雪水消。","相將折楊柳，爭取最長條。"]', '["閶闔春风起，蓬萊雪水消。","相將折楊柳，爭取最长條。"]', '诗', 'shi', '', NULL, '春遊曲三首 三 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d7d1b5d-eb29-43d5-b118-4f67e94b5fac', '遠別離二首 一', '远別離二首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["楊柳黃金穗，梧桐碧玉枝。","春來消息斷，早晚是歸期。"]', '["楊柳黄金穗，梧桐碧玉枝。","春来消息斷，早晚是归期。"]', '诗', 'shi', '', NULL, '遠別離二首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7a8d208-1c29-42c8-9702-3409395028be', '遠別離二首 二', '远別離二首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["玳織鴛鴦履，金裝翡翠篸。","畏人相問著，不擬到城南。"]', '["玳织鴛鴦履，金裝翡翠篸。","畏人相问著，不擬到城南。"]', '诗', 'shi', '', NULL, '遠別離二首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9902f83-33d4-426e-abe1-7599b7213602', '閨人贈遠二首 一', '閨人贈远二首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["君行登隴上，妾夢在閨中。","玉筯千行落，銀牀一半空。"]', '["君行登隴上，妾梦在閨中。","玉筯千行落，銀牀一半空。"]', '诗', 'shi', '', NULL, '閨人贈遠二首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d7c97b7-554f-41c8-8bda-4905568bff87', '閨人贈遠二首 二', '閨人贈远二首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["綺席春眠覺，紗窗曉望迷。","朦朧殘夢裏，猶自在遼西。"]', '["綺席春眠覺，紗窗晓望迷。","朦朧殘梦裏，猶自在遼西。"]', '诗', 'shi', '', NULL, '閨人贈遠二首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61881aae-99b0-421a-9e40-461b5577bdd0', '從軍詞五首 一', '從軍词五首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["荒雞隔水啼，汗馬逐風嘶。","終日隨征斾，何時罷鼓鼙。"]', '["荒雞隔水啼，汗马逐风嘶。","終日隨征斾，何时罷鼓鼙。"]', '诗', 'shi', '', NULL, '從軍詞五首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ac3a05c-e82c-4618-ba14-baa5e81fb52a', '從軍詞五首 二', '從軍词五首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["孤心眠夜雪，滿眼是秋沙。","萬里猶防塞，三年不見家。"]', '["孤心眠夜雪，满眼是秋沙。","万里猶防塞，三年不见家。"]', '诗', 'shi', '', NULL, '從軍詞五首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d18e1018-c4c2-43e6-9d84-59d72479ba32', '從軍詞五首 三', '從軍词五首 三', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["却望冰河闊，前登雪嶺高。","征人幾多在，又擬戰臨洮。"]', '["却望冰河闊，前登雪嶺高。","征人幾多在，又擬戰臨洮。"]', '诗', 'shi', '', NULL, '從軍詞五首 三 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d27bc90-4397-414b-838b-351dae2db9e0', '從軍詞五首 四', '從軍词五首 四', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["胡風千里驚，漢月五更明。","縱有還家夢，猶聞出塞聲。"]', '["胡风千里驚，漢月五更明。","縱有還家梦，猶闻出塞声。"]', '诗', 'shi', '', NULL, '從軍詞五首 四 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5957c111-ca5d-4fd9-bb2a-2bbeb2c999ec', '從軍詞五首 五', '從軍词五首 五', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["暮雪連青海，陰霞覆白山。","可憐班定遠，生入玉門關。"]', '["暮雪連青海，陰霞覆白山。","可怜班定远，生入玉门关。"]', '诗', 'shi', '', NULL, '從軍詞五首 五 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f035b62-bdd6-43fd-a6bf-0ddd1152974d', '思君恩', '思君恩', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["小苑鶯歌歇，長門蝶舞多。","眼看春又去，翠輦不經過。"]', '["小苑鶯歌歇，长门蝶舞多。","眼看春又去，翠輦不經過。"]', '诗', 'shi', '', NULL, '思君恩 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcb5eda2-fc75-45ba-9688-78a84da4765c', '王昭君', '王昭君', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["錦車天外去，毳幕雪中開。","魏闕蒼龍遠，蕭關赤鴈哀。"]', '["錦车天外去，毳幕雪中开。","魏闕蒼龙远，蕭关赤鴈哀。"]', '诗', 'shi', '', NULL, '王昭君 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06dc389e-07c6-4cb8-b989-01f814d70569', '發潭州寄李寧常侍', '發潭州寄李寧常侍', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["君今侍紫垣，我已墮青天。","委廢從茲日，旋歸在幾年。","心爲西靡樹，眼是北流泉。","更過長沙去，江風滿驛船。"]', '["君今侍紫垣，我已墮青天。","委廢從茲日，旋归在幾年。","心爲西靡樹，眼是北流泉。","更過长沙去，江风满驛船。"]', '诗', 'shi', '', NULL, '發潭州寄李寧常侍 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71241dbb-d128-4c4f-ad76-6ab8d2a25659', '李相薨後題斷金集', '李相薨後題斷金集', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["一覽斷金集，載悲埋玉人。","牙弦千古絕，珠淚萬行新。"]', '["一覽斷金集，載悲埋玉人。","牙弦千古絕，珠泪万行新。"]', '诗', 'shi', '', NULL, '李相薨後題斷金集 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc298162-a2f5-4294-83ac-d9d4802324ed', '年少行四首 一', '年少行四首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["少小邊州慣放狂，驏騎蕃馬射黃羊。","如今年老無筋力，猶倚營門數鴈行。"]', '["少小邊州慣放狂，驏騎蕃马射黄羊。","如今年老無筋力，猶倚營门數鴈行。"]', '诗', 'shi', '', NULL, '年少行四首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d99244c-884a-4fdb-8e5e-1f28f4916dd3', '年少行四首 二', '年少行四首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["家本清河住五城，須憑弓箭得功名。","等閑飛鞚秋原上，獨向寒雲試射聲。"]', '["家本清河住五城，須憑弓箭得功名。","等闲飞鞚秋原上，独向寒云試射声。"]', '诗', 'shi', '', NULL, '年少行四首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63ff323f-75cb-4c3b-9b10-7a6581ef3f6f', '年少行四首 三', '年少行四首 三', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["弓背霞明劒照霜，秋風走馬出咸陽。","未收天子河湟地，不擬回頭望故鄉。"]', '["弓背霞明劒照霜，秋风走马出咸陽。","未收天子河湟地，不擬回头望故乡。"]', '诗', 'shi', '', NULL, '年少行四首 三 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1186edbd-673b-4513-8940-d72170efa4d3', '年少行四首 四', '年少行四首 四', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["霜滿中庭月滿樓，金樽玉柱對清秋。","當年稱意須行樂，不到天明不肯休。"]', '["霜满中庭月满楼，金樽玉柱对清秋。","當年稱意須行乐，不到天明不肯休。"]', '诗', 'shi', '', NULL, '年少行四首 四 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10d6554f-1643-4b92-9755-710cfa425a3d', '塞下曲二首 一', '塞下曲二首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["雪滿衣裳冰滿鬚，曉隨飛將伐單于。","平生意氣今何在，把得家書淚似珠。"]', '["雪满衣裳冰满鬚，晓隨飞將伐單于。","平生意氣今何在，把得家书泪似珠。"]', '诗', 'shi', '', NULL, '塞下曲二首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07a5b7af-0096-4a0c-ba4f-a4f972e9e365', '塞下曲二首 二', '塞下曲二首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["邊草蕭條塞鴈飛，征人南望淚沾衣。","黃塵滿面長須戰，白髮生頭未得歸。"]', '["邊草蕭條塞鴈飞，征人南望泪沾衣。","黄塵满面长須戰，白髮生头未得归。"]', '诗', 'shi', '', NULL, '塞下曲二首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d65a0f84-3f75-4d4e-bb8b-1a275c1cf586', '遊春詞', '游春词', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["高樓曉見一花開，便覺春光四面來。","暖日晴雲知次第，東風不用更相催。"]', '["高楼晓见一花开，便覺春光四面来。","暖日晴云知次第，东风不用更相催。"]', '诗', 'shi', '', NULL, '遊春詞 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cff4c658-ee2e-42d6-9d1e-4a336e80047d', '漢苑行', '漢苑行', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["雲霞五采浮天闕，梅柳千般夾御溝。","不上黃花南北望，豈知春色滿神州。"]', '["云霞五采浮天闕，梅柳千般夾御溝。","不上黄花南北望，豈知春色满神州。"]', '诗', 'shi', '', NULL, '漢苑行 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('853bcd83-f155-4a45-ad4f-491ba6cd0eaa', '中元日贈張尊師', '中元日贈張尊師', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["偶來人世值中元，不獻玄都永日閑。","寂寂焚香在仙觀，知師遙禮玉京山。"]', '["偶来人世值中元，不獻玄都永日闲。","寂寂焚香在仙观，知師遙禮玉京山。"]', '诗', 'shi', '', NULL, '中元日贈張尊師 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('057539ad-9727-429a-8be1-f292f65e6fd6', '赴東都別牡丹', '赴东都別牡丹', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["十年不見小庭花，紫萼臨開又別家。","上馬出門回首望，何時更得到京華。"]', '["十年不见小庭花，紫萼臨开又別家。","上马出门回首望，何时更得到京华。"]', '诗', 'shi', '', NULL, '赴東都別牡丹 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d445f406-1dc3-4fb6-a450-9de1e5cf5c36', '寄禮部劉郎中', '寄禮部劉郎中', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["一別三年在上京，仙垣終日選羣英。","除書每下皆先看，唯有劉郎無姓名。"]', '["一別三年在上京，仙垣終日選羣英。","除书每下皆先看，唯有劉郎無姓名。"]', '诗', 'shi', '', NULL, '寄禮部劉郎中 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f18c052e-4df5-4c24-ae21-eac858b65ed8', '坐中聞思帝鄉有感', '坐中闻思帝乡有感', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["年年不見帝鄉春，白日尋思夜夢頻。","上酒忽聞吹此曲，坐中惆悵更何人。"]', '["年年不见帝乡春，白日尋思夜梦頻。","上酒忽闻吹此曲，坐中惆悵更何人。"]', '诗', 'shi', '', NULL, '坐中聞思帝鄉有感 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a83b0b1a-e2d2-4c3a-be9d-f63eff04d1ad', '春思寄夢得樂天', '春思寄梦得乐天', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["花滿中庭酒滿樽，平明獨坐到黃昏。","春來詩思偏何處，飛過函關入鼎門。"]', '["花满中庭酒满樽，平明独坐到黄昏。","春来诗思偏何处，飞過函关入鼎门。"]', '诗', 'shi', '', NULL, '春思寄夢得樂天 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd9b3b55-83f4-4931-9520-5c78ba2dc073', '皇城中花園譏劉白賞春不及', '皇城中花园譏劉白賞春不及', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["五鳳樓西花一園，低枝小樹盡芳繁。","洛陽才子何曾愛，下馬貪趨廣運門。"]', '["五鳳楼西花一园，低枝小樹尽芳繁。","洛陽才子何曾愛，下马貪趨廣運门。"]', '诗', 'shi', '', NULL, '皇城中花園譏劉白賞春不及 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ff6835-1024-4b44-bbbd-e89cb8913ffa', '相思河', '相思河', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["誰把相思號比河，塞垣車馬往來多。","只應自古征人淚，灑向空洲作碧波。"]', '["誰把相思號比河，塞垣车马往来多。","只應自古征人泪，灑向空洲作碧波。"]', '诗', 'shi', '', NULL, '相思河 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ccdcda9-4793-4bc5-863b-00c69dc7d692', '三月晦日會李員外座中頻以老大不醉見譏因有此贈', '三月晦日會李員外座中頻以老大不醉见譏因有此贈', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["三月唯殘一日春，玉山傾倒白鷗馴。","不辭便學山公醉，花下無人作主人。"]', '["三月唯殘一日春，玉山傾倒白鷗馴。","不辞便学山公醉，花下無人作主人。"]', '诗', 'shi', '', NULL, '三月晦日會李員外座中頻以老大不醉見譏因有此贈 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ac3e55f-2010-415a-b261-59355c6e4756', '賦山', '賦山', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["山，聳峻，回環。","滄海上，白雲間。","商老深尋，謝公遠攀。","古巖泉滴滴，幽谷鳥關關。","樹島西連隴塞，猨聲南徹荆蠻。","世人只向簪裾老，芳草空餘麋鹿閑。"]', '["山，聳峻，回环。","滄海上，白云间。","商老深尋，謝公远攀。","古巖泉滴滴，幽谷鸟关关。","樹島西連隴塞，猨声南徹荆蠻。","世人只向簪裾老，芳草空餘麋鹿闲。"]', '诗', 'shi', '', NULL, '賦山 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d00f416-f540-421b-95b2-0cdb5fe21daa', '句', '句', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["何日居三署，終年尾百僚。","移石幾迴敲廢印，開箱何處送新圖。","唯應四仲祭，使者暫悲嗟。","偶逢蒲家郎，乃是葛仙客。","行常乘青竹，飢即煮白石。","腰間嫌大組，心內保尺宅。","我願從之遊，深卜鍊上液。"]', '["何日居三署，終年尾百僚。","移石幾迴敲廢印，开箱何处送新圖。","唯應四仲祭，使者暫悲嗟。","偶逢蒲家郎，乃是葛仙客。","行常乘青竹，飢即煮白石。","腰间嫌大組，心內保尺宅。","我願從之游，深卜鍊上液。"]', '诗', 'shi', '', NULL, '句 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3994414-ab96-48c8-ad91-dc2755cd96e5', '享惠昭太子廟樂章', '享惠昭太子廟乐章', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["重輪始發祥，齒胄方興學。","冥然升紫府，鏗爾薦清樂。","奠斝致馨香，在庭紛羽籥。","禮成神既醉，髣髴緱山鶴。"]', '["重輪始發祥，齒胄方兴学。","冥然升紫府，鏗爾薦清乐。","奠斝致馨香，在庭紛羽籥。","禮成神既醉，髣髴緱山鹤。"]', '诗', 'shi', '', NULL, '享惠昭太子廟樂章 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dcc7d56-6cb5-40fe-8261-18b2923542bb', '夏日對雨', '夏日对雨', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["登樓逃盛夏，萬象正埃塵。","對面雷嗔樹，當街雨趁人。","簷疎蛛網重，地溼燕泥新。","吟罷清風起，荷香滿四鄰。"]', '["登楼逃盛夏，万象正埃塵。","对面雷嗔樹，當街雨趁人。","簷疎蛛網重，地溼燕泥新。","吟罷清风起，荷香满四鄰。"]', '诗', 'shi', '', NULL, '夏日對雨 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc08e47a-6fac-4073-b5e0-1f035dee25d0', '白二十二侍郎有雙鶴留在洛下予西園多野水長松可以栖息遂以詩請之', '白二十二侍郎有雙鹤留在洛下予西园多野水长松可以栖息遂以诗請之', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["聞君有雙鶴，羈旅洛城東。","未放歸仙去，何如乞老翁。","且將臨野水，莫閉在樊籠。","好是長鳴處，西園白露中。"]', '["闻君有雙鹤，羈旅洛城东。","未放归仙去，何如乞老翁。","且將臨野水，莫閉在樊籠。","好是长鳴处，西园白露中。"]', '诗', 'shi', '', NULL, '白二十二侍郎有雙鶴留在洛下予西園多野水長松可以栖息遂以詩請之 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3027811-f99a-444a-b8dd-378cd05be12f', '竇七中丞見示初至夏口獻元戎詩輒戲和之', '竇七中丞见示初至夏口獻元戎诗輒戲和之', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["出佐青油幕，來吟白雪篇。","須爲九臯鶴，莫上五湖船。","故態君應在，新詩我亦便。","元侯看再入，好被暫流連。"]', '["出佐青油幕，来吟白雪篇。","須爲九臯鹤，莫上五湖船。","故態君應在，新诗我亦便。","元侯看再入，好被暫流連。"]', '诗', 'shi', '', NULL, '竇七中丞見示初至夏口獻元戎詩輒戲和之 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc10fb4f-5e6c-4ab4-82ee-904929155fbf', '酬張秘書因寄馬贈詩', '酬張秘书因寄马贈诗', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["滿城馳逐皆求馬，古寺閑行獨與君。","代步本慙非逸足，緣情何幸枉高文。","若逢佳麗從將換，莫共駑駘角出羣。","飛控著鞭能顧我，當時王粲亦從軍。"]', '["满城驰逐皆求马，古寺闲行独與君。","代步本慙非逸足，緣情何幸枉高文。","若逢佳丽從將換，莫共駑駘角出羣。","飞控著鞭能顧我，當时王粲亦從軍。"]', '诗', 'shi', '', NULL, '酬張秘書因寄馬贈詩 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82fd4dc3-e911-4f44-aaba-0124c39d363b', '真慧寺', '真慧寺', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["遍尋真蹟躡莓苔，世事全拋不忍回。","上界不知何處去，西天移向此間來。","巖前芍藥師親種，嶺上青松佛手栽。","更有一般人不見，白蓮花向半天開。"]', '["遍尋真蹟躡莓苔，世事全拋不忍回。","上界不知何处去，西天移向此间来。","巖前芍藥師親種，嶺上青松佛手栽。","更有一般人不见，白蓮花向半天开。"]', '诗', 'shi', '', NULL, '真慧寺 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c483097d-225a-4508-b8f2-2d0a055e9d2d', '中書即事', '中书即事', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["有意效承平，無功荅聖明。","灰心緣忍事，霜鬢爲論兵。","道直身還在，恩深命轉輕。","鹽梅非擬議，葵藿是平生。","白日長懸照，蒼蠅謾發聲。","高陽舊田里，終使謝歸耕。"]', '["有意效承平，無功荅聖明。","灰心緣忍事，霜鬢爲論兵。","道直身還在，恩深命轉轻。","鹽梅非擬議，葵藿是平生。","白日长懸照，蒼蠅謾發声。","高陽旧田里，終使謝归耕。"]', '诗', 'shi', '', NULL, '中書即事 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('561556a9-9bd2-450a-9d38-622e35baa029', '中和節詔賜公卿尺', '中和節詔賜公卿尺', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["陽和行慶賜，尺度及羣公。","荷寵承佳節，傾心立大中。","短長思合製，遠近貴攸同。","共仰財成德，將酬分寸功。","作程施有政，垂範播無窮。","願續南山壽，千春奉聖躬。"]', '["陽和行慶賜，尺度及羣公。","荷寵承佳節，傾心立大中。","短长思合製，远近貴攸同。","共仰財成德，將酬分寸功。","作程施有政，垂範播無窮。","願續南山壽，千春奉聖躬。"]', '诗', 'shi', '', NULL, '中和節詔賜公卿尺 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f4d92f2-7130-41c1-a5f9-dcb72c9c42ad', '至日登樂遊園', '至日登乐游园', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["陰律隨寒改，陽和應節生。","祥雲觀魏闕，瑞氣映秦城。","驗炭論時政，書雲受歲盈。","晷移長日至，霧斂遠霄清。","景暖仙梅動，風柔御柳傾。","那堪封得意，空對物華情。"]', '["陰律隨寒改，陽和應節生。","祥云观魏闕，瑞氣映秦城。","驗炭論时政，书云受歲盈。","晷移长日至，霧斂远霄清。","景暖仙梅动，风柔御柳傾。","那堪封得意，空对物华情。"]', '诗', 'shi', '', NULL, '至日登樂遊園 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7c03e7-3e18-4e74-ba29-7d1dd2ab1963', '奉酬中書相公至日圓丘攝事合於中書後閣宿齋移止於集賢院敘懷見寄之作', '奉酬中书相公至日圓丘攝事合於中书後閣宿斋移止於集賢院敘懷见寄之作', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["翼亮登三命，謨猷本一心。","致齋移秘府，祗事見沖襟。","皓月當延閣，祥風自禁林。","相庭方積玉，王度已如金。","運偶唐虞盛，情同丙魏深。","幽蘭與白雪，何處寄庸音。"]', '["翼亮登三命，謨猷本一心。","致斋移秘府，祗事见沖襟。","皓月當延閣，祥风自禁林。","相庭方積玉，王度已如金。","運偶唐虞盛，情同丙魏深。","幽蘭與白雪，何处寄庸音。"]', '诗', 'shi', '', NULL, '奉酬中書相公至日圓丘攝事合於中書後閣宿齋移止於集賢院敘懷見寄之作 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cee4958-7cfa-47af-b997-474f07026a79', '太原題廳壁', '太原題廳壁', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["危事經非一，浮榮得是空。","白頭官舍裏，今日又春風。"]', '["危事經非一，浮榮得是空。","白头官舍裏，今日又春风。"]', '诗', 'shi', '', NULL, '太原題廳壁 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2758358b-0b09-4d28-a760-c7bad0e24604', '溪居', '溪居', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["門徑俯清溪，茅簷古木齊。","紅塵飄不到，時有水禽[啼]。"]', '["门徑俯清溪，茅簷古木齊。","紅塵飄不到，时有水禽[啼]。"]', '诗', 'shi', '', NULL, '溪居 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cf58d4c-891c-428a-aded-f7a152f484c4', '喜遇劉二十八', '喜遇劉二十八', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["病來佳興少，老去舊遊稀。","笑語縱橫作，盃觴絡繹飛。"]', '["病来佳兴少，老去旧游稀。","笑語縱橫作，盃觴絡繹飞。"]', '诗', 'shi', '', NULL, '喜遇劉二十八 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcd50811-3a5f-4243-b5c6-76142813cf1f', '送劉', '送劉', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["不歸丹掖去，銅竹漫云云。","惟喜因過我，須知未賀君。"]', '["不归丹掖去，銅竹漫云云。","惟喜因過我，須知未賀君。"]', '诗', 'shi', '', NULL, '送劉 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0738c2d1-fb75-4b8b-855e-55a75fa55f79', '再送', '再送', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["頃來多謔浪，此夕任喧紛。","故態猶應在，行期未要聞。"]', '["頃来多謔浪，此夕任喧紛。","故態猶應在，行期未要闻。"]', '诗', 'shi', '', NULL, '再送 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd56ceb-779a-4207-b29b-252041b08edb', '涼風亭睡覺', '涼风亭睡覺', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["飽食緩行新睡覺，一甌新茗侍兒煎。","脫巾斜倚繩牀坐，風送水聲來耳邊。"]', '["飽食緩行新睡覺，一甌新茗侍兒煎。","脫巾斜倚繩牀坐，风送水声来耳邊。"]', '诗', 'shi', '', NULL, '涼風亭睡覺 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e3a9d6c-5437-4b81-93f6-ccb33c11bdbd', '雪中訝諸公不相訪', '雪中訝諸公不相訪', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["憶昨雨多泥又深，猶能攜妓遠過尋。","滿空亂雪花相似，何事居然無賞心。"]', '["憶昨雨多泥又深，猶能携妓远過尋。","满空亂雪花相似，何事居然無賞心。"]', '诗', 'shi', '', NULL, '雪中訝諸公不相訪 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fbd455e-35f0-4785-9671-9b31bdd3db9d', '傍水閑行', '傍水闲行', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["閑餘何處覺身輕，暫脫朝衣傍水行。","鷗鳥亦知人意靜，故來相近不相驚。"]', '["闲餘何处覺身轻，暫脫朝衣傍水行。","鷗鸟亦知人意静，故来相近不相驚。"]', '诗', 'shi', '', NULL, '傍水閑行 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e95c7ae1-b846-4b76-b889-3b8ab60bfa15', '句', '句', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["兩人同日事征西，今日君先奉紫泥。","待平賊壘報天子，莫指仙山示武夫。","野人不識中書令，喚作陶家與謝家。","君若有心求逸足，我還留意在名姝。"]', '["兩人同日事征西，今日君先奉紫泥。","待平賊壘報天子，莫指仙山示武夫。","野人不識中书令，喚作陶家與謝家。","君若有心求逸足，我還留意在名姝。"]', '诗', 'shi', '', NULL, '句 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe7cee2-1f29-42af-84f5-c464844e1e0c', '元和聖德詩', '元和聖德诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["皇帝即阼，物無違拒。","曰暘而暘，曰雨而雨。","維是元年，有盜在夏。","欲覆其州，以踵近武。","皇帝曰嘻，豈不在我。","負鄙爲艱，縱則不可。","出師征之，其衆十旅。","軍其城下，告以福禍。","腹敗枝披，不敢保聚。","擲首陴外，降旛夜豎。","疆外之險，莫過蜀土。","韋臯去鎮，劉闢守後。","血人於牙，不肯吐口。","開庫啗士，曰隨所取。","汝張汝弓，汝鼓汝鼓。","汝爲表書，求我帥汝。","事始上聞，在列咸怒。","皇帝曰然，嗟遠士女。","苟附而安，則且付與。","讀命於庭，出節少府。","朝發京師，夕至其部。","闢喜謂黨，汝振而伍。","蜀可全有，此不當受。","萬牛臠炙，萬甕行酒。","以錦纏股，以紅帕首。","有恇其兇，有餌其誘。","其出穰穰，隊以萬數。","遂劫東川，遂據城阻。","皇帝曰嗟，其又可許。","爰命崇文，分卒禁禦。","有安其驅，無暴我野。","日行三十，徐壁其右。","闢黨聚謀，鹿頭是守。","崇文奉詔，進退規矩。","戰不貪殺，擒不濫數。","四方節度，整兵頓馬。","上章請討，俟命起坐。","皇帝曰嘻，無汝煩苦。","荆幷洎梁，在國門戶。","出師三千，各選爾醜。","四軍齊作，殷其如阜。","或拔其角，或脫其距。","長驅洋洋，無有齟齬。","八月壬午，闢棄城走。","載妻與妾，包裹稚乳。","是日崇文，入處其宇。","分散逐捕，搜原剔藪。","闢窮見窘，無地自處。","俯視大江，不見洲渚。","遂自顛倒，若杵投臼。","取之江中，枷脰械手。","婦女纍纍，啼哭拜叩。","來獻闕下，以告廟社。","周示城市，咸使觀覩。","解脫攣索，夾以砧斧。","婉婉弱子，赤立傴僂。","牽頭曳足，先斷腰膂。","次及其徒，體骸撐拄。","末乃取闢，駭汗如寫。","揮刀紛紜，爭刌膾脯。","優賞將吏，扶珪綴組。","帛堆其家，粟塞其庾。","哀憐陣沒，廩給孤寡。","贈官封墓，周帀宏溥。","經戰伐地，寬免租簿。","施令酬功，急疾如火。","天地中間，莫不順序。","幽恒青魏，東盡海浦。","南至徐蔡，區外雜虜。","怛威赧德，踧踖蹈舞。","掉棄兵革，私習簋簠。","來請來覲，十百其耦。","皇帝曰吁，伯父叔舅。","各安爾位，訓厥甿畮。","正月元日，初見宗祖。","躬執百禮，登降拜俯。","薦於新宮，視瞻梁梠。","慼見容色，淚落入俎。","侍祠之臣，助我惻楚。","乃以上辛，於郊用牡。","除於國南，鱗筍毛簴。","廬幕周施，開揭磊砢。","獸盾騰挐，圓壇帖妥。","天兵四羅，旂常婀娜。","駕龍十二，魚魚雅雅。","宵昇於丘，奠璧獻斝。","衆樂驚作，轟豗融冶。","紫焰噓呵，高靈下墮。","羣星從坐，錯落侈哆。","日君月妃，煥赫婐㛂。","瀆鬼濛鴻，嶽祗嶪峩。","飫沃羶薌，產祥降嘏。","鳳皇應奏，舒翼自拊。","赤麟黃龍，逶陀結糾。","卿士庶人，黃童白叟。","踴躍歡呀，失喜噎歐。","乾清坤夷，境落褰舉。","帝車回來，日正當午。","幸丹鳳門，大赦天下。","滌濯剗磢，磨滅瑕垢。","續功臣嗣，拔賢任耉。","孩養無告，仁滂施厚。","皇帝神聖，通達今古。","聽聰視明，一似堯禹。","生知法式，動得理所。","天錫皇帝，爲天下主。","幷包畜養，無異細鉅。","億載萬年，敢有違者。","皇帝儉勤，盥濯陶瓦。","斥遣浮華，好此綈紵。","勅戒四方，侈則有咎。","天錫皇帝，多麥與黍。","無召水旱，耗於雀鼠。","億載萬年，有富無窶。","皇帝正直，別白善否。","擅命而狂，既翦既去。","盡逐羣姦，靡有遺侶。","天錫皇帝，厖臣碩輔。","博問遐觀，以置左右。","億載萬年，無敢余侮。","皇帝大孝，慈祥悌友。","怡怡愉愉，奉太皇后。","浹於族親，濡及九有。","天錫皇帝，與天齊壽。","登茲太平，無怠永久。","億載萬年，爲父爲母。","博士臣愈，職是訓詁。","作爲歌詩，以配吉甫。"]', '["皇帝即阼，物無違拒。","曰暘而暘，曰雨而雨。","維是元年，有盜在夏。","欲覆其州，以踵近武。","皇帝曰嘻，豈不在我。","負鄙爲艱，縱則不可。","出師征之，其衆十旅。","軍其城下，告以福禍。","腹敗枝披，不敢保聚。","擲首陴外，降旛夜豎。","疆外之險，莫過蜀土。","韋臯去鎮，劉闢守後。","血人於牙，不肯吐口。","开庫啗士，曰隨所取。","汝張汝弓，汝鼓汝鼓。","汝爲表书，求我帥汝。","事始上闻，在列咸怒。","皇帝曰然，嗟远士女。","苟附而安，則且付與。","读命於庭，出節少府。","朝發京師，夕至其部。","闢喜謂黨，汝振而伍。","蜀可全有，此不當受。","万牛臠炙，万甕行酒。","以錦纏股，以紅帕首。","有恇其兇，有餌其誘。","其出穰穰，隊以万數。","遂劫东川，遂據城阻。","皇帝曰嗟，其又可許。","爰命崇文，分卒禁禦。","有安其驱，無暴我野。","日行三十，徐壁其右。","闢黨聚謀，鹿头是守。","崇文奉詔，進退規矩。","戰不貪殺，擒不濫數。","四方節度，整兵頓马。","上章請討，俟命起坐。","皇帝曰嘻，無汝煩苦。","荆幷洎梁，在国门戶。","出師三千，各選爾醜。","四軍齊作，殷其如阜。","或拔其角，或脫其距。","长驱洋洋，無有齟齬。","八月壬午，闢棄城走。","載妻與妾，包裹稚乳。","是日崇文，入处其宇。","分散逐捕，搜原剔藪。","闢窮见窘，無地自处。","俯視大江，不见洲渚。","遂自顛倒，若杵投臼。","取之江中，枷脰械手。","婦女纍纍，啼哭拜叩。","来獻闕下，以告廟社。","周示城市，咸使观覩。","解脫攣索，夾以砧斧。","婉婉弱子，赤立傴僂。","牽头曳足，先斷腰膂。","次及其徒，體骸撐拄。","末乃取闢，駭汗如寫。","揮刀紛紜，爭刌膾脯。","優賞將吏，扶珪綴組。","帛堆其家，粟塞其庾。","哀怜陣沒，廩給孤寡。","贈官封墓，周帀宏溥。","經戰伐地，寬免租簿。","施令酬功，急疾如火。","天地中间，莫不順序。","幽恒青魏，东尽海浦。","南至徐蔡，區外杂虜。","怛威赧德，踧踖蹈舞。","掉棄兵革，私習簋簠。","来請来覲，十百其耦。","皇帝曰吁，伯父叔舅。","各安爾位，訓厥甿畮。","正月元日，初见宗祖。","躬執百禮，登降拜俯。","薦於新宮，視瞻梁梠。","慼见容色，泪落入俎。","侍祠之臣，助我惻楚。","乃以上辛，於郊用牡。","除於国南，鱗筍毛簴。","廬幕周施，开揭磊砢。","獸盾腾挐，圓壇帖妥。","天兵四羅，旂常婀娜。","駕龙十二，鱼鱼雅雅。","宵昇於丘，奠璧獻斝。","衆乐驚作，轟豗融冶。","紫焰噓呵，高靈下墮。","羣星從坐，錯落侈哆。","日君月妃，煥赫婐㛂。","瀆鬼濛鴻，嶽祗嶪峩。","飫沃羶薌，產祥降嘏。","鳳皇應奏，舒翼自拊。","赤麟黄龙，逶陀結糾。","卿士庶人，黄童白叟。","踴躍歡呀，失喜噎歐。","乾清坤夷，境落褰舉。","帝车回来，日正當午。","幸丹鳳门，大赦天下。","滌濯剗磢，磨滅瑕垢。","續功臣嗣，拔賢任耉。","孩養無告，仁滂施厚。","皇帝神聖，通達今古。","听聰視明，一似堯禹。","生知法式，动得理所。","天錫皇帝，爲天下主。","幷包畜養，無異細鉅。","億載万年，敢有違者。","皇帝儉勤，盥濯陶瓦。","斥遣浮华，好此綈紵。","勅戒四方，侈則有咎。","天錫皇帝，多麦與黍。","無召水旱，耗於雀鼠。","億載万年，有富無窶。","皇帝正直，別白善否。","擅命而狂，既翦既去。","尽逐羣姦，靡有遺侶。","天錫皇帝，厖臣碩輔。","博问遐观，以置左右。","億載万年，無敢余侮。","皇帝大孝，慈祥悌友。","怡怡愉愉，奉太皇后。","浹於族親，濡及九有。","天錫皇帝，與天齊壽。","登茲太平，無怠永久。","億載万年，爲父爲母。","博士臣愈，職是訓詁。","作爲歌诗，以配吉甫。"]', '诗', 'shi', '', NULL, '元和聖德詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('654b2cd5-a026-4e0c-94a1-4353e22f66fe', '琴操十首', '琴操十首', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["秋之水兮，其色幽幽。","我將濟兮，不得其由。","涉其淺兮，石齧我足。","乘其深兮，龍入我舟。","我濟而悔兮，將安歸尤。","歸兮歸兮，無與石鬬兮，無應龍求。"]', '["秋之水兮，其色幽幽。","我將濟兮，不得其由。","涉其淺兮，石齧我足。","乘其深兮，龙入我舟。","我濟而悔兮，將安归尤。","归兮归兮，無與石鬬兮，無應龙求。"]', '诗', 'shi', '', NULL, '琴操十首 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b575e455-6047-48b7-9324-944c351954d9', '琴操十首', '琴操十首', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["蘭之猗猗，揚揚其香。","不採而佩，於蘭何傷。","今天之旋，其曷爲然。","我行四方，以日以年。","雪霜貿貿，薺麥之茂。","子如不傷，我不爾覯。","薺麥之茂，薺麥之有。","君子之傷，君子之守。"]', '["蘭之猗猗，揚揚其香。","不採而佩，於蘭何傷。","今天之旋，其曷爲然。","我行四方，以日以年。","雪霜貿貿，薺麦之茂。","子如不傷，我不爾覯。","薺麦之茂，薺麦之有。","君子之傷，君子之守。"]', '诗', 'shi', '', NULL, '琴操十首 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a346c963-e9c5-4eb9-a051-ce9713bd5aac', '琴操十首', '琴操十首', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["龜之氛兮，不能雲雨。","龜之枿兮，不中梁柱。","龜之大兮，祗以奄魯。","知將隳兮，哀莫余伍。","周公有鬼兮，嗟余歸輔。"]', '["龟之氛兮，不能云雨。","龟之枿兮，不中梁柱。","龟之大兮，祗以奄魯。","知將隳兮，哀莫余伍。","周公有鬼兮，嗟余归輔。"]', '诗', 'shi', '', NULL, '琴操十首 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d21c567b-1289-4d1d-9587-62086220f8e1', '琴操十首', '琴操十首', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["雨之施物以孳，我何意於彼爲。","自周之先，其艱其勤。","以有疆宇，私我後人。","我祖在上，四方在下。","厥臨孔威，敢戲以侮。","孰荒於門，孰治於田。","四海既均，越裳是臣。"]', '["雨之施物以孳，我何意於彼爲。","自周之先，其艱其勤。","以有疆宇，私我後人。","我祖在上，四方在下。","厥臨孔威，敢戲以侮。","孰荒於门，孰治於田。","四海既均，越裳是臣。"]', '诗', 'shi', '', NULL, '琴操十首 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82c329e7-e0e2-44ab-b767-b522a9eef1b3', '琴操十首', '琴操十首', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["目窈窈兮，其凝其盲。","耳肅肅兮，聽不聞聲。","朝不日出兮，夜不見月與星。","有知無知兮，爲死爲生。","嗚呼！臣罪當誅兮，天王聖明。"]', '["目窈窈兮，其凝其盲。","耳肅肅兮，听不闻声。","朝不日出兮，夜不见月與星。","有知無知兮，爲死爲生。","嗚呼！臣罪當誅兮，天王聖明。"]', '诗', 'shi', '', NULL, '琴操十首 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1cd230f-4948-445a-af00-52b2b8553815', '琴操十首', '琴操十首', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["我家於豳，自我先公。","伊我承序，敢有不同。","今狄之人，將土我疆。","民爲我戰，誰使死傷。","彼岐有岨，我往獨處。","爾莫余追，無思我悲。"]', '["我家於豳，自我先公。","伊我承序，敢有不同。","今狄之人，將土我疆。","民爲我戰，誰使死傷。","彼岐有岨，我往独处。","爾莫余追，無思我悲。"]', '诗', 'shi', '', NULL, '琴操十首 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8891be4-edc5-48ef-9720-42d2f9cc9557', '琴操十首', '琴操十首', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["父兮兒寒，母兮兒飢。","兒罪當笞，逐兒何爲。","兒在中野，以宿以處。","四無人聲，誰與兒語。","兒寒何衣，兒飢何食。","兒行於野，履霜以足。","母生衆兒，有母憐之。","獨無母憐，兒寧不悲。"]', '["父兮兒寒，母兮兒飢。","兒罪當笞，逐兒何爲。","兒在中野，以宿以处。","四無人声，誰與兒語。","兒寒何衣，兒飢何食。","兒行於野，履霜以足。","母生衆兒，有母怜之。","独無母怜，兒寧不悲。"]', '诗', 'shi', '', NULL, '琴操十首 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c04667c7-3b68-477e-9fd6-a4119e40fcca', '琴操十首', '琴操十首', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["雉之飛，於朝日。","羣雌孤雄，意氣橫出。","當東而西，當啄而飛。","隨飛隨啄，羣雌粥粥。","嗟我雖人，曾不如彼雉雞。","生身七十年，無一妾與妃。"]', '["雉之飞，於朝日。","羣雌孤雄，意氣橫出。","當东而西，當啄而飞。","隨飞隨啄，羣雌粥粥。","嗟我雖人，曾不如彼雉雞。","生身七十年，無一妾與妃。"]', '诗', 'shi', '', NULL, '琴操十首 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c6e4aa0-b89a-47ba-9b1e-df99778e0de5', '琴操十首', '琴操十首', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["雄鵠銜枝來，雌鵠啄泥歸。","巢成不生子，大義當乖離。","江漢水之大，鵠身鳥之微。","更無相逢日，且可繞樹相隨飛。"]', '["雄鵠銜枝来，雌鵠啄泥归。","巢成不生子，大義當乖離。","江漢水之大，鵠身鸟之微。","更無相逢日，且可繞樹相隨飞。"]', '诗', 'shi', '', NULL, '琴操十首 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41df718e-bcaf-4cef-8b2d-3ea668ddac93', '琴操十首', '琴操十首', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["有獸維貍兮，我夢得之。","其身孔明兮，而頭不知。","吉凶何爲兮，覺坐而思。","巫咸上天兮，識者其誰。"]', '["有獸維貍兮，我梦得之。","其身孔明兮，而头不知。","吉凶何爲兮，覺坐而思。","巫咸上天兮，識者其誰。"]', '诗', 'shi', '', NULL, '琴操十首 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6a2da11-7374-4d2c-abce-6029793c24e5', '南山詩', '南山诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["吾聞京城南，茲惟羣山囿。","東西兩際海，巨細難悉究。","山經及地志，茫昧非受授。","團辭試提挈，挂一念萬漏。","欲休諒不能，粗敘所經覯。","嘗昇崇丘望，戢戢見相湊。","晴明出稜角，縷脈碎分繡。","蒸嵐相澒洞，表裏忽通透。","無風自飄簸，融液煦柔茂。","橫雲時平凝，點點露數岫。","天空浮修眉，濃綠畫新就。","孤撐有巉絕，海浴褰鵬噣。","春陽潛沮洳，濯濯吐深秀。","巖巒雖嵂崒，軟弱類含酎。","夏炎百木盛，蔭鬱增埋覆。","神靈日歊歔，雲氣爭結構。","秋霜喜刻轢，磔卓立癯瘦。","參差相疊重，剛耿陵宇宙。","冬行雖幽墨，冰雪工琢鏤。","新曦照危峨，億丈恒高袤。","明昏無停態，頃刻異狀候。","西南雄太白，突起莫間簉。","藩都配德運，分宅占丁戊。","逍遙越坤位，詆訐陷乾竇。","空虛寒兢兢，風氣較搜漱。","朱維方燒日，陰霰縱騰糅。","昆明大池北，去覿偶晴晝。","緜聯窮俯視，倒側困清漚。","微瀾動水面，踴躍躁猱狖。","驚呼惜破碎，仰喜呀不仆。","前尋徑杜墅，岔蔽畢原陋。","崎嶇上軒昂，始得觀覽富。","行行將遂窮，嶺陸煩互走。","勃然思坼裂，擁掩難恕宥。","巨靈與夸蛾，遠賈期必售。","還疑造物意，固護蓄精祐。","力雖能排斡，雷電怯呵詬。","攀緣脫手足，蹭蹬抵積甃。","茫如試矯首，堛塞生怐愗。","威容喪蕭爽，近新迷遠舊。","拘官計日月，欲進不可又。","因緣窺其湫，凝湛閟陰嘼。","魚蝦可俯掇，神物安敢寇。","林柯有脫葉，欲墮鳥驚救。","爭銜彎環飛，投棄急哺鷇。","旋歸道回睨，達枿壯復奏。","吁嗟信奇怪，峙質能化貿。","前年遭譴謫，探歷得邂逅。","初從藍田入，顧盻勞頸脰。","時天晦大雪，淚目苦矇瞀。","峻塗拖長冰，直上若懸溜。","褰衣步推馬，顛蹶退且復。","蒼黃忘遐睎，所矚纔左右。","杉篁咤蒲蘇，杲耀攢介胄。","專心憶平道，脫險逾避臭。","昨來逢清霽，宿願忻始副。","崢嶸躋冢頂，倏閃雜鼯鼬。","前低劃開闊，爛漫堆衆皺。","或連若相從，或蹙若相鬬。","或妥若弭伏，或竦若驚雊。","或散若瓦解，或赴若輻湊。","或翩若船遊，或決若馬驟。","或背若相惡，或向若相佑。","或亂若抽筍，或嵲若注灸。","或錯若繪畫，或繚若篆籀。","或羅若星離，或蓊若雲逗。","或浮若波濤，或碎若鋤耨。","或如賁育倫，賭勝勇前購。","先強勢已出，後鈍嗔䛠譳。","或如帝王尊，叢集朝賤幼。","雖親不褻狎，雖遠不悖謬。","或如臨食案，肴核紛飣餖。","又如遊九原，墳墓包槨柩。","或纍若盆甖，或揭若㽅豆。","或覆若曝鼈，或頹若寢獸。","或蜿若藏龍，或翼若搏鷲。","或齊若友朋，或隨若先後。","或迸若流落，或顧若宿留。","或戾若仇讐，或密若婚媾。","或儼若峩冠，或翻若舞袖。","或屹若戰陣，或圍若蒐狩。","或靡然東注，或偃然北首。","或如火熺焰，或若氣饙餾。","或行而不輟，或遺而不收。","或斜而不倚，或弛而不彀。","或赤若禿鬝，或燻若柴槱。","或如龜拆兆，或若卦分繇。","或前橫若剝，或後斷若姤。","延延離又屬，夬夬叛還遘。","喁喁魚闖萍，落落月經宿。","誾誾樹牆垣，巘巘駕庫廄。","參參削劍戟，煥煥銜瑩琇。","敷敷花披萼，闟闟屋摧霤。","悠悠舒而安，兀兀狂以狃。","超超出猶奔，蠢蠢駭不懋。","大哉立天地，經紀肖營腠。","厥初孰開張，僶俯誰勸侑。","創茲樸而巧，戮力忍勞疚。","得非施斧斤，無乃假詛咒。","鴻荒竟無傳，功大莫酬僦。","嘗聞於祠官，芬苾降歆嗅。","斐然作歌詩，惟用贊報酭。"]', '["吾闻京城南，茲惟羣山囿。","东西兩際海，巨細难悉究。","山經及地志，茫昧非受授。","團辞試提挈，挂一念万漏。","欲休諒不能，粗敘所經覯。","嘗昇崇丘望，戢戢见相湊。","晴明出稜角，縷脈碎分繡。","蒸嵐相澒洞，表裏忽通透。","無风自飄簸，融液煦柔茂。","橫云时平凝，点点露數岫。","天空浮修眉，濃綠畫新就。","孤撐有巉絕，海浴褰鵬噣。","春陽潛沮洳，濯濯吐深秀。","巖巒雖嵂崒，軟弱類含酎。","夏炎百木盛，蔭鬱增埋覆。","神靈日歊歔，云氣爭結構。","秋霜喜刻轢，磔卓立癯瘦。","參差相叠重，剛耿陵宇宙。","冬行雖幽墨，冰雪工琢鏤。","新曦照危峨，億丈恒高袤。","明昏無停態，頃刻異狀候。","西南雄太白，突起莫间簉。","藩都配德運，分宅占丁戊。","逍遙越坤位，詆訐陷乾竇。","空虛寒兢兢，风氣較搜漱。","朱維方燒日，陰霰縱腾糅。","昆明大池北，去覿偶晴晝。","緜聯窮俯視，倒側困清漚。","微瀾动水面，踴躍躁猱狖。","驚呼惜破碎，仰喜呀不仆。","前尋徑杜墅，岔蔽畢原陋。","崎嶇上軒昂，始得观覽富。","行行將遂窮，嶺陸煩互走。","勃然思坼裂，擁掩难恕宥。","巨靈與夸蛾，远賈期必售。","還疑造物意，固護蓄精祐。","力雖能排斡，雷電怯呵詬。","攀緣脫手足，蹭蹬抵積甃。","茫如試矯首，堛塞生怐愗。","威容喪蕭爽，近新迷远旧。","拘官計日月，欲進不可又。","因緣窺其湫，凝湛閟陰嘼。","鱼蝦可俯掇，神物安敢寇。","林柯有脫葉，欲墮鸟驚救。","爭銜彎环飞，投棄急哺鷇。","旋归道回睨，達枿壯复奏。","吁嗟信奇怪，峙質能化貿。","前年遭譴謫，探歷得邂逅。","初從藍田入，顧盻勞頸脰。","时天晦大雪，泪目苦矇瞀。","峻塗拖长冰，直上若懸溜。","褰衣步推马，顛蹶退且复。","蒼黄忘遐睎，所矚纔左右。","杉篁咤蒲蘇，杲耀攢介胄。","專心憶平道，脫險逾避臭。","昨来逢清霽，宿願忻始副。","崢嶸躋冢頂，倏閃杂鼯鼬。","前低劃开闊，爛漫堆衆皺。","或連若相從，或蹙若相鬬。","或妥若弭伏，或竦若驚雊。","或散若瓦解，或赴若輻湊。","或翩若船游，或決若马驟。","或背若相惡，或向若相佑。","或亂若抽筍，或嵲若注灸。","或錯若繪畫，或繚若篆籀。","或羅若星離，或蓊若云逗。","或浮若波濤，或碎若鋤耨。","或如賁育倫，賭勝勇前購。","先強勢已出，後鈍嗔䛠譳。","或如帝王尊，叢集朝賤幼。","雖親不褻狎，雖远不悖謬。","或如臨食案，肴核紛飣餖。","又如游九原，墳墓包槨柩。","或纍若盆甖，或揭若㽅豆。","或覆若曝鼈，或頹若寢獸。","或蜿若藏龙，或翼若搏鷲。","或齊若友朋，或隨若先後。","或迸若流落，或顧若宿留。","或戾若仇讐，或密若婚媾。","或儼若峩冠，或翻若舞袖。","或屹若戰陣，或圍若蒐狩。","或靡然东注，或偃然北首。","或如火熺焰，或若氣饙餾。","或行而不輟，或遺而不收。","或斜而不倚，或弛而不彀。","或赤若禿鬝，或燻若柴槱。","或如龟拆兆，或若卦分繇。","或前橫若剝，或後斷若姤。","延延離又屬，夬夬叛還遘。","喁喁鱼闖萍，落落月經宿。","誾誾樹牆垣，巘巘駕庫廄。","參參削劍戟，煥煥銜瑩琇。","敷敷花披萼，闟闟屋摧霤。","悠悠舒而安，兀兀狂以狃。","超超出猶奔，蠢蠢駭不懋。","大哉立天地，經紀肖營腠。","厥初孰开張，僶俯誰勸侑。","創茲樸而巧，戮力忍勞疚。","得非施斧斤，無乃假詛咒。","鴻荒竟無傳，功大莫酬僦。","嘗闻於祠官，芬苾降歆嗅。","斐然作歌诗，惟用贊報酭。"]', '诗', 'shi', '', NULL, '南山詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba5fed4-43d1-4d38-a68e-a791b68c2a9e', '謝自然詩', '謝自然诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["果州南充縣，寒女謝自然。","童騃無所識，但聞有神僊。","輕生學其術，乃在金泉山。","繁華榮慕絕，父母慈愛捐。","凝心感魑魅，慌惚難具言。","一朝坐空室，雲霧生其間。","如聆笙竽韻，來自冥冥天。","白日變幽晦，蕭蕭風景寒。","簷楹蹔明滅，五色光屬聯。","觀者徒傾駭，躑躅詎敢前。","須臾自輕舉，飄若風中煙。","茫茫八紘大，影響無由緣。","里胥上其事，郡守驚且歎。","驅車領官吏，甿俗爭相先。","入門無所見，冠履同蛻蟬。","皆云神僊事，灼灼信可傳。","余聞古夏后，象物知神姦。","山林民可入，魍魎莫逢旃。","逶迤不復振，後世恣欺謾。","幽明紛雜亂，人鬼更相殘。","秦皇雖篤好，漢武洪其源。","自從二主來，此禍竟連連。","木石生怪變，狐貍騁妖患。","莫能盡性命，安得更長延。","人生處萬類，知識最爲賢。","奈何不自信，反欲從物遷。","往者不可悔，孤魂抱深冤。","來者猶可誡，余言豈空文。","人生有常理，男女各有倫。","寒衣及飢食，在紡績耕耘。","下以保子孫，上以奉君親。","苟異於此道，皆爲棄其身。","噫乎彼寒女，永託異物羣。","感傷遂成詩，昧者宜書紳。"]', '["果州南充縣，寒女謝自然。","童騃無所識，但闻有神僊。","轻生学其術，乃在金泉山。","繁华榮慕絕，父母慈愛捐。","凝心感魑魅，慌惚难具言。","一朝坐空室，云霧生其间。","如聆笙竽韻，来自冥冥天。","白日变幽晦，蕭蕭风景寒。","簷楹蹔明滅，五色光屬聯。","观者徒傾駭，躑躅詎敢前。","須臾自轻舉，飄若风中煙。","茫茫八紘大，影响無由緣。","里胥上其事，郡守驚且歎。","驱车領官吏，甿俗爭相先。","入门無所见，冠履同蛻蟬。","皆云神僊事，灼灼信可傳。","余闻古夏后，象物知神姦。","山林民可入，魍魎莫逢旃。","逶迤不复振，後世恣欺謾。","幽明紛杂亂，人鬼更相殘。","秦皇雖篤好，漢武洪其源。","自從二主来，此禍竟連連。","木石生怪变，狐貍騁妖患。","莫能尽性命，安得更长延。","人生处万類，知識最爲賢。","奈何不自信，反欲從物遷。","往者不可悔，孤魂抱深冤。","来者猶可誡，余言豈空文。","人生有常理，男女各有倫。","寒衣及飢食，在紡績耕耘。","下以保子孫，上以奉君親。","苟異於此道，皆爲棄其身。","噫乎彼寒女，永託異物羣。","感傷遂成诗，昧者宜书紳。"]', '诗', 'shi', '', NULL, '謝自然詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03afc4d5-6c21-4d39-b6f8-2b3065f74216', '秋懷詩十一首 一', '秋懷诗十一首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["窗前兩好樹，衆葉光薿薿。","秋風一拂披，策策鳴不已。","微燈照空牀，夜半偏入耳。","愁憂無端來，感歎成坐起。","天明視顏色，與故不相似。","羲和驅日月，疾急不可恃。","浮生雖多塗，趨死惟一軌。","胡爲浪自苦，得酒且歡喜。"]', '["窗前兩好樹，衆葉光薿薿。","秋风一拂披，策策鳴不已。","微灯照空牀，夜半偏入耳。","愁憂無端来，感歎成坐起。","天明視顏色，與故不相似。","羲和驱日月，疾急不可恃。","浮生雖多塗，趨死惟一軌。","胡爲浪自苦，得酒且歡喜。"]', '诗', 'shi', '', NULL, '秋懷詩十一首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b831d2-e67b-442e-95d6-88f2247bfa0a', '秋懷詩十一首 二', '秋懷诗十一首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["白露下百草，蕭蘭共雕悴。","青青四牆下，已復生滿地。","寒蟬暫寂寞，蟋蟀鳴自恣。","運行無窮期，稟受氣苦異。","適時各得所，松栢不必貴。"]', '["白露下百草，蕭蘭共雕悴。","青青四牆下，已复生满地。","寒蟬暫寂寞，蟋蟀鳴自恣。","運行無窮期，稟受氣苦異。","適时各得所，松栢不必貴。"]', '诗', 'shi', '', NULL, '秋懷詩十一首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3791123-b34e-48cf-a640-e28e3d52609f', '秋懷詩十一首 三', '秋懷诗十一首 三', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["彼時何卒卒，我志何曼曼。","犀首空好飲，廉頗尚能飯。","學堂日無事，驅馬適所願。","茫茫出門路，欲去聊自勸。","歸還閱書史，文字浩千萬。","陳跡竟誰尋，賤嗜非貴獻。","丈夫意有在，女子乃多怨。"]', '["彼时何卒卒，我志何曼曼。","犀首空好饮，廉頗尚能飯。","学堂日無事，驱马適所願。","茫茫出门路，欲去聊自勸。","归還閱书史，文字浩千万。","陳跡竟誰尋，賤嗜非貴獻。","丈夫意有在，女子乃多怨。"]', '诗', 'shi', '', NULL, '秋懷詩十一首 三 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ceb6a0-47e1-436d-bb9a-adbcda63dd80', '秋懷詩十一首 四', '秋懷诗十一首 四', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["秋氣日惻惻，秋空日凌凌。","上無枝上蜩，下無盤中蠅。","豈不感時節，耳目去所憎。","清曉卷書坐，南山見高稜。","其下澄湫水，有蛟寒可罾。","惜哉不得往，豈謂吾無能。"]', '["秋氣日惻惻，秋空日凌凌。","上無枝上蜩，下無盤中蠅。","豈不感时節，耳目去所憎。","清晓卷书坐，南山见高稜。","其下澄湫水，有蛟寒可罾。","惜哉不得往，豈謂吾無能。"]', '诗', 'shi', '', NULL, '秋懷詩十一首 四 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddf17534-3921-4fa9-bbff-258ef28fa1ee', '秋懷詩十一首 五', '秋懷诗十一首 五', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["離離挂空悲，慼慼抱虛警。","露泫秋樹高，蟲弔寒夜永。","歛退就新懦，趨營悼前猛。","歸愚識夷塗，汲古得修綆。","名浮猶有耻，味薄真自幸。","庶幾遺悔尤，即此是幽屏。"]', '["離離挂空悲，慼慼抱虛警。","露泫秋樹高，蟲弔寒夜永。","歛退就新懦，趨營悼前猛。","归愚識夷塗，汲古得修綆。","名浮猶有耻，味薄真自幸。","庶幾遺悔尤，即此是幽屏。"]', '诗', 'shi', '', NULL, '秋懷詩十一首 五 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b885b956-4a98-4db3-8095-236c932c5c06', '秋懷詩十一首 六', '秋懷诗十一首 六', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["今晨不成起，端坐盡日景。","蟲鳴室幽幽，月吐窗冏冏。","喪懷若迷方，浮念劇含梗。","塵埃慵伺候，文字浪馳騁。","尚須勉其頑，王事有朝請。"]', '["今晨不成起，端坐尽日景。","蟲鳴室幽幽，月吐窗冏冏。","喪懷若迷方，浮念劇含梗。","塵埃慵伺候，文字浪驰騁。","尚須勉其頑，王事有朝請。"]', '诗', 'shi', '', NULL, '秋懷詩十一首 六 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9907f486-7772-410b-8c3e-70bd19cdbe0d', '秋懷詩十一首 七', '秋懷诗十一首 七', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["秋夜不可晨，秋日苦易暗。","我無汲汲志，何以有此憾。","寒雞空在棲，缺月煩屢瞰。","有琴具徽絃，再鼓聽愈淡。","古聲久埋滅，無由見真濫。","低心逐時趨，苦勉祗能暫。","有如乘風船，一縱不可纜。","不如覰文字，丹鉛事點勘。","豈必求贏餘，所要石與甔。"]', '["秋夜不可晨，秋日苦易暗。","我無汲汲志，何以有此憾。","寒雞空在棲，缺月煩屢瞰。","有琴具徽絃，再鼓听愈淡。","古声久埋滅，無由见真濫。","低心逐时趨，苦勉祗能暫。","有如乘风船，一縱不可纜。","不如覰文字，丹鉛事点勘。","豈必求贏餘，所要石與甔。"]', '诗', 'shi', '', NULL, '秋懷詩十一首 七 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0476e322-b94e-4a68-85fe-972017812b8d', '秋懷詩十一首 八', '秋懷诗十一首 八', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["卷卷落地葉，隨風走前軒。","鳴聲若有意，顛倒相追奔。","空堂黃昏暮，我坐默不言。","童子自外至，吹燈當我前。","問我我不應，饋我我不餐。","退坐西壁下，讀詩盡數編。","作者非今士，相去時已千。","其言有感觸，使我復悽酸。","願謂汝童子，置書且安眠。","丈夫屬有念，事業無窮年。"]', '["卷卷落地葉，隨风走前軒。","鳴声若有意，顛倒相追奔。","空堂黄昏暮，我坐默不言。","童子自外至，吹灯當我前。","问我我不應，饋我我不餐。","退坐西壁下，读诗尽數編。","作者非今士，相去时已千。","其言有感觸，使我复悽酸。","願謂汝童子，置书且安眠。","丈夫屬有念，事業無窮年。"]', '诗', 'shi', '', NULL, '秋懷詩十一首 八 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('741bfdb1-9279-4bb5-977f-0b063dcd43db', '秋懷詩十一首 九', '秋懷诗十一首 九', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["霜風侵梧桐，衆葉著樹乾。","空堦一片下，琤若摧琅玕。","謂是夜氣滅，望舒霣其團。","青冥無依倚，飛轍危難安。","驚起出戶視，倚楹久汍瀾。","憂愁費晷景，日月如跳丸。","迷復不計遠，爲君駐塵鞍。"]', '["霜风侵梧桐，衆葉著樹乾。","空堦一片下，琤若摧琅玕。","謂是夜氣滅，望舒霣其團。","青冥無依倚，飞轍危难安。","驚起出戶視，倚楹久汍瀾。","憂愁費晷景，日月如跳丸。","迷复不計远，爲君駐塵鞍。"]', '诗', 'shi', '', NULL, '秋懷詩十一首 九 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f2ec192-f117-4f53-a433-844d8f56052e', '秋懷詩十一首 十', '秋懷诗十一首 十', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["暮暗來客去，羣囂各收聲。","悠悠偃宵寂，斖斖抱秋明。","世累忽進慮，外憂遂侵誠。","強懷張不滿，弱念缺已盈。","詰屈避語穽，冥茫觸心兵。","敗虞千金棄，得比寸草榮。","知耻足爲勇，晏然誰汝令。"]', '["暮暗来客去，羣囂各收声。","悠悠偃宵寂，斖斖抱秋明。","世累忽進慮，外憂遂侵誠。","強懷張不满，弱念缺已盈。","詰屈避語穽，冥茫觸心兵。","敗虞千金棄，得比寸草榮。","知耻足爲勇，晏然誰汝令。"]', '诗', 'shi', '', NULL, '秋懷詩十一首 十 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11fe203c-8fbb-4287-b319-0eff081a3e1c', '秋懷詩十一首 十一', '秋懷诗十一首 十一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["鮮鮮霜中菊，既晚何用好。","揚揚弄芳蝶，爾生還不早。","運窮兩值遇，婉孌死相保。","西風蟄龍蛇，衆木日凋槁。","由來命分爾，泯滅豈足道。"]', '["鲜鲜霜中菊，既晚何用好。","揚揚弄芳蝶，爾生還不早。","運窮兩值遇，婉孌死相保。","西风蟄龙蛇，衆木日凋槁。","由来命分爾，泯滅豈足道。"]', '诗', 'shi', '', NULL, '秋懷詩十一首 十一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c325ca32-5efc-4c90-89d3-853ca1782713', '赴江陵途中寄贈王二十補闕李十一拾遺李二十六員外翰林三學士', '赴江陵途中寄贈王二十補闕李十一拾遺李二十六員外翰林三学士', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["孤臣昔放逐，血泣追愆尤。","汗漫不省識，怳如乘桴浮。","或自疑上疏，上疏豈其由。","是年京師旱，田畝少所收。","上憐民無食，征賦半已休。","有司恤經費，未免煩徵求。","富者既云急，貧者固已流。","傳聞閭里間，赤子棄渠溝。","持男易斗粟，掉臂莫肯酬。","我時出衢路，餓者何其稠。","親逢道邊死，佇立久咿嚘。","歸舍不能食，有如魚中鉤。","適會除御史，誠當得言秋。","拜疏移閤門，爲忠寧自謀。","上陳人疾苦，無令絕其喉。","下陳畿甸內，根本理宜優。","積雪騐豐熟，幸寬待蠶麰。","天子惻然感，司空歎綢繆。","謂言即施設，乃反遷炎州。","同官盡才俊，偏善柳與劉。","或慮語言洩，傳之落冤讐。","二子不宜爾，將疑斷還不。","中使臨門遣，頃刻不得留。","病妹臥牀褥，分知隔明幽。","悲啼乞就別，百請不頷頭。","弱妻抱稚子，出拜忘慚羞。","僶俛不回顧，行行詣連州。","朝爲青雲士，暮作白頭囚。","商山季冬月，冰凍絕行輈。","春風洞庭浪，出沒驚孤舟。","逾嶺到所任，低顏奉君侯。","酸寒何足道，隨事生瘡疣。","遠地觸途異，吏民似猨猴。","生獰多忿很，辭舌紛嘲啁。","白日屋簷下，雙鳴鬬鵂鶹。","有蛇類兩首，有蠱羣飛遊。","窮冬或搖扇，盛夏或重裘。","颶起最可畏，訇哮簸陵丘。","雷霆助光怪，氣象難比侔。","癘疫忽潛遘，十家無一瘳。","猜嫌動置毒，對案輙懷愁。","前日遇恩赦，私心喜還憂。","果然又羈縶，不得歸鋤耰。","此府雄且大，騰凌盡戈矛。","棲棲法曹掾，何處事卑陬。","生平企仁義，所學皆孔周。","早知大理官，不列三后儔。","何況親犴獄，敲搒發姦偷。","懸知失事勢，恐自罹罝罘。","湘水清且急，涼風日脩脩。","胡爲首歸路，旅泊尚夷猶。","昨者京使至，嗣皇傳冕旒。","赫然下明詔，首罪誅共吺。","復聞顛夭輩，峨冠進鴻疇。","班行再肅穆，璜珮鳴琅璆。","佇繼貞觀烈，邊封脫兜鍪。","三賢推侍從，卓犖傾枚鄒。","高議參造化，清文煥皇猷。","協心輔齊聖，致理同毛輶。","小雅詠鹿鳴，食苹貴呦呦。","遺風邈不嗣，豈憶嘗同裯。","失志早衰換，前期擬蜉蝣。","自從齒牙缺，始慕舌爲柔。","因疾鼻又塞，漸能等薰蕕。","深思罷官去，畢命依松楸。","空懷焉能果，但見歲已遒。","殷湯閔禽獸，解網祝蛛蝥。","雷煥掘寶劍，冤氛消斗牛。","茲道誠可尚，誰能借前籌。","殷勤答吾友，明月非暗投。"]', '["孤臣昔放逐，血泣追愆尤。","汗漫不省識，怳如乘桴浮。","或自疑上疏，上疏豈其由。","是年京師旱，田畝少所收。","上怜民無食，征賦半已休。","有司恤經費，未免煩徵求。","富者既云急，貧者固已流。","傳闻閭里间，赤子棄渠溝。","持男易斗粟，掉臂莫肯酬。","我时出衢路，餓者何其稠。","親逢道邊死，佇立久咿嚘。","归舍不能食，有如鱼中鉤。","適會除御史，誠當得言秋。","拜疏移閤门，爲忠寧自謀。","上陳人疾苦，無令絕其喉。","下陳畿甸內，根本理宜優。","積雪騐豐熟，幸寬待蠶麰。","天子惻然感，司空歎綢繆。","謂言即施設，乃反遷炎州。","同官尽才俊，偏善柳與劉。","或慮語言洩，傳之落冤讐。","二子不宜爾，將疑斷還不。","中使臨门遣，頃刻不得留。","病妹臥牀褥，分知隔明幽。","悲啼乞就別，百請不頷头。","弱妻抱稚子，出拜忘慚羞。","僶俛不回顧，行行詣連州。","朝爲青云士，暮作白头囚。","商山季冬月，冰凍絕行輈。","春风洞庭浪，出沒驚孤舟。","逾嶺到所任，低顏奉君侯。","酸寒何足道，隨事生瘡疣。","远地觸途異，吏民似猨猴。","生獰多忿很，辞舌紛嘲啁。","白日屋簷下，雙鳴鬬鵂鶹。","有蛇類兩首，有蠱羣飞游。","窮冬或搖扇，盛夏或重裘。","颶起最可畏，訇哮簸陵丘。","雷霆助光怪，氣象难比侔。","癘疫忽潛遘，十家無一瘳。","猜嫌动置毒，对案輙懷愁。","前日遇恩赦，私心喜還憂。","果然又羈縶，不得归鋤耰。","此府雄且大，腾凌尽戈矛。","棲棲法曹掾，何处事卑陬。","生平企仁義，所学皆孔周。","早知大理官，不列三后儔。","何況親犴獄，敲搒發姦偷。","懸知失事勢，恐自罹罝罘。","湘水清且急，涼风日脩脩。","胡爲首归路，旅泊尚夷猶。","昨者京使至，嗣皇傳冕旒。","赫然下明詔，首罪誅共吺。","复闻顛夭輩，峨冠進鴻疇。","班行再肅穆，璜珮鳴琅璆。","佇繼貞观烈，邊封脫兜鍪。","三賢推侍從，卓犖傾枚鄒。","高議參造化，清文煥皇猷。","協心輔齊聖，致理同毛輶。","小雅詠鹿鳴，食苹貴呦呦。","遺风邈不嗣，豈憶嘗同裯。","失志早衰換，前期擬蜉蝣。","自從齒牙缺，始慕舌爲柔。","因疾鼻又塞，漸能等薰蕕。","深思罷官去，畢命依松楸。","空懷焉能果，但见歲已遒。","殷湯閔禽獸，解網祝蛛蝥。","雷煥掘寶劍，冤氛消斗牛。","茲道誠可尚，誰能借前籌。","殷勤答吾友，明月非暗投。"]', '诗', 'shi', '', NULL, '赴江陵途中寄贈王二十補闕李十一拾遺李二十六員外翰林三學士 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac10786c-b760-4114-bc0a-ef4b4a8169f1', '暮行河堤上', '暮行河堤上', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["暮行河堤上，四顧不見人。","衰草際黃雲，感歎愁我神。","夜歸孤舟臥，展轉空及晨。","謀計竟何就，嗟嗟世與身。"]', '["暮行河堤上，四顧不见人。","衰草際黄云，感歎愁我神。","夜归孤舟臥，展轉空及晨。","謀計竟何就，嗟嗟世與身。"]', '诗', 'shi', '', NULL, '暮行河堤上 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5d58781-aacb-4f28-b3c2-03c8b81d820c', '夜歌', '夜歌', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["靜夜有清光，閑堂仍獨息。","念身幸無恨，志氣方自得。","樂哉何所憂，所憂非我力。"]', '["静夜有清光，闲堂仍独息。","念身幸無恨，志氣方自得。","乐哉何所憂，所憂非我力。"]', '诗', 'shi', '', NULL, '夜歌 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e99bb3c6-6ea1-4d0c-b50d-dd9c9a401566', '重雲李觀疾贈之', '重云李观疾贈之', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["天行失其度，陰氣來干陽。","重雲閉白日，炎燠成寒涼。","小人但咨怨，君子惟憂傷。","飲食爲減少，身體豈寧康。","此志誠足貴，懼非職所當。","藜羹尚如此，肉食安可嘗。","窮冬百草死，幽桂乃芬芳。","且況天地間，大運自有常。","勸君善飲食，鸞鳳本高翔。"]', '["天行失其度，陰氣来干陽。","重云閉白日，炎燠成寒涼。","小人但咨怨，君子惟憂傷。","饮食爲減少，身體豈寧康。","此志誠足貴，懼非職所當。","藜羹尚如此，肉食安可嘗。","窮冬百草死，幽桂乃芬芳。","且況天地间，大運自有常。","勸君善饮食，鸾鳳本高翔。"]', '诗', 'shi', '', NULL, '重雲李觀疾贈之 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd67771f-6ce5-4d1a-bf33-b9aeae8cf25b', '江漢答孟郊', '江漢答孟郊', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["江漢雖云廣，乘舟渡無艱。","流沙信難行，馬足常往還。","淒風結衝波，狐裘能禦寒。","終宵處幽室，華燭光爛爛。","苟能行忠信，可以居夷蠻。","嗟余與夫子，此義每所敦。","何爲復見贈，繾綣在不諼。"]', '["江漢雖云廣，乘舟渡無艱。","流沙信难行，马足常往還。","淒风結衝波，狐裘能禦寒。","終宵处幽室，华燭光爛爛。","苟能行忠信，可以居夷蠻。","嗟余與夫子，此義每所敦。","何爲复见贈，繾綣在不諼。"]', '诗', 'shi', '', NULL, '江漢答孟郊 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d39658f3-b254-4985-abf0-48751db03198', '長安交遊者贈孟郊', '长安交游者贈孟郊', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["長安交遊者，貧富各有徒。","親朋相過時，亦各有以娛。","陋室有文史，高門有笙竽。","何能辨榮悴，且欲分賢愚。"]', '["长安交游者，貧富各有徒。","親朋相過时，亦各有以娛。","陋室有文史，高门有笙竽。","何能辨榮悴，且欲分賢愚。"]', '诗', 'shi', '', NULL, '長安交遊者贈孟郊 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a4d16e-ae4f-4e05-b202-2e87d05ddb2f', '岐山下二首 一', '岐山下二首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["誰謂我有耳，不聞鳳皇鳴。","朅來岐山下，日暮邊鴻驚。"]', '["誰謂我有耳，不闻鳳皇鳴。","朅来岐山下，日暮邊鴻驚。"]', '诗', 'shi', '', NULL, '岐山下二首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dc40063-1872-4321-9f83-dd57dd94c52e', '岐山下二首 二', '岐山下二首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["丹穴五色羽，其名爲鳳皇。","昔周有盛德，此鳥鳴高岡。","和聲隨祥風，窅窕相飄揚。","聞者亦何事，但知時俗康。","自從公旦死，千載閟其光。","吾君亦勤理，遲爾一來翔。"]', '["丹穴五色羽，其名爲鳳皇。","昔周有盛德，此鸟鳴高岡。","和声隨祥风，窅窕相飄揚。","闻者亦何事，但知时俗康。","自從公旦死，千載閟其光。","吾君亦勤理，遲爾一来翔。"]', '诗', 'shi', '', NULL, '岐山下二首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fce632a-061a-469b-b5f8-7dd73ba93127', '北極贈李觀', '北極贈李观', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["北極有羈羽，南溟有沈鱗。","川源浩浩隔，影響兩無因。","風雲一朝會，變化成一身。","誰言道里遠，感激疾如神。","我年二十五，求友昧其人。","哀歌西京市，乃與夫子親。","所尚苟同趨，賢愚豈異倫。","方爲金石姿，萬世無緇磷。","無爲兒女態，憔悴悲賤貧。"]', '["北極有羈羽，南溟有沈鱗。","川源浩浩隔，影响兩無因。","风云一朝會，变化成一身。","誰言道里远，感激疾如神。","我年二十五，求友昧其人。","哀歌西京市，乃與夫子親。","所尚苟同趨，賢愚豈異倫。","方爲金石姿，万世無緇磷。","無爲兒女態，憔悴悲賤貧。"]', '诗', 'shi', '', NULL, '北極贈李觀 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c70ab6f4-5915-40f9-84c3-beaefa04c55b', '此日足可惜贈張籍', '此日足可惜贈張籍', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["此日足可惜，此酒不足嘗。","捨酒去相語，共分一日光。","念昔未知子，孟君自南方。","自矜有所得，言子有文章。","我名屬相府，欲往不得行。","思之不可見，百端在中腸。","維時月魄死，冬日朝在房。","驅馳公事退，聞子適及城。","命車載之至，引坐於中堂。","開懷聽其說，往往副所望。","孔丘歿已遠，仁義路久荒。","紛紛百家起，詭怪相披猖。","長老守所聞，後生習爲常。","少知誠難得，純粹古已亡。","譬彼植園木，有根易爲長。","留之不遣去，館置城西旁。","歲時未云幾，浩浩觀湖江。","衆夫指之笑，謂我知不明。","兒童畏雷電，魚鼈驚夜光。","州家舉進士，選試繆所當。","馳辭對我策，章句何煒煌。","相公朝服立，工席歌鹿鳴。","禮終樂亦闋，相拜送於庭。","之子去須臾，赫赫流盛名。","竊喜復竊歎，諒知有所成。","人事安可恒，奄忽令我傷。","聞子高第日，正從相公喪。","哀情逢吉語，惝怳難爲雙。","暮宿偃師西，徒展轉在牀。","夜聞汴州亂，遶壁行徬徨。","我時留妻子，倉卒不及將。","相見不復期，零落甘所丁。","驕兒未絕乳，念之不能忘。","忽如在我所，耳若聞啼聲。","中途安得返，一日不可更。","俄有東來說，我家免罹殃。","乘船下汴水，東去趨彭城。","從喪朝至洛，還走不及停。","假道經盟津，出入行澗岡。","日西入軍門，羸馬顛且僵。","主人願少留，延入陳壺觴。","卑賤不敢辭，忽忽心如狂。","飲食豈知味，絲竹徒轟轟。","平明脫身去，決若驚鳧翔。","黃昏次汜水，欲過無舟航。","號呼久乃至，夜濟十里黃。","中流上灘潬，沙水不可詳。","驚波暗合沓，星宿爭翻芒。","轅馬蹢躅鳴，左右泣僕童。","甲午憩時門，臨泉窺鬬龍。","東南出陳許，陂澤平茫茫。","道邊草木花，紅紫相低昂。","百里不逢人，角角雄雉鳴。","行行二月暮，乃及徐南疆。","下馬步堤岸，上船拜吾兄。","誰云經艱難，百口無夭殤。","僕射南陽公，宅我睢水陽。","篋中有餘衣，盎中有餘糧。","閉門讀書史，窗戶忽已涼。","日念子來遊，子豈知我情。","別離未爲久，辛苦多所經。","對食每不飽，共言無倦聽。","連延三十日，晨坐達五更。","我友二三子，宦遊在西京。","東野窺禹穴，李翱觀濤江。","蕭條千萬里，會合安可逢。","淮之水舒舒，楚山直叢叢。","子又捨我去，我懷焉所窮。","男兒不再壯，百歲如風狂。","高爵尚可求，無爲守一鄉。"]', '["此日足可惜，此酒不足嘗。","捨酒去相語，共分一日光。","念昔未知子，孟君自南方。","自矜有所得，言子有文章。","我名屬相府，欲往不得行。","思之不可见，百端在中腸。","維时月魄死，冬日朝在房。","驱驰公事退，闻子適及城。","命车載之至，引坐於中堂。","开懷听其说，往往副所望。","孔丘歿已远，仁義路久荒。","紛紛百家起，詭怪相披猖。","长老守所闻，後生習爲常。","少知誠难得，純粹古已亡。","譬彼植园木，有根易爲长。","留之不遣去，館置城西旁。","歲时未云幾，浩浩观湖江。","衆夫指之笑，謂我知不明。","兒童畏雷電，鱼鼈驚夜光。","州家舉進士，選試繆所當。","驰辞对我策，章句何煒煌。","相公朝服立，工席歌鹿鳴。","禮終乐亦闋，相拜送於庭。","之子去須臾，赫赫流盛名。","竊喜复竊歎，諒知有所成。","人事安可恒，奄忽令我傷。","闻子高第日，正從相公喪。","哀情逢吉語，惝怳难爲雙。","暮宿偃師西，徒展轉在牀。","夜闻汴州亂，遶壁行徬徨。","我时留妻子，倉卒不及將。","相见不复期，零落甘所丁。","驕兒未絕乳，念之不能忘。","忽如在我所，耳若闻啼声。","中途安得返，一日不可更。","俄有东来说，我家免罹殃。","乘船下汴水，东去趨彭城。","從喪朝至洛，還走不及停。","假道經盟津，出入行澗岡。","日西入軍门，羸马顛且僵。","主人願少留，延入陳壺觴。","卑賤不敢辞，忽忽心如狂。","饮食豈知味，絲竹徒轟轟。","平明脫身去，決若驚鳧翔。","黄昏次汜水，欲過無舟航。","號呼久乃至，夜濟十里黄。","中流上灘潬，沙水不可詳。","驚波暗合沓，星宿爭翻芒。","轅马蹢躅鳴，左右泣僕童。","甲午憩时门，臨泉窺鬬龙。","东南出陳許，陂澤平茫茫。","道邊草木花，紅紫相低昂。","百里不逢人，角角雄雉鳴。","行行二月暮，乃及徐南疆。","下马步堤岸，上船拜吾兄。","誰云經艱难，百口無夭殤。","僕射南陽公，宅我睢水陽。","篋中有餘衣，盎中有餘糧。","閉门读书史，窗戶忽已涼。","日念子来游，子豈知我情。","別離未爲久，辛苦多所經。","对食每不飽，共言無倦听。","連延三十日，晨坐達五更。","我友二三子，宦游在西京。","东野窺禹穴，李翱观濤江。","蕭條千万里，會合安可逢。","淮之水舒舒，楚山直叢叢。","子又捨我去，我懷焉所窮。","男兒不再壯，百歲如风狂。","高爵尚可求，無爲守一乡。"]', '诗', 'shi', '', NULL, '此日足可惜贈張籍 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75e8e864-7f92-42e9-9467-8988475bdf49', '幽懷', '幽懷', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["幽懷不能寫，行此春江潯。","適與佳節會，士女競光陰。","凝妝耀洲渚，繁吹蕩人心。","間關林中鳥，亦知和爲音。","豈無一尊酒，自酌還自吟。","但悲時易失，四序迭相侵。","我歌君子行，視古猶視今。"]', '["幽懷不能寫，行此春江潯。","適與佳節會，士女競光陰。","凝妝耀洲渚，繁吹蕩人心。","间关林中鸟，亦知和爲音。","豈無一尊酒，自酌還自吟。","但悲时易失，四序迭相侵。","我歌君子行，視古猶視今。"]', '诗', 'shi', '', NULL, '幽懷 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8564b270-5b39-41d3-a7ab-78fb21eb9784', '君子法天運', '君子法天運', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["君子法天運，四時可前知。","小人惟所遇，寒暑不可期。","利害有常勢，取捨無定姿。","焉能使我心，皎皎遠憂疑。"]', '["君子法天運，四时可前知。","小人惟所遇，寒暑不可期。","利害有常勢，取捨無定姿。","焉能使我心，皎皎远憂疑。"]', '诗', 'shi', '', NULL, '君子法天運 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f411fea-83c6-4e86-aadb-3e0fd0827366', '落葉送陳羽', '落葉送陳羽', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["落葉不更息，斷蓬無復歸。","飄颻終自異，邂逅暫相依。","悄悄深夜語，悠悠寒月輝。","誰云少年別，流淚各沾衣。"]', '["落葉不更息，斷蓬無复归。","飄颻終自異，邂逅暫相依。","悄悄深夜語，悠悠寒月輝。","誰云少年別，流泪各沾衣。"]', '诗', 'shi', '', NULL, '落葉送陳羽 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2897aade-bb54-46a4-83c1-c27b6060bbf1', '歸彭城', '归彭城', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["天下兵又動，太平竟何時。","訏謨者誰子，無乃失所宜。","前年關中旱，閭井多死飢。","去歲東郡水，生民爲流屍。","上天不虛應，禍福各有隨。","我欲進短策，無由至彤墀。","刳肝以爲紙，瀝血以書辭。","上言陳堯舜，下言引龍夔。","言詞多感激，文字少葳蕤。","一讀已自怪，再尋良自疑。","食芹雖云美，獻御固已癡。","緘封在骨髓，耿耿空自奇。","昨者到京城，屢陪高車馳。","周行多俊異，議論無瑕疵。","見待頗異禮，未能去毛皮。","到口不敢吐，徐徐俟其巘。","歸來戎馬間，驚顧似羈雌。","連日或不語，終朝見相欺。","乘閑輙騎馬，茫茫詣空陂。","遇酒即酩酊，君知我爲誰。"]', '["天下兵又动，太平竟何时。","訏謨者誰子，無乃失所宜。","前年关中旱，閭井多死飢。","去歲东郡水，生民爲流屍。","上天不虛應，禍福各有隨。","我欲進短策，無由至彤墀。","刳肝以爲紙，瀝血以书辞。","上言陳堯舜，下言引龙夔。","言词多感激，文字少葳蕤。","一读已自怪，再尋良自疑。","食芹雖云美，獻御固已癡。","緘封在骨髓，耿耿空自奇。","昨者到京城，屢陪高车驰。","周行多俊異，議論無瑕疵。","见待頗異禮，未能去毛皮。","到口不敢吐，徐徐俟其巘。","归来戎马间，驚顧似羈雌。","連日或不語，終朝见相欺。","乘闲輙騎马，茫茫詣空陂。","遇酒即酩酊，君知我爲誰。"]', '诗', 'shi', '', NULL, '歸彭城 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('683c0d72-400f-4807-9cd9-b619b5e80c85', '醉後', '醉後', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["煌煌東方星，奈此衆客醉。","初喧或忿爭，中靜雜嘲戲。","淋漓身上衣，顛倒筆下字。","人生如此少，酒賤且勤置。"]', '["煌煌东方星，奈此衆客醉。","初喧或忿爭，中静杂嘲戲。","淋漓身上衣，顛倒笔下字。","人生如此少，酒賤且勤置。"]', '诗', 'shi', '', NULL, '醉後 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4518d55f-9277-4e8a-a975-2790eac6b3c9', '醉贈張秘書', '醉贈張秘书', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["人皆勸我酒，我若耳不聞。","今日到君家，呼酒持勸君。","爲此座上客，及余各能文。","君詩多態度，藹藹春空雲。","東野動驚俗，天葩吐奇芬。","張籍學古淡，軒鶴避雞羣。","阿買不識字，頗知書八分。","詩成使之寫，亦足張吾軍。","所以欲得酒，爲文俟其醺。","酒味既冷冽，酒氣又氛氳。","性情漸浩浩，諧笑方云云。","此誠得酒意，餘外徒繽紛。","長安衆富兒，盤饌羅羶葷。","不解文字飲，惟能醉紅裙。","雖得一餉樂，有如聚飛蚊。","今我及數子，固無蕕與薰。","險語破鬼膽，高詞嫓皇墳。","至寶不雕琢，神功謝鋤耘。","方今向太平，元凱承華勛。","吾徒幸無事，庶以窮朝曛。"]', '["人皆勸我酒，我若耳不闻。","今日到君家，呼酒持勸君。","爲此座上客，及余各能文。","君诗多態度，藹藹春空云。","东野动驚俗，天葩吐奇芬。","張籍学古淡，軒鹤避雞羣。","阿買不識字，頗知书八分。","诗成使之寫，亦足張吾軍。","所以欲得酒，爲文俟其醺。","酒味既冷冽，酒氣又氛氳。","性情漸浩浩，諧笑方云云。","此誠得酒意，餘外徒繽紛。","长安衆富兒，盤饌羅羶葷。","不解文字饮，惟能醉紅裙。","雖得一餉乐，有如聚飞蚊。","今我及數子，固無蕕與薰。","險語破鬼膽，高词嫓皇墳。","至寶不雕琢，神功謝鋤耘。","方今向太平，元凱承华勛。","吾徒幸無事，庶以窮朝曛。"]', '诗', 'shi', '', NULL, '醉贈張秘書 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac52d797-2192-4024-a66f-7e5749f3d08c', '同冠峽', '同冠峽', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["南方二月半，春物亦已少。","維舟山水間，晨坐聽百鳥。","宿雲尚含姿，朝日忽升曉。","羇旅感和鳴，囚拘念輕矯。","潺湲淚久迸，詰曲思增繞。","行矣且無然，蓋棺事乃了。"]', '["南方二月半，春物亦已少。","維舟山水间，晨坐听百鸟。","宿云尚含姿，朝日忽升晓。","羇旅感和鳴，囚拘念轻矯。","潺湲泪久迸，詰曲思增繞。","行矣且無然，蓋棺事乃了。"]', '诗', 'shi', '', NULL, '同冠峽 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('252b4e33-b8d1-462d-a8e9-55a9766df5cf', '送惠師', '送惠師', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["惠師浮屠者，乃是不羇人。","十五愛山水，超然謝朋親。","脫冠翦頭髮，飛步遺蹤塵。","發跡入四明，梯空上秋旻。","遂登天台望，衆壑皆嶙峋。","夜宿最高頂，舉頭看星辰。","光芒相照燭，南北爭羅陳。","茲地絕翔走，自然嚴且神。","微風吹木石，澎湃聞韶鈞。","夜半起下視，溟波銜日輪。","魚龍驚踴躍，呌嘯成悲辛。","怪氣或紫赤，敲磨共輪囷。","金鴉既騰翥，六合俄清新。","常聞禹穴奇，東去窺甌閩。","越俗不好古，流傳失其真。","幽蹤邈難得，聖路嗟長堙。","回臨浙江濤，屹起高峨岷。","壯志死不息，千年如隔晨。","是非竟何有，棄去非吾倫。","凌江詣廬嶽，浩蕩極遊巡。","崔崒沒雲表，陂陀浸湖淪。","是時雨初霽，懸瀑垂天紳。","前年往羅浮，步戛南海漘。","大哉陽德盛，榮茂恒留春。","鵬鶱墮長翮，鯨戲側脩鱗。","自來連州寺，曾未造城闉。","日攜青雲客，探勝窮崖濱。","太守邀不去，羣官請徒頻。","囊無一金資，翻謂富者貧。","昨日忽不見，我令訪其隣。","奔波自追及，把手問所因。","顧我却興歡，君寧異於民。","離合自古然，辭別安足珍。","吾聞九疑好，夙志今欲伸。","斑竹啼舜婦，清湘沈楚臣。","衡山與洞庭，此固道所循。","尋崧方抵洛，歷華遂之秦。","浮游靡定處，偶往即通津。","吾言子當去，子道非吾遵。","江魚不池活，野鳥難籠馴。","吾非西方敎，憐子狂且醇。","吾嫉惰遊者，憐子愚且諄。","去矣各異趣，何爲浪霑巾。"]', '["惠師浮屠者，乃是不羇人。","十五愛山水，超然謝朋親。","脫冠翦头髮，飞步遺蹤塵。","發跡入四明，梯空上秋旻。","遂登天台望，衆壑皆嶙峋。","夜宿最高頂，舉头看星辰。","光芒相照燭，南北爭羅陳。","茲地絕翔走，自然嚴且神。","微风吹木石，澎湃闻韶鈞。","夜半起下視，溟波銜日輪。","鱼龙驚踴躍，呌嘯成悲辛。","怪氣或紫赤，敲磨共輪囷。","金鴉既腾翥，六合俄清新。","常闻禹穴奇，东去窺甌閩。","越俗不好古，流傳失其真。","幽蹤邈难得，聖路嗟长堙。","回臨浙江濤，屹起高峨岷。","壯志死不息，千年如隔晨。","是非竟何有，棄去非吾倫。","凌江詣廬嶽，浩蕩極游巡。","崔崒沒云表，陂陀浸湖淪。","是时雨初霽，懸瀑垂天紳。","前年往羅浮，步戛南海漘。","大哉陽德盛，榮茂恒留春。","鵬鶱墮长翮，鯨戲側脩鱗。","自来連州寺，曾未造城闉。","日携青云客，探勝窮崖濱。","太守邀不去，羣官請徒頻。","囊無一金資，翻謂富者貧。","昨日忽不见，我令訪其隣。","奔波自追及，把手问所因。","顧我却兴歡，君寧異於民。","離合自古然，辞別安足珍。","吾闻九疑好，夙志今欲伸。","斑竹啼舜婦，清湘沈楚臣。","衡山與洞庭，此固道所循。","尋崧方抵洛，歷华遂之秦。","浮游靡定处，偶往即通津。","吾言子當去，子道非吾遵。","江鱼不池活，野鸟难籠馴。","吾非西方敎，怜子狂且醇。","吾嫉惰游者，怜子愚且諄。","去矣各異趣，何爲浪霑巾。"]', '诗', 'shi', '', NULL, '送惠師 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bca537d-3b97-4aec-bcb3-1884ce9ca87b', '送靈師', '送靈師', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["佛法入中國，爾來六百年。","齊民逃賦役，高士著幽禪。","官吏不之制，紛紛聽其然。","耕桑日失隸，朝署時遣賢。","靈師皇甫姓，胤胄本蟬聯。","少小涉書史，早能綴文篇。","中間不得意，失跡成延遷。","逸志不拘敎，軒騰斷牽攣。","圍棊鬬白黑，生死隨機權。","六博在一擲，梟盧叱回旋。","戰詩誰與敵，浩汗橫戈鋋。","飲酒盡百𧣴，嘲詣思逾鮮。","有時醉花月，高唱清且緜。","四座咸寂默，杳如奏湘弦。","尋勝不憚險，黔江屢洄沿。","瞿塘五六月，驚電讓歸船。","怒水忽中裂，千尋墮幽泉。","環回勢益急，仰見團團天。","投身豈得計，性命甘徒捐。","浪沫蹙翻涌，漂浮再生全。","同行二十人，魂骨俱坑填。","靈師不挂懷，冒涉道轉延。","開忠二州牧，詩賦時多傳。","失職不把筆，珠璣爲君編。","強留費日月，密席羅嬋娟。","昨者至林邑，使君數開筵。","逐客三四公，盈懷贈蘭荃。","湖游泛漭沆，溪宴駐潺湲。","別語不許出，行裾動遭牽。","隣州競招請，書札何翩翩。","十月下桂嶺，乘寒恣窺緣。","落落王員外，爭迎獲其先。","自從入賓館，占恡久能專。","吾徒頗攜被，接宿窮歡妍。","聽說兩京事，分明皆眼前。","縱橫雜謠俗，瑣屑咸羅穿。","材調真可惜，朱丹在磨研。","方將歛之道，且欲冠其顛。","韶陽李太守，高步凌雲烟。","得客輙忘食，開囊乞繒錢。","手持南曹敘，字重青瑤鐫。","古氣參彖繫，高標摧太玄。","維舟事干謁，披讀頭風痊。","還如舊相識，傾壺暢幽悁。","以此復留滯，歸驂幾時鞭。"]', '["佛法入中国，爾来六百年。","齊民逃賦役，高士著幽禪。","官吏不之制，紛紛听其然。","耕桑日失隸，朝署时遣賢。","靈師皇甫姓，胤胄本蟬聯。","少小涉书史，早能綴文篇。","中间不得意，失跡成延遷。","逸志不拘敎，軒腾斷牽攣。","圍棊鬬白黑，生死隨機權。","六博在一擲，梟盧叱回旋。","戰诗誰與敵，浩汗橫戈鋋。","饮酒尽百𧣴，嘲詣思逾鲜。","有时醉花月，高唱清且緜。","四座咸寂默，杳如奏湘弦。","尋勝不憚險，黔江屢洄沿。","瞿塘五六月，驚電讓归船。","怒水忽中裂，千尋墮幽泉。","环回勢益急，仰见團團天。","投身豈得計，性命甘徒捐。","浪沫蹙翻涌，漂浮再生全。","同行二十人，魂骨俱坑填。","靈師不挂懷，冒涉道轉延。","开忠二州牧，诗賦时多傳。","失職不把笔，珠璣爲君編。","強留費日月，密席羅嬋娟。","昨者至林邑，使君數开筵。","逐客三四公，盈懷贈蘭荃。","湖游泛漭沆，溪宴駐潺湲。","別語不許出，行裾动遭牽。","隣州競招請，书札何翩翩。","十月下桂嶺，乘寒恣窺緣。","落落王員外，爭迎獲其先。","自從入賓館，占恡久能專。","吾徒頗携被，接宿窮歡妍。","听说兩京事，分明皆眼前。","縱橫杂謠俗，瑣屑咸羅穿。","材調真可惜，朱丹在磨研。","方將歛之道，且欲冠其顛。","韶陽李太守，高步凌云烟。","得客輙忘食，开囊乞繒錢。","手持南曹敘，字重青瑤鐫。","古氣參彖繫，高標摧太玄。","維舟事干謁，披读头风痊。","還如旧相識，傾壺暢幽悁。","以此复留滯，归驂幾时鞭。"]', '诗', 'shi', '', NULL, '送靈師 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e9ac5c4-8f12-40f3-acce-39567d0bdfc5', '縣齋有懷', '縣斋有懷', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["少小尚奇偉，平生足悲吒。","猶嫌子夏儒，肯學樊遲稼。","事業窺臯稷，文章蔑曹謝。","濯纓起江湖，綴佩雜蘭麝。","悠悠指長道，去去策高駕。","誰爲傾國媒，自許連城價。","初隨計吏貢，屢入澤宮射。","雖免十上勞，何能一戰霸。","人情忌殊異，世路多權詐。","蹉跎顏遂低，摧折氣愈下。","冶長信非罪，侯生或遭駡。","懷書出皇都，銜淚渡清灞。","身將老寂寞，志欲死閑暇。","朝食不盈腸，冬衣纔掩髂。","軍書既頻召，戎馬乃連跨。","大梁從相公，彭城赴僕射。","弓箭圍狐兔，絲竹羅酒{炙火=肉}。","兩府變荒涼，三年就休假。","求官去東洛，犯雪過西華。","塵埃紫陌春，風雨靈臺夜。","名聲荷朋友，援引乏姻婭。","雖陪彤庭臣，詎縱青冥靶。","寒空聳危闕，曉色曜脩架。","捐軀辰在丁，鎩翮時方蜡。","投荒誠職分，領邑幸寬赦。","湖波翻日車，嶺石坼天罅。","毒霧恒熏晝，炎風每燒夏。","雷威固已加，颶勢仍相借。","氣象杳難測，聲音吁可怕。","夷言聽未慣，越俗循猶乍。","指摘兩憎嫌，睢盱互猜訝。","祗緣恩未報，豈謂生足藉。","嗣皇新繼明，率土日流化。","惟思滌瑕垢，長去事桑柘。","斸嵩開雲扃，壓潁抗風榭。","禾麥種滿地，梨棗栽繞舍。","兒童稍長成，雀鼠得驅嚇。","官租日輸納，村酒時邀迓。","閑愛老農愚，歸弄小女姹。","如今便可爾，何用畢婚嫁。"]', '["少小尚奇偉，平生足悲吒。","猶嫌子夏儒，肯学樊遲稼。","事業窺臯稷，文章蔑曹謝。","濯纓起江湖，綴佩杂蘭麝。","悠悠指长道，去去策高駕。","誰爲傾国媒，自許連城價。","初隨計吏貢，屢入澤宮射。","雖免十上勞，何能一戰霸。","人情忌殊異，世路多權詐。","蹉跎顏遂低，摧折氣愈下。","冶长信非罪，侯生或遭駡。","懷书出皇都，銜泪渡清灞。","身將老寂寞，志欲死闲暇。","朝食不盈腸，冬衣纔掩髂。","軍书既頻召，戎马乃連跨。","大梁從相公，彭城赴僕射。","弓箭圍狐兔，絲竹羅酒{炙火=肉}。","兩府变荒涼，三年就休假。","求官去东洛，犯雪過西华。","塵埃紫陌春，风雨靈台夜。","名声荷朋友，援引乏姻婭。","雖陪彤庭臣，詎縱青冥靶。","寒空聳危闕，晓色曜脩架。","捐軀辰在丁，鎩翮时方蜡。","投荒誠職分，領邑幸寬赦。","湖波翻日车，嶺石坼天罅。","毒霧恒熏晝，炎风每燒夏。","雷威固已加，颶勢仍相借。","氣象杳难測，声音吁可怕。","夷言听未慣，越俗循猶乍。","指摘兩憎嫌，睢盱互猜訝。","祗緣恩未報，豈謂生足藉。","嗣皇新繼明，率土日流化。","惟思滌瑕垢，长去事桑柘。","斸嵩开云扃，壓潁抗风榭。","禾麦種满地，梨棗栽繞舍。","兒童稍长成，雀鼠得驱嚇。","官租日輸納，村酒时邀迓。","闲愛老農愚，归弄小女姹。","如今便可爾，何用畢婚嫁。"]', '诗', 'shi', '', NULL, '縣齋有懷 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cb1d784-de31-45d5-a95d-0f1e92b00341', '合江亭', '合江亭', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["紅亭枕湘江，蒸水會其左。","瞰臨眇空闊，綠淨不可唾。","維昔經營初，邦君實王佐。","翦林遷神祠，買地費家貨。","梁棟宏可愛，結構麗匪過。","伊人去軒騰，茲宇遂頹挫。","老郎來何暮，高唱久乃和。","樹蘭盈九畹，栽竹逾萬个。","長綆汲滄浪，幽蹊下坎坷。","波濤夜俯聽，雲樹朝對臥。","初如遺宦情，終乃最郡課。","人生誠無幾，事往悲豈奈。","蕭條緜歲時，契闊繼庸懦。","勝事誰復論，醜聲日已播。","中丞黜凶邪，天子閔窮餓。","君侯至之初，閭里自相賀。","淹滯樂閑曠，勤苦勸慵惰。","爲余掃塵階，命樂醉衆座。","窮秋感平分，新月憐半破。","願書巖上石，勿使泥塵涴。"]', '["紅亭枕湘江，蒸水會其左。","瞰臨眇空闊，綠淨不可唾。","維昔經營初，邦君實王佐。","翦林遷神祠，買地費家貨。","梁棟宏可愛，結構丽匪過。","伊人去軒腾，茲宇遂頹挫。","老郎来何暮，高唱久乃和。","樹蘭盈九畹，栽竹逾万个。","长綆汲滄浪，幽蹊下坎坷。","波濤夜俯听，云樹朝对臥。","初如遺宦情，終乃最郡課。","人生誠無幾，事往悲豈奈。","蕭條緜歲时，契闊繼庸懦。","勝事誰复論，醜声日已播。","中丞黜凶邪，天子閔窮餓。","君侯至之初，閭里自相賀。","淹滯乐闲曠，勤苦勸慵惰。","爲余掃塵階，命乐醉衆座。","窮秋感平分，新月怜半破。","願书巖上石，勿使泥塵涴。"]', '诗', 'shi', '', NULL, '合江亭 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07bec374-ff61-4d05-842c-c57c25f1d888', '陪杜侍御遊湘西兩寺獨宿有題一首因獻楊常侍', '陪杜侍御游湘西兩寺独宿有題一首因獻楊常侍', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["長沙千里平，勝地猶在險。","況當江闊處，斗起勢匪漸。","深林高玲瓏，青山上琬琰。","路窮臺殿闢，佛事煥且儼。","剖竹走泉源，開廊架崖广。","是時秋之殘，暑氣尚未歛。","羣行忘後先，朋息棄拘檢。","客堂喜空涼，華榻有清簟。","澗蔬煮蒿芹，水果剝菱芡。","伊余夙所慕，陪賞亦云忝。","幸逢車馬歸，獨宿門不掩。","山樓黑無月，漁火燦星點。","夜風一何喧，杉檜屢磨颭。","猶疑在波濤，怵惕夢成魘。","靜思屈原沈，遠憶賈誼貶。","椒蘭爭妬忌，絳灌共讒諂。","誰令悲生腸，坐使淚盈臉。","翻飛乏羽翼，指摘困瑕玷。","珥貂藩維重，政化類分陝。","禮賢道何優，奉己事苦儉。","大廈棟方隆，巨川檝行剡。","經營誠少暇，遊宴固已歉。","旅程愧淹留，徂歲嗟荏苒。","平生每多感，柔翰遇頻染。","展轉嶺猿鳴，曙燈青睒睒。"]', '["长沙千里平，勝地猶在險。","況當江闊处，斗起勢匪漸。","深林高玲瓏，青山上琬琰。","路窮台殿闢，佛事煥且儼。","剖竹走泉源，开廊架崖广。","是时秋之殘，暑氣尚未歛。","羣行忘後先，朋息棄拘檢。","客堂喜空涼，华榻有清簟。","澗蔬煮蒿芹，水果剝菱芡。","伊余夙所慕，陪賞亦云忝。","幸逢车马归，独宿门不掩。","山楼黑無月，漁火燦星点。","夜风一何喧，杉檜屢磨颭。","猶疑在波濤，怵惕梦成魘。","静思屈原沈，远憶賈誼貶。","椒蘭爭妬忌，絳灌共讒諂。","誰令悲生腸，坐使泪盈臉。","翻飞乏羽翼，指摘困瑕玷。","珥貂藩維重，政化類分陝。","禮賢道何優，奉己事苦儉。","大廈棟方隆，巨川檝行剡。","經營誠少暇，游宴固已歉。","旅程愧淹留，徂歲嗟荏苒。","平生每多感，柔翰遇頻染。","展轉嶺猿鳴，曙灯青睒睒。"]', '诗', 'shi', '', NULL, '陪杜侍御遊湘西兩寺獨宿有題一首因獻楊常侍 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262d09ef-c986-4c06-81a4-9a75c6d83719', '岳陽樓別竇司直', '岳陽楼別竇司直', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["洞庭九州間，厥大誰與讓。","南匯羣崖水，北注何奔放。","瀦爲七百里，吞納各殊狀。","自古澄不清，環混無歸向。","炎風日搜攪，幽怪多冗長。","軒然大波起，宇宙隘而妨。","巍峩拔嵩華，騰踔較健壯。","聲音一何宏，轟輵車萬兩。","猶疑帝軒轅，張樂就空曠。","蛟螭露筍簴，縞練吹組帳。","鬼神非人世，節奏頗跌踼。","陽施見誇麗，陰閉感悽愴。","朝過宜春口，極北缺隄障。","夜纜巴陵洲，叢芮纔可傍。","星河盡涵泳，俯仰迷下上。","餘瀾怒不已，喧聒鳴甕盎。","明登岳陽樓，輝煥朝日亮。","飛廉戢其威，清晏息纖纊。","泓澄湛凝綠，物影巧相況。","江豚時出戲，驚波忽蕩瀁。","時當冬之孟，隙竅縮寒漲。","前臨指近岸，側坐眇難望。","滌濯神魂醒，幽懷舒以暢。","主人孩童舊，握手乍忻悵。","憐我竄逐歸，相見得無恙。","開筵交履舃，爛漫倒家釀。","杯行無留停，高柱送清唱。","中盤進橙栗，投擲傾脯醬。","歡窮悲心生，婉孌不能忘。","念昔始讀書，志欲干霸王。","屠龍破千金，爲藝亦云亢。","愛才不擇行，觸事得讒謗。","前年出官由，此禍最無妄。","公卿採虛名，擢拜識天仗。","姦猜畏彈射，斥逐恣欺誑。","新恩移府庭，逼側廁諸將。","于嗟苦駑緩，但懼失宜當。","追思南渡時，魚腹甘所葬。","嚴程迫風帆，劈箭入高浪。","顛沈在須臾，忠鯁誰復諒。","生還真可喜，尅己自懲創。","庶從今日後，粗識得與喪。","事多改前好，趣有獲新尚。","誓耕十畝田，不取萬乘相。","細君知蠶織，稚子已能餉。","行當掛其冠，生死君一訪。"]', '["洞庭九州间，厥大誰與讓。","南匯羣崖水，北注何奔放。","瀦爲七百里，吞納各殊狀。","自古澄不清，环混無归向。","炎风日搜攪，幽怪多冗长。","軒然大波起，宇宙隘而妨。","巍峩拔嵩华，腾踔較健壯。","声音一何宏，轟輵车万兩。","猶疑帝軒轅，張乐就空曠。","蛟螭露筍簴，縞練吹組帳。","鬼神非人世，節奏頗跌踼。","陽施见誇丽，陰閉感悽愴。","朝過宜春口，極北缺隄障。","夜纜巴陵洲，叢芮纔可傍。","星河尽涵泳，俯仰迷下上。","餘瀾怒不已，喧聒鳴甕盎。","明登岳陽楼，輝煥朝日亮。","飞廉戢其威，清晏息纖纊。","泓澄湛凝綠，物影巧相況。","江豚时出戲，驚波忽蕩瀁。","时當冬之孟，隙竅縮寒漲。","前臨指近岸，側坐眇难望。","滌濯神魂醒，幽懷舒以暢。","主人孩童旧，握手乍忻悵。","怜我竄逐归，相见得無恙。","开筵交履舃，爛漫倒家釀。","杯行無留停，高柱送清唱。","中盤進橙栗，投擲傾脯醬。","歡窮悲心生，婉孌不能忘。","念昔始读书，志欲干霸王。","屠龙破千金，爲藝亦云亢。","愛才不擇行，觸事得讒謗。","前年出官由，此禍最無妄。","公卿採虛名，擢拜識天仗。","姦猜畏彈射，斥逐恣欺誑。","新恩移府庭，逼側廁諸將。","于嗟苦駑緩，但懼失宜當。","追思南渡时，鱼腹甘所葬。","嚴程迫风帆，劈箭入高浪。","顛沈在須臾，忠鯁誰复諒。","生還真可喜，尅己自懲創。","庶從今日後，粗識得與喪。","事多改前好，趣有獲新尚。","誓耕十畝田，不取万乘相。","細君知蠶织，稚子已能餉。","行當掛其冠，生死君一訪。"]', '诗', 'shi', '', NULL, '岳陽樓別竇司直 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42a51a2c-f1b6-4e71-a991-23f0d1f9804e', '送文暢師北遊', '送文暢師北游', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["昔在四門館，晨有僧來謁。","自言本吳人，少小學城闕。","已窮佛根源，粗識事輗軏。","攣拘屈吾真，戒轄思遠發。","薦紳秉筆徒，聲譽耀前閥。","從求送行詩，屢造忍顛蹶。","今成十餘卷，浩汗羅斧鉞。","先生閟窮巷，未得窺剞劂。","又聞識大道，何路補剠刖。","出其囊中文，滿聽實清越。","謂僧當少安，草序頗排訐。","上論古之初，所以施賞罰。","下開迷惑胸，窙豁劚株橜。","僧時不聽瑩，若飲水救暍。","風塵一出門，時日多如髮。","三年竄荒嶺，守縣坐深樾。","徴租聚異物，詭製怛巾襪。","幽窮誰共語，思想甚含噦。","昨來得京官，照壁喜見蝎。","況逢舊親識，無不比鶼蟨。","長安多門戶，弔慶少休歇。","而能勤來過，重惠安可揭。","當今聖政初，恩澤完{羽戊}狘。","胡爲不自暇，飄戾逐鸇𪆙。","僕射領北門，威德壓胡羯。","相公鎮幽都，竹帛爛勳伐。","酒場舞閨姝，獵騎圍邊月。","開張篋中寶，自可得津筏。","從茲富裘馬，寧復茹藜蕨。","余期報恩後，謝病老耕垡。","庇身指蓬茅，逞志縱獫猲。","僧還相訪來，山藥煮可掘。"]', '["昔在四门館，晨有僧来謁。","自言本吳人，少小学城闕。","已窮佛根源，粗識事輗軏。","攣拘屈吾真，戒轄思远發。","薦紳秉笔徒，声譽耀前閥。","從求送行诗，屢造忍顛蹶。","今成十餘卷，浩汗羅斧鉞。","先生閟窮巷，未得窺剞劂。","又闻識大道，何路補剠刖。","出其囊中文，满听實清越。","謂僧當少安，草序頗排訐。","上論古之初，所以施賞罰。","下开迷惑胸，窙豁劚株橜。","僧时不听瑩，若饮水救暍。","风塵一出门，时日多如髮。","三年竄荒嶺，守縣坐深樾。","徴租聚異物，詭製怛巾襪。","幽窮誰共語，思想甚含噦。","昨来得京官，照壁喜见蝎。","況逢旧親識，無不比鶼蟨。","长安多门戶，弔慶少休歇。","而能勤来過，重惠安可揭。","當今聖政初，恩澤完{羽戊}狘。","胡爲不自暇，飄戾逐鸇𪆙。","僕射領北门，威德壓胡羯。","相公鎮幽都，竹帛爛勳伐。","酒場舞閨姝，獵騎圍邊月。","开張篋中寶，自可得津筏。","從茲富裘马，寧复茹藜蕨。","余期報恩後，謝病老耕垡。","庇身指蓬茅，逞志縱獫猲。","僧還相訪来，山藥煮可掘。"]', '诗', 'shi', '', NULL, '送文暢師北遊 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b1eba88-6a05-45fa-a6a5-fdc07f93d248', '答張徹', '答張徹', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["辱贈不知報，我歌爾其聆。","首敘始識面，次言後分形。","道途緜萬里，日月垂十齡。","浚郊避兵亂，睢岸連門停。","肝膽一古劒，波濤兩浮萍。","漬墨竄舊史，磨丹注前經。","義苑手秘寶，文堂耳驚霆。","暄晨躡露舃，暑夕眠風櫺。","結友子讓抗，請師我慚丁。","初味猶噉蔗，遂通斯建瓴。","搜奇日有富，嗜善心無寧。","石梁平侹侹，沙水光泠泠。","乘枯摘野豔，沈細抽潛腥。","遊寺去陟巘，尋徑返穿汀。","緣雲竹竦竦，失路麻冥冥。","淫潦忽翻野，平蕪眇開溟。","防泄塹夜塞，懼衝城晝扃。","及去事戎轡，相逢宴軍伶。","觥秋縱兀兀，獵旦馳駉駉。","從賦始分手，朝京忽同舲。","急時促暗櫂，戀月留虛亭。","畢事驅傳馬，安居守窗螢。","梅花灞水別，宮燭驪山醒。","省選逮投足，鄉賓尚摧翎。","塵祛又一摻，淚眥還雙熒。","洛邑得休告，華山窮絕陘。","倚巖睨海浪，引袖拂天星。","日駕此迴轄，金神所司刑。","泉紳拖修白，石劒攢高青。","磴蘚澾拳跼，梯颷颭伶俜。","悔狂已咋指，垂誡仍鐫銘。","峩豸忝備列，伏蒲愧分涇。","微誠慕橫草，瑣力摧撞筵。","疊雪走商嶺，飛波航洞庭。","下險疑墮井，守官類拘囹。","荒餐茹獠蠱，幽夢感湘靈。","刺史肅蓍蔡，吏人沸蝗螟。","點綴簿上字，趨蹌閤前鈴。","賴其飽山水，得以娛瞻聽。","紫樹雕斐亹，碧流滴瓏玲。","暎波鋪遠錦，插地列長屏。","愁狖酸骨死，怪花醉魂馨。","潛苞絳實坼，幽乳翠毛零。","赦行五百里，月變三十蓂。","漸階羣振鷺，入學誨螟蛉。","苹甘謝鳴鹿，罍滿慚罄瓶。","冏冏抱瑚璉，飛飛聯鶺鴒。","魚鬣欲脫背，虬光先照硎。","豈獨出醜類，方當動朝廷。","勤來得唔語，勿憚宿寒廳。"]', '["辱贈不知報，我歌爾其聆。","首敘始識面，次言後分形。","道途緜万里，日月垂十齡。","浚郊避兵亂，睢岸連门停。","肝膽一古劒，波濤兩浮萍。","漬墨竄旧史，磨丹注前經。","義苑手秘寶，文堂耳驚霆。","暄晨躡露舃，暑夕眠风櫺。","結友子讓抗，請師我慚丁。","初味猶噉蔗，遂通斯建瓴。","搜奇日有富，嗜善心無寧。","石梁平侹侹，沙水光泠泠。","乘枯摘野豔，沈細抽潛腥。","游寺去陟巘，尋徑返穿汀。","緣云竹竦竦，失路麻冥冥。","淫潦忽翻野，平蕪眇开溟。","防泄塹夜塞，懼衝城晝扃。","及去事戎轡，相逢宴軍伶。","觥秋縱兀兀，獵旦驰駉駉。","從賦始分手，朝京忽同舲。","急时促暗櫂，戀月留虛亭。","畢事驱傳马，安居守窗螢。","梅花灞水別，宮燭驪山醒。","省選逮投足，乡賓尚摧翎。","塵祛又一摻，泪眥還雙熒。","洛邑得休告，华山窮絕陘。","倚巖睨海浪，引袖拂天星。","日駕此迴轄，金神所司刑。","泉紳拖修白，石劒攢高青。","磴蘚澾拳跼，梯颷颭伶俜。","悔狂已咋指，垂誡仍鐫銘。","峩豸忝備列，伏蒲愧分涇。","微誠慕橫草，瑣力摧撞筵。","叠雪走商嶺，飞波航洞庭。","下險疑墮井，守官類拘囹。","荒餐茹獠蠱，幽梦感湘靈。","刺史肅蓍蔡，吏人沸蝗螟。","点綴簿上字，趨蹌閤前鈴。","賴其飽山水，得以娛瞻听。","紫樹雕斐亹，碧流滴瓏玲。","暎波鋪远錦，插地列长屏。","愁狖酸骨死，怪花醉魂馨。","潛苞絳實坼，幽乳翠毛零。","赦行五百里，月变三十蓂。","漸階羣振鷺，入学誨螟蛉。","苹甘謝鳴鹿，罍满慚罄瓶。","冏冏抱瑚璉，飞飞聯鶺鴒。","鱼鬣欲脫背，虬光先照硎。","豈独出醜類，方當动朝廷。","勤来得唔語，勿憚宿寒廳。"]', '诗', 'shi', '', NULL, '答張徹 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2083af19-c093-4389-8493-46de8922dbea', '薦士', '薦士', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["周詩三百篇，雅麗理訓誥。","曾經聖人手，議論安敢到。","五言出漢時，蘇李首更號。","東都漸瀰漫，派別百川導。","建安能者七，卓犖變風操。","逶迤抵晉宋，氣象日凋耗。","中間數鮑謝，比近最清奧。","齊梁及陳隋，衆作等蟬噪。","搜春摘花卉，沿襲傷剽盜。","國朝盛文章，子昂始高蹈。","勃興得李杜，萬類困陵暴。","後來相繼生，亦各臻閫奧。","有窮者孟郊，受材實雄驁。","冥觀洞古今，象外逐幽好。","橫空盤硬語，妥帖力排奡。","敷柔肆紆餘，奮猛卷海潦。","榮華肖天秀，捷疾逾響報。","行身踐規矩，甘辱恥媚竈。","孟軻分邪正，眸子看瞭眊。","杳然粹而清，可以鎮浮躁。","酸寒溧陽尉，五十幾何耄。","孜孜營甘旨，辛苦久所冒。","俗流知者誰，指注競嘲慠。","聖皇索遺逸，髦士日登造。","廟堂有賢相，愛遇均覆燾。","況承歸與張，二公迭嗟悼。","青冥送吹噓，強箭射魯縞。","胡爲久無成，使以歸期告。","霜風破佳菊，嘉節迫吹帽。","念將決焉去，感物增戀嫪。","彼微水中荇，尚煩左右芼。","魯侯國至小，廟鼎猶納郜。","幸當擇珉玉，寧有棄珪瑁。","悠悠我之思，擾擾風中纛。","上言媿無路，日夜惟心禱。","鶴翎不天生，變化在啄菢。","通波非難圖，尺地易可漕。","善善不汲汲，後時徒悔懊。","救死具八珍，不如一簞犒。","微詩公勿誚，愷悌神所勞。"]', '["周诗三百篇，雅丽理訓誥。","曾經聖人手，議論安敢到。","五言出漢时，蘇李首更號。","东都漸瀰漫，派別百川導。","建安能者七，卓犖变风操。","逶迤抵晉宋，氣象日凋耗。","中间數鲍謝，比近最清奧。","齊梁及陳隋，衆作等蟬噪。","搜春摘花卉，沿襲傷剽盜。","国朝盛文章，子昂始高蹈。","勃兴得李杜，万類困陵暴。","後来相繼生，亦各臻閫奧。","有窮者孟郊，受材實雄驁。","冥观洞古今，象外逐幽好。","橫空盤硬語，妥帖力排奡。","敷柔肆紆餘，奮猛卷海潦。","榮华肖天秀，捷疾逾响報。","行身踐規矩，甘辱恥媚竈。","孟軻分邪正，眸子看瞭眊。","杳然粹而清，可以鎮浮躁。","酸寒溧陽尉，五十幾何耄。","孜孜營甘旨，辛苦久所冒。","俗流知者誰，指注競嘲慠。","聖皇索遺逸，髦士日登造。","廟堂有賢相，愛遇均覆燾。","況承归與張，二公迭嗟悼。","青冥送吹噓，強箭射魯縞。","胡爲久無成，使以归期告。","霜风破佳菊，嘉節迫吹帽。","念將決焉去，感物增戀嫪。","彼微水中荇，尚煩左右芼。","魯侯国至小，廟鼎猶納郜。","幸當擇珉玉，寧有棄珪瑁。","悠悠我之思，擾擾风中纛。","上言媿無路，日夜惟心禱。","鹤翎不天生，变化在啄菢。","通波非难圖，尺地易可漕。","善善不汲汲，後时徒悔懊。","救死具八珍，不如一簞犒。","微诗公勿誚，愷悌神所勞。"]', '诗', 'shi', '', NULL, '薦士 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b17e7f46-07c8-4596-9a54-6e6e88f40bae', '喜侯喜至贈張籍張徹', '喜侯喜至贈張籍張徹', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["昔我在南時，數君常在念。","搖搖不可止，諷詠日喁噞。","如以膏濯衣，每漬垢逾染。","又如心中疾，鍼石非所砭。","常思得遊處，至死無倦厭。","地遐物奇怪，水鏡涵石劒。","荒花窮漫亂，幽獸工騰閃。","礙目不忍窺，忽忽坐昏墊。","逢神多所祝，豈忘靈即驗。","依依夢歸路，歷歷想行店。","今者誠自幸，所懷無一欠。","孟生去雖索，侯氏來還歉。","欹眠聽新詩，屋角月豔豔。","雜作承間騁，交驚舌互舚。","繽紛指瑕疵，拒捍阻城塹。","以余經摧挫，固請發鉛槧。","居然妄推讓，見謂爇天燄。","比疎語徒妍，悚息不敢占。","呼奴具盤餐，飣餖魚菜贍。","人生但如此，朱紫安足僭。"]', '["昔我在南时，數君常在念。","搖搖不可止，諷詠日喁噞。","如以膏濯衣，每漬垢逾染。","又如心中疾，鍼石非所砭。","常思得游处，至死無倦厭。","地遐物奇怪，水镜涵石劒。","荒花窮漫亂，幽獸工腾閃。","礙目不忍窺，忽忽坐昏墊。","逢神多所祝，豈忘靈即驗。","依依梦归路，歷歷想行店。","今者誠自幸，所懷無一欠。","孟生去雖索，侯氏来還歉。","欹眠听新诗，屋角月豔豔。","杂作承间騁，交驚舌互舚。","繽紛指瑕疵，拒捍阻城塹。","以余經摧挫，固請發鉛槧。","居然妄推讓，见謂爇天燄。","比疎語徒妍，悚息不敢占。","呼奴具盤餐，飣餖鱼菜贍。","人生但如此，朱紫安足僭。"]', '诗', 'shi', '', NULL, '喜侯喜至贈張籍張徹 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('200b2b04-581a-4327-bb3e-aab077bf8c37', '古風', '古风', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["今日曷不樂，幸時不用兵。","無曰既蹙矣，乃尚可以生。","彼州之賦，去汝不顧。","此州之役，去我奚適。","一邑之水，可走而違。","天下湯湯，曷其而歸。","好我衣服，甘我飲食。","無念百年，聊樂一日。"]', '["今日曷不乐，幸时不用兵。","無曰既蹙矣，乃尚可以生。","彼州之賦，去汝不顧。","此州之役，去我奚適。","一邑之水，可走而違。","天下湯湯，曷其而归。","好我衣服，甘我饮食。","無念百年，聊乐一日。"]', '诗', 'shi', '', NULL, '古風 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70f9e020-b7c4-42d5-8986-ae2f7f8b30e0', '駑驥', '駑驥', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["駑駘誠齷齪，市者何其稠。","力小若易制，價微良易酬。","渴飲一斗水，飢食一束芻。","嘶鳴當大路，志氣若有餘。","騏驥生絕域，自矜無匹儔。","牽驅入市門，行者不爲留。","借問價幾何，黃金比嵩丘。","借問行幾何，咫尺視九州。","飢食玉山禾，渴飲醴泉流。","問誰能爲御，曠世不可求。","惟昔穆天子，乘之極遐遊。","王良執其轡，造父挾其輈。","因言天外事，茫惚使人愁。","駑駘謂騏驥，餓死余爾羞。","有能必見用，有德必見收。","孰云時與命，通塞皆自由。","騏驥不敢言，低徊但垂頭。","人皆劣騏驥，共以駑駘優。","喟余獨興歎，才命不同謀。","寄詩同心子，爲我商聲謳。"]', '["駑駘誠齷齪，市者何其稠。","力小若易制，價微良易酬。","渴饮一斗水，飢食一束芻。","嘶鳴當大路，志氣若有餘。","騏驥生絕域，自矜無匹儔。","牽驱入市门，行者不爲留。","借问價幾何，黄金比嵩丘。","借问行幾何，咫尺視九州。","飢食玉山禾，渴饮醴泉流。","问誰能爲御，曠世不可求。","惟昔穆天子，乘之極遐游。","王良執其轡，造父挾其輈。","因言天外事，茫惚使人愁。","駑駘謂騏驥，餓死余爾羞。","有能必见用，有德必见收。","孰云时與命，通塞皆自由。","騏驥不敢言，低徊但垂头。","人皆劣騏驥，共以駑駘優。","喟余独兴歎，才命不同謀。","寄诗同心子，爲我商声謳。"]', '诗', 'shi', '', NULL, '駑驥 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f85e4e-6083-4d1a-ae90-e8623eeb1c21', '馬厭穀', '马厭穀', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["馬厭穀兮，士不厭糠籺。","土被文繡兮，士無短褐。","彼其得志兮，不我虞。","一朝失志兮，其何如。","已焉哉，嗟嗟乎鄙夫！。"]', '["马厭穀兮，士不厭糠籺。","土被文繡兮，士無短褐。","彼其得志兮，不我虞。","一朝失志兮，其何如。","已焉哉，嗟嗟乎鄙夫！。"]', '诗', 'shi', '', NULL, '馬厭穀 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe8d13c5-7dbc-419c-b628-19508a95e2ac', '出門', '出门', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["長安百萬家，出門無所之。","豈敢尚幽獨，與世實參差。","古人雖已死，書上有其辭。","開卷讀且想，千載若相期。","出門各有道，我道方未夷。","且於此中息，天命不吾欺。"]', '["长安百万家，出门無所之。","豈敢尚幽独，與世實參差。","古人雖已死，书上有其辞。","开卷读且想，千載若相期。","出门各有道，我道方未夷。","且於此中息，天命不吾欺。"]', '诗', 'shi', '', NULL, '出門 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3750468c-5a67-4cbb-a237-77444d2163dc', '嗟哉董生行', '嗟哉董生行', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["淮水出桐柏，山東馳遙遙。","千里不能休，淝水出其側。","不能千里百里入淮流，壽州屬縣有安豐。","唐貞元時縣人董生召南隱居行義於其中，刺史不能薦。","天子不聞名聲，爵祿不及門。","門外惟有吏，日來徴租更索錢。","嗟哉董生朝出耕，夜歸讀古人書。","盡日不得息，或山而樵。","或水而漁，入廚具甘旨。","上堂問起居，父母不慼慼。","妻子不咨咨，嗟哉董生孝且慈。","人不識，惟有天翁知。","生祥下瑞無時期，家有狗乳出求食。","雞來哺其兒，啄啄庭中拾蟲蟻。","哺之不食鳴聲悲，徬徨躑躅久不去。","以翼來覆待狗歸，嗟哉董生。","誰將與儔，時之人。","夫妻相虐，兄弟爲讐。","食君之祿，而令父母愁。","亦獨何心，嗟哉董生無與儔。"]', '["淮水出桐柏，山东驰遙遙。","千里不能休，淝水出其側。","不能千里百里入淮流，壽州屬縣有安豐。","唐貞元时縣人董生召南隐居行義於其中，刺史不能薦。","天子不闻名声，爵祿不及门。","门外惟有吏，日来徴租更索錢。","嗟哉董生朝出耕，夜归读古人书。","尽日不得息，或山而樵。","或水而漁，入廚具甘旨。","上堂问起居，父母不慼慼。","妻子不咨咨，嗟哉董生孝且慈。","人不識，惟有天翁知。","生祥下瑞無时期，家有狗乳出求食。","雞来哺其兒，啄啄庭中拾蟲蟻。","哺之不食鳴声悲，徬徨躑躅久不去。","以翼来覆待狗归，嗟哉董生。","誰將與儔，时之人。","夫妻相虐，兄弟爲讐。","食君之祿，而令父母愁。","亦独何心，嗟哉董生無與儔。"]', '诗', 'shi', '', NULL, '嗟哉董生行 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b49395d3-2826-4e8d-a78f-b9ac7b4a8629', '烽火', '烽火', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["登高望烽火，誰謂塞塵飛。","王城富且樂，曷不事光輝。","勿言日已暮，相見恐行稀。","願君熟念此，秉燭夜中歸。","我歌寧自感，乃獨淚霑衣。"]', '["登高望烽火，誰謂塞塵飞。","王城富且乐，曷不事光輝。","勿言日已暮，相见恐行稀。","願君熟念此，秉燭夜中归。","我歌寧自感，乃独泪霑衣。"]', '诗', 'shi', '', NULL, '烽火 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b596522-409c-4275-946f-c2d690037e4c', '汴州亂二首 一', '汴州亂二首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["汴州城門朝不開，天狗墮地聲如雷。","健兒爭誇殺留後，連屋累棟燒成灰。","諸侯咫尺不能救，孤士何者自興哀。"]', '["汴州城门朝不开，天狗墮地声如雷。","健兒爭誇殺留後，連屋累棟燒成灰。","諸侯咫尺不能救，孤士何者自兴哀。"]', '诗', 'shi', '', NULL, '汴州亂二首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53e33fb7-1422-4979-a25e-54d4ca820c76', '汴州亂二首 二', '汴州亂二首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["母從子走者爲誰，大夫夫人留後兒。","昨日乘車騎大馬，坐者起趨乘者下。","廟堂不肯用干戈，嗚呼奈汝母子何。"]', '["母從子走者爲誰，大夫夫人留後兒。","昨日乘车騎大马，坐者起趨乘者下。","廟堂不肯用干戈，嗚呼奈汝母子何。"]', '诗', 'shi', '', NULL, '汴州亂二首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4457599b-144f-4707-85f1-efd47cc89c03', '利劒', '利劒', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["利劒光耿耿，佩之使我無邪心。","故人念我寡徒侶，持用贈我比知音。","我心如冰劒如雪，不能刺讒夫。","使我心腐劒鋒折，決雲中斷開青天。","噫，劒與我俱變化歸黃泉。"]', '["利劒光耿耿，佩之使我無邪心。","故人念我寡徒侶，持用贈我比知音。","我心如冰劒如雪，不能刺讒夫。","使我心腐劒鋒折，決云中斷开青天。","噫，劒與我俱变化归黄泉。"]', '诗', 'shi', '', NULL, '利劒 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4a96752-93b2-4088-bdb3-4c45a5584e78', '齪齪', '齪齪', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["齪齪當世士，所憂在飢寒。","但見賤者悲，不聞貴者歎。","大賢事業異，遠抱非俗觀。","報國心皎潔，念時涕汍瀾。","妖姬坐左右，柔指發哀彈。","酒肴雖日陳，感激寧爲歡。","秋陰欺白日，泥潦不少乾。","河堤決東郡，老弱隨驚湍。","天意固有屬，誰能詰其端。","願辱太守薦，得充諫諍官。","排雲呌閶闔，披腹呈琅玕。","致君豈無術，自進誠獨難。"]', '["齪齪當世士，所憂在飢寒。","但见賤者悲，不闻貴者歎。","大賢事業異，远抱非俗观。","報国心皎潔，念时涕汍瀾。","妖姬坐左右，柔指發哀彈。","酒肴雖日陳，感激寧爲歡。","秋陰欺白日，泥潦不少乾。","河堤決东郡，老弱隨驚湍。","天意固有屬，誰能詰其端。","願辱太守薦，得充諫諍官。","排云呌閶闔，披腹呈琅玕。","致君豈無術，自進誠独难。"]', '诗', 'shi', '', NULL, '齪齪 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5c8234e-7102-45e6-91cf-9409e797be87', '河之水二首寄子姪老成 一', '河之水二首寄子姪老成 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["河之水，去悠悠，我不如，水東流。","我有孤姪在海陬，三年不見兮使我生憂。","日復日，夜復夜，三年不見汝，使我鬢髮未老而先化。"]', '["河之水，去悠悠，我不如，水东流。","我有孤姪在海陬，三年不见兮使我生憂。","日复日，夜复夜，三年不见汝，使我鬢髮未老而先化。"]', '诗', 'shi', '', NULL, '河之水二首寄子姪老成 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac2a0a60-ef91-46f9-8cc5-85e53ab6cb6e', '河之水二首寄子姪老成 二', '河之水二首寄子姪老成 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["河之水，悠悠去，我不如，水東注。","我有孤姪在海浦，三年不見兮使我心苦。","采蕨於山，緡魚於淵。","我徂京師，不遠其還。"]', '["河之水，悠悠去，我不如，水东注。","我有孤姪在海浦，三年不见兮使我心苦。","采蕨於山，緡鱼於淵。","我徂京師，不远其還。"]', '诗', 'shi', '', NULL, '河之水二首寄子姪老成 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e73e2743-3752-4ba3-938a-fb59cd3965ee', '山石', '山石', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["山石犖確行徑微，黃昏到寺蝙蝠飛。","升堂坐階新雨足，芭蕉葉大支子肥。","僧言古壁佛畫好，以火來照所見稀。","鋪牀拂席置羹飯，疎糲亦足飽我飢。","夜深靜臥百蟲絕，清月出嶺光入扉。","天明獨去無道路，出入高下窮煙霏。","山紅澗碧紛爛漫，時見松櫪皆十圍。","當流赤足蹋澗石，水聲激激風吹衣。","人生如此自可樂，豈必局束爲人鞿。","嗟哉吾黨二三子，安得至老不更歸。"]', '["山石犖確行徑微，黄昏到寺蝙蝠飞。","升堂坐階新雨足，芭蕉葉大支子肥。","僧言古壁佛畫好，以火来照所见稀。","鋪牀拂席置羹飯，疎糲亦足飽我飢。","夜深静臥百蟲絕，清月出嶺光入扉。","天明独去無道路，出入高下窮煙霏。","山紅澗碧紛爛漫，时见松櫪皆十圍。","當流赤足蹋澗石，水声激激风吹衣。","人生如此自可乐，豈必局束爲人鞿。","嗟哉吾黨二三子，安得至老不更归。"]', '诗', 'shi', '', NULL, '山石 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20dea002-e0ee-453b-89a0-f54b746aa435', '天星送楊凝郎中賀正', '天星送楊凝郎中賀正', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["天星牢落雞喔咿，僕夫起餐車載脂。","正當窮冬寒未已，借問君子行安之。","會朝元正無不至，受命上宰須及期。","侍從近臣有虛位，公今此去歸何時。"]', '["天星牢落雞喔咿，僕夫起餐车載脂。","正當窮冬寒未已，借问君子行安之。","會朝元正無不至，受命上宰須及期。","侍從近臣有虛位，公今此去归何时。"]', '诗', 'shi', '', NULL, '天星送楊凝郎中賀正 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b331937f-9771-430b-a036-810ffc42bc17', '汴泗交流贈張僕射', '汴泗交流贈張僕射', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["汴泗交流郡城角，築場十步平如削。","短垣三面繚逶迤，擊鼓騰騰樹赤旗。","新秋朝涼未見日，公早結束來何爲。","分曹決勝約前定，百馬攢蹄近相暎。","毬驚杖奮合且離，紅牛纓紱黃金羈。","側身轉臂著馬腹，霹靂應手神珠馳。","超遙散漫兩閑暇，揮霍紛紜爭變化。","發難得巧意氣麤，讙聲四合壯士呼。","此誠習戰非爲劇，豈若安坐行良圖。","當今忠臣不可得，公馬莫走須殺賊。"]', '["汴泗交流郡城角，築場十步平如削。","短垣三面繚逶迤，擊鼓腾腾樹赤旗。","新秋朝涼未见日，公早結束来何爲。","分曹決勝約前定，百马攢蹄近相暎。","毬驚杖奮合且離，紅牛纓紱黄金羈。","側身轉臂著马腹，霹靂應手神珠驰。","超遙散漫兩闲暇，揮霍紛紜爭变化。","發难得巧意氣麤，讙声四合壯士呼。","此誠習戰非爲劇，豈若安坐行良圖。","當今忠臣不可得，公马莫走須殺賊。"]', '诗', 'shi', '', NULL, '汴泗交流贈張僕射 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ca666d1-7adb-409b-97d6-ec3761cb62b1', '忽忽', '忽忽', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["忽忽乎余未知生之爲樂也，願脫去而無因。","安得長翮大翼如雲生我身，乘風振奮出六合，絕浮塵。","死生哀樂兩相棄，是非得失付閑人。"]', '["忽忽乎余未知生之爲乐也，願脫去而無因。","安得长翮大翼如云生我身，乘风振奮出六合，絕浮塵。","死生哀乐兩相棄，是非得失付闲人。"]', '诗', 'shi', '', NULL, '忽忽 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba0e5915-5198-4cf2-b744-7e09636ed846', '鳴雁', '鳴雁', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["嗷嗷鳴雁鳴且飛，窮秋南去春北歸。","去寒就暖識所依，天長地闊棲息稀。","風霜酸苦稻粱微，毛羽摧落身不肥。","裴回反顧羣侶違，哀鳴欲下洲渚非。","江南水闊朝雲多，草長沙軟無網羅。"]', '["嗷嗷鳴雁鳴且飞，窮秋南去春北归。","去寒就暖識所依，天长地闊棲息稀。","风霜酸苦稻粱微，毛羽摧落身不肥。","裴回反顧羣侶違，哀鳴欲下洲渚非。","江南水闊朝云多，草长沙軟無網羅。"]', '诗', 'shi', '', NULL, '鳴雁 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b039de2e-47b6-4186-aae8-a127314e75a6', '龍移', '龙移', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["天昏地黑蛟龍移，雷驚電激雄雌隨。","清泉百丈化爲土，魚鼈枯死吁可悲。"]', '["天昏地黑蛟龙移，雷驚電激雄雌隨。","清泉百丈化爲土，鱼鼈枯死吁可悲。"]', '诗', 'shi', '', NULL, '龍移 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9447c07-1419-4545-81e2-7b172defd810', '雉帶箭', '雉带箭', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["原頭火燒靜兀兀，野雉畏鷹出復沒。","將軍欲以巧伏人，盤馬彎弓惜不發。","地形漸窄觀者多，雉驚弓滿勁箭加。","衝人決起百餘尺，紅翎白鏃相傾斜。","將軍仰笑軍吏賀，五色離披馬前墮。"]', '["原头火燒静兀兀，野雉畏鷹出复沒。","將軍欲以巧伏人，盤马彎弓惜不發。","地形漸窄观者多，雉驚弓满勁箭加。","衝人決起百餘尺，紅翎白鏃相傾斜。","將軍仰笑軍吏賀，五色離披马前墮。"]', '诗', 'shi', '', NULL, '雉帶箭 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a7096f2-fea3-4d20-856c-dc77eec999b4', '條山蒼', '條山蒼', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["條山蒼，河水黃。","浪波沄沄去，松柏在山岡。"]', '["條山蒼，河水黄。","浪波沄沄去，松柏在山岡。"]', '诗', 'shi', '', NULL, '條山蒼 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('563399e5-c9e7-4d62-9bc9-002d005e95ae', '贈鄭兵曹', '贈鄭兵曹', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["尊酒相逢十載前，君爲壯夫我少年。","尊酒相逢十載後，我爲壯夫君白首。","我材與世不相當，戢鱗委翅無復望。","當今賢俊皆周行，君何爲乎亦遑遑。","桮行到君莫停手，破除萬事無過酒。"]', '["尊酒相逢十載前，君爲壯夫我少年。","尊酒相逢十載後，我爲壯夫君白首。","我材與世不相當，戢鱗委翅無复望。","當今賢俊皆周行，君何爲乎亦遑遑。","桮行到君莫停手，破除万事無過酒。"]', '诗', 'shi', '', NULL, '贈鄭兵曹 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('746089bc-7a9d-46f1-8ff4-7636f0403347', '桃源圖', '桃源圖', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["神僊有無何渺茫，桃源之說誠荒唐。","流水盤迴山百轉，生綃數幅垂中堂。","武陵太守好事者，題封遠寄南宮下。","南宮先生忻得之，波濤入筆驅文辭。","文工畫妙各臻極，異境恍惚移於斯。","架巖鑿谷開宮室，接屋連牆千萬日。","嬴顛劉蹶了不聞，地坼天分非所恤。","種桃處處惟開花，川原近遠蒸紅霞。","初來猶自念鄉邑，歲久此地還成家。","漁舟之子來何所，物色相猜更問語。","大蛇中斷喪前王，羣馬南渡開新主。","聽終辭絕共悽然，自說經今六百年。","當時萬事皆眼見，不知幾許猶流傳。","爭持酒食來相饋，禮數不同樽俎異。","月明伴宿玉堂空，骨冷魂清無夢寐。","夜半金雞啁哳鳴，火輪飛出客心驚。","人間有累不可住，依然離別難爲情。","船開櫂進一迴顧，萬里蒼蒼煙水暮。","世俗寧知僞與真，至今傳者武陵人。"]', '["神僊有無何渺茫，桃源之说誠荒唐。","流水盤迴山百轉，生綃數幅垂中堂。","武陵太守好事者，題封远寄南宮下。","南宮先生忻得之，波濤入笔驱文辞。","文工畫妙各臻極，異境恍惚移於斯。","架巖鑿谷开宮室，接屋連牆千万日。","嬴顛劉蹶了不闻，地坼天分非所恤。","種桃处处惟开花，川原近远蒸紅霞。","初来猶自念乡邑，歲久此地還成家。","漁舟之子来何所，物色相猜更问語。","大蛇中斷喪前王，羣马南渡开新主。","听終辞絕共悽然，自说經今六百年。","當时万事皆眼见，不知幾許猶流傳。","爭持酒食来相饋，禮數不同樽俎異。","月明伴宿玉堂空，骨冷魂清無梦寐。","夜半金雞啁哳鳴，火輪飞出客心驚。","人间有累不可住，依然離別难爲情。","船开櫂進一迴顧，万里蒼蒼煙水暮。","世俗寧知僞與真，至今傳者武陵人。"]', '诗', 'shi', '', NULL, '桃源圖 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59dd1b2c-1a22-4b38-b7e3-317385d03d69', '東方半明', '东方半明', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["東方半明大星沒，獨有太白配殘月。","嗟爾殘月勿相疑，同光共影須臾期。","殘月暉暉，太白睒睒。","雞三號，更五點。"]', '["东方半明大星沒，独有太白配殘月。","嗟爾殘月勿相疑，同光共影須臾期。","殘月暉暉，太白睒睒。","雞三號，更五点。"]', '诗', 'shi', '', NULL, '東方半明 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76fe79f6-b932-454a-bc36-c44768ec3b1e', '贈唐衢', '贈唐衢', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["虎有爪兮牛有角，虎可搏兮牛可觸。","奈何君獨抱奇材，手把鋤犁餓空谷。","當今天子急賢良，匭函朝出開明光。","胡不上書自薦達，坐令四海如虞唐。"]', '["虎有爪兮牛有角，虎可搏兮牛可觸。","奈何君独抱奇材，手把鋤犁餓空谷。","當今天子急賢良，匭函朝出开明光。","胡不上书自薦達，坐令四海如虞唐。"]', '诗', 'shi', '', NULL, '贈唐衢 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7ff814c-b1c6-4b1a-bbb5-c6ebc3c0611c', '貞女峽', '貞女峽', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["江盤峽束春湍豪，風雷戰鬬魚龍逃。","懸流轟轟射水府，一瀉百里翻雲濤。","漂船擺石萬瓦裂，咫尺性命輕鴻毛。"]', '["江盤峽束春湍豪，风雷戰鬬鱼龙逃。","懸流轟轟射水府，一瀉百里翻云濤。","漂船擺石万瓦裂，咫尺性命轻鴻毛。"]', '诗', 'shi', '', NULL, '貞女峽 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8a78c3e-05d9-4ccd-823b-6014df3fc388', '贈侯喜', '贈侯喜', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["吾黨侯生字叔起，呼我持竿釣溫水。","平明鞭馬出都門，盡日行行荆棘裏。","溫水微茫絕又流，深如車轍闊容輈。","蝦蟆跳過雀兒浴，此縱有魚何足求。","我爲侯生不能已，盤針擘粒投泥滓。","晡時堅坐到黃昏，手倦目勞方一起。","暫動還休未可期，蝦行蛭渡似皆疑。","舉竿引線忽有得，一寸纔分鱗與鬐。","是日侯生與韓子，良久歎息相看悲。","我今行事盡如此，此事正好爲吾規。","半世遑遑就舉選，一名始得紅顏衰。","人間事勢豈不見，徒自辛苦終何爲。","便當提攜妻與子，南入箕潁無還時。","叔起君今氣方銳，我言至切君勿嗤。","君欲釣魚須遠去，大魚豈肯居沮洳。"]', '["吾黨侯生字叔起，呼我持竿釣溫水。","平明鞭马出都门，尽日行行荆棘裏。","溫水微茫絕又流，深如车轍闊容輈。","蝦蟆跳過雀兒浴，此縱有鱼何足求。","我爲侯生不能已，盤針擘粒投泥滓。","晡时堅坐到黄昏，手倦目勞方一起。","暫动還休未可期，蝦行蛭渡似皆疑。","舉竿引線忽有得，一寸纔分鱗與鬐。","是日侯生與韓子，良久歎息相看悲。","我今行事尽如此，此事正好爲吾規。","半世遑遑就舉選，一名始得紅顏衰。","人间事勢豈不见，徒自辛苦終何爲。","便當提携妻與子，南入箕潁無還时。","叔起君今氣方銳，我言至切君勿嗤。","君欲釣鱼須远去，大鱼豈肯居沮洳。"]', '诗', 'shi', '', NULL, '贈侯喜 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7be03a6d-ac09-47a6-a6e3-0df5447664ad', '古意', '古意', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["太華峰頭玉井蓮，開花十丈藕如船。","冷比雪霜甘比蜜，一片入口沈痾痊。","我欲求之不憚遠，青壁無路難夤緣。","安得長梯上摘實，下種七澤根株連。"]', '["太华峰头玉井蓮，开花十丈藕如船。","冷比雪霜甘比蜜，一片入口沈痾痊。","我欲求之不憚远，青壁無路难夤緣。","安得长梯上摘實，下種七澤根株連。"]', '诗', 'shi', '', NULL, '古意 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e98bed-27fa-4dbe-8d6e-e7cb8c3e4d97', '八月十五夜贈張功曹', '八月十五夜贈張功曹', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["纖雲四卷天無河，清風吹空月舒波。","沙平水息聲影絕，一桮相屬君當歌。","君歌聲酸辭且苦，不能聽終淚如雨。","洞庭連天九疑高，蛟龍出沒猩鼯號。","十生九死到官所，幽居默默如藏逃。","下牀畏蛇食畏藥，海氣濕蟄熏腥臊。","昨者州前搥大鼓，嗣皇繼聖登夔臯。","赦書一日行萬里，罪從大辟皆除死。","遷者追廻流者還，滌瑕蕩垢清朝班。","州家申名使家抑，坎軻祗得移荆蠻。","判司卑官不堪說，未免捶楚塵埃間。","同時輩流多上道，天路幽險難追攀。","君歌且休聽我歌，我歌今與君殊科。"]', '["纖云四卷天無河，清风吹空月舒波。","沙平水息声影絕，一桮相屬君當歌。","君歌声酸辞且苦，不能听終泪如雨。","洞庭連天九疑高，蛟龙出沒猩鼯號。","十生九死到官所，幽居默默如藏逃。","下牀畏蛇食畏藥，海氣濕蟄熏腥臊。","昨者州前搥大鼓，嗣皇繼聖登夔臯。","赦书一日行万里，罪從大辟皆除死。","遷者追廻流者還，滌瑕蕩垢清朝班。","州家申名使家抑，坎軻祗得移荆蠻。","判司卑官不堪说，未免捶楚塵埃间。","同时輩流多上道，天路幽險难追攀。","君歌且休听我歌，我歌今與君殊科。"]', '诗', 'shi', '', NULL, '八月十五夜贈張功曹 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ae27a0-2641-41e6-8c0a-60a9185f8b6d', '謁衡嶽廟遂宿嶽寺題門樓', '謁衡嶽廟遂宿嶽寺題门楼', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["五嶽祭秩皆三公，四方環鎮嵩當中。","火維地荒足妖怪，天假神柄專其雄。","噴雲泄霧藏半腹，雖有絕頂誰能窮。","我來正逢秋雨節，陰氣晦昧無清風。","潛心默禱若有應，豈非正直能感通。","須臾靜掃衆峰出，仰見突兀撐青空。","紫蓋連延接天柱，石廩騰擲堆祝融。","森然魄動下馬拜，松柏一逕趨靈宮。","粉牆丹柱動光彩，鬼物圖畫填青紅。","升階傴僂薦脯酒，欲以菲薄明其衷。","廟令老人識神意，睢盱偵伺能鞠躬。","手持桮珓導我擲，云此最吉餘難同。","竄逐蠻荒幸不死，衣食纔足甘長終。","侯王將相望久絕，神縱欲福難爲功。","夜投佛寺上高閣，星月掩暎雲朣朧。","猿鳴鐘動不知曙，杲杲寒日生於東。"]', '["五嶽祭秩皆三公，四方环鎮嵩當中。","火維地荒足妖怪，天假神柄專其雄。","噴云泄霧藏半腹，雖有絕頂誰能窮。","我来正逢秋雨節，陰氣晦昧無清风。","潛心默禱若有應，豈非正直能感通。","須臾静掃衆峰出，仰见突兀撐青空。","紫蓋連延接天柱，石廩腾擲堆祝融。","森然魄动下马拜，松柏一逕趨靈宮。","粉牆丹柱动光彩，鬼物圖畫填青紅。","升階傴僂薦脯酒，欲以菲薄明其衷。","廟令老人識神意，睢盱偵伺能鞠躬。","手持桮珓導我擲，云此最吉餘难同。","竄逐蠻荒幸不死，衣食纔足甘长終。","侯王將相望久絕，神縱欲福难爲功。","夜投佛寺上高閣，星月掩暎云朣朧。","猿鳴鐘动不知曙，杲杲寒日生於东。"]', '诗', 'shi', '', NULL, '謁衡嶽廟遂宿嶽寺題門樓 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbf39485-2f70-4257-b954-dfbbad49b405', '岣嶁山', '岣嶁山', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["岣嶁山尖神禹碑，字青石赤形模奇。","科斗拳身薤倒披，鸞飄鳳泊拏虎螭。","事嚴跡秘鬼莫窺，道人獨上偶見之。","我來咨嗟涕漣洏，千搜萬索何處有，森森綠樹猿猱悲。"]', '["岣嶁山尖神禹碑，字青石赤形模奇。","科斗拳身薤倒披，鸾飄鳳泊拏虎螭。","事嚴跡秘鬼莫窺，道人独上偶见之。","我来咨嗟涕漣洏，千搜万索何处有，森森綠樹猿猱悲。"]', '诗', 'shi', '', NULL, '岣嶁山 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2f34256-4855-4cd4-9687-7f469e349afa', '永貞行', '永貞行', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["君不見太皇諒陰未出令，小人乘時偷國柄。","北軍百萬虎與貔，天子自將非他師。","一朝奪印付私黨，懍懍朝士何能爲。","狐鳴梟噪爭署置，睗睒跳踉相嫵媚。","夜作詔書朝拜官，超資越序曾無難。","公然白日受賄賂，火齊磊落堆金盤。","元臣故老不敢語，晝臥涕泣何汍瀾。","董賢三公誰復惜，侯景九錫行可歎。","國家功高德且厚，天位未許庸夫干。","嗣皇卓犖信英主，文如太宗武高祖。","膺圖受禪登明堂，共流幽州鯀死羽。","四門肅穆賢俊登，數君匪親豈其朋。","郎官清要爲世稱，荒郡迫野嗟可矜。","湖波連天日相騰，蠻俗生梗瘴癘烝。","江氛嶺祲昏若凝，一蛇兩頭見未曾。","怪鳥鳴喚令人憎，蟲蟲羣飛夜撲燈。","雄虺毒螫墮股肱，食中置藥肝心崩。","左右使令詐難憑，慎勿浪信常兢兢。","吾嘗同僚情可勝，具書目見非妄徵，嗟爾既往宜爲懲。"]', '["君不见太皇諒陰未出令，小人乘时偷国柄。","北軍百万虎與貔，天子自將非他師。","一朝奪印付私黨，懍懍朝士何能爲。","狐鳴梟噪爭署置，睗睒跳踉相嫵媚。","夜作詔书朝拜官，超資越序曾無难。","公然白日受賄賂，火齊磊落堆金盤。","元臣故老不敢語，晝臥涕泣何汍瀾。","董賢三公誰复惜，侯景九錫行可歎。","国家功高德且厚，天位未許庸夫干。","嗣皇卓犖信英主，文如太宗武高祖。","膺圖受禪登明堂，共流幽州鯀死羽。","四门肅穆賢俊登，數君匪親豈其朋。","郎官清要爲世稱，荒郡迫野嗟可矜。","湖波連天日相腾，蠻俗生梗瘴癘烝。","江氛嶺祲昏若凝，一蛇兩头见未曾。","怪鸟鳴喚令人憎，蟲蟲羣飞夜撲灯。","雄虺毒螫墮股肱，食中置藥肝心崩。","左右使令詐难憑，慎勿浪信常兢兢。","吾嘗同僚情可勝，具书目见非妄徵，嗟爾既往宜爲懲。"]', '诗', 'shi', '', NULL, '永貞行 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9892fa9-0e3e-499c-8351-97cfb1b21f6d', '洞庭湖阻風贈張十一署', '洞庭湖阻风贈張十一署', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["十月陰氣盛，北風無時休。","蒼茫洞庭岸，與子維雙舟。","霧雨晦爭泄，波濤怒相投。","犬雞斷四聽，糧絕誰與謀。","相去不容步，險如礙山丘。","清談可以飽，夢想接無由。","男女喧左右，飢啼但啾啾。","非懷北歸興，何用勝羇愁。","雲外有白日，寒光自悠悠。","能令暫開霽，過是吾無求。"]', '["十月陰氣盛，北风無时休。","蒼茫洞庭岸，與子維雙舟。","霧雨晦爭泄，波濤怒相投。","犬雞斷四听，糧絕誰與謀。","相去不容步，險如礙山丘。","清談可以飽，梦想接無由。","男女喧左右，飢啼但啾啾。","非懷北归兴，何用勝羇愁。","云外有白日，寒光自悠悠。","能令暫开霽，過是吾無求。"]', '诗', 'shi', '', NULL, '洞庭湖阻風贈張十一署 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8236d0ab-42ac-46ca-bc05-8d925e2e1145', '李花贈張十一署', '李花贈張十一署', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["江陵城西二月尾，花不見桃惟見李。","風揉雨練雪羞比，波濤翻空杳無涘。","君知此處花何似，白花倒燭天夜明。","羣雞驚鳴官吏起，金烏海底初飛來。","朱輝散射青霞開，迷魂亂眼看不得。","照耀萬樹繁如堆，念昔少年著遊燕。","對花豈省曾辭桮，自從流落憂感集。","欲去未到先思廻，祗今四十已如此。","後日更老誰論哉，力攜一尊獨就醉，不忍虛擲委黃埃。"]', '["江陵城西二月尾，花不见桃惟见李。","风揉雨練雪羞比，波濤翻空杳無涘。","君知此处花何似，白花倒燭天夜明。","羣雞驚鳴官吏起，金烏海底初飞来。","朱輝散射青霞开，迷魂亂眼看不得。","照耀万樹繁如堆，念昔少年著游燕。","对花豈省曾辞桮，自從流落憂感集。","欲去未到先思廻，祗今四十已如此。","後日更老誰論哉，力携一尊独就醉，不忍虛擲委黄埃。"]', '诗', 'shi', '', NULL, '李花贈張十一署 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23700eca-9b4c-4f1d-a75d-3ea1c8b70909', '杏花', '杏花', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["居鄰北郭古寺空，杏花兩株能白紅。","曲江滿園不可到，看此寧避雨與風。","二年流竄出嶺外，所見草木多異同。","冬寒不嚴地恒泄，陽氣發亂無全功。","浮花浪蘂鎮長有，纔開還落瘴霧中。","山榴躑躅少意思，照耀黃紫徒爲叢。","鷓鴣鉤輈猿呌歇，杳杳深谷攢青楓。","豈如此樹一來翫，若在京國情何窮。","今旦胡爲忽惆悵，萬片飄泊隨西東。","明年更發應更好，道人莫忘鄰家翁。"]', '["居鄰北郭古寺空，杏花兩株能白紅。","曲江满园不可到，看此寧避雨與风。","二年流竄出嶺外，所见草木多異同。","冬寒不嚴地恒泄，陽氣發亂無全功。","浮花浪蘂鎮长有，纔开還落瘴霧中。","山榴躑躅少意思，照耀黄紫徒爲叢。","鷓鴣鉤輈猿呌歇，杳杳深谷攢青楓。","豈如此樹一来翫，若在京国情何窮。","今旦胡爲忽惆悵，万片飄泊隨西东。","明年更發應更好，道人莫忘鄰家翁。"]', '诗', 'shi', '', NULL, '杏花 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e4dbc15-db20-492e-9de7-d5ebb5111e15', '感春四首 一', '感春四首 一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["我所思兮在何所，情多地遐兮徧處處。","東西南北皆欲往，千江隔兮萬山阻。","春風吹園雜花開，朝日照屋百鳥語。","三桮取醉不復論，一生長恨奈何許。"]', '["我所思兮在何所，情多地遐兮徧处处。","东西南北皆欲往，千江隔兮万山阻。","春风吹园杂花开，朝日照屋百鸟語。","三桮取醉不复論，一生长恨奈何許。"]', '诗', 'shi', '', NULL, '感春四首 一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91833140-4a32-4508-b50e-2d5e57c4940d', '感春四首 二', '感春四首 二', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["皇天平分成四時，春氣漫誕最可悲。","雜花妝林草蓋地，白日坐上傾天維。","蜂喧鳥咽留不得，紅萼萬片從風吹。","豈如秋霜雖慘冽，摧落老物誰惜之。","爲此徑須沽酒飲，自外天地棄不疑。","近憐李杜無檢束，爛漫長醉多文辭。","屈原離騷二十五，不肯餔啜糟與醨。","惜哉此子巧言語，不到聖處寧非癡。","幸逢堯舜明四目，條理品彙皆得宜。","平明出門暮歸舍，酩酊馬上知爲誰。"]', '["皇天平分成四时，春氣漫誕最可悲。","杂花妝林草蓋地，白日坐上傾天維。","蜂喧鸟咽留不得，紅萼万片從风吹。","豈如秋霜雖慘冽，摧落老物誰惜之。","爲此徑須沽酒饮，自外天地棄不疑。","近怜李杜無檢束，爛漫长醉多文辞。","屈原離騷二十五，不肯餔啜糟與醨。","惜哉此子巧言語，不到聖处寧非癡。","幸逢堯舜明四目，條理品彙皆得宜。","平明出门暮归舍，酩酊马上知爲誰。"]', '诗', 'shi', '', NULL, '感春四首 二 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('921befa8-bb39-4bf2-962d-62e91fa15c50', '感春四首 三', '感春四首 三', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["朝騎一馬出，暝就一牀臥。","詩書漸欲拋，節行久已惰。","冠敧感髮禿，語誤驚齒墮。","孤負平生心，已矣知何奈。"]', '["朝騎一马出，暝就一牀臥。","诗书漸欲拋，節行久已惰。","冠敧感髮禿，語誤驚齒墮。","孤負平生心，已矣知何奈。"]', '诗', 'shi', '', NULL, '感春四首 三 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c77e255-86e3-4307-b43b-d0c05a85103e', '感春四首 四', '感春四首 四', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["我恨不如江頭人，長網橫江遮紫鱗。","獨宿荒陂射鳧雁，賣納租賦官不嗔。","歸來歡笑對妻子，衣食自給寧羞貧。","今者無端讀書史，智慧祗足勞精神。","畫蛇著足無處用，兩鬢霜白趨埃塵。","乾愁漫解坐自累，與衆異趣誰相親。","數桮澆腸雖暫醉，皎皎萬慮醒還新。","百年未滿不得死，且可勤買拋青春。"]', '["我恨不如江头人，长網橫江遮紫鱗。","独宿荒陂射鳧雁，賣納租賦官不嗔。","归来歡笑对妻子，衣食自給寧羞貧。","今者無端读书史，智慧祗足勞精神。","畫蛇著足無处用，兩鬢霜白趨埃塵。","乾愁漫解坐自累，與衆異趣誰相親。","數桮澆腸雖暫醉，皎皎万慮醒還新。","百年未满不得死，且可勤買拋青春。"]', '诗', 'shi', '', NULL, '感春四首 四 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ae550b6-e1b7-406d-9834-8ffeb33e8824', '寒食日出遊', '寒食日出游', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["李花初發君始病，我往看君花轉盛。","走馬城西惆悵歸，不忍千株雪相暎。","邇來又見桃與梨，交開紅白如爭競。","可憐物色阻攜手，空展霜縑吟九詠。","紛紛落盡泥與塵，不共新妝比端正。","桐華最晚今已繁，君不強起時難更。","關山遠別固其理，寸步難見始知命。","憶昔與君同貶官，夜渡洞庭看斗柄。","豈料生還得一處，引袖拭淚悲且慶。","各言生死兩追隨，直置心親無貌敬。","念君又署南荒吏，路指鬼門幽且敻。","三公盡是知音人，曷不薦賢陛下聖。","囊空甑倒誰救之，我今一食日還併。","自然憂氣損天和，安得康強保天性。","斷鶴兩翅鳴何哀，縶驥四足氣空橫。","今朝寒食行野外，綠楊帀岸蒲生迸。","宋玉庭邊不見人，輕浪參差魚動鏡。","自嗟孤賤足瑕疵，特見放縱荷寬政。","飲酒寧嫌𧣴底深，題詩尚倚筆鋒勁。","明宵故欲相就醉，有月莫愁當火令。"]', '["李花初發君始病，我往看君花轉盛。","走马城西惆悵归，不忍千株雪相暎。","邇来又见桃與梨，交开紅白如爭競。","可怜物色阻携手，空展霜縑吟九詠。","紛紛落尽泥與塵，不共新妝比端正。","桐华最晚今已繁，君不強起时难更。","关山远別固其理，寸步难见始知命。","憶昔與君同貶官，夜渡洞庭看斗柄。","豈料生還得一处，引袖拭泪悲且慶。","各言生死兩追隨，直置心親無貌敬。","念君又署南荒吏，路指鬼门幽且敻。","三公尽是知音人，曷不薦賢陛下聖。","囊空甑倒誰救之，我今一食日還併。","自然憂氣損天和，安得康強保天性。","斷鹤兩翅鳴何哀，縶驥四足氣空橫。","今朝寒食行野外，綠楊帀岸蒲生迸。","宋玉庭邊不见人，轻浪參差鱼动镜。","自嗟孤賤足瑕疵，特见放縱荷寬政。","饮酒寧嫌𧣴底深，題诗尚倚笔鋒勁。","明宵故欲相就醉，有月莫愁當火令。"]', '诗', 'shi', '', NULL, '寒食日出遊 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce009e2-990c-44a5-b952-c2a8f6e66a65', '憶昨行和張十一', '憶昨行和張十一', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["憶昨夾鍾之呂初吹灰，上公禮罷元侯廻。","車載牲牢甕舁酒，並召賓客延鄒枚。","腰金首翠光照耀，絲竹迥發清以哀。","青天白日花草麗，玉斝屢舉傾金罍。","張君名聲座所屬，起舞先醉長松摧。","宿酲未解舊痁作，深室靜臥聞風雷。","自期殞命在春序，屈指數日憐嬰孩。","危辭苦語感我耳，淚落不揜何漼漼。","念昔從君渡湘水，大帆夜劃窮高桅。","陽山鳥路出臨武，驛馬拒地驅頻隤。","踐蛇茹蠱不擇死，忽有飛詔從天來。","伾文未揃崖州熾，雖得赦宥恒愁猜。","近者三姦悉破碎，羽窟無底幽黃能。","眼中了了見鄉國，知有歸日眉方開。","今君縱署天涯吏，投檄北去何難哉。","無妄之憂勿藥喜，一善自足禳千災。","頭輕目朗肌骨健，古劒新劚磨塵埃。","殃消禍散百福併，從此直至耉與鮐。","嵩山東頭伊洛岸，勝事不假須穿栽。","君當先行我待滿，沮溺可繼窮年推。"]', '["憶昨夾鍾之呂初吹灰，上公禮罷元侯廻。","车載牲牢甕舁酒，並召賓客延鄒枚。","腰金首翠光照耀，絲竹迥發清以哀。","青天白日花草丽，玉斝屢舉傾金罍。","張君名声座所屬，起舞先醉长松摧。","宿酲未解旧痁作，深室静臥闻风雷。","自期殞命在春序，屈指數日怜嬰孩。","危辞苦語感我耳，泪落不揜何漼漼。","念昔從君渡湘水，大帆夜劃窮高桅。","陽山鸟路出臨武，驛马拒地驱頻隤。","踐蛇茹蠱不擇死，忽有飞詔從天来。","伾文未揃崖州熾，雖得赦宥恒愁猜。","近者三姦悉破碎，羽窟無底幽黄能。","眼中了了见乡国，知有归日眉方开。","今君縱署天涯吏，投檄北去何难哉。","無妄之憂勿藥喜，一善自足禳千災。","头轻目朗肌骨健，古劒新劚磨塵埃。","殃消禍散百福併，從此直至耉與鮐。","嵩山东头伊洛岸，勝事不假須穿栽。","君當先行我待满，沮溺可繼窮年推。"]', '诗', 'shi', '', NULL, '憶昨行和張十一 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a72f002a-1c4a-4196-8f07-53c3465a185f', '劉生詩', '劉生诗', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["生名師命其姓劉，自少軒輊非常儔。","棄家如遺來遠遊，東走梁宋暨揚州。","遂凌大江極東陬，洪濤舂天禹穴幽。","越女一笑三年留，南逾橫嶺入炎州。","青鯨高磨波山浮，怪魅炫曜堆蛟虬。","山㺑讙譟猩猩遊，毒氣爍體黃膏流。","問胡不歸良有由，美酒傾水{炙火=肉}肥牛。","妖歌慢舞爛不收，倒心廻腸爲青眸。","千金邀顧不可酬，乃獨遇之盡綢繆。","瞥然一餉成十秋，昔鬚未生今白頭。","五管歷徧無賢侯，迴望萬里還家羞。","陽山窮邑惟猿猴，手持釣竿遠相投。","我爲羅列陳前修，芟蒿斬蓬利鋤耰。","天星廻環數纔周，文學穰穰囷倉稠。","車輕御良馬力優，咄哉識路行勿休，往取將相酬恩讐。"]', '["生名師命其姓劉，自少軒輊非常儔。","棄家如遺来远游，东走梁宋暨揚州。","遂凌大江極东陬，洪濤舂天禹穴幽。","越女一笑三年留，南逾橫嶺入炎州。","青鯨高磨波山浮，怪魅炫曜堆蛟虬。","山㺑讙譟猩猩游，毒氣爍體黄膏流。","问胡不归良有由，美酒傾水{炙火=肉}肥牛。","妖歌慢舞爛不收，倒心廻腸爲青眸。","千金邀顧不可酬，乃独遇之尽綢繆。","瞥然一餉成十秋，昔鬚未生今白头。","五管歷徧無賢侯，迴望万里還家羞。","陽山窮邑惟猿猴，手持釣竿远相投。","我爲羅列陳前修，芟蒿斬蓬利鋤耰。","天星廻环數纔周，文学穰穰囷倉稠。","车轻御良马力優，咄哉識路行勿休，往取將相酬恩讐。"]', '诗', 'shi', '', NULL, '劉生詩 韓愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d58b48b-9486-4f1a-bbef-7d62b62a9104', '鄭羣贈簟', '鄭羣贈簟', 'b09cb1e1-03d0-4ffd-ad81-3c20266fd65c', '唐', '["蘄州笛竹天下知，鄭君所寶尤瓌奇。","攜來當晝不得臥，一府傳看黃琉璃。","體堅色淨又藏節，盡眼凝滑無瑕疵。","法曹貧賤衆所易，腰腹空大何能爲。","自從五月困暑濕，如坐深甑遭蒸炊。","手磨袖拂心語口，慢膚多汗真相宜。","日暮歸來獨惆悵，有賣直欲傾家資。","誰謂故人知我意，卷送八尺含風漪。","呼奴掃地鋪未了，光彩照耀驚童兒。","青蠅側翅蚤蝨避，肅肅疑有清飆吹。","倒身甘寢百疾愈，却願天日恒炎曦。","明珠青玉不足報，贈子相好無時衰。"]', '["蘄州笛竹天下知，鄭君所寶尤瓌奇。","携来當晝不得臥，一府傳看黄琉璃。","體堅色淨又藏節，尽眼凝滑無瑕疵。","法曹貧賤衆所易，腰腹空大何能爲。","自從五月困暑濕，如坐深甑遭蒸炊。","手磨袖拂心語口，慢膚多汗真相宜。","日暮归来独惆悵，有賣直欲傾家資。","誰謂故人知我意，卷送八尺含风漪。","呼奴掃地鋪未了，光彩照耀驚童兒。","青蠅側翅蚤蝨避，肅肅疑有清飆吹。","倒身甘寢百疾愈，却願天日恒炎曦。","明珠青玉不足報，贈子相好無时衰。"]', '诗', 'shi', '', NULL, '鄭羣贈簟 韓愈 shi');
